/* v226: le lingue del sito. Date e numeri nel formato del paese; arabo e
   panjabi (Pakistan) si scrivono da destra a sinistra. */
var LUX_LANGS = [{"code": "it", "name": "Italiano"}, {"code": "en", "name": "English"}, {"code": "es", "name": "Español"}, {"code": "fr", "name": "Français"}, {"code": "de", "name": "Deutsch"}, {"code": "pt", "name": "Português"}, {"code": "ru", "name": "Русский"}, {"code": "zh", "name": "中文"}, {"code": "ja", "name": "日本語"}, {"code": "hi", "name": "हिन्दी"}, {"code": "bn", "name": "বাংলা"}, {"code": "ar", "name": "العربية"}, {"code": "pnb", "name": "پنجابی"}];
