/* Le copertine caricate sono spesso file a piena risoluzione (pensati per
   la lettura), ma nelle griglie servono solo come miniatura — scaricare
   l'originale intero lì è lo spreco più grande di banda del sito. Supabase
   (piano Pro) sa ridimensionare/comprimere l'immagine al volo: basta
   chiedere l'endpoint "render/image" invece di "object" con una larghezza
   target. Se l'URL non è uno Storage Supabase riconoscibile (es. servizio
   esterno), lo lasciamo intatto invece di romperlo. */
function coverThumbUrl(url, width){
  if(!url) return url;
  var marker = '/storage/v1/object/public/';
  var idx = url.indexOf(marker);
  if(idx === -1) return url;
  // v219: su 2G / risparmio dati miniature più piccole (circa un terzo dei byte)
  if(window.LUX_NET === 'slow') width = Math.round(width * 0.6);
  return url.slice(0, idx) + '/storage/v1/render/image/public/' + url.slice(idx + marker.length) + '?width=' + width + '&quality=70';
}

/* ============ AVATAR CON INIZIALI DI RISERVA ============
   Quando manca la foto profilo, invece di un'immagine rotta si mostra un
   cerchio con le iniziali, sempre dello stesso colore per la stessa persona.
   avatarSrc() restituisce direttamente un src per <img>: così si può usare
   ovunque ci sia già un <img> (liste, intestazione chat) senza cambiare
   la struttura HTML né gli id/eventi collegati. */
function avatarInitials(name){
  // solo lettere e cifre: simboli ed emoji nel nome non diventano iniziali
  var words = String(name || '').trim().split(/\s+/)
    .map(function(w){ return w.replace(/[^\p{L}\p{N}]/gu, ''); })
    .filter(Boolean);
  if(words.length === 0) return '?';
  var first = Array.from(words[0])[0] || '';
  var second = words.length > 1 ? (Array.from(words[words.length - 1])[0] || '') : '';
  return (first + second).toUpperCase() || '?';
}
function avatarColorPair(seed){
  var pairs = [
    ['#7a1a2b', '#2a080e'], // vino
    ['#2b5a4c', '#0c1f1c'], // verderame
    ['#6b4718', '#231505'], // bronzo
    ['#4b2660', '#160a1d'], // prugna
    ['#5c2a24', '#1c0c0b'], // sangue di bue
    ['#2c3f5c', '#0b1220']  // blu notte
  ];
  var str = String(seed || ''), h = 0;
  for(var i = 0; i < str.length; i++){ h = ((h << 5) - h + str.charCodeAt(i)) | 0; }
  return pairs[Math.abs(h) % pairs.length];
}
function avatarInitialsDataUri(name, seed){
  var c = avatarColorPair(seed || name);
  var txt = avatarInitials(name).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  var svg =
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80">' +
      '<defs>' +
        '<radialGradient id="g" cx="35%" cy="30%" r="75%"><stop offset="0" stop-color="' + c[0] + '"/><stop offset="1" stop-color="' + c[1] + '"/></radialGradient>' +
        '<linearGradient id="r" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".18"/><stop offset=".5" stop-color="#fff" stop-opacity="0"/></linearGradient>' +
      '</defs>' +
      '<circle cx="40" cy="40" r="40" fill="url(#g)"/>' +
      '<circle cx="40" cy="40" r="38.5" fill="url(#r)" stroke="#e3c273" stroke-opacity=".35" stroke-width="1"/>' +
      '<text x="40" y="41" text-anchor="middle" dominant-baseline="central" font-family="Cinzel,Georgia,\'Times New Roman\',serif" font-size="' + (txt.length > 1 ? 28 : 34) + '" font-weight="700" fill="#000" fill-opacity=".45" dx="0" dy="1.5">' + txt + '</text>' +
      '<text x="40" y="41" text-anchor="middle" dominant-baseline="central" font-family="Cinzel,Georgia,\'Times New Roman\',serif" font-size="' + (txt.length > 1 ? 28 : 34) + '" font-weight="700" fill="#e3c273">' + txt + '</text>' +
    '</svg>';
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
}
function avatarSrc(avatarUrl, name, seed, size){
  if(avatarUrl) return coverThumbUrl(avatarUrl, size || 80);
  return avatarInitialsDataUri(name, seed);
}
function avatarHtml(avatarUrl, name, seed, cls, size){
  return '<img class="' + escapeHtml(cls || '') + '" src="' + escapeHtml(avatarSrc(avatarUrl, name, seed, size)) + '" alt="" loading="lazy">';
}

/* Se la trasformazione immagini non è disponibile sul progetto Supabase,
   la versione ridotta risponde con errore invece che con l'immagine.
   Questo intercetta l'errore e mette al suo posto l'originale, in
   automatico e per sempre — nessun controllo manuale da fare: o funziona
   la miniatura leggera, o il sito torna da solo all'immagine intera. */
document.addEventListener('error', function(e){
  var img = e.target;
  if(img && img.tagName === 'IMG' && img.dataset && img.dataset.fallback && img.src !== img.dataset.fallback){
    img.src = img.dataset.fallback;
  }
}, true);

function getSession(){
  try{ return JSON.parse(localStorage.getItem('lux_session') || 'null'); }catch(e){ return null; }
}
function setSession(session){
  if(session){
    session.expires_at = Date.now() + (session.expires_in || 3600) * 1000;
    localStorage.setItem('lux_session', JSON.stringify(session));
  } else { localStorage.removeItem('lux_session'); }
}
function isSignedIn(){ var s = getSession(); return !!(s && s.access_token); }
function isAdmin(){ var s = getSession(); return isSignedIn() && s.user && s.user.email === ADMIN_EMAIL; }
function currentUserId(){ var s = getSession(); return s && s.user ? s.user.id : null; }
function currentUserEmail(){ var s = getSession(); return s && s.user ? s.user.email : null; }

// Nome da mostrare ad ALTRI utenti (commenti, canali, messaggi privati) — non deve
// mai contenere l'email, che è un dato privato. Se l'utente non ha ancora scelto
// un nome visualizzato, si usa un nome anonimo ma stabile basato sul suo id.
function publicDisplayName(profile){
  if(profile && profile.display_name) return profile.display_name;
  var uid = currentUserId();
  return uid ? (t('notif.someone') + ' ' + uid.slice(0,6)) : t('notif.someone');
}

// Access tokens expire after ~1 hour. Refresh a bit before that so the
// person never silently "falls out" of their session while the tab is open.
/* ============ PRESENCE (chi è online — solo per chi ha un account collegato) ============ */
var HEARTBEAT_INTERVAL_MS = 60000; // manda un segnale ogni 60 secondi
var ONLINE_WINDOW_MS = 120000; // considerato "online ora" se visto negli ultimi 2 minuti

// sendHeartbeat e heartbeatPresence scrivevano entrambe "ultimo attivo"
// ogni minuto, negli stessi istanti: due scritture identiche nel database.
// Ora chi arriva per secondo, entro 30 secondi dall'altro, non riscrive.
var lastHeartbeatAt = 0;
function sendHeartbeat(){
  if(!isSignedIn()) return;
  lastHeartbeatAt = Date.now();
  var session = getSession();
  fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(currentUserId()), {
    method:'PATCH',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
    body: JSON.stringify({last_seen: new Date().toISOString()})
  }).catch(function(){ /* un battito perso non è un problema, il prossimo lo corregge */ });
}

function startHeartbeat(){
  sendHeartbeat();
  setInterval(function(){
    if(document.visibilityState === 'visible' && isSignedIn()) sendHeartbeat();
  }, HEARTBEAT_INTERVAL_MS);
}

function refreshSessionIfNeeded(){
  var s = getSession();
  if(!s || !s.refresh_token) return Promise.resolve(false);
  var msLeft = (s.expires_at || 0) - Date.now();
  if(msLeft > 5 * 60 * 1000) return Promise.resolve(true); // still fresh, nothing to do
  return fetch(SUPABASE_URL + '/auth/v1/token?grant_type=refresh_token', {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Content-Type':'application/json' },
    body: JSON.stringify({refresh_token: s.refresh_token})
  }).then(function(r){ return r.json().catch(function(){ return {}; }).then(function(data){
    if(r.ok && data.access_token){ setSession(data); return true; }
    // v219: solo un rifiuto vero (rinnovo non più valido) chiude la sessione.
    // Prima anche un errore di rete la chiudeva: su 2G/3G, in galleria o in
    // ascensore, aprire il sito voleva dire ritrovarsi fuori dall'account.
    // E solo se nel frattempo un'altra scheda non l'ha già rinnovata: in quel
    // caso il "no" riguarda il codice vecchio, non la sessione di adesso.
    var now = getSession();
    if((r.status === 400 || r.status === 401 || r.status === 403) && now && now.refresh_token === s.refresh_token) setSession(null);
    return false;
  }); }).catch(function(){ return false; });
}

function authSignIn(email, password){
  return fetch(SUPABASE_URL + '/auth/v1/token?grant_type=password', {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Content-Type':'application/json' },
    body: JSON.stringify({email:email, password:password})
  }).then(function(r){
    return r.json().then(function(data){
      if(!r.ok) throw new Error(data.error_description || data.msg || ('sign-in failed: ' + r.status));
      return data;
    });
  });
}
function authSignUp(email, password){
  return fetch(SUPABASE_URL + '/auth/v1/signup', {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Content-Type':'application/json' },
    body: JSON.stringify({email:email, password:password})
  }).then(function(r){
    return r.json().then(function(data){
      if(!r.ok) throw new Error(data.error_description || data.msg || ('sign-up failed: ' + r.status));
      return data; // data.session is null if email confirmation is required
    });
  });
}
function authSignOut(){ setSession(null); currentProfile = null; }

/* ============ MATURE CONTENT TOGGLE ============ */
// Site defaults to all-ages. The 18+ switch is additive, not exclusive: OFF
// shows only Tutti; ON shows Tutti PLUS 18+ together — Tutti content must
// never disappear because of this toggle. Only asks for age confirmation
// the first time it's turned on (per browser).
var matureVisible = false;

// Singola fonte di verità per il filtro 18+/Tutti, usata ovunque nel sito
// invece di ripetere il confronto in ogni funzione di rendering.
function matureOk(item){ return (matureVisible || !item.mature) && characterVisible(item); }

function openMatureModal(){ var m = document.getElementById('matureModal'); m.style.zIndex = '1000'; m.classList.remove('hidden'); }
function closeMatureModal(){ document.getElementById('matureModal').classList.add('hidden'); }

// v222: il 18+ vale per tutta la visita (finché il browser o l'app restano aperti),
// non più per la sola pagina: a ogni nuova visita riparte spento, come prima
function matureOnThisVisit(){
  try { return sessionStorage.getItem('lux_mature_on') === '1' && localStorage.getItem('lux_age_ok') === '1'; } catch(e){ return false; }
}
function rememberMatureForVisit(on){
  try { if(on) sessionStorage.setItem('lux_mature_on', '1'); else sessionStorage.removeItem('lux_mature_on'); } catch(e){}
}

function setMatureVisible(on){
  matureVisible = on;
  rememberMatureForVisit(on);
  try { localStorage.setItem('lux_mature_visible', on ? '1' : '0'); } catch(e){}
  var sw = document.getElementById('matureSwitch');
  if(sw) sw.checked = on;
  updateMatureStateLabel();
  renderCatalog();
  refreshMusicLibraryIfOpen();
  if(on) scrollToMatureContent();
}

// Attivando il 18+, porta subito l'utente ai contenuti appena sbloccati
// (PixAI se presente, altrimenti lo schedario) invece di lasciarlo dov'era
// a dover scorrere a cercarli — da qualunque pagina lo attivi.
function scrollToMatureContent(){
  if(pendingDeepLinkItem) return; // sta per aprirsi un titolo specifico da link diretto — non redirigere altrove
  var onSchedario = !!document.getElementById('library');
  if(!onSchedario){
    window.location.href = 'schedario.html#library';
    return;
  }
  setTimeout(function(){
    var pixai = document.getElementById('pixaiCarousel');
    var target = (pixai && !pixai.classList.contains('hidden')) ? pixai : document.getElementById('library');
    if(target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, 60); // dopo renderCatalog(), così il carosello PixAI è già visibile/nascosto correttamente
}

function updateMatureStateLabel(){
  var el = document.getElementById('matureStateLabel');
  if(el) el.textContent = t(matureVisible ? 'state.mature' : 'state.allages');
}

/* ============ DAY / NIGHT THEME ============ */
function applyTheme(theme){
  document.body.classList.toggle('theme-light', theme === 'light');
  document.documentElement.classList.toggle('lux-light', theme === 'light'); // colore di fondo usato durante l'avvio (vedi loader.js)
  var moonIcon = document.getElementById('themeIconMoon');
  var sunIcon = document.getElementById('themeIconSun');
  if(moonIcon) moonIcon.classList.toggle('hidden', theme === 'light');
  if(sunIcon) sunIcon.classList.toggle('hidden', theme !== 'light');
  var themeColorMeta = document.querySelector('meta[name="theme-color"]');
  if(themeColorMeta) themeColorMeta.setAttribute('content', theme === 'light' ? '#f4efe2' : '#6e1423');
  localStorage.setItem('lux_theme', theme);
}
function initTheme(){
  var saved = localStorage.getItem('lux_theme');
  if(!saved){
    saved = (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches) ? 'light' : 'dark';
  }
  applyTheme(saved);
  document.getElementById('btnTheme') && document.getElementById('btnTheme').addEventListener('click', function(){
    applyTheme(document.body.classList.contains('theme-light') ? 'dark' : 'light');
  });
}

function initMatureToggle(){
  var sw = document.getElementById('matureSwitch');
  if(!sw){ matureVisible = false; return; } // pagina senza il menu principale (es. luxtify.html) — niente da inizializzare qui
  // spento a ogni nuova visita; acceso se lo era già in questa visita (pagina precedente)
  matureVisible = matureOnThisVisit();
  sw.checked = matureVisible;
  updateMatureStateLabel();

  sw.addEventListener('change', function(){
    if(sw.checked){
      var verified = localStorage.getItem('lux_age_ok') === '1';
      if(verified){
        setMatureVisible(true);
      } else {
        sw.checked = false; // revert until confirmed
        openMatureModal();
      }
    } else {
      setMatureVisible(false);
    }
  });

  var promoBanner = document.getElementById('maturePromoBanner');
  if(promoBanner){
    promoBanner.addEventListener('click', function(e){
      e.preventDefault();
      if(!sw.checked) sw.click();
    });
  }

  document.getElementById('gateEnter') && document.getElementById('gateEnter').addEventListener('click', function(){
    localStorage.setItem('lux_age_ok','1');
    closeMatureModal();
    setMatureVisible(true);
    if(pendingDeepLinkItem){
      var toOpen = pendingDeepLinkItem;
      pendingDeepLinkItem = null;
      openTitleModal(toOpen);
    }
    runPendingMatureAction();
  });
  document.getElementById('gateLeave') && document.getElementById('gateLeave').addEventListener('click', function(){
    closeMatureModal();
    pendingDeepLinkItem = null;
  });
  document.getElementById('matureModal') && document.getElementById('matureModal').addEventListener('click', function(e){
    if(e.target.id === 'matureModal'){
      closeMatureModal();
      pendingDeepLinkItem = null;
    }
  });
}

/* ============ REGISTRATION QUIZ (rallenta le registrazioni casuali — non
   è sicurezza vera, è un ostacolo: chi vuole aggirarlo cancellando i dati
   del browser può sempre farlo, ma scoraggia i tentativi automatici/pigri) ============ */
var QUIZ_QUESTIONS = [
  { q:"Chi è il fondatore di LUX COMICS & MEDUSA COMICS?", options:["Lucifer Morningstar","Nox Morningstar","Lucio Emerald","Nox Lucifera"], correct:1 },
  { q:"Quante collane principali compongono l'Archivio?", options:["Due","Tre","Quattro","Cinque"], correct:2 },
  { q:"Chi è la sorella di Lucifer in questo universo?", options:["Lilith","Medusa","Lucifera","Nox"], correct:2 },
  { q:"In quale città è ambientata la collana LUX?", options:["Londra","Los Angeles","Edimburgo","New York"], correct:1 },
  { q:"Come si chiama la dimora di Lucio?", options:["The Black Manor","LUX Noir","Emerald Palace","Silver City"], correct:2 },
  { q:"In quale città è ambientata The Black Manor?", options:["Edimburgo","Los Angeles","Londra","Parigi"], correct:0 }
];
var QUIZ_MAX_FAILS = 4;
var QUIZ_LOCKOUT_MS = 10 * 60 * 1000;
var quizPassed = false;
var currentQuizQuestion = null;

/* Interruttore "domande alla registrazione" (gestionale → Manutenzione). Vale per tutto il sito.
   Se la colonna non esiste ancora (SQL non lanciato) o la lettura fallisce, restano accese: comportamento di prima. */
var registrationQuizEnabled = true;
function fetchRegistrationQuizSetting(){
  if(!SUPABASE_URL) return Promise.resolve(registrationQuizEnabled);
  return fetch(SUPABASE_URL + '/rest/v1/site_status?select=registration_quiz&id=eq.1', {
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + SUPABASE_ANON_KEY }
  })
    .then(function(r){ if(!r.ok) throw new Error('registration quiz read failed: ' + r.status); return r.json(); })
    .then(function(rows){
      var row = rows && rows[0] ? rows[0] : null;
      registrationQuizEnabled = !(row && row.registration_quiz === false);
      var sw = document.getElementById('registrationQuizSwitch');
      if(sw) sw.checked = registrationQuizEnabled;
      applyRegistrationQuizSetting();
      return registrationQuizEnabled;
    })
    .catch(function(err){ console.warn('Registration quiz setting read failed:', err); return registrationQuizEnabled; });
}
/* se il modulo di registrazione è già aperto con le domande e nel frattempo risulta che sono spente, le toglie */
function applyRegistrationQuizSetting(){
  var modal = document.getElementById('authModal');
  if(!modal || modal.classList.contains('hidden')) return;
  if(authMode === 'register' && !registrationQuizEnabled && !quizPassed){
    quizPassed = true;
    renderQuizGate();
  }
}
function setRegistrationQuizSetting(on){
  var session = getSession();
  if(!SUPABASE_URL || !session) return Promise.resolve(false);
  return fetch(SUPABASE_URL + '/rest/v1/site_status?id=eq.1', {
    method:'PATCH',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'return=representation' },
    body: JSON.stringify({ registration_quiz: on })
  })
    .then(function(r){ if(!r.ok) throw new Error('registration quiz write failed: ' + r.status); return r.json(); })
    .then(function(rows){
      if(!rows || !rows.length) throw new Error('registration quiz write: nessuna riga toccata (permessi?)');
      registrationQuizEnabled = on;
      return true;
    })
    .catch(function(err){ console.warn('Registration quiz write failed:', err); return false; });
}

function getQuizState(){
  try {
    var raw = localStorage.getItem('lux_quiz_state');
    return raw ? JSON.parse(raw) : {fails:0, lockoutUntil:0};
  } catch(e){ return {fails:0, lockoutUntil:0}; }
}
function saveQuizState(state){
  try { localStorage.setItem('lux_quiz_state', JSON.stringify(state)); } catch(e){}
}

function renderQuizGate(){
  var gate = document.getElementById('registerQuizGate');
  var fieldsWrap = document.getElementById('authFieldsWrap');
  if(quizPassed){
    gate.classList.add('hidden');
    fieldsWrap.classList.remove('hidden');
    return;
  }
  fieldsWrap.classList.add('hidden');
  gate.classList.remove('hidden');

  var qError = document.getElementById('quizError');
  var qText = document.getElementById('quizQuestionText');
  var qOptions = document.getElementById('quizOptions');
  var state = getQuizState();
  var now = Date.now();

  if(state.lockoutUntil > now){
    qText.textContent = '';
    qOptions.innerHTML = '';
    var minsLeft = Math.ceil((state.lockoutUntil - now) / 60000);
    qError.textContent = t('quiz.lockedOut').replace('{min}', minsLeft);
    return;
  }

  qError.textContent = '';
  currentQuizQuestion = QUIZ_QUESTIONS[Math.floor(Math.random() * QUIZ_QUESTIONS.length)];
  qText.textContent = currentQuizQuestion.q;
  qOptions.innerHTML = '';
  currentQuizQuestion.options.forEach(function(opt, idx){
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'btn btn-ghost btn-sm quiz-option-btn';
    btn.textContent = opt;
    btn.addEventListener('click', function(){ answerQuiz(idx); });
    qOptions.appendChild(btn);
  });
}

function answerQuiz(selectedIdx){
  var state = getQuizState();
  if(selectedIdx === currentQuizQuestion.correct){
    quizPassed = true;
    state.fails = 0;
    saveQuizState(state);
    renderQuizGate();
  } else {
    state.fails = (state.fails || 0) + 1;
    if(state.fails >= QUIZ_MAX_FAILS){
      state.lockoutUntil = Date.now() + QUIZ_LOCKOUT_MS;
      state.fails = 0;
    }
    saveQuizState(state);
    renderQuizGate();
  }
}

var authMode = 'login';
function openAuth(mode){
  authMode = mode || 'login';
  document.getElementById('authError').textContent = '';
  document.getElementById('authUser').value = '';
  document.getElementById('authPass').value = '';
  var titleKey = authMode === 'login' ? 'auth.loginTitle' : 'auth.registerTitle';
  document.getElementById('authTitle').textContent = t(titleKey);
  document.getElementById('authSubmit').textContent = t(authMode === 'login' ? 'auth.loginBtn' : 'auth.registerBtn');
  var switchLabel = document.getElementById('authSwitch');
  var switchText = document.getElementById('authSwitchText');
  if(authMode === 'login'){
    switchText.textContent = t('auth.switchToRegister');
    switchLabel.textContent = t('auth.switchToRegisterBtn');
  } else {
    switchText.textContent = t('auth.switchToLogin');
    switchLabel.textContent = t('auth.switchToLoginBtn');
  }
  if(authMode === 'register'){
    quizPassed = !registrationQuizEnabled; // domande spente dal gestionale: campi subito visibili
    renderQuizGate();
    fetchRegistrationQuizSetting(); // riallinea con quello che ha scelto l'admin, senza bloccare l'apertura
  } else {
    document.getElementById('registerQuizGate').classList.add('hidden');
    document.getElementById('authFieldsWrap').classList.remove('hidden');
  }
  document.getElementById('authModal').classList.remove('hidden');
}
function closeAuth(){ document.getElementById('authModal').classList.add('hidden'); }

function handleAuthSubmit(){
  if(authMode === 'register' && !quizPassed) return; // difesa in più, i campi restano comunque nascosti finché non superi il quiz
  var email = document.getElementById('authUser').value.trim();
  var pass = document.getElementById('authPass').value;
  var err = document.getElementById('authError');
  err.textContent = '';
  if(!email || !pass){ err.textContent = t('err.required'); return; }
  if(!SUPABASE_URL){ err.textContent = t('sync.notConfigured'); return; }


  if(authMode === 'register'){
    authSignUp(email, pass).then(function(data){
      if(data.session){
        setSession(data.session);
        closeAuth();
        afterAuthChange();
      } else {
        closeAuth();
        alert(t('auth.confirmEmailSent'));
      }
    }).catch(function(e){
      err.textContent = e.message || t('err.badLogin');
    });
  } else {
    authSignIn(email, pass).then(function(data){
      setSession(data);
      closeAuth();
      afterAuthChange();
    }).catch(function(e){
      err.textContent = t('err.badLogin');
    });
  }
}

function afterAuthChange(){
  refreshAuthUI();
  refreshAdminUI();
  renderCatalog();
  Promise.all([loadFavorites(true), loadReadingProgress(true)]).then(renderCatalogIfReady);
  loadLikes();
  loadNotifications();
  loadUnreadDmCount();
  loadCharacterFollows();
  syncAdminErrorFlag();
  loadMyCreationSession().then(refreshAdminUI);
  sendHeartbeat();
  renderMaintenanceBanner(); // se chi si è appena autenticato è l'admin, il blocco manutenzione deve sparire subito
  renderNightClosureLock(); // idem per la chiusura notturna
  var reader = document.getElementById('pageReader');
  if(reader && !reader.classList.contains('hidden')){ showReaderPage(readerIndex); } // aggiorna subito alla versione pulita se stava già leggendo
}

function acctChipAvatarHtml(avatarUrl, name){
  if(avatarUrl){
    return '<img class="acct-chip-avatar" src="' + coverThumbUrl(escapeHtml(avatarUrl), 60) + '" alt="" loading="lazy">';
  }
  var initial = (name || '?').replace('@','').charAt(0).toUpperCase();
  return '<span class="acct-chip-avatar-init">' + escapeHtml(initial) + '</span>';
}

/* ---- Pulsante Community nella barra: visibilità + pallino "novità" ----
   Il pallino si accende per richieste di amicizia ricevute o messaggi privati non letti
   (stessi dati e stessa regola della lista Messaggi privati). Sulla pagina Community resta spento. */
function isOnCommunityPage(){ return /\/community(\.html)?\/?$/.test(window.location.pathname); }

function setCommunityDot(on){
  var dot = document.getElementById('navCommunityDot');
  if(!dot) return;
  var wasHidden = dot.classList.contains('hidden');
  dot.classList.toggle('hidden', !on);
  dot.setAttribute('aria-label', t('nav.communityNews'));
  if(on && wasHidden){ dot.classList.remove('pop'); requestAnimationFrame(function(){ dot.classList.add('pop'); }); } // prima: void offsetWidth = ricalcolo forzato di tutta la pagina
}

// Il pallino della Community e il contatore dei messaggi non letti leggono
// esattamente le stesse conversazioni: se chiedono entro 5 secondi l'uno
// dall'altro, la richiesta a Supabase è una sola e la risposta si condivide.
var _dmThreadsShared = { at:0, uid:null, promise:null };
function fetchMyDmThreads(uid){
  var now = Date.now();
  if(_dmThreadsShared.promise && _dmThreadsShared.uid === uid && now - _dmThreadsShared.at < 5000) return _dmThreadsShared.promise;
  var promise = fetch(SUPABASE_URL + '/rest/v1/dm_threads?select=*&or=(user_a.eq.' + encodeURIComponent(uid) + ',user_b.eq.' + encodeURIComponent(uid) + ')', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : null; }).catch(function(){ return null; });
  _dmThreadsShared = { at:now, uid:uid, promise:promise };
  return promise;
}

function refreshCommunityDot(){
  if(!document.getElementById('navCommunityDot')) return;
  if(!isSignedIn() || isOnCommunityPage()){ setCommunityDot(false); return; }
  var uid = currentUserId();
  var pendingReq = fetch(SUPABASE_URL + '/rest/v1/friendships?addressee_id=eq.' + encodeURIComponent(uid) + '&status=eq.pending&select=id&limit=1', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : null; }).catch(function(){ return null; });
  var threads = fetchMyDmThreads(uid);
  Promise.all([pendingReq, threads]).then(function(res){
    if(res[0] === null && res[1] === null) return; // entrambe fallite: non cambiamo quello che si vede
    var hasReq = !!(res[0] && res[0].length);
    var hasUnread = !!(res[1] && res[1].some(function(th){
      var s = dmThreadState(th, uid);
      return !s.read && !s.archived;
    }));
    setCommunityDot(hasReq || hasUnread);
  });
}

function refreshAuthUI(){
  var chip = document.getElementById('acctChip');
  if(!chip) return; // pagina senza il menu principale (es. luxtify.html) — niente da aggiornare qui
  homeRailAuthCheck();
  var btnLogin = document.getElementById('btnLoginTop');
  var btnLogout = document.getElementById('btnLogoutTop');
  var navCommunity = document.getElementById('navCommunity');
  var navContatti = document.getElementById('navContatti');
  var navMyComics = document.getElementById('navMyComics');
  var navCommunityTop = document.getElementById('navCommunityTop');
  var communitySection = document.getElementById('communitySection');
  var smallnoxFloat = document.getElementById('smallnoxFloat');
  if(isSignedIn()){
    // Never show the raw email in the UI — for the admin account it would
    // expose a real name via the address. Show the public persona instead;
    // for any other signed-in visitor, show just the part before "@".
    if(isAdmin()){
      var founderUid = currentUserId();
      chip.innerHTML = acctChipAvatarHtml('', 'Nox Morningstar') + '<span>Nox Morningstar</span> ' + verifiedBadge('verified.founder');
      if(founderUid){
        fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(founderUid) + '&select=avatar_url', { headers: communityHeaders() })
          .then(function(r){ return r.ok ? r.json() : []; })
          .then(function(rows){
            var avatarUrl = (rows[0] && rows[0].avatar_url) || '';
            chip.innerHTML = acctChipAvatarHtml(avatarUrl, 'Nox Morningstar') + '<span>Nox Morningstar</span> ' + verifiedBadge('verified.founder');
          })
          .catch(function(){}); // il nome+badge sono già a posto anche se questa chiamata fallisce
      }
    } else {
      var uid = currentUserId();
      var fallback = '@' + (currentUserEmail() || '').split('@')[0];
      chip.innerHTML = acctChipAvatarHtml('', fallback) + '<span>' + escapeHtml(fallback) + '</span>'; // placeholder finché arriva il profilo vero
      if(uid){
        fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(uid) + '&select=display_name,avatar_url,verified', { headers: communityHeaders() })
          .then(function(r){ return r.ok ? r.json() : []; })
          .then(function(rows){
            var p = rows[0] || {};
            var name = (p.display_name && p.display_name !== t('notif.someone')) ? p.display_name : fallback;
            chip.innerHTML = acctChipAvatarHtml(p.avatar_url || '', name) + '<span>' + escapeHtml(name) + '</span> ' + verifiedBadge('verified.commenter', !!p.verified);
          })
          .catch(function(){}); // il fallback col solo nome resta visibile anche se questa chiamata fallisce
      }
    }
    chip.classList.remove('hidden');
    btnLogin.classList.add('hidden');
    btnLogout.classList.remove('hidden');
    if(navCommunity) navCommunity.classList.remove('hidden');
    if(navCommunityTop){
      navCommunityTop.classList.remove('hidden');
      if(isOnCommunityPage()) navCommunityTop.setAttribute('aria-current', 'page'); else navCommunityTop.removeAttribute('aria-current');
    }
    refreshCommunityDot();
    if(navContatti) navContatti.classList.remove('hidden');
    if(navMyComics) navMyComics.classList.remove('hidden');
    if(communitySection) communitySection.classList.remove('hidden');
    if(smallnoxFloat) smallnoxFloat.classList.remove('hidden');
    refreshSmallNoxBadge();
    refreshPushButtonUI();
    loadChannels();
    loadContattiPage();
    var pendingCommunityTab = sessionStorage.getItem('lux_pending_community_tab');
    if(pendingCommunityTab && document.getElementById('communitySection')){
      sessionStorage.removeItem('lux_pending_community_tab');
      switchCommunityTab(pendingCommunityTab);
    }
  } else {
    chip.classList.add('hidden');
    btnLogin.classList.remove('hidden');
    btnLogout.classList.add('hidden');
    if(navCommunity) navCommunity.classList.add('hidden');
    if(navCommunityTop) navCommunityTop.classList.add('hidden');
    setCommunityDot(false);
    if(navContatti) navContatti.classList.add('hidden');
    if(navMyComics) navMyComics.classList.add('hidden');
    if(communitySection) communitySection.classList.add('hidden');
    if(smallnoxFloat) smallnoxFloat.classList.add('hidden');
  }
}

function refreshAdminUI(){
  var gateBox = document.getElementById('adminGateBox');
  var manageBox = document.getElementById('adminManageBox');
  var gateMsg = document.getElementById('adminGateMessage');
  var gateSignIn = document.getElementById('btnGateSignIn');
  var navAdmin = document.getElementById('navAdmin');
  var adminSection = document.getElementById('adminSection');
  var adminTabs = document.getElementById('adminTabs');
  var collabBanner = document.getElementById('collabSessionBanner');
  var smallnoxCard = document.getElementById('smallnoxCard');
  var admin = isAdmin();
  var collab = !admin && hasActiveCreationSession();
  // Arrivo da uno dei 5 collegamenti rapidi nel modal profilo ("crea per
  // Lucifer" ecc.): pre-seleziona il personaggio nel modulo, una tantum.
  var pendingCharacter = sessionStorage.getItem('lux_pending_new_title_character');
  if(pendingCharacter && document.getElementById('fCharacter')){
    sessionStorage.removeItem('lux_pending_new_title_character');
    document.getElementById('fCharacter').value = pendingCharacter;
  }
  // La voce "Amministra" nel menu va aggiornata su OGNI pagina (vive nell'header
  // condiviso) — non solo su admin.html, dove invece vivono gateBox/manageBox.
  if(navAdmin) navAdmin.classList.toggle('hidden', !isSignedIn());
  if(!gateBox || !manageBox) return;
  if(admin){
    if(adminSection) adminSection.classList.remove('hidden'); // arrivando direttamente su admin.html (non da un click sul link) va rivelata qui, non solo dal click handler
    gateBox.classList.add('hidden');
    manageBox.classList.remove('hidden');
    if(adminTabs) adminTabs.classList.remove('hidden');
    if(collabBanner) collabBanner.classList.add('hidden');
    if(smallnoxCard) smallnoxCard.classList.remove('hidden');
    injectDraftModeToggle();
    injectNsfwRescanButton();
    renderAdminList();
    renderModerationQueue();
    loadSocialLinksIntoForm();
    renderCharImageAdmin();
    renderStatsPanel();
    renderSiteViewsAdmin(); // v220
    renderAdminRequests();
    renderAdminAnnouncements();
    renderAdminUsers();
    renderAdminSessions();
    var pendingAdminTab = sessionStorage.getItem('lux_pending_admin_tab');
    if(pendingAdminTab){
      sessionStorage.removeItem('lux_pending_admin_tab');
      switchAdminTab(pendingAdminTab);
    }
  } else if(isSignedIn()){
    // Chiunque sia registrato vede il modulo "Aggiungi allo schedario" +
    // i propri titoli già pubblicati — niente altre tab, niente dati altrui.
    // (collab distingue solo chi opera dentro una sessione di
    // collaborazione attiva, per il banner sotto — non serve più per
    // decidere CHI può pubblicare: ora può chiunque sia loggato.)
    if(adminSection) adminSection.classList.remove('hidden');
    gateBox.classList.add('hidden');
    manageBox.classList.remove('hidden');
    if(adminTabs) adminTabs.classList.add('hidden');
    if(smallnoxCard) smallnoxCard.classList.add('hidden');
    document.querySelectorAll('.admin-tab-panel').forEach(function(panel){
      panel.classList.toggle('hidden', panel.dataset.tabPanel !== 'catalog');
    });
    // Strumenti di massa (export/import dell'intero catalogo, elenco
    // completo) restano solo per l'admin pieno — non hanno senso per chi
    // pubblica solo i propri titoli.
    var btnExport = document.getElementById('btnExport');
    var btnImport = document.getElementById('btnImport');
    var adminListEl = document.getElementById('adminList');
    if(btnExport) btnExport.classList.add('hidden');
    if(btnImport) btnImport.classList.add('hidden');
    if(adminListEl) adminListEl.classList.add('hidden');
    var addEntryBtn = document.getElementById('btnAddEntry');
    if(collabBanner){
      collabBanner.classList.toggle('hidden', !collab);
      if(collab) renderCollabSessionBanner();
    }
    if(addEntryBtn) addEntryBtn.classList.remove('hidden');
    // Senza una toolbar admin non c'è nessun "+ Nuovo titolo" da cliccare:
    // il modulo va aperto direttamente, altrimenti resta un pannello a
    // scomparsa chiuso che nessuno saprebbe come raggiungere. Non tocca
    // un'eventuale modifica già in corso.
    if(!editingItemId) startNewTitleFlow();
    renderMyTitles();
  } else {
    gateMsg.textContent = t('admin.gate.notSignedIn');
    gateSignIn.classList.remove('hidden');
    if(adminSection) adminSection.classList.add('hidden');
  }
  updateSyncStatus();
}

