var editingItemId = null; // se valorizzato, handleAddEntry() salva una MODIFICA invece di una nuova voce

/* Iniettato una sola volta: colonna dei sigilli nel form Admin (stesso
   stile oro dei filtri dello Schedario) più la card che compare accanto
   alla riga su cui passi sopra, posizionata via JS (non con un semplice
   "a destra della colonna": su una pagina larga finiva lontanissima dal
   sigillo, in mezzo al vuoto — così segue sempre la riga giusta). Uso
   classi mie invece di riusare .genre-seal/.genre-seal-label dello
   Schedario: quelle hanno uno stile pensato per mini-schede verticali e
   mandavano l'etichetta a capo sotto al cerchio anche qui. */
function ensureGenreCheckStyle(){
  if(document.getElementById('genreCheckStyle')) return;
  var styleEl = document.createElement('style');
  styleEl.id = 'genreCheckStyle';
  styleEl.textContent =
    '.genre-check-column{display:flex;flex-direction:column;gap:8px;}' +
    '.genre-check-seal{display:flex;align-items:center;gap:10px;cursor:pointer;padding:6px 10px;border-radius:8px;border:1px solid transparent;}' +
    '.genre-check-seal:hover{border-color:rgba(201,162,77,0.35);}' +
    '.genre-check-seal.active{border-color:#c9a24d;background:rgba(201,162,77,0.08);}' +
    '.genre-check-seal input{position:absolute;opacity:0;width:0;height:0;}' +
    '.gcs-circle{flex:0 0 auto;width:30px;height:30px;border-radius:50%;border:1.5px solid #c9a24d;color:#c9a24d;' +
    'display:flex;align-items:center;justify-content:center;font-family:"Cinzel",serif;font-size:12px;font-weight:600;}' +
    '.gcs-label{flex:1 1 auto;color:#f0e4cd;font-family:"Crimson Pro",serif;font-size:14px;white-space:nowrap;}' +
    '#genreCheckPreview{position:fixed;width:220px;height:140px;border-radius:10px;overflow:hidden;' +
    'border:1px solid rgba(201,162,77,0.4);background-size:cover;background-position:center;background-color:#180f10;' +
    'pointer-events:none;z-index:500;}' +
    '#genreCheckPreview::before{content:"";position:absolute;inset:0;background:rgba(11,6,7,0.45);}' +
    '#genreCheckPreview .genre-check-preview-label{position:relative;z-index:1;color:#f0e4cd;font-family:"Cinzel",serif;font-size:14px;' +
    'display:flex;align-items:center;justify-content:center;height:100%;text-align:center;padding:0 12px;}' +
    '@media (max-width:640px){#genreCheckPreview{position:static;width:100%;height:120px;margin-top:8px;}}'; // niente hover reale su touch, sotto invece che di fianco quando compare
  document.head.appendChild(styleEl);
}

function showGenreCheckPreview(g, anchorEl){
  var preview = document.getElementById('genreCheckPreview');
  if(!preview) return;
  var file = GENRE_BANNERS[g];
  preview.style.backgroundImage = file ? 'url(' + file + ')' : '';
  preview.querySelector('.genre-check-preview-label').textContent = g;
  preview.classList.remove('hidden');
  // Sotto i 640px la preview è statica (sotto ai sigilli, via CSS) — non
  // ha senso calcolarle una posizione: si sposterebbe fuori schermo.
  if(anchorEl && window.innerWidth > 640){
    var rect = anchorEl.getBoundingClientRect();
    var left = rect.right + 16;
    if(left + 220 > window.innerWidth) left = rect.left - 220 - 16; // non c'è spazio a destra: passa a sinistra della riga
    preview.style.left = Math.max(8, left) + 'px';
    preview.style.top = Math.max(8, rect.top) + 'px';
  }
}
function hideGenreCheckPreview(){
  var preview = document.getElementById('genreCheckPreview');
  if(preview) preview.classList.add('hidden');
}

function renderGenreChecks(){
  var block = document.getElementById('fGenresBlock');
  if(!block || block.childElementCount) return;
  ensureGenreCheckStyle();
  block.classList.add('genre-check-column');

  var preview = document.createElement('div');
  preview.id = 'genreCheckPreview';
  preview.className = 'hidden';
  preview.innerHTML = '<div class="genre-check-preview-label"></div>';
  block.appendChild(preview);

  catList().map(function(c){ return c.id; }).forEach(function(g){
    var wrap = document.createElement('label');
    wrap.className = 'genre-check-seal';
    wrap.innerHTML = '<input type="checkbox" value="'+escapeHtml(g)+'">' +
      '<span class="gcs-circle">'+escapeHtml(genreMonogram(g))+'</span>' +
      '<span class="gcs-label">'+escapeHtml(g)+'</span>';
    var input = wrap.querySelector('input');
    input.addEventListener('change', function(){ wrap.classList.toggle('active', input.checked); });
    wrap.addEventListener('mouseenter', function(){ showGenreCheckPreview(g, wrap); }); // desktop
    wrap.addEventListener('mouseleave', hideGenreCheckPreview);
    wrap.addEventListener('click', function(){ showGenreCheckPreview(g, wrap); }); // touch: niente hover reale, il tap che seleziona mostra anche l'anteprima
    block.appendChild(wrap);
  });
}
function getSelectedGenres(){
  var block = document.getElementById('fGenresBlock');
  if(!block) return [];
  return Array.prototype.slice.call(block.querySelectorAll('input:checked')).map(function(el){return el.value;});
}
function setSelectedGenres(arr){
  var block = document.getElementById('fGenresBlock');
  if(!block) return;
  arr = arr || [];
  Array.prototype.forEach.call(block.querySelectorAll('input'), function(el){
    el.checked = arr.indexOf(el.value) !== -1;
    if(el.parentElement) el.parentElement.classList.toggle('active', el.checked); // il cambio programmato non scatena 'change': sincronizziamo qui il sigillo
  });
}

function openEditTitle(id){
  var item = getCatalog().find(function(x){ return x.id === id; });
  if(!item) return;
  editingItemId = id;
  document.getElementById('fTitle').value = item.title || '';
  document.getElementById('fCharacter').value = item.character || '';
  document.getElementById('fIssue').value = item.issue || '';
  document.getElementById('fSeriesKey').value = item.series_key || '';
  document.getElementById('fChapterNumber').value = item.chapter_number != null ? item.chapter_number : '';
  document.getElementById('fDate').value = item.date || '';
  document.getElementById('fPrice').value = item.price != null ? item.price : '';
  document.getElementById('fStock').value = item.stock != null ? item.stock : '';
  document.getElementById('fSynopsis').value = item.synopsis || '';
  document.getElementById('fMature').checked = !!item.mature;
  renderGenreChecks();
  setSelectedGenres(item.genres);
  resetCollabBlocks();
  var collabArr = (item.collaborators && item.collaborators.length)
    ? item.collaborators
    : (item.collaborator_name ? [{ name:item.collaborator_name, url:item.collaborator_url, verified:item.collaborator_verified }] : []);
  collabArr.slice(0,6).forEach(function(c, idx){
    var i = idx + 1;
    if(i > 1){ // il blocco 1 è sempre visibile, dal 2 in su vanno rivelati esplicitamente
      var blockEl = document.getElementById('collabBlock' + i);
      if(blockEl) blockEl.classList.remove('hidden');
    }
    var nEl = document.getElementById('fCollabName' + i);
    var uEl = document.getElementById('fCollabUrl' + i);
    var vEl = document.getElementById('fCollabVerified' + i);
    if(nEl) nEl.value = c.name || '';
    if(uEl) uEl.value = c.url || '';
    if(vEl) vEl.checked = !!c.verified;
  });
  updateAddCollabBtn();
  var btn = document.getElementById('btnAddEntry');
  if(btn){ btn.textContent = t('admin.saveChanges'); btn.classList.remove('hidden'); }
  var cancelBtn = document.getElementById('btnCancelEditTitle');
  if(cancelBtn) cancelBtn.classList.remove('hidden');
  switchAdminTab('catalog');
  document.getElementById('fTitle').scrollIntoView({behavior:'smooth', block:'center'});
  openTitleFormDrawer();
  showMusicSectionForEdit(id);
}

function cancelEditTitle(){
  editingItemId = null;
  document.getElementById('fTitle').value = '';
  document.getElementById('fIssue').value = '';
  document.getElementById('fSeriesKey').value = '';
  document.getElementById('fChapterNumber').value = '';
  document.getElementById('fDate').value = '';
  document.getElementById('fPrice').value = '';
  document.getElementById('fStock').value = '';
  resetCollabBlocks();
  document.getElementById('fSynopsis').value = '';
  document.getElementById('fMature').checked = false;
  renderGenreChecks();
  setSelectedGenres([]);
  var btn = document.getElementById('btnAddEntry');
  if(btn){
    btn.textContent = t('admin.add');
    if(!isSignedIn()) btn.classList.add('hidden');
  }
  var cancelBtn = document.getElementById('btnCancelEditTitle');
  if(cancelBtn) cancelBtn.classList.add('hidden');
  closeTitleFormDrawer();
  hideMusicSectionForNew();
}

/* ============ MODALITÀ BOZZA (anteprima locale prima di pubblicare) ============
   Quando attiva: aggiungere un titolo o cambiare una copertina NON scrive
   su Supabase — resta salvato solo in questo browser (localStorage), con
   un'anteprima che usa lo stesso identico HTML/CSS delle card vere, ma
   con l'immagine mostrata direttamente dal file locale (nessuna rete,
   nessuna cache CDN di mezzo — quello che vedi è sempre esatto).
   "Pubblica bozze" manda tutto online, una voce alla volta. */
function isDraftModeOn(){ return localStorage.getItem('lux_draft_mode') === '1'; }
function injectDraftModeToggle(){
  if(document.getElementById('draftModeToggleWrap')) return; // già inserito, non duplicare
  var list = document.getElementById('adminList');
  if(!list || !list.parentNode) return;
  var wrap = document.createElement('div');
  wrap.id = 'draftModeToggleWrap';
  wrap.className = 'draft-mode-toggle-wrap';
  wrap.innerHTML =
    '<label class="draft-mode-toggle">'+
      '<input type="checkbox" id="chkDraftMode"'+(isDraftModeOn()?' checked':'')+'>'+
      '<span>Modalità bozza — nuovi titoli e copertine restano solo qui finché non pubblichi</span>'+
    '</label>'+
    '<div id="draftBar" class="draft-bar hidden"></div>';
  list.parentNode.insertBefore(wrap, list);
  document.getElementById('chkDraftMode').addEventListener('change', function(e){
    setDraftMode(e.target.checked);
  });
  renderDraftBar();
}
function setDraftMode(on){ localStorage.setItem('lux_draft_mode', on ? '1' : '0'); renderAdminList(); renderDraftBar(); }
function getDraft(){
  try{ return JSON.parse(localStorage.getItem('lux_admin_draft') || '{"newItems":[],"coverEdits":{}}'); }
  catch(e){ return {newItems:[], coverEdits:{}}; }
}
function saveDraft(d){ localStorage.setItem('lux_admin_draft', JSON.stringify(d)); }
function draftPendingCount(){
  var d = getDraft();
  return d.newItems.length + Object.keys(d.coverEdits).length;
}
function fileToDataUrl(file){
  return new Promise(function(resolve, reject){
    var reader = new FileReader();
    reader.onload = function(){ resolve(reader.result); };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}
function renderDraftBar(){
  var bar = document.getElementById('draftBar');
  if(!bar) return;
  var n = draftPendingCount();
  if(!isDraftModeOn() || n === 0){ bar.classList.add('hidden'); bar.innerHTML=''; return; }
  bar.classList.remove('hidden');
  bar.innerHTML =
    '<span>' + n + ' modifiche in bozza, non ancora online</span>' +
    '<button type="button" class="btn btn-primary btn-sm" id="btnPublishDraft">Pubblica bozze</button>' +
    '<button type="button" class="btn btn-ghost btn-sm" id="btnDiscardDraft">Scarta bozze</button>';
  document.getElementById('btnPublishDraft').addEventListener('click', publishDraft);
  document.getElementById('btnDiscardDraft').addEventListener('click', function(){
    if(!confirm('Scartare tutte le modifiche in bozza non ancora pubblicate?')) return;
    saveDraft({newItems:[], coverEdits:{}});
    renderAdminList(); renderDraftBar();
  });
}
function publishDraft(){
  var d = getDraft();
  var bar = document.getElementById('draftBar');
  if(bar) bar.innerHTML = '<span>Pubblicazione in corso…</span>';

  var chain = Promise.resolve();

  // 1) copertine cambiate su titoli esistenti
  Object.keys(d.coverEdits).forEach(function(itemId){
    chain = chain.then(function(){
      return dataUrlToBlob(d.coverEdits[itemId]).then(function(blob){
        return uploadCoverForExistingItem(itemId, blob, undefined, undefined, true);
      });
    });
  });

  // 2) titoli nuovi (stessa logica di handleAddEntry, ma senza passare da qui di nuovo)
  d.newItems.forEach(function(draftItem){
    chain = chain.then(function(){
      return publishSingleDraftNewItem(draftItem);
    });
  });

  chain.then(function(){
    saveDraft({newItems:[], coverEdits:{}});
    return fetchCatalogFromSupabase();
  }).then(function(){
    renderCatalog(); renderAdminList(); renderDraftBar();
  }).catch(function(err){
    console.warn('Publish draft failed:', err);
    if(bar) bar.innerHTML = '<span style="color:#d9756b;">Pubblicazione fallita: ' + (err && err.message ? err.message : 'errore') + '</span>';
  });
}
function dataUrlToBlob(dataUrl){
  return fetch(dataUrl).then(function(r){ return r.blob(); });
}
function publishSingleDraftNewItem(draftItem){
  var newItem = {
    id: 'c' + Date.now() + Math.floor(Math.random()*1000),
    character: draftItem.character, title: draftItem.title, issue: draftItem.issue,
    series_key: draftItem.seriesKey || null, chapter_number: (draftItem.chapterNumber !== '' && draftItem.chapterNumber != null) ? Number(draftItem.chapterNumber) : null,
    date: draftItem.date || new Date().toISOString().slice(0,10),
    price: draftItem.price ? Number(draftItem.price) : null,
    stock: (draftItem.stock !== undefined && draftItem.stock !== '') ? Number(draftItem.stock) : null,
    collaborator_name: null, collaborator_url: null, collaborator_verified: false, collaborators: [],
    synopsis: draftItem.synopsis, mature: draftItem.mature, genres: draftItem.genres || [], pages: [], cover_url: null, pdf_url: null,
    created_by: !isAdmin() ? currentUserId() : null,
    synopsis_it: null, synopsis_es: null, synopsis_fr: null, synopsis_de: null
  };
  var steps = Promise.resolve();
  steps = steps.then(function(){
    return translateSynopsis(draftItem.synopsis).then(function(result){
      applySynopsisTranslations(newItem, result); // v226: tutte le lingue
    }).catch(function(){});
  });
  if(draftItem.coverDataUrl){
    steps = steps.then(function(){
      return dataUrlToBlob(draftItem.coverDataUrl).then(function(blob){
        return compressImageFile(blob, 2600, 0.92);
      }).then(function(compressed){
        return uploadCatalogAsset(compressed, newItem.id + '/cover-' + Date.now() + '.jpg');
      });
    }).then(function(url){ newItem.cover_url = url; });
  }
  return steps.then(function(){ return supabaseInsert(newItem); });
}

function handleAddEntry(){
  var title = document.getElementById('fTitle').value.trim();
  var character = document.getElementById('fCharacter').value;
  var issue = document.getElementById('fIssue').value.trim();
  var seriesKey = document.getElementById('fSeriesKey').value.trim();
  var chapterNumberRaw = document.getElementById('fChapterNumber').value;
  var date = document.getElementById('fDate').value;
  var price = document.getElementById('fPrice').value;
  var stock = document.getElementById('fStock').value;
  var collabList = [];
  for(var ci = 1; ci <= 6; ci++){
    var cnEl = document.getElementById('fCollabName' + ci);
    var cuEl = document.getElementById('fCollabUrl' + ci);
    var cvEl = document.getElementById('fCollabVerified' + ci);
    if(!cnEl) continue;
    var cn = cnEl.value.trim();
    if(!cn) continue;
    collabList.push({
      name: cn,
      url: cuEl ? cuEl.value.trim() || null : null,
      verified: cvEl ? cvEl.checked : false
    });
  }
  var synopsis = document.getElementById('fSynopsis').value.trim();
  var mature = document.getElementById('fMature').checked;
  var genres = getSelectedGenres();
  var err = document.getElementById('adminError');
  var status = document.getElementById('pagesUploadStatus');
  err.textContent = '';
  status.textContent = '';
  if(!title || !synopsis){
    err.textContent = t('err.required');
    return;
  }
  var isEdit = !!editingItemId;
  // Chiunque sia loggato può pubblicare un titolo nuovo — non più riservato
  // ad admin o a chi ha una sessione di collaborazione attiva (coerente con
  // l'apertura della pubblicazione a tutti gli utenti registrati).
  if(!isEdit && !isSignedIn()){
    err.textContent = t('collabSession.expired');
    return;
  }

  // Modalità bozza (solo per titoli NUOVI, non per modifiche a uno già
  // esistente): salva tutto in locale, non tocca Supabase, mostra
  // un'anteprima con la copertina vera. "Pubblica bozze" fa il resto dopo.
  if(!isEdit && isDraftModeOn()){
    var draftItem = {
      character: character, title: title, issue: issue, date: date,
      seriesKey: seriesKey || null, chapterNumber: chapterNumberRaw,
      price: price, stock: stock, synopsis: synopsis, mature: mature, genres: genres, coverDataUrl: null
    };
    var afterSave = function(){
      var d = getDraft();
      d.newItems.push(draftItem);
      saveDraft(d);
      document.getElementById('fTitle').value = '';
      document.getElementById('fIssue').value = '';
      document.getElementById('fSeriesKey').value = '';
      document.getElementById('fChapterNumber').value = '';
      document.getElementById('fDate').value = '';
      document.getElementById('fPrice').value = '';
      document.getElementById('fStock').value = '';
      document.getElementById('fSynopsis').value = '';
      document.getElementById('fMature').checked = false;
      setSelectedGenres([]);
      status.textContent = 'Titolo salvato in bozza — non ancora online.';
      renderDraftBar();
    };
    if(pendingCover){
      compressImageFile(pendingCover.file, 500, 0.8).then(function(compressed){
        return fileToDataUrl(compressed);
      }).then(function(dataUrl){
        draftItem.coverDataUrl = dataUrl;
        afterSave();
      }).catch(function(err){
        console.warn('Draft new-item cover preview failed:', err);
        status.textContent = '✕ ' + (err && err.message ? err.message : 'errore anteprima copertina');
      });
    } else {
      afterSave();
    }
    return;
  }

  var existing = isEdit ? getCatalog().find(function(x){ return x.id === editingItemId; }) : null;
  if(isEdit && !existing){ isEdit = false; editingItemId = null; } // la voce originale non c'è più — meglio ripartire da zero che salvare nel vuoto

  var newItem = isEdit ? {
    id: existing.id,
    character: character, title: title, issue: issue,
    date: date || existing.date || new Date().toISOString().slice(0,10),
    price: price ? Number(price) : null,
    stock: stock !== '' ? Number(stock) : null,
    collaborator_name: collabList[0] ? collabList[0].name : null,
    collaborator_url: collabList[0] ? collabList[0].url : null,
    collaborator_verified: collabList[0] ? collabList[0].verified : false,
    collaborators: collabList,
    series_key: seriesKey || null, chapter_number: chapterNumberRaw !== '' ? Number(chapterNumberRaw) : null,
    synopsis: synopsis, mature: mature, genres: genres,
    pages: existing.pages || [], pages_clean: existing.pages_clean || [],
    pages_watermarked: existing.pages_watermarked, cover_url: existing.cover_url || null,
    pdf_url: existing.pdf_url || null, created_by: existing.created_by || null,
    permanent: existing.permanent,
    synopsis_it: existing.synopsis_it || null, synopsis_es: existing.synopsis_es || null,
    synopsis_fr: existing.synopsis_fr || null, synopsis_de: existing.synopsis_de || null
  } : {
    id: 'c' + Date.now(),
    character: character, title: title, issue: issue,
    date: date || new Date().toISOString().slice(0,10),
    price: price ? Number(price) : null,
    stock: stock !== '' ? Number(stock) : null,
    collaborator_name: collabList[0] ? collabList[0].name : null,
    collaborator_url: collabList[0] ? collabList[0].url : null,
    collaborator_verified: collabList[0] ? collabList[0].verified : false,
    collaborators: collabList,
    series_key: seriesKey || null, chapter_number: chapterNumberRaw !== '' ? Number(chapterNumberRaw) : null,
    synopsis: synopsis, mature: mature, genres: genres, pages: [], cover_url: null, pdf_url: null,
    created_by: !isAdmin() ? currentUserId() : null,
    synopsis_it: null, synopsis_es: null, synopsis_fr: null, synopsis_de: null
  };
  // v226: le altre lingue del catalogo (in modifica restano quelle di prima finché non arriva la nuova traduzione)
  synopsisDbLangs().forEach(function(l){
    var k = 'synopsis_' + l;
    if(!(k in newItem)) newItem[k] = isEdit && existing ? (existing[k] || null) : null;
  });

  var btn = document.getElementById('btnAddEntry');
  btn.disabled = true;
  runTitleUploadSequence(newItem, isEdit);
}

/* Costruisce e lancia la sequenza di caricamento di un titolo (traduzione sinossi, copertina,
   PDF, pagine). Funzione a sé — non solo dentro handleAddEntry — perché così "Riprova" nella
   schermata di SmallNox può richiamarla di nuovo sugli stessi identici file, senza dover
   rifare tutto il modulo da capo. Se qualcosa fallisce a metà, ripartire la rifà tutta da capo
   (non riprende esattamente dal punto interrotto), ma sugli stessi file, non su altri a caso. */
function runTitleUploadSequence(newItem, isEdit){
  var btn = document.getElementById('btnAddEntry');
  var err = document.getElementById('adminError');
  var status = document.getElementById('pagesUploadStatus');
  btn.disabled = true;
  err.textContent = '';

  var totalBytes = (pendingCover ? pendingCover.file.size : 0) + (pendingPdf ? pendingPdf.size : 0)
    + pendingPages.reduce(function(sum, p){ return sum + p.file.size * 2; }, 0); // ogni pagina viaggia due volte: filigranata + pulita
  var sentBytes = 0;
  var showsOverlay = totalBytes > 0;
  function bumpBytes(delta){
    sentBytes += delta;
    if(showsOverlay) snoProgress((sentBytes / Math.max(totalBytes, 1)) * 100);
  }
  function setLabel(label){ if(showsOverlay) document.getElementById('snoStatus').textContent = label; }
  if(showsOverlay) snoStart(t('sno.uploadStart'), function(){ runTitleUploadSequence(newItem, isEdit); });

  var uploadSteps = Promise.resolve();

  // translate the synopsis into IT/ES/FR/DE up front — best-effort: if DeepL
  // isn't configured yet or the call fails, the title still saves fine and
  // just falls back to the English synopsis until it's translated later
  uploadSteps = uploadSteps.then(function(){
    status.textContent = t('synopsis.translating');
    return translateSynopsis(newItem.synopsis).then(function(result){
      applySynopsisTranslations(newItem, result); // v226: tutte le lingue
    }).catch(function(translateErr){
      console.warn('Synopsis translation failed, continuing without it:', translateErr);
    });
  });

  if(pendingCover){
    var coverExtMatch = /\.([a-zA-Z0-9]+)$/.exec(pendingCover.file.name || '');
    var coverExt = coverExtMatch ? coverExtMatch[1].toLowerCase() : 'jpg';
    uploadSteps = uploadSteps.then(function(){
      status.textContent = t('cover.uploading');
      setLabel(t('cover.uploading'));
      return compressImageFile(pendingCover.file, 2600, 0.92).then(function(compressed){
        return classifyFileMaturity(compressed).then(function(isMature){
          if(isMature) newItem.mature = true;
          var lastLoaded = 0;
          return uploadCatalogAsset(compressed, newItem.id + '/cover-' + Date.now() + '.' + coverExt, function(loaded){
            bumpBytes(loaded - lastLoaded); lastLoaded = loaded;
          });
        });
      });
    }).then(function(url){ newItem.cover_url = url; });
  }

  if(pendingPdf){
    uploadSteps = uploadSteps.then(function(){
      status.textContent = t('pdf.uploading');
      setLabel(t('pdf.uploading'));
      var lastLoaded = 0;
      return uploadCatalogPdf(pendingPdf, newItem.id + '/comic.pdf', function(loaded){
        bumpBytes(loaded - lastLoaded); lastLoaded = loaded;
      });
    }).then(function(path){ newItem.pdf_url = path; });
  }

  uploadSteps = uploadSteps.then(function(){
    return uploadAllPendingPages(newItem.id, function(delta, label){
      bumpBytes(delta);
      if(label != null) setLabel(label);
    });
  });

  uploadSteps.then(function(result){
    if(result.urls.length > 0){
      newItem.pages = result.urls;
      newItem.pages_clean = result.cleanPaths;
      newItem.pages_watermarked = true; // new uploads always go through the watermark step
    }
    status.textContent = '';
    var items = getCatalog();
    if(isEdit){
      var idx = items.findIndex(function(x){ return x.id === newItem.id; });
      if(idx >= 0) items[idx] = newItem;
    } else {
      items.push(newItem);
    }
    saveCatalogLocal(items);
    document.getElementById('fTitle').value = '';
    document.getElementById('fIssue').value = '';
    document.getElementById('fSeriesKey').value = '';
    document.getElementById('fChapterNumber').value = '';
    document.getElementById('fDate').value = '';
    document.getElementById('fPrice').value = '';
    document.getElementById('fStock').value = '';
    resetCollabBlocks();
    document.getElementById('fSynopsis').value = '';
    document.getElementById('fMature').checked = false;
    setSelectedGenres([]);
    clearPendingPages();
    clearPendingCover();
    clearPendingPdf();
    renderCatalog();
    renderAdminList();
    renderMyTitles();
    if(isEdit){
      var savedId = newItem.id;
      var patch = {}; for(var k in newItem){ if(k !== 'id') patch[k] = newItem[k]; }
      supabaseUpdate(savedId, patch);
      cancelEditTitle();
    } else {
      supabaseInsert(newItem);
    }
    btn.disabled = false;
    if(showsOverlay) snoFinish(true, t('sno.uploadDoneCaption'), t('sno.uploadDoneStatus'));
  }).catch(function(e){
    status.textContent = '';
    err.textContent = t('pages.uploadError');
    console.warn('Asset upload failed:', e);
    btn.disabled = false;
    if(showsOverlay) snoFinish(false, t('sno.errorCaption'), t('sno.uploadFailStatus'));
  });
}

function handleExport(){
  var data = JSON.stringify(getCatalog(), null, 2);
  var blob = new Blob([data], {type:'application/json'});
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = 'lux-comics-catalog.json';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
function handleImport(file){
  var reader = new FileReader();
  reader.onload = function(e){
    try{
      var data = JSON.parse(e.target.result);
      if(Array.isArray(data)){
        // merge into local cache (existing ids updated, new ids added)
        var current = getCatalog();
        var byId = {};
        current.forEach(function(i){ byId[i.id] = i; });
        data.forEach(function(i){ byId[i.id] = i; });
        var merged = Object.keys(byId).map(function(k){ return byId[k]; });
        saveCatalogLocal(merged);
        renderCatalog();
        renderAdminList();
        supabaseBulkUpsert(data); // note: import adds/updates but doesn't delete titles missing from the file
      }
    }catch(err){
      alert('JSON non valido / Invalid JSON');
    }
  };
  reader.readAsText(file);
}

/* ============ FAVORITES ============ */
var favoriteIds = new Set();
var readingProgressMap = {}; // catalog_id -> last_page (0-based), solo titoli iniziati e non finiti
// Diventa true quando il catalogo fresco è arrivato da Supabase. Prima di
// allora preferiti e progressi di lettura NON ridisegnano niente: vengono
// solo ricordati, e il primo disegno del catalogo li usa già. Prima ognuno
// dei due ridisegnava tutta la home per conto suo — a volte con la copia
// vecchia salvata sul telefono, prima ancora che arrivasse quella nuova —
// così la home veniva ricostruita fino a tre volte di fila all'apertura.
var catalogFreshLoaded = false;
function renderCatalogIfReady(){ if(catalogFreshLoaded) renderCatalog(); }
var luxCatalogLoad = null;
function luxHomeReveal(promises){
  var done = false;
  var finish = function(){
    if(done) return;
    done = true;
    requestAnimationFrame(function(){
      document.body.classList.remove('home-loading');
      document.body.classList.add('home-ready');
      var sk = document.getElementById('homeSkeleton');
      if(sk && sk.parentNode) sk.parentNode.removeChild(sk);
    });
  };
  Promise.all(promises.map(function(p){ return Promise.resolve(p).catch(function(){}); }))
    .then(function(){ setTimeout(finish, 40); });
  setTimeout(finish, 2600); // mai più di così: se un dato tarda, la pagina si mostra lo stesso
}

/* ============ APP SU TELEFONO: foglio "Tu" e contatori della barra in basso ============
   La barra e il foglio sono in chrome-footer.html; qui solo il comportamento.
   Il foglio non rifà nessuna logica: ogni voce "preme" il comando vero che sta
   nell'intestazione (nascosta su telefono), così tema, 18+, lingua, solo testo,
   accesso e carrello continuano a funzionare esattamente come prima. */
// v214: la bolla di SmallNox si fa da parte mentre scorri e torna quando ti fermi,
// così non copre prezzi, pulsanti e testi mentre leggi
function initSmallnoxAutoHide(){
  var el = document.getElementById('smallnoxFloat');
  if(!el || el.dataset.autohide) return;
  el.dataset.autohide = '1';
  var timer = null;
  window.addEventListener('scroll', function(){
    el.classList.add('sn-away');
    clearTimeout(timer);
    timer = setTimeout(function(){ el.classList.remove('sn-away'); }, 900);
  }, { passive: true });
}
// loader.js mostra il riquadro rosso degli errori solo se qui risulta l'admin
function syncAdminErrorFlag(){
  try {
    if(isAdmin()) localStorage.setItem('lux_is_admin', '1');
    else localStorage.removeItem('lux_is_admin');
  } catch(e){}
}
function initAppShell(){
  var sheet = document.getElementById('appTuSheet');
  var backdrop = document.getElementById('appTuBackdrop');
  var tuTab = document.getElementById('appTabTu');
  if(!sheet || !backdrop || !tuTab) return;
  if(sheet.dataset.ready) return;
  sheet.dataset.ready = '1';
  var byId = function(id){ return document.getElementById(id); };
  var press = function(id){ var el = byId(id); if(el) el.click(); };

  function setSwitch(id, on){ var sw = byId(id); if(sw) sw.setAttribute('aria-checked', on ? 'true' : 'false'); }
  function sync(){
    var signed = isSignedIn();
    var chip = byId('acctChip');
    var who = byId('appTuWho');
    if(who) who.innerHTML = (signed && chip) ? chip.innerHTML : '';
    if(byId('appTuGuest')) byId('appTuGuest').hidden = signed;
    if(byId('appTuLogin')) byId('appTuLogin').hidden = signed;
    if(byId('appTuProfile')) byId('appTuProfile').hidden = !signed;
    if(byId('appTuLogout')) byId('appTuLogout').hidden = !signed;
    var navAdmin = byId('navAdmin');
    if(byId('appTuAdmin')) byId('appTuAdmin').hidden = !navAdmin || navAdmin.classList.contains('hidden');
    var push = byId('btnEnablePush'), pushRow = byId('appTuPush');
    if(pushRow){
      pushRow.hidden = !push || push.classList.contains('hidden');
      // v221: la voce dice com'è davvero: attive (con «Prova»), da attivare, errore
      var pst = !push ? 'off' : push.classList.contains('push-btn-active') ? 'on' : push.classList.contains('push-btn-error') ? 'error' : 'off';
      pushRow.classList.toggle('is-on', pst === 'on');
      pushRow.classList.toggle('is-error', pst === 'error');
      var pl = byId('appTuPushLabel'), pv = byId('appTuPushState'), ph = byId('appTuPushHint');
      if(pl) pl.textContent = pst === 'on' ? t('push.enabled') : pst === 'error' ? t('push.errorShort')
        : (pushUnavailableReason() === 'ios-not-installed' ? t('push.installFirst') : t('apptu.push'));
      if(pv && pv.textContent !== t('push.testSent')) pv.textContent = pst === 'on' ? t('push.test') : '';
      if(ph) ph.hidden = pst !== 'on' || pushRow.hidden;
    }
    var count = (typeof cart !== 'undefined' && cart && cart.length) ? String(cart.length) : '';
    if(byId('appTuCartCount')) byId('appTuCartCount').textContent = count;
    setSwitch('appTuTheme', !document.body.classList.contains('theme-light'));
    var ms = byId('matureSwitch');
    setSwitch('appTuMature', !!(ms && ms.checked));
    setSwitch('appTuTextOnly', document.body.classList.contains('text-only-mode'));
    var src = byId('langSelect'), dst = byId('appTuLang');
    if(src && dst){
      if(dst.options.length !== src.options.length){
        dst.innerHTML = '';
        Array.prototype.forEach.call(src.options, function(o){ dst.appendChild(new Option(o.textContent, o.value)); });
      }
      dst.value = src.value;
    }
    if(byId('appTuClose')) byId('appTuClose').setAttribute('aria-label', t('apptu.close'));
    if(byId('appTuInstall')) byId('appTuInstall').hidden = !a2hsCanInstall();
  }
  function open(){
    sync();
    var vv = byId('appTuVersion');
    if(vv) vv.textContent = 'v' + (window.LUX_VERSION || '');
    sheet.classList.add('open');
    backdrop.classList.add('open');
    tuTab.setAttribute('aria-expanded', 'true');
    setTimeout(function(){ var c = byId('appTuClose'); if(c) c.focus(); }, 60);
  }
  function close(){
    if(!sheet.classList.contains('open')) return;
    sheet.classList.remove('open');
    backdrop.classList.remove('open');
    tuTab.setAttribute('aria-expanded', 'false');
    tuTab.focus();
  }
  tuTab.addEventListener('click', function(){ if(sheet.classList.contains('open')) close(); else open(); });
  backdrop.addEventListener('click', close);
  if(byId('appTuClose')) byId('appTuClose').addEventListener('click', close);
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape' && sheet.classList.contains('open')) close(); });

  if(byId('appTuLogin')) byId('appTuLogin').addEventListener('click', function(){ close(); press('btnLoginTop'); });
  if(byId('appTuLogout')) byId('appTuLogout').addEventListener('click', function(){ close(); press('btnLogoutTop'); });
  if(byId('appTuProfile')) byId('appTuProfile').addEventListener('click', function(){ close(); goToOwnProfile(); });
  if(byId('appTuCart')) byId('appTuCart').addEventListener('click', function(){ close(); openCartModal(); });
  if(byId('appTuPush')) byId('appTuPush').addEventListener('click', function(){ press('btnEnablePush'); setTimeout(sync, 400); });
  if(byId('appTuUpdate')) byId('appTuUpdate').addEventListener('click', function(){ window.location.reload(); });
  if(byId('appTuInstall')) byId('appTuInstall').addEventListener('click', function(){ close(); openInstallGuide(); });
  if(byId('appTuTheme')) byId('appTuTheme').addEventListener('click', function(){ press('btnTheme'); sync(); });
  if(byId('appTuTextOnly')) byId('appTuTextOnly').addEventListener('click', function(){ press('btnTextOnly'); sync(); });
  if(byId('appTuMature')) byId('appTuMature').addEventListener('click', function(){
    // stesso percorso dell'interruttore in alto: conferma dell'età compresa
    close();
    press('matureSwitch');
  });
  var ms = byId('matureSwitch');
  if(ms) ms.addEventListener('change', function(){ setTimeout(sync, 0); });
  if(byId('appTuLang')) byId('appTuLang').addEventListener('change', function(e){
    var src = byId('langSelect');
    if(!src) return;
    src.value = e.target.value;
    src.dispatchEvent(new Event('change', { bubbles: true }));
    setTimeout(sync, 0);
  });
  // v220: da computer, in fondo alla navigazione: tema, 18+ e lingua a un clic
  function syncSide(){
    var sw = byId('matureSwitch'), m = byId('appSideMature');
    if(m) m.setAttribute('aria-pressed', sw && sw.checked ? 'true' : 'false');
    var src = byId('langSelect'), dst = byId('appSideLang'), code = byId('appSideLangCode');
    if(src && dst){
      if(dst.options.length !== src.options.length){
        dst.innerHTML = '';
        Array.prototype.forEach.call(src.options, function(o){ dst.appendChild(new Option(o.textContent, o.value)); });
      }
      dst.value = src.value;
      if(code) code.textContent = String(src.value || '').toUpperCase();
    }
  }
  if(byId('appSideTheme')) byId('appSideTheme').addEventListener('click', function(){ press('btnTheme'); });
  if(byId('appSideMature')) byId('appSideMature').addEventListener('click', function(){ press('matureSwitch'); setTimeout(syncSide, 0); });
  if(byId('appSideLang')) byId('appSideLang').addEventListener('change', function(e){
    var src = byId('langSelect');
    if(!src) return;
    src.value = e.target.value;
    src.dispatchEvent(new Event('change', { bubbles: true }));
    setTimeout(syncSide, 0);
  });
  if(ms) ms.addEventListener('change', function(){ setTimeout(syncSide, 0); });
  if(byId('langSelect')) byId('langSelect').addEventListener('change', function(){ setTimeout(syncSide, 0); });
  syncSide();

  // contatori della barra: copiano quelli dell'intestazione, aggiornati dalle funzioni di sempre
  function mirror(srcId, apply){
    var src = byId(srcId);
    if(!src || !window.MutationObserver) return;
    var run = function(){ apply(src); };
    run();
    new MutationObserver(run).observe(src, { attributes: true, childList: true, characterData: true, subtree: true });
  }
  mirror('chatHeaderBadge', function(src){
    var b = byId('appTabMsgBadge');
    if(!b) return;
    var n = (src.textContent || '').trim();
    b.textContent = n;
    b.classList.toggle('hidden', src.classList.contains('hidden') || !n || n === '0');
  });
  mirror('navCommunityDot', function(src){
    var d = byId('appTabCommunityDot');
    if(d) d.classList.toggle('hidden', src.classList.contains('hidden'));
  });
  // v216: sugli schermi grandi la navigazione a sinistra ha anche Notifiche e
  // Carrello. Aprono gli stessi pannelli dell'intestazione e ne copiano i contatori.
  var wideNotif = byId('appTabNotif'), wideCart = byId('appTabCart');
  if(wideNotif){
    wideNotif.addEventListener('click', function(e){
      e.stopPropagation(); // altrimenti il clic "fuori dal pannello" lo richiuderebbe subito
      press('btnNotifications');
    });
    mirror('btnNotifications', function(src){ wideNotif.hidden = src.classList.contains('hidden'); });
    mirror('notifBadge', function(src){
      var b = byId('appTabNotifBadge');
      if(!b) return;
      var n = (src.textContent || '').trim();
      b.textContent = n;
      b.classList.toggle('hidden', src.classList.contains('hidden') || !n || n === '0');
    });
    mirror('notifPanel', function(src){ wideNotif.setAttribute('aria-expanded', src.classList.contains('hidden') ? 'false' : 'true'); });
  }
  // v217: in fondo alla navigazione il tuo account (immagine e nome, come
  // nell'intestazione) e "Condividi l'app", al posto del pulsante rosso volante
  var wideWho = byId('appTabWho');
  if(wideWho){
    mirror('acctChip', function(src){
      wideWho.innerHTML = (isSignedIn() && !src.classList.contains('hidden')) ? src.innerHTML : '';
    });
  }
  var wideShare = byId('appTabShare');
  if(wideShare) wideShare.addEventListener('click', function(){ shareApp(); });
  if(wideCart){
    wideCart.addEventListener('click', function(){ press('btnCart'); });
    mirror('cartCount', function(src){
      var b = byId('appTabCartBadge');
      if(!b) return;
      var n = (src.textContent || '').trim();
      b.textContent = n;
      b.classList.toggle('hidden', src.classList.contains('hidden') || !n || n === '0');
    });
  }
  mirror('acctChip', function(){ if(sheet.classList.contains('open')) sync(); });
  // anche nel menu da computer, in fondo
  var menu = byId('mainNavDropdown');
  if(menu && !byId('menuVersionLine')){
    var line = document.createElement('div');
    line.id = 'menuVersionLine';
    line.className = 'menu-version-line';
    line.textContent = t('apptu.version') + ' v' + (window.LUX_VERSION || '');
    menu.appendChild(line);
  }
}

/* ============ HOME DA COMPUTER: IL TACCUINO A DESTRA (v220) ============
   Sugli schermi larghi (da 1560px) la home ha una terza colonna: chi è
   online e le visualizzazioni del sito, l'ultima canzone su Luxtify (si
   ascolta da qui, col lettore di sempre), gli ultimi messaggi dei canali
   pubblici e i quattro custodi. Su telefono e iPad non compare e non scarica
   niente; su 2G nemmeno da computer. */
var homeRailMq = null;
function setupHomeRail(){
  if(!sideRailPage() || !window.matchMedia || !SUPABASE_URL) return; // v223: anche nelle altre pagine
  if(window.LUX_NET === 'slow') return;
  if(!homeRailMq){
    homeRailMq = window.matchMedia('(min-width: 1560px)');
    var onChange = function(){ if(homeRailMq.matches) buildHomeRail(); };
    if(homeRailMq.addEventListener) homeRailMq.addEventListener('change', onChange);
    else if(homeRailMq.addListener) homeRailMq.addListener(onChange);
  }
  if(homeRailMq.matches) buildHomeRail();
}
// cambio lingua: il Taccuino si rifà nella lingua nuova
function refreshHomeRailLang(){
  var old = document.getElementById('homeRail');
  if(!old) return;
  old.parentNode.removeChild(old);
  buildHomeRail();
}
// v221: se chi guarda entra o esce, il Taccuino si rifà ("Online ora" e la
// Community si vedono solo dopo l'accesso)
function homeRailAuthCheck(){
  var rail = document.getElementById('homeRail');
  if(!rail) return;
  if(rail.getAttribute('data-signed') === (isSignedIn() ? '1' : '0')) return;
  refreshHomeRailLang();
}
function homeRailName(p){
  return (p && p.display_name) || (t('notif.someone') + ' ' + String((p && p.id) || '').slice(0, 6));
}
// testo semplice per l'anteprima di un messaggio: niente formattazione, spoiler coperti
function homeRailPlain(body){
  return String(body || '')
    .replace(/```[\s\S]*?```/g, ' … ')
    .replace(/\|\|[^|\n]+\|\|/g, '•••')
    .replace(/`([^`\n]+)`/g, '$1')
    .replace(/\*\*([^*\n]+)\*\*/g, '$1').replace(/\*([^*\n]+)\*/g, '$1').replace(/~~([^~\n]+)~~/g, '$1')
    .replace(/(^|\n)>\s?/g, '$1')
    .replace(/[^\s@<>()"']+@[^\s@<>()"']+\.[a-z]{2,}/gi, '•••') // v221: niente indirizzi email in home
    .replace(/\s+/g, ' ').trim();
}
function homeRailCard(key, eyebrow, title, inner, link){
  return '<section class="home-rail-card" data-rail="' + key + '"' + (key === 'seals' ? '' : ' hidden') + '>' +
    '<div class="home-rail-head"><div class="home-rail-eyebrow">' + escapeHtml(eyebrow) + '</div><h3>' + escapeHtml(title) + '</h3></div>' +
    inner + (link || '') + '</section>';
}
function buildHomeRail(){
  if(document.getElementById('homeRail')) return;
  var arrow = ' <span aria-hidden="true">→</span>';
  var spines = Object.keys(LUX_CHAR_SPINES).filter(function(id){ var c = charById(id); return !c || c.visible !== false; }).map(function(id){
    var name = charDisplayName(id);
    return '<a class="lux-spine lux-spine-' + id.toLowerCase() + '" href="schedario.html?character=' + encodeURIComponent(id) + '#library" aria-label="' +
      escapeHtml(t('rail.collection').replace('{name}', name)) + '"><em>' + escapeHtml(name) + '</em></a>';
  }).join('');
  var rail = document.createElement('aside');
  rail.id = 'homeRail';
  rail.className = 'home-rail';
  rail.setAttribute('aria-label', t('rail.label'));
  rail.setAttribute('data-signed', isSignedIn() ? '1' : '0');
  rail.innerHTML =
    homeRailCard('now', t('rail.now'), t('rail.online'), '<div class="home-rail-online"></div><p class="home-rail-note"></p><div class="home-rail-stats"></div>',
      '<a class="home-rail-link" href="community.html#communitySection">' + escapeHtml(t('rail.toCommunity')) + arrow + '</a>') +
    homeRailCard('song', t('rail.onLuxtify'), t('rail.latestSong'), '<div class="home-rail-song"></div>') +
    homeRailCard('posts', t('rail.fromCommunity'), t('rail.latestMsgs'), '<div class="home-rail-posts"></div>',
      '<a class="home-rail-link" href="community.html#communitySection">' + escapeHtml(t('rail.openCommunity')) + arrow + '</a>') +
    (spines ? homeRailCard('seals', t('rail.seals'), t('rail.keepers'), '<div class="home-rail-spines">' + spines + '</div>') : '');
  document.body.appendChild(rail);
  document.body.classList.add('has-home-rail');
  fillHomeRailNow(rail);
  fillHomeRailSong(rail);
  fillHomeRailPosts(rail);
}
function fillHomeRailNow(rail){
  var card = rail.querySelector('[data-rail="now"]');
  var me = currentUserId();
  // chi è online lo vede solo chi ha fatto l'accesso, come nel resto del sito
  var people = isSignedIn()
    ? fetch(SUPABASE_URL + '/rest/v1/profiles?select=id,display_name,avatar_url,last_seen&order=last_seen.desc.nullslast&limit=40', { headers: communityHeaders() })
        .then(function(r){ return r.ok ? r.json() : []; }).catch(function(){ return []; })
    : Promise.resolve([]);
  var totals = fetch(SUPABASE_URL + '/rest/v1/rpc/site_view_totals', {
    method:'POST', headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + SUPABASE_ANON_KEY, 'Content-Type':'application/json' }, body:'{}'
  }).then(function(r){ return r.ok ? r.json() : null; }).catch(function(){ return null; });
  Promise.all([people, totals]).then(function(res){
    if(!card || !card.isConnected) return;
    var on = (Array.isArray(res[0]) ? res[0] : []).filter(function(p){ return p && p.id !== me && isOnlineSince(p.last_seen); });
    var tot = res[1] && typeof res[1] === 'object' && res[1].views != null ? res[1] : null;
    var avBox = card.querySelector('.home-rail-online'), note = card.querySelector('.home-rail-note'), stats = card.querySelector('.home-rail-stats');
    if(on.length){
      avBox.innerHTML = on.slice(0, 5).map(function(p){
        var name = homeRailName(p);
        return '<a class="home-rail-av" href="profile.html?user=' + encodeURIComponent(p.id) + '" title="' + escapeHtml(name) + '">' +
          '<img src="' + escapeHtml(avatarSrc(p.avatar_url, p.display_name, p.id, 80)) + '" alt="' + escapeHtml(name) + '" loading="lazy"><i aria-hidden="true"></i></a>';
      }).join('') + (on.length > 5 ? '<span class="home-rail-more">+' + (on.length - 5) + '</span>' : '');
      var a = homeRailName(on[0]), b = on[1] ? homeRailName(on[1]) : '';
      note.textContent = on.length === 1 ? t('rail.onlineOne').replace('{a}', a)
        : on.length === 2 ? t('rail.onlineTwo').replace('{a}', a).replace('{b}', b)
        : t('rail.onlineMany').replace('{a}', a).replace('{b}', b).replace('{n}', on.length - 2);
    } else {
      avBox.parentNode.removeChild(avBox);
      note.parentNode.removeChild(note);
      card.querySelector('h3').textContent = t('rail.viewsTitle');
    }
    if(tot){
      var fmt = function(n){ return Number(n || 0).toLocaleString(luxLocale()); };
      stats.innerHTML = '<div class="home-rail-stat"><b>' + fmt(tot.views) + '</b><span>' + escapeHtml(t('rail.views')) + '</span></div>' +
        '<div class="home-rail-stat"><b>' + fmt(tot.today_views) + '</b><span>' + escapeHtml(t('rail.today')) + '</span></div>';
    } else {
      stats.parentNode.removeChild(stats);
    }
    if(on.length || tot) card.hidden = false;
  });
}
function fillHomeRailSong(rail){
  var card = rail.querySelector('[data-rail="song"]');
  fetch(SUPABASE_URL + '/rest/v1/songs?select=*,catalog(title,cover_url,mature,character)&order=created_at.desc&limit=12', { headers:{ 'apikey':SUPABASE_ANON_KEY } })
    .then(function(r){ return r.ok ? r.json() : []; }).catch(function(){ return []; })
    .then(function(rows){
      if(!card || !card.isConnected || !Array.isArray(rows)) return;
      // l'ultima canzone che si può ascoltare: con il 18+ spento le esplicite si saltano
      var s = rows.filter(function(x){ return x && x.audio_url && !songIsLocked(x); })[0];
      if(!s) return;
      var cover = lxSongCover(s);
      card.querySelector('.home-rail-song').innerHTML =
        (cover ? '<img src="' + escapeHtml(coverThumbUrl(cover, 160)) + '" data-fallback="' + escapeHtml(cover) + '" alt="" loading="lazy">' : '') +
        '<div class="home-rail-song-t"><b>' + escapeHtml(s.title || '') + '</b><span>' + escapeHtml(s.artist || 'Luxtify') + '</span></div>' +
        '<button type="button" class="home-rail-play" aria-label="' + escapeHtml(t('rail.listen') + ': ' + (s.title || '')) + '">' +
        '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.5v13l11-6.5z"/></svg></button>';
      card.querySelector('.home-rail-play').addEventListener('click', function(){ openMusicPlayer([s], t('rail.latestSong')); });
      card.hidden = false;
    });
}
function fillHomeRailPosts(rail){
  var card = rail.querySelector('[data-rail="posts"]');
  // v221: la Community si legge solo dopo l'accesso, come nella sua pagina
  if(!isSignedIn()) return;
  // solo i canali pubblici (non quelli dei server), e niente messaggi nascosti dalla moderazione
  fetch(SUPABASE_URL + '/rest/v1/channels?community_id=is.null&select=id,name', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(chans){
      // v221: un canale che ha per nome un indirizzo email non compare mai in home
      chans = (Array.isArray(chans) ? chans : []).filter(function(c){ return c && c.id && String(c.name || '').indexOf('@') === -1; });
      if(!chans.length) return [];
      var names = {};
      chans.forEach(function(c){ names[c.id] = c.name; });
      return fetch(SUPABASE_URL + '/rest/v1/channel_messages?channel_id=in.(' + chans.map(function(c){ return encodeURIComponent(c.id); }).join(',') +
          ')&hidden=not.is.true&select=id,channel_id,user_id,author_name,body,created_at&order=created_at.desc&limit=3', { headers: communityHeaders() })
        .then(function(r){ return r.ok ? r.json() : []; })
        .then(function(msgs){ return (Array.isArray(msgs) ? msgs : []).map(function(m){ m._ch = names[m.channel_id] || ''; return m; }); });
    })
    .catch(function(){ return []; })
    .then(function(msgs){
      if(!card || !card.isConnected || !msgs.length) return;
      var ids = msgs.map(function(m){ return m.user_id; }).filter(function(id, i, all){ return id && all.indexOf(id) === i; });
      var avatars = ids.length
        ? fetch(SUPABASE_URL + '/rest/v1/profiles?id=in.(' + ids.map(encodeURIComponent).join(',') + ')&select=id,avatar_url', { headers: communityHeaders() })
            .then(function(r){ return r.ok ? r.json() : []; }).catch(function(){ return []; })
        : Promise.resolve([]);
      return avatars.then(function(ps){
        var av = {};
        (Array.isArray(ps) ? ps : []).forEach(function(p){ av[p.id] = p.avatar_url; });
        card.querySelector('.home-rail-posts').innerHTML = msgs.map(function(m){
          var name = m.author_name || t('notif.someone');
          var raw = String(m.body || '').trim();
          var text = !raw ? '<i>' + escapeHtml(t('rail.attach')) + '</i>' : isGifUrl(raw) ? '<i>' + escapeHtml(t('rail.gif')) + '</i>' : escapeHtml(homeRailPlain(raw));
          return '<a class="home-rail-post" href="community.html#communitySection">' +
            '<span class="home-rail-av"><img src="' + escapeHtml(avatarSrc(av[m.user_id], name, m.user_id, 64)) + '" alt="" loading="lazy"></span>' +
            '<div class="home-rail-post-b"><div class="home-rail-post-h"><b>' + escapeHtml(name) + '</b><span>' +
            (m._ch ? '#' + escapeHtml(m._ch) + ' · ' : '') + escapeHtml(notifTimeAgo(m.created_at)) + '</span></div><p>' + text + '</p></div></a>';
        }).join('');
        card.hidden = false;
      });
    });
}

/* ============ v223: SPAZI DA COMPUTER, SCHEDA DEL CONTATTO, CONDIVIDI ============ */
// Le scelte A della v222. Si accendono con tre classi sul body che mette loader.js
// (lux-wide, lux-chat3, lux-share-a): senza le classi il sito resta com'era.

// ---- impaginazione da computer (lux-wide, vedi style.css) ----
function luxLayoutMode(){ return document.body.classList.contains('lux-wide') ? 'wide' : ''; }
// il Taccuino a destra: in home sempre; nelle altre pagine quando lo schermo si riempie
function sideRailPage(){
  if(document.getElementById('testo')) return true;
  if(!luxLayoutMode() || !document.body.classList.contains('has-app-tabbar')) return false;
  if(document.getElementById('chatSection') || document.getElementById('adminSection') || document.getElementById('luxtifySection')) return false;
  return true;
}
// cambiando impaginazione il Taccuino compare o sparisce (serve all'anteprima)
function luxLayoutChanged(){
  if(sideRailPage()){ setupHomeRail(); return; }
  var old = document.getElementById('homeRail');
  if(old && old.parentNode) old.parentNode.removeChild(old);
  document.body.classList.remove('has-home-rail');
}

// ---- Messaggi da computer: la scheda del contatto ----
var chatInfoPhotoList = [];
var chatInfoMq = null, chatInfoPending = null;
function chatInfoMode(){ return document.body.classList.contains('lux-chat3') ? 3 : 0; }
// la scheda c'è solo da computer (da 1320 px): su telefono e tablet non si scarica niente
function chatInfoWide(){ return !!(window.matchMedia && window.matchMedia('(min-width: 1320px)').matches); }
function chatInfoEl(){
  var box = document.getElementById('chatBox');
  if(!box) return null;
  var el = document.getElementById('chatInfo');
  if(!el){
    el = document.createElement('aside');
    el.id = 'chatInfo';
    el.className = 'chat-info';
    el.setAttribute('aria-label', t('chatInfo.label'));
    box.appendChild(el);
  }
  return el;
}
function ensureChatInfoButton(){
  var head = document.querySelector('#chatBox .chat-page-header');
  if(!head || document.getElementById('btnChatInfo')) return;
  var b = document.createElement('button');
  b.type = 'button';
  b.id = 'btnChatInfo';
  b.className = 'chat-icon-btn chat-header-action chat-info-btn';
  b.setAttribute('aria-label', t('chatInfo.label'));
  b.setAttribute('aria-expanded', 'false');
  b.title = t('chatInfo.label');
  b.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v5.5M12 7.6h.01"/></svg>';
  b.addEventListener('click', function(){ toggleChatInfo(); });
  head.appendChild(b);
  // anche il nome in alto apre la scheda
  var info = head.querySelector('.chat-header-info');
  if(info){
    info.classList.add('chat-header-info-btn');
    info.addEventListener('click', function(){ if(chatInfoMode()) toggleChatInfo(true); });
  }
}
function toggleChatInfo(force){
  var el = chatInfoEl();
  if(!el) return;
  var open = typeof force === 'boolean' ? force : !el.classList.contains('open');
  el.classList.toggle('open', open);
  var b = document.getElementById('btnChatInfo');
  if(b) b.setAttribute('aria-expanded', open ? 'true' : 'false');
}
function chatInfoPhotosHtml(){
  if(!chatInfoPhotoList.length) return '<p class="chat-info-note">' + escapeHtml(t('chatInfo.noPhotos')) + '</p>';
  return '<div class="chat-info-photos">' + chatInfoPhotoList.slice(-9).reverse().map(function(u){
    return '<button type="button" data-photo="' + escapeHtml(u) + '"><img src="' + escapeHtml(coverThumbUrl(u, 200)) + '" alt="" loading="lazy"></button>';
  }).join('') + '</div>';
}
function wireChatInfoPhotos(root){
  Array.prototype.forEach.call(root.querySelectorAll('[data-photo]'), function(b){
    b.addEventListener('click', function(){ openImageLightbox(b.getAttribute('data-photo')); });
  });
}
// le foto della conversazione aperta (chiamata da loadChatMessages)
function updateChatInfoPhotos(rows){
  chatInfoPhotoList = (rows || []).filter(function(m){ return m && m.attachment_url && m.attachment_type === 'image'; }).map(function(m){ return m.attachment_url; });
  var sec = document.getElementById('chatInfoPhotos');
  if(!sec) return;
  sec.querySelector('h4 span').textContent = '(' + chatInfoPhotoList.length + ')';
  var body = sec.querySelector('.chat-info-photos-body');
  body.innerHTML = chatInfoPhotosHtml();
  wireChatInfoPhotos(body);
}
function renderChatInfo(otherUserId){
  if(!chatInfoMode() || !otherUserId) return;
  if(!chatInfoWide()){
    // schermo stretto: la scheda si prepara solo se la finestra si allarga
    chatInfoPending = otherUserId;
    if(!chatInfoMq && window.matchMedia){
      chatInfoMq = window.matchMedia('(min-width: 1320px)');
      var onWide = function(){ if(chatInfoMq.matches && chatInfoPending){ var id = chatInfoPending; chatInfoPending = null; renderChatInfo(id); } };
      if(chatInfoMq.addEventListener) chatInfoMq.addEventListener('change', onWide);
      else if(chatInfoMq.addListener) chatInfoMq.addListener(onWide);
    }
    return;
  }
  chatInfoPending = null;
  ensureChatInfoButton();
  var el = chatInfoEl();
  if(!el) return;
  el.setAttribute('data-user', otherUserId);
  el.innerHTML = '<p class="chat-info-loading">…</p>';
  var enc = encodeURIComponent(otherUserId);
  var hdr = { headers: communityHeaders() };
  var asList = function(r){ return r.ok ? r.json() : []; };
  var profile = fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + enc + '&select=*', hdr).then(asList).then(function(rows){ return rows[0] || null; }).catch(function(){ return null; });
  var friends = fetch(SUPABASE_URL + '/rest/v1/friendships?select=id&status=eq.accepted&or=(requester_id.eq.' + enc + ',addressee_id.eq.' + enc + ')', hdr)
    .then(asList).then(function(rows){ return rows.length; }).catch(function(){ return null; });
  var followers = loadFollowerCount(otherUserId).then(function(n){ return n; }, function(){ return null; });
  var favs = fetch(SUPABASE_URL + '/rest/v1/favorites?user_id=eq.' + enc + '&select=catalog_id', hdr).then(asList).then(function(rows){ return rows.length; }).catch(function(){ return null; });
  Promise.all([profile, friends, followers, favs]).then(function(res){
    if(el.getAttribute('data-user') !== otherUserId) return; // nel frattempo si è aperta un'altra conversazione
    var p = res[0];
    if(!p){ el.innerHTML = '<p class="chat-info-empty">' + escapeHtml(t('chatInfo.none')) + '</p>'; return; }
    var name = p.display_name || t('notif.someone');
    var online = isOnlineSince(p.last_seen);
    var status = online ? t('userDir.online') : (p.last_seen ? t('chatInfo.lastSeen').replace('{t}', notifTimeAgo(p.last_seen)) : t('userDir.offline'));
    var num = function(n, key){ return '<div class="chat-info-num"><b>' + (n == null ? '—' : Number(n).toLocaleString(luxLocale())) + '</b><span>' + escapeHtml(t(key)) + '</span></div>'; };
    var sec = function(title, inner, id){ return '<div class="chat-info-sec"' + (id ? ' id="' + id + '"' : '') + '><h4>' + title + '</h4>' + inner + '</div>'; };
    var socialDefs = [['social_instagram', 'Instagram'], ['social_twitter', 'X'], ['social_tiktok', 'TikTok'], ['social_website', t('profile.website')]];
    var socials = socialDefs.filter(function(s){ return p[s[0]]; }).map(function(s){
      var raw = String(p[s[0]]);
      var href = /^https?:\/\//i.test(raw) ? raw : ('https://' + raw.replace(/^@/, ''));
      return '<a class="chat-info-tag" href="' + escapeHtml(href) + '" target="_blank" rel="noopener">' + escapeHtml(s[1]) + '</a>';
    }).join('');
    var favChars = (p.favorite_characters || []).map(function(f){ return '<span class="chat-info-tag">' + escapeHtml(f) + '</span>'; }).join('');
    var joined = p.created_at ? new Date(p.created_at) : null;
    var hidden = p.is_private && !(friendshipCache[otherUserId] && friendshipCache[otherUserId].status === 'accepted');
    el.innerHTML =
      '<div class="chat-info-banner"><button type="button" class="chat-info-close" aria-label="' + escapeHtml(t('share.close')) + '">×</button></div>' +
      '<div class="chat-info-id"><span class="chat-info-av"><img src="' + escapeHtml(avatarSrc(p.avatar_url, name, otherUserId, 192)) + '" alt=""><i class="' + (online ? 'on' : '') + '"></i></span>' +
        '<div class="chat-info-name">' + escapeHtml(name) + ' ' + verifiedBadge('verified.commenter', !!p.verified) + roleBadgeHtml(p.role) + '</div>' +
        '<div class="chat-info-status">' + escapeHtml(status) + '</div></div>' +
      '<div class="chat-info-actions"><a class="btn btn-ghost btn-sm" href="profile.html?user=' + enc + '">' + escapeHtml(t('chatInfo.profile')) + '</a>' +
        '<button type="button" class="btn btn-ghost btn-sm" data-ci="bg">' + escapeHtml(t('chatInfo.background')) + '</button></div>' +
      (hidden ? sec(escapeHtml(t('chatInfo.privateTitle')), '<p class="chat-info-note">' + escapeHtml(t('chatInfo.private')) + '</p>') :
        (p.bio ? sec(escapeHtml(t('chatInfo.bio')), '<p class="chat-info-bio">' + escapeHtml(p.bio) + '</p>') : '') +
        sec(escapeHtml(t('chatInfo.numbers')), '<div class="chat-info-nums">' + num(res[1], 'chatInfo.friends') + num(res[2], 'chatInfo.followers') + num(res[3], 'chatInfo.favs') + '</div>') +
        (favChars ? sec(escapeHtml(t('chatInfo.favChars')), '<div class="chat-info-tags">' + favChars + '</div>') : '') +
        (socials ? sec('Social', '<div class="chat-info-tags">' + socials + '</div>') : '')) +
      sec(escapeHtml(t('chatInfo.photos')) + ' <span>(' + chatInfoPhotoList.length + ')</span>', '<div class="chat-info-photos-body">' + chatInfoPhotosHtml() + '</div>', 'chatInfoPhotos') +
      (joined && !isNaN(joined) ? '<p class="chat-info-joined">' + escapeHtml(t('pubProfile.memberSince').replace('{date}', joined.toLocaleDateString(luxLocale(), { day: 'numeric', month: 'long', year: 'numeric' }))) + '</p>' : '');
    if(p.banner_url) el.querySelector('.chat-info-banner').style.backgroundImage = 'url("' + String(p.banner_url).replace(/["\\\n\r]/g, '') + '")';
    el.querySelector('.chat-info-close').addEventListener('click', function(){ toggleChatInfo(false); });
    el.querySelector('.chat-info-av img').addEventListener('click', function(){ openAvatarInfo(otherUserId); });
    el.querySelector('[data-ci="bg"]').addEventListener('click', function(){ var b = document.getElementById('btnChatBg'); if(b) b.click(); });
    wireChatInfoPhotos(el);
  });
}

// ---- Condividi: le app, con il link della pagina d'anteprima (copertina e titolo) ----
function luxShareMode(){ return document.body.classList.contains('lux-share-a') ? 'a' : ''; }
var LUX_SHARE_IC = {
  whatsapp: '<path d="M20 11.4a8.2 8.2 0 0 1-12.1 7.2L4 19.8l1.3-3.7A8.2 8.2 0 1 1 20 11.4z"/>',
  telegram: '<path d="M5 12h13.5M13 6.5l5.5 5.5-5.5 5.5"/>',
  instagram: '<rect x="3.5" y="7" width="17" height="12.5" rx="3"/><circle cx="12" cy="13.2" r="3.4"/><path d="M8.6 7l1.4-2.5h4L15.4 7"/>',
  facebook: '<circle cx="9" cy="8.6" r="3.1"/><path d="M3.6 19c.6-3.1 2.7-4.9 5.4-4.9s4.8 1.8 5.4 4.9"/><circle cx="16.6" cy="9.6" r="2.5"/><path d="M15.8 14.3c2.5-.2 4.2 1.3 4.7 4.7"/>',
  x: '<path d="M4.5 19.5l1-4.2L15.8 5a2.1 2.1 0 0 1 3 3L8.5 18.4z"/><path d="M13.8 7l3 3"/>',
  email: '<rect x="3.5" y="5.5" width="17" height="13" rx="2"/><path d="M4 7l8 6.2L20 7"/>',
  copy: '<path d="M10.2 13.8a4.2 4.2 0 0 0 6 0l2.9-2.9a4.2 4.2 0 0 0-6-6l-1.1 1.1"/><path d="M13.8 10.2a4.2 4.2 0 0 0-6 0l-2.9 2.9a4.2 4.2 0 0 0 6 6l1.1-1.1"/>',
  more: '<path d="M12 3.5v11M8 7.5l4-4 4 4"/><path d="M5.5 11.5v7a2 2 0 0 0 2 2h9a2 2 0 0 0 2-2v-7"/>',
  done: '<path d="M5 12.5l4.5 4.5L19 7.5"/>'
};
function luxShareIcon(id){ return '<svg viewBox="0 0 24 24" aria-hidden="true">' + (LUX_SHARE_IC[id] || '') + '</svg>'; }
function luxShareTargets(){
  var list = [
    { id: 'whatsapp', label: 'WhatsApp', c: '#128c4a' },
    { id: 'telegram', label: 'Telegram', c: '#1b88c2' },
    { id: 'instagram', label: 'Instagram', c: 'linear-gradient(45deg,#e8762c,#cf2872 55%,#7b3fb0)' },
    { id: 'facebook', label: 'Facebook', c: '#1764d6' },
    { id: 'x', label: 'X', c: '#16181c' },
    { id: 'email', label: t('share.email'), c: '#6e1423' },
    { id: 'copy', label: t('share.copyLink'), c: '#3b2a1f' }
  ];
  if(navigator.share) list.push({ id: 'more', label: t('share.more'), c: '#2c2024' });
  return list;
}
function luxShareHref(id, s){
  var e = encodeURIComponent;
  if(id === 'whatsapp') return 'https://wa.me/?text=' + e(s.text + ' ' + s.url);
  if(id === 'telegram') return 'https://t.me/share/url?url=' + e(s.url) + '&text=' + e(s.text);
  if(id === 'facebook') return 'https://www.facebook.com/sharer/sharer.php?u=' + e(s.url);
  if(id === 'x') return 'https://twitter.com/intent/tweet?text=' + e(s.text) + '&url=' + e(s.url);
  if(id === 'email') return 'mailto:?subject=' + e(s.title) + '&body=' + e(s.text + '\n' + s.url);
  if(id === 'instagram') return 'https://www.instagram.com/direct/inbox/';
  return '';
}
function luxShareButton(target, s){
  var href = luxShareHref(target.id, s);
  var inner = '<span class="lux-share-ic" style="--c:' + target.c + ';background:' + target.c + '">' + luxShareIcon(target.id) + '</span><span class="lux-share-lbl">' + escapeHtml(target.label) + '</span>';
  if(href) return '<a class="lux-share-btn" data-share="' + target.id + '" href="' + escapeHtml(href) + '"' + (target.id === 'email' ? '' : ' target="_blank" rel="noopener"') + '>' + inner + '</a>';
  return '<button type="button" class="lux-share-btn" data-share="' + target.id + '">' + inner + '</button>';
}
function luxCopyText(text){
  if(navigator.clipboard && navigator.clipboard.writeText) return navigator.clipboard.writeText(text);
  return new Promise(function(res, rej){
    try {
      var ta = document.createElement('textarea');
      ta.value = text; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      var ok = document.execCommand('copy');
      document.body.removeChild(ta);
      if(ok) res(); else rej(new Error('copy'));
    } catch(e){ rej(e); }
  });
}
function luxShareFlash(btn, ok){
  var lbl = btn.querySelector('.lux-share-lbl'), ic = btn.querySelector('.lux-share-ic');
  if(!lbl || !ic || btn.dataset.flash) return;
  btn.dataset.flash = '1';
  var oldL = lbl.textContent, oldI = ic.innerHTML;
  lbl.textContent = ok ? t('share.copiedShort') : t('share.copyManual');
  if(ok){ btn.classList.add('is-done'); ic.innerHTML = luxShareIcon('done'); }
  setTimeout(function(){ lbl.textContent = oldL; ic.innerHTML = oldI; btn.classList.remove('is-done'); delete btn.dataset.flash; }, 2200);
}
function luxShareNative(s, withFile){
  if(!navigator.share) return Promise.reject(new Error('no share'));
  var data = { title: s.title, text: s.text, url: s.url };
  if(!withFile || !s.cover || !navigator.canShare) return navigator.share(data);
  return fetchAsBlob(s.cover).then(function(blob){
    var file = new File([blob], 'copertina.' + ((blob.type && blob.type.split('/')[1]) || 'jpg'), { type: blob.type || 'image/jpeg' });
    if(navigator.canShare({ files: [file] })) data.files = [file];
    return navigator.share(data);
  }, function(){ return navigator.share(data); });
}
function wireShareButtons(root, s){
  Array.prototype.forEach.call(root.querySelectorAll('[data-share]'), function(btn){
    btn.addEventListener('click', function(e){
      var id = btn.getAttribute('data-share');
      if(s.onShare && !s.counted){ s.counted = true; try { s.onShare(); } catch(err){} }
      if(id === 'copy'){
        e.preventDefault();
        luxCopyText(s.text + ' ' + s.url).then(function(){ luxShareFlash(btn, true); }, function(){
          luxShareFlash(btn, false);
          var inp = document.querySelector('#luxShare .lux-share-url');
          if(inp){ inp.focus(); inp.select(); }
        });
        return;
      }
      if(id === 'more'){
        e.preventDefault();
        luxShareNative(s, true).catch(function(){});
        return;
      }
      if(id === 'instagram'){
        // Instagram non accetta link mandati da un sito: dal telefono si passa dal
        // menu di condivisione (dove compare Instagram, con la copertina); dal
        // computer si copia il link e si aprono i messaggi di Instagram
        var coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
        if(coarse && navigator.share){ e.preventDefault(); luxShareNative(s, true).catch(function(){}); return; }
        luxCopyText(s.text + ' ' + s.url).catch(function(){});
        var note = document.querySelector('#luxShare .lux-share-note');
        if(note) note.innerHTML = '<b>' + escapeHtml(t('share.igCopied')) + '</b>';
      }
    });
  });
}
function openSharePanel(s){
  var box = document.getElementById('luxShare');
  if(!box){
    box = document.createElement('div');
    box.id = 'luxShare';
    box.className = 'lux-share';
    box.hidden = true;
    box.setAttribute('role', 'dialog');
    box.setAttribute('aria-modal', 'true');
    box.setAttribute('aria-labelledby', 'luxShareTitle');
    box.addEventListener('click', function(e){ if(e.target === box) closeSharePanel(); });
    document.addEventListener('keydown', function(e){ if(e.key === 'Escape' && !box.hidden) closeSharePanel(); });
    document.body.appendChild(box);
  }
  box.innerHTML =
    '<div class="lux-share-sheet">' +
      '<div class="lux-share-head"><h3 id="luxShareTitle">' + escapeHtml(t('share.title')) + '</h3><button type="button" class="lux-share-x" aria-label="' + escapeHtml(t('share.close')) + '">×</button></div>' +
      '<div class="lux-share-card">' + (s.image ? '<img src="' + escapeHtml(s.image) + '" alt="">' : '') +
        '<div class="lux-share-card-t"><b>' + escapeHtml(s.title) + '</b><span>' + escapeHtml(s.sub || t('share.tagline')) + '</span>' +
        '<input class="lux-share-url" type="text" readonly value="' + escapeHtml(s.url) + '" aria-label="Link"></div></div>' +
      '<div class="lux-share-grid">' + luxShareTargets().map(function(tg){ return luxShareButton(tg, s); }).join('') + '</div>' +
      '<p class="lux-share-note">' + escapeHtml(t('share.note')) + '</p>' +
    '</div>';
  box.querySelector('.lux-share-x').addEventListener('click', closeSharePanel);
  wireShareButtons(box, s);
  box.hidden = false;
  var first = box.querySelector('.lux-share-btn');
  if(first) setTimeout(function(){ first.focus(); }, 30);
}
function closeSharePanel(){ var box = document.getElementById('luxShare'); if(box) box.hidden = true; }

// nella scheda del titolo le app principali sono già in vista
function renderTitleShareRow(item){
  var modal = document.getElementById('titleModal');
  var old = document.getElementById('titleShareRow');
  if(old && old.parentNode) old.parentNode.removeChild(old);
  if(luxShareMode() !== 'a' || !modal || !item) return;
  var anchor = document.getElementById('pageReader'); // subito sotto titolo e trama, prima delle tavole: si vede appena si apre la scheda
  if(!anchor || !anchor.parentNode) return;
  var s = titleShareData(item);
  var keep = { whatsapp: 1, telegram: 1, instagram: 1, facebook: 1 };
  var row = document.createElement('div');
  row.id = 'titleShareRow';
  row.className = 'lux-share-row';
  row.innerHTML = '<span class="lux-share-row-label">' + escapeHtml(t('share.rowLabel')) + '</span>' +
    luxShareTargets().filter(function(tg){ return keep[tg.id]; }).map(function(tg){ return luxShareButton(tg, s); }).join('') +
    '<button type="button" class="lux-share-btn" id="titleShareMore"><span class="lux-share-ic" style="background:#3b2a1f">' + luxShareIcon('more') + '</span>' +
    '<span class="lux-share-lbl">' + escapeHtml(t('share.others')) + '</span></button>';
  anchor.parentNode.insertBefore(row, anchor);
  wireShareButtons(row, s);
  // "Altre app" apre il pannello completo (X, email, copia link…)
  row.querySelector('#titleShareMore').addEventListener('click', function(){ openSharePanel(titleShareData(item)); });
}
function titleShareData(item){
  var collabArr = (item.collaborators && item.collaborators.length) ? item.collaborators : (item.collaborator_name ? [{ name: item.collaborator_name }] : []);
  var collabNames = collabArr.map(function(c){ return c.name; }).join(', ');
  return {
    title: item.title,
    text: item.title + ' — ' + t('share.tagline') + (collabNames ? ' ' + t('collab.credit') + ' ' + collabNames : ''),
    url: previewPagePath('t', item.id),
    image: item.cover_url ? coverThumbUrl(item.cover_url, 160) : '',
    cover: item.cover_url || '',
    onShare: function(){ trackShare(item.id); bumpLocalCount(item.id, 'share_count', 1); }
  };
}

/* ============ VISUALIZZAZIONI DEL SITO (v220) ============
   Ogni pagina aperta conta una visualizzazione; la prima pagina di ogni visita
   conta anche una visita. Non contano: le tue pagine da amministratore, la
   stessa pagina ricaricata entro mezz'ora, i programmi automatici.
   Niente di personale: nel database ci sono solo due numeri per giorno
   (vedi visualizzazioni.sql). */
function scheduleSiteViewCount(){
  setTimeout(countSiteView, window.LUX_NET === 'slow' ? 8000 : 2500); // dopo i contenuti, mai al loro posto
}
function countSiteView(){
  if(!SUPABASE_URL || isAdmin() || navigator.webdriver) return;
  var newVisit = false;
  try {
    var key = 'lux_sv:' + (window.location.pathname || '/');
    var last = +(sessionStorage.getItem(key) || 0);
    if(last && Date.now() - last < 30 * 60000) return;
    sessionStorage.setItem(key, String(Date.now()));
    if(!sessionStorage.getItem('lux_sv_visit')){ sessionStorage.setItem('lux_sv_visit', '1'); newVisit = true; }
  } catch(e){}
  fetch(SUPABASE_URL + '/rest/v1/rpc/count_site_view', {
    method:'POST', keepalive:true,
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + SUPABASE_ANON_KEY, 'Content-Type':'application/json' },
    body: JSON.stringify({ new_visit: newVisit })
  }).catch(function(){});
}

/* Amministra › Statistiche: visualizzazioni del sito, ultimi 14 giorni */
function renderSiteViewsAdmin(){
  if(!isAdmin()) return;
  var box = document.getElementById('siteViewsAdmin');
  if(!box || !SUPABASE_URL) return;
  var h = { 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + SUPABASE_ANON_KEY, 'Content-Type':'application/json' };
  Promise.all([
    fetch(SUPABASE_URL + '/rest/v1/site_views_daily?select=day,views,visits&order=day.desc&limit=30', { headers: h })
      .then(function(r){ if(!r.ok) throw new Error('site_views_daily ' + r.status); return r.json(); }),
    fetch(SUPABASE_URL + '/rest/v1/rpc/site_view_totals', { method:'POST', headers: h, body:'{}' })
      .then(function(r){ if(!r.ok) throw new Error('site_view_totals ' + r.status); return r.json(); })
  ]).then(function(res){
    var rows = Array.isArray(res[0]) ? res[0] : [], tot = res[1] || {};
    var byDay = {};
    rows.forEach(function(r){ byDay[r.day] = r; });
    // i giorni del calendario di Roma (anche col cambio dell'ora)
    var todayKey = new Intl.DateTimeFormat('en-CA', { timeZone:'Europe/Rome', year:'numeric', month:'2-digit', day:'2-digit' }).format(new Date());
    var p = todayKey.split('-').map(Number);
    var days = [];
    for(var i = 13; i >= 0; i--){
      var dt = new Date(Date.UTC(p[0], p[1] - 1, p[2] - i));
      var k = dt.toISOString().slice(0, 10), r = byDay[k] || {};
      days.push({ label: i === 0 ? 'oggi' : dt.toLocaleDateString('it-IT', { day:'numeric', month:'short', timeZone:'UTC' }),
        long: dt.toLocaleDateString('it-IT', { weekday:'long', day:'numeric', month:'long', timeZone:'UTC' }), views: +(r.views || 0), visits: +(r.visits || 0) });
    }
    var n = function(x){ return Number(x || 0).toLocaleString('it-IT'); };
    var last7 = days.slice(-7).reduce(function(s, d){ return s + d.views; }, 0);
    var last7v = days.slice(-7).reduce(function(s, d){ return s + d.visits; }, 0);
    var today = days[days.length - 1];
    var max = Math.max.apply(null, days.map(function(d){ return d.views; })) || 0;
    var maxIdx = max ? days.map(function(d){ return d.views; }).lastIndexOf(max) : -1;
    var since = tot.since ? new Date(tot.since + 'T12:00:00Z').toLocaleDateString('it-IT', { day:'numeric', month:'long', year:'numeric', timeZone:'UTC' }) : '';
    box.innerHTML =
      '<div class="sv-figs">' +
        '<div class="sv-fig"><span>Oggi</span><b>' + n(today.views) + '</b><small>' + n(today.visits) + ' visite</small></div>' +
        '<div class="sv-fig"><span>Ultimi 7 giorni</span><b>' + n(last7) + '</b><small>' + n(last7v) + ' visite</small></div>' +
        '<div class="sv-fig"><span>In totale</span><b>' + n(tot.views) + '</b><small>' + n(tot.visits) + ' visite</small></div>' +
      '</div>' +
      '<div class="sv-chart"><div class="sv-cols">' + days.map(function(d, i){
          var pct = max ? Math.round(d.views / max * 1000) / 10 : 0;
          var showVal = d.views && (i === days.length - 1 || i === maxIdx);
          return '<button type="button" class="sv-col" style="--h:' + pct + '%" data-i="' + i + '" aria-label="' + escapeHtml(d.long + ': ' + n(d.views) + ' visualizzazioni, ' + n(d.visits) + ' visite') + '">' +
            (showVal ? '<em aria-hidden="true">' + n(d.views) + '</em>' : '') +
            '<i style="height:' + pct + '%' + (d.views ? ';min-height:2px' : '') + '"></i></button>';
        }).join('') + '</div>' +
        '<div class="sv-axis" aria-hidden="true"><span>' + escapeHtml(days[0].label) + '</span><span>' + escapeHtml(days[6].label) + '</span><span>oggi</span></div>' +
        '<div class="sv-tip" hidden></div></div>' +
      '<details class="sv-more"><summary>I numeri giorno per giorno</summary><table class="sv-table"><thead><tr><th>Giorno</th><th>Visualizzazioni</th><th>Visite</th></tr></thead><tbody>' +
        days.slice().reverse().map(function(d){ return '<tr><td>' + escapeHtml(d.long) + '</td><td>' + n(d.views) + '</td><td>' + n(d.visits) + '</td></tr>'; }).join('') +
      '</tbody></table></details>' +
      '<p class="form-note">Una visualizzazione è una pagina aperta; una visita è un giro sul sito, anche di più pagine. Le tue pagine da amministratore non contano.' +
        (since ? ' Conteggio iniziato ' + (/^(8|11) /.test(since) ? 'l’' : 'il ') + escapeHtml(since) + '.' : '') + '</p>';
    var tip = box.querySelector('.sv-tip'), chart = box.querySelector('.sv-chart');
    Array.prototype.forEach.call(box.querySelectorAll('.sv-col'), function(col){
      var d = days[+col.getAttribute('data-i')];
      var show = function(){
        tip.textContent = '';
        var b = document.createElement('b'); b.textContent = n(d.views) + ' visualizzazioni';
        tip.appendChild(b);
        tip.appendChild(document.createTextNode(n(d.visits) + ' visite · ' + d.long));
        var cr = chart.getBoundingClientRect(), r2 = col.getBoundingClientRect();
        tip.hidden = false;
        var half = tip.offsetWidth / 2, x = r2.left - cr.left + r2.width / 2;
        tip.style.left = Math.max(half, Math.min(cr.width - half, x)) + 'px';
      };
      var hide = function(){ tip.hidden = true; };
      col.addEventListener('pointerenter', show);
      col.addEventListener('focus', show);
      col.addEventListener('pointerleave', hide);
      col.addEventListener('blur', hide);
    });
  }).catch(function(e){
    console.warn('Visualizzazioni del sito:', e);
    box.innerHTML = '<p class="form-note">Per contare le visualizzazioni lancia <b>visualizzazioni.sql</b> in Supabase → SQL Editor (una volta sola). Da quel momento i numeri compaiono qui.</p>';
  });
}

/* ============ INSTALLA L'APP (iPhone, iPad, Android) ============
   Su iPhone le notifiche arrivano solo se il sito è stato aggiunto alla
   schermata Home, e Apple non lascia che un sito si installi da solo: questo
   avviso spiega i due tocchi necessari. Su Android Chrome offre la sua
   finestra di installazione e basta un pulsante. Nell'app già installata
   l'avviso non compare: al suo posto, una volta, l'invito alle notifiche. */
var a2hsDeferredPrompt = null;
window.addEventListener('beforeinstallprompt', function(e){
  e.preventDefault();
  a2hsDeferredPrompt = e;
  setTimeout(function(){ maybeShowInstallBanner(); }, 1500);
});
window.addEventListener('appinstalled', function(){
  a2hsDeferredPrompt = null;
  var b = document.getElementById('a2hsBanner');
  if(b && b.parentNode) b.parentNode.removeChild(b);
});
function a2hsInAppBrowser(){
  return /FBAN|FBAV|Instagram|TikTok|BytedanceWebview|musical_ly|Line\/|Snapchat|Pinterest|LinkedInApp|Twitter/i.test(navigator.userAgent || '');
}
function a2hsSnoozed(key){ try { return Date.now() < +(localStorage.getItem(key) || 0); } catch(e){ return false; } }
function a2hsSnooze(key, days){ try { localStorage.setItem(key, String(Date.now() + days * 86400000)); } catch(e){} }
function a2hsCountVisit(){
  // una visita per sessione di navigazione, non una per ogni pagina aperta
  try {
    if(sessionStorage.getItem('lux_pv_counted')) return +(localStorage.getItem('lux_pv') || 0);
    var n = +(localStorage.getItem('lux_pv') || 0) + 1;
    localStorage.setItem('lux_pv', String(n));
    sessionStorage.setItem('lux_pv_counted', '1');
    return n;
  } catch(e){ return 1; }
}
function a2hsCanInstall(){
  if(isStandaloneApp()) return false;
  return isIOSDevice() || !!a2hsDeferredPrompt;
}
var A2HS_SHARE_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 15V3M8 7l4-4 4 4M6 11H5a1 1 0 0 0-1 1v8a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-8a1 1 0 0 0-1-1h-1"/></svg>';
var A2HS_ADD_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2zM12 8v8M8 12h8"/></svg>';
var A2HS_DOTS_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h.01M12 12h.01M19 12h.01"/></svg>';
var A2HS_BELL_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 16V11a6 6 0 0 1 12 0v5l2 2H4zM10 20a2 2 0 0 0 4 0"/></svg>';

function luxBottomCard(id, iconHtml, title, sub, goLabel, onGo, onClose){
  var old = document.getElementById(id);
  if(old && old.parentNode) old.parentNode.removeChild(old);
  var el = document.createElement('div');
  el.id = id;
  el.className = 'lux-bottom-card';
  el.setAttribute('role', 'dialog');
  el.setAttribute('aria-labelledby', id + 'Title');
  el.innerHTML = iconHtml +
    '<div class="lbc-text"><div class="lbc-title" id="' + id + 'Title">' + escapeHtml(title) + '</div><div class="lbc-sub">' + escapeHtml(sub) + '</div></div>' +
    '<div class="lbc-actions"><button type="button" class="lbc-go">' + escapeHtml(goLabel) + '</button>' +
    '<button type="button" class="lbc-close" aria-label="' + escapeHtml(t('a2hs.later')) + '">×</button></div>';
  document.body.appendChild(el);
  el.querySelector('.lbc-go').addEventListener('click', function(){ onGo(el); });
  el.querySelector('.lbc-close').addEventListener('click', function(){ if(el.parentNode) el.parentNode.removeChild(el); onClose(); });
  requestAnimationFrame(function(){ el.classList.add('on'); });
  return el;
}
function closeBottomCard(id){
  var el = document.getElementById(id);
  if(el && el.parentNode) el.parentNode.removeChild(el);
}
function a2hsBlockedNow(){
  // mai sopra il lettore, la chat a schermo intero o una finestra aperta
  var reader = document.getElementById('pageReader');
  if(reader && !reader.classList.contains('hidden')) return true;
  if(document.body.classList.contains('chat-fullscreen')) return true;
  if(document.querySelector('.modal-backdrop:not(.hidden)')) return true;
  return false;
}
function maybeShowInstallBanner(){
  if(!a2hsCanInstall() || a2hsSnoozed('lux_a2hs_until') || document.getElementById('a2hsBanner')) return;
  if(a2hsBlockedNow()) return;
  // solo dopo un segno di interesse: chi ha fatto l'accesso, o chi torna sul sito
  var visits = +(localStorage.getItem('lux_pv') || 0);
  if(!isSignedIn() && visits < 2) return;
  var inApp = isIOSDevice() && a2hsInAppBrowser();
  var android = !isIOSDevice() && !!a2hsDeferredPrompt;
  luxBottomCard('a2hsBanner', '<img class="lbc-icon" src="apple-touch-icon.png" alt="" width="44" height="44">',
    t('a2hs.title'), inApp ? t('a2hs.subInApp') : t('a2hs.sub'),
    android ? t('a2hs.install') : t('a2hs.how'),
    function(el){
      if(android && a2hsDeferredPrompt){
        var p = a2hsDeferredPrompt;
        a2hsDeferredPrompt = null;
        p.prompt();
        (p.userChoice || Promise.resolve()).then(function(){ closeBottomCard('a2hsBanner'); });
        return;
      }
      openInstallGuide();
    },
    function(){ a2hsSnooze('lux_a2hs_until', 30); });
}
function openInstallGuide(){
  if(!isIOSDevice() && a2hsDeferredPrompt){
    var p = a2hsDeferredPrompt;
    a2hsDeferredPrompt = null;
    p.prompt();
    return;
  }
  var inApp = a2hsInAppBrowser();
  var steps = inApp
    ? [[A2HS_DOTS_SVG, t('a2hs.inapp1')], ['', t('a2hs.inapp2')], ['', t('a2hs.inapp3')]]
    : [[A2HS_SHARE_SVG, t('a2hs.step1')], [A2HS_ADD_SVG, t('a2hs.step2')], ['', t('a2hs.step3')], [A2HS_BELL_SVG, t('a2hs.step4')]];
  luxSheet('<h2 class="las-title">' + escapeHtml(t('a2hs.guideTitle')) + '</h2>' +
    '<ol class="a2hs-steps">' + steps.map(function(st, i){
      return '<li><span class="a2hs-num">' + (i + 1) + '</span><span class="a2hs-step-text">' + escapeHtml(st[1]) + '</span>' + (st[0] ? '<span class="a2hs-step-ico">' + st[0] + '</span>' : '') + '</li>';
    }).join('') + '</ol>' +
    '<button type="button" class="las-primary" data-las-close>' + escapeHtml(t('a2hs.ok')) + '</button>');
  closeBottomCard('a2hsBanner');
  a2hsSnooze('lux_a2hs_until', 7); // l'ha visto: lo si ripropone solo tra una settimana
}
// dentro l'app installata: una volta, l'invito ad attivare le notifiche
function maybeAskPushInApp(force){
  if(!isSignedIn() || pushUnavailableReason() !== null) return;
  if(typeof Notification === 'undefined' || Notification.permission !== 'default') return;
  if(!force && (!isStandaloneApp() || a2hsSnoozed('lux_pushask_until'))) return;
  if(a2hsBlockedNow() || document.getElementById('pushAskCard')) return;
  luxBottomCard('pushAskCard', '<span class="lbc-icon lbc-bell">' + A2HS_BELL_SVG + '</span>',
    t('push.askTitle'), t('push.askSub'), t('push.askGo'),
    function(){ closeBottomCard('pushAskCard'); enablePushNotifications(); },
    function(){ a2hsSnooze('lux_pushask_until', 30); });
}
function initInstallPrompts(){
  a2hsCountVisit();
  setTimeout(function(){
    if(isStandaloneApp()) maybeAskPushInApp(false);
    else maybeShowInstallBanner();
  }, 3500);
}

/* ============ SEGUI UN PERSONAGGIO ============
   Chi segue un personaggio riceve un avviso nella campanella (e sul telefono,
   se ha le notifiche attive) quando esce un suo titolo nuovo. L'avviso lo
   scrive Supabase stesso con un trigger sulla tabella catalog: non dipende da
   chi ha il sito aperto. Qui solo il pulsante e la lista di chi segui. */
var followedChars = new Set();
function loadCharacterFollows(){
  if(!isSignedIn() || !SUPABASE_URL){ followedChars = new Set(); refreshFollowButtons(); return Promise.resolve(); }
  return fetch(SUPABASE_URL + '/rest/v1/character_follows?select=character_id&user_id=eq.' + encodeURIComponent(currentUserId()), { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){ followedChars = new Set((rows || []).map(function(r){ return r.character_id; })); refreshFollowButtons(); })
    .catch(function(){});
}
function followButtonHtml(id){
  var on = followedChars.has(id);
  return '<button type="button" class="follow-btn' + (on ? ' is-on' : '') + '" data-follow="' + escapeHtml(id) + '" aria-pressed="' + on + '">' +
    A2HS_BELL_SVG + '<span class="follow-label">' + escapeHtml(on ? t('follow.on') : t('follow.off')) + '</span></button>';
}
function refreshFollowButtons(){
  document.querySelectorAll('[data-follow]').forEach(function(b){
    var on = followedChars.has(b.getAttribute('data-follow'));
    b.classList.toggle('is-on', on);
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
    var l = b.querySelector('.follow-label');
    if(l) l.textContent = on ? t('follow.on') : t('follow.off');
  });
}
function toggleFollowCharacter(id){
  if(!isSignedIn()){ openAuth('login'); return; }
  var session = getSession();
  var uid = currentUserId();
  var wasOn = followedChars.has(id);
  var name = charDisplayName(id);
  if(wasOn) followedChars.delete(id); else followedChars.add(id);
  refreshFollowButtons();
  var req = wasOn
    ? fetch(SUPABASE_URL + '/rest/v1/character_follows?user_id=eq.' + encodeURIComponent(uid) + '&character_id=eq.' + encodeURIComponent(id), {
        method: 'DELETE', headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + session.access_token } })
    : fetch(SUPABASE_URL + '/rest/v1/character_follows', {
        method: 'POST', headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + session.access_token, 'Content-Type': 'application/json', 'Prefer': 'resolution=ignore-duplicates' },
        body: JSON.stringify({ user_id: uid, character_id: id }) });
  req.then(function(r){
    if(!r.ok) throw new Error('follow ' + r.status);
    luxToast((wasOn ? t('follow.undone') : t('follow.done')).replace('{name}', name));
    if(!wasOn){
      // per ricevere l'avviso anche sul telefono: su iPhone serve l'app installata,
      // altrove le notifiche attive. Lo si propone subito, una volta sola.
      var reason = pushUnavailableReason();
      if(reason === 'ios-not-installed' && !a2hsSnoozed('lux_a2hs_follow')){ a2hsSnooze('lux_a2hs_follow', 30); setTimeout(openInstallGuide, 900); }
      else if(reason === null) setTimeout(function(){ maybeAskPushInApp(true); }, 900);
    }
  }).catch(function(err){
    console.warn('Segui personaggio:', err);
    if(wasOn) followedChars.add(id); else followedChars.delete(id);
    refreshFollowButtons();
    luxToast(t('follow.error'));
  });
}
document.addEventListener('click', function(e){
  var b = e.target.closest && e.target.closest('[data-follow]');
  if(!b) return;
  e.preventDefault();
  e.stopPropagation();
  toggleFollowCharacter(b.getAttribute('data-follow'));
});

/* ============ HOME: CONTINUA A LEGGERE (si vede solo su telefono) ============
   Il primo titolo iniziato e non finito, con il punto in cui ci si era fermati. */
function renderHomeContinue(){
  var hero = document.getElementById('testo');
  if(!hero || !hero.parentNode) return;
  var sec = document.getElementById('homeContinueSection');
  var items = (isSignedIn() ? getCatalog() : []).filter(function(item){
    if(!matureOk(item)) return false;
    var total = (item.pages && item.pages.length) || 0;
    var lp = readingProgressMap[item.id];
    return typeof lp === 'number' && total > 1 && lp > 0 && lp < total - 1;
  });
  if(items.length === 0){ if(sec) sec.classList.add('hidden'); return; }
  if(!sec){
    sec = document.createElement('section');
    sec.className = 'section';
    sec.id = 'homeContinueSection';
    hero.parentNode.insertBefore(sec, hero.nextSibling);
  }
  var item = items[0];
  var total = item.pages.length;
  var lp = readingProgressMap[item.id];
  var pct = Math.round(((lp + 1) / total) * 100);
  var cover = item.cover_url
    ? '<img src="' + escapeHtml(coverThumbUrl(item.cover_url, 200)) + '" data-fallback="' + escapeHtml(item.cover_url) + '" alt="" loading="lazy" decoding="async">'
    : '<span class="init">' + escapeHtml((item.character || '?').charAt(0)) + '</span>';
  sec.innerHTML =
    '<div class="section-head"><div><h2>' + escapeHtml(t('mycomics.tab.continue')) + '</h2></div></div>' +
    '<button type="button" class="home-continue-card">' + cover +
      '<span class="home-continue-text">' +
        '<span class="home-continue-title">' + escapeHtml(item.title) + '</span>' +
        '<span class="home-continue-label">' + escapeHtml(t('card.progress').replace('{page}', lp + 1).replace('{total}', total)) + '</span>' +
        '<span class="home-continue-bar"><span style="width:' + pct + '%"></span></span>' +
      '</span>' +
      '<span class="home-continue-go">' + escapeHtml(t('apphome.resume')) + '</span>' +
    '</button>';
  sec.classList.remove('hidden');
  sec.querySelector('.home-continue-card').addEventListener('click', function(){ openTitleModal(item); });
}

/* ============ USER PROFILE (display name, bio, avatar, favorite characters) ============ */
var currentProfile = null;

// Il popup "Il mio profilo" è superato — la pagina profile.html a schermo
// intero ha già tutto (stessi campi, dentro "Modifica profilo"), più
// diario/foto/video/titoli che il popup non mostrava affatto.
function goToOwnProfile(){
  if(!isSignedIn()){ openAuth('login'); return; }
  window.location.href = 'profile.html?user=' + encodeURIComponent(currentUserId());
}

function openProfileModal(){
  if(!isSignedIn()){ openAuth('login'); return; }
  var profileErrEl = document.getElementById('profileError');
  if(profileErrEl) profileErrEl.textContent = '';
  var requestErrEl = document.getElementById('requestError');
  if(requestErrEl) requestErrEl.textContent = '';
  var reqBodyEl = document.getElementById('fRequestBody');
  if(reqBodyEl) reqBodyEl.value = '';
  loadOwnProfile().then(function(){
    populateProfileForm();
    document.getElementById('profileModal').classList.remove('hidden');
  });
}
function closeProfileModal(){ document.getElementById('profileModal').classList.add('hidden'); }

function loadOwnProfile(){
  var session = getSession();
  if(!session) return Promise.resolve();
  return fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(currentUserId()) + '&select=*', {
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
  })
    .then(function(r){ if(!r.ok) throw new Error('profile read failed'); return r.json(); })
    .then(function(rows){ currentProfile = rows[0] || null; })
    .catch(function(err){ console.warn('Profile load failed:', err); currentProfile = null; });
}
function populateProfileForm(){
  var p = currentProfile || {};
  document.getElementById('fDisplayName').value = p.display_name || '';
  document.getElementById('fBio').value = p.bio || '';
  document.getElementById('profileAvatarImg').src = p.avatar_url || '';
  document.getElementById('profileAvatarImg').style.opacity = p.avatar_url ? '1' : '0.2';
  document.getElementById('fBirthDate').value = p.birth_date || '';
  document.getElementById('fGender').value = p.gender || '';
  document.getElementById('profileBannerImg').src = p.banner_url || '';
  document.getElementById('fSocialInstagram').value = p.social_instagram || '';
  document.getElementById('fSocialTwitter').value = p.social_twitter || '';
  document.getElementById('fSocialTiktok').value = p.social_tiktok || '';
  document.getElementById('fSocialWebsite').value = p.social_website || '';
  var privateCb = document.getElementById('fPrivateProfile');
  if(privateCb){
    privateCb.checked = !!p.is_private;
    var hint = document.getElementById('privateProfileHint');
    if(hint) hint.textContent = privateCb.checked ? t('profile.privateProfileHintOn') : t('profile.privateProfileHint');
    privateCb.onchange = function(){
      if(hint) hint.textContent = privateCb.checked ? t('profile.privateProfileHintOn') : t('profile.privateProfileHint');
    };
  }
  var favs = p.favorite_characters || [];
  document.querySelectorAll('.fav-char-cb').forEach(function(cb){
    cb.checked = favs.indexOf(cb.value) !== -1;
  });
  renderProfileCreateBox();
}

/* Sezione "Crea contenuti" del modal profilo: slegata da "I Miei Comic"
   (quella è lettura/possesso, questa è pubblicazione), visibile solo a chi
   ha già un motivo per pubblicare — stessa condizione che sblocca la vista
   ristretta di Admin. Ogni sigillo porta al modulo "Aggiungi allo
   schedario" con il personaggio già scelto. */
function renderProfileCreateBox(){
  var box = document.getElementById('profileCreateBox');
  var grid = document.getElementById('profileCreateGrid');
  if(!box || !grid) return;
  var canCreate = isSignedIn();
  box.classList.toggle('hidden', !canCreate);
  if(!canCreate) return;
  var chars = charList(false).map(function(c){ return c.id; });
  grid.innerHTML = chars.map(function(name){
    var img = characterImages[name];
    var inner = img ? '<img src="'+img+'" alt="">' : '<span class="profile-create-init">'+name.charAt(0)+'</span>';
    return '<button type="button" class="profile-create-seal" data-character="'+name+'">'+inner+'<span>'+name+'</span></button>';
  }).join('');
  grid.querySelectorAll('.profile-create-seal').forEach(function(btn){
    btn.addEventListener('click', function(){
      sessionStorage.setItem('lux_pending_new_title_character', btn.getAttribute('data-character'));
      window.location.href = 'admin.html';
    });
  });
}
function pickAvatarPublicUrl(userId, ext){
  return SUPABASE_URL + '/storage/v1/object/public/avatars/' + userId + '/avatar.' + ext + '?t=' + Date.now();
}
function pickAvatarHdPublicUrl(userId, ext){
  return SUPABASE_URL + '/storage/v1/object/public/avatars/' + userId + '/avatar-hd.' + ext + '?t=' + Date.now();
}
function pickBannerPublicUrl(userId, ext){
  return SUPABASE_URL + '/storage/v1/object/public/avatars/' + userId + '/banner.' + ext + '?t=' + Date.now();
}
/* Pannello "Modifica profilo" dentro profile.html: il pulsante lo apre e lo chiude (prima non era collegato a niente) */
function setProfileEditOpen(open){
  var panel = document.getElementById('profileEditPanel');
  var btn = document.getElementById('btnToggleProfileEdit');
  if(!panel) return;
  if(open){
    if(!isSignedIn()){ openAuth('login'); return; }
    var errEl = document.getElementById('profileError');
    if(errEl) errEl.textContent = '';
    loadOwnProfile().then(function(){
      populateProfileForm();
      panel.classList.remove('hidden');
      if(btn){ btn.textContent = t('profile.editClose'); btn.setAttribute('aria-expanded', 'true'); }
      var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      try { panel.scrollIntoView({ block:'start', behavior: reduce ? 'auto' : 'smooth' }); } catch(e){}
      var nameEl = document.getElementById('fDisplayName');
      if(nameEl && !nameEl.value){ try { nameEl.focus({ preventScroll:true }); } catch(e){ nameEl.focus(); } }
    });
  } else {
    panel.classList.add('hidden');
    if(btn){ btn.textContent = t('profile.edit'); btn.setAttribute('aria-expanded', 'false'); }
  }
}
function toggleProfileEditPanel(){
  var panel = document.getElementById('profileEditPanel');
  if(!panel) return;
  setProfileEditOpen(panel.classList.contains('hidden'));
}

/* Errore HTTP con dettaglio leggibile (stato + messaggio del server), mostrato accanto a "Salvataggio non riuscito" */
function httpFailure(what, r){
  return r.text().then(function(txt){
    var msg = '';
    try { var j = JSON.parse(txt); msg = j.message || j.error_description || j.error || j.hint || ''; } catch(e){ msg = String(txt || '').slice(0, 90); }
    var e = new Error(what + ' failed: ' + r.status);
    e.detail = what + ' ' + r.status + (msg ? ': ' + String(msg).slice(0, 90) : '');
    throw e;
  });
}

function saveProfile(){
  var session = getSession();
  if(!session) return;
  var err = document.getElementById('profileError');
  if(err) err.textContent = '';
  var displayName = document.getElementById('fDisplayName').value.trim();
  var bio = document.getElementById('fBio').value.trim();
  var birthDate = document.getElementById('fBirthDate').value;
  var gender = document.getElementById('fGender').value;
  var socialInstagram = document.getElementById('fSocialInstagram').value.trim();
  var socialTwitter = document.getElementById('fSocialTwitter').value.trim();
  var socialTiktok = document.getElementById('fSocialTiktok').value.trim();
  var socialWebsite = document.getElementById('fSocialWebsite').value.trim();
  var favs = Array.from(document.querySelectorAll('.fav-char-cb:checked')).map(function(cb){ return cb.value; });
  var isPrivateCb = document.getElementById('fPrivateProfile');
  var isPrivate = isPrivateCb ? isPrivateCb.checked : (currentProfile ? !!currentProfile.is_private : false);
  var btn = document.getElementById('btnSaveProfile');
  btn.disabled = true;

  var avatarStep = Promise.resolve(currentProfile ? currentProfile.avatar_url : null);
  var avatarFile = document.getElementById('fProfileAvatar').files[0];
  if(avatarFile){
    var extMatch = /\.([a-zA-Z0-9]+)$/.exec(avatarFile.name || '');
    var ext = extMatch ? extMatch[1].toLowerCase() : 'jpg';
    var path = currentUserId() + '/avatar.' + ext;
    avatarStep = fetch(SUPABASE_URL + '/storage/v1/object/avatars/' + path, {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'x-upsert':'true', 'Content-Type': avatarFile.type || 'image/jpeg' },
      body: avatarFile
    }).then(function(r){
      if(!r.ok) return httpFailure('avatar', r);
      return pickAvatarPublicUrl(currentUserId(), ext);
    });
  }

  var avatarHdStep = Promise.resolve(currentProfile ? currentProfile.avatar_hd_url : null);
  var avatarHdFile = document.getElementById('fProfileAvatarHd').files[0];
  if(avatarHdFile){
    var extMatchHd = /\.([a-zA-Z0-9]+)$/.exec(avatarHdFile.name || '');
    var extHd = extMatchHd ? extMatchHd[1].toLowerCase() : 'jpg';
    var pathHd = currentUserId() + '/avatar-hd.' + extHd;
    avatarHdStep = fetch(SUPABASE_URL + '/storage/v1/object/avatars/' + pathHd, {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'x-upsert':'true', 'Content-Type': avatarHdFile.type || 'image/jpeg' },
      body: avatarHdFile
    }).then(function(r){
      if(!r.ok) return httpFailure('avatar-hd', r);
      return pickAvatarHdPublicUrl(currentUserId(), extHd);
    });
  }

  var bannerStep = Promise.resolve(currentProfile ? currentProfile.banner_url : null);
  var bannerFile = document.getElementById('fProfileBanner').files[0];
  if(bannerFile){
    var extMatchBn = /\.([a-zA-Z0-9]+)$/.exec(bannerFile.name || '');
    var extBn = extMatchBn ? extMatchBn[1].toLowerCase() : 'jpg';
    var pathBn = currentUserId() + '/banner.' + extBn;
    bannerStep = fetch(SUPABASE_URL + '/storage/v1/object/avatars/' + pathBn, {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'x-upsert':'true', 'Content-Type': bannerFile.type || 'image/jpeg' },
      body: bannerFile
    }).then(function(r){
      if(!r.ok) return httpFailure('banner', r);
      return pickBannerPublicUrl(currentUserId(), extBn);
    });
  }

  Promise.all([avatarStep, avatarHdStep, bannerStep]).then(function(results){
    var avatarUrl = results[0];
    var avatarHdUrl = results[1];
    var bannerUrl = results[2];
    var uid = currentUserId();
    var fields = {
      display_name: displayName || null, bio: bio || null,
      avatar_url: avatarUrl || null, avatar_hd_url: avatarHdUrl || null, banner_url: bannerUrl || null,
      birth_date: birthDate || null, gender: gender || null,
      social_instagram: socialInstagram || null, social_twitter: socialTwitter || null,
      social_tiktok: socialTiktok || null, social_website: socialWebsite || null,
      favorite_characters: favs
    };
    // "profilo privato" si manda solo se questa schermata ha davvero l'interruttore: sulla pagina profilo non c'è, e così non si tocca una colonna che potrebbe non esistere
    if(isPrivateCb) fields.is_private = isPrivate;
    var writeHeaders = {
      'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token,
      'Content-Type':'application/json', 'Prefer':'return=representation'
    };
    // prima si aggiorna la riga che c'è già: serve solo il permesso di modificare il proprio profilo
    return fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(uid), {
      method:'PATCH', headers: writeHeaders, body: JSON.stringify(fields)
    }).then(function(r){
      if(!r.ok) return httpFailure('save', r);
      return r.json();
    }).then(function(rows){
      if(rows && rows.length) return rows;
      // nessuna riga da aggiornare: il profilo non c'è ancora, lo creiamo
      return fetch(SUPABASE_URL + '/rest/v1/profiles', {
        method:'POST',
        headers: Object.assign({}, writeHeaders, { 'Prefer':'resolution=merge-duplicates,return=representation' }),
        body: JSON.stringify(Object.assign({ id: uid }, fields))
      }).then(function(r){
        if(!r.ok) return httpFailure('create', r);
        return r.json();
      });
    });
  }).then(function(rows){
    currentProfile = rows[0];
    populateProfileForm();
    document.getElementById('fProfileAvatar').value = '';
    document.getElementById('fProfileAvatarHd').value = '';
    document.getElementById('fProfileBanner').value = '';
    if(document.getElementById('profileSection')){ window.location.reload(); return; } // sulla pagina profilo: si rivedono subito nome e immagini nuovi
  }).catch(function(e){
    console.warn('Profile save failed:', e);
    err.textContent = t('profile.saveError') + (e && e.detail ? ' (' + e.detail + ')' : '');
  }).then(function(){
    btn.disabled = false;
  });
}

/* ============ POPUP INFO AVATAR (click su un avatar ovunque nel sito) ============ */
function genderLabel(g){
  if(g === 'M') return t('profile.genderM');
  if(g === 'F') return t('profile.genderF');
  if(g === 'X') return t('profile.genderX');
  return null;
}
function openAvatarInfo(userId){
  if(!userId) return;
  fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(userId) + '&select=display_name,avatar_url,avatar_hd_url,birth_date,gender,verified', { headers: communityHeaders() })
    .then(function(r){ if(!r.ok) throw new Error('avatar info read failed'); return r.json(); })
    .then(function(rows){
      var p = rows[0];
      if(!p) return;
      var bigUrl = p.avatar_hd_url || p.avatar_url || '';
      document.getElementById('avatarInfoImg').src = bigUrl;
      document.getElementById('avatarInfoImg').style.opacity = bigUrl ? '1' : '0.15';
      document.getElementById('avatarInfoImg').onclick = function(){ openImageLightbox(bigUrl); };
      var verifiedTag = ' ' + verifiedBadge('verified.commenter', !!p.verified);
      document.getElementById('avatarInfoName').innerHTML = escapeHtml(p.display_name || t('notif.someone')) + verifiedTag;
      var rows2 = '';
      if(p.birth_date){
        var d = new Date(p.birth_date);
        if(!isNaN(d)) rows2 += '<div class="avatar-info-row"><span class="k">' + t('profile.birthDate') + '</span><span class="v">' + d.toLocaleDateString() + '</span></div>';
      }
      var gLabel = genderLabel(p.gender);
      if(gLabel) rows2 += '<div class="avatar-info-row"><span class="k">' + t('profile.gender') + '</span><span class="v">' + escapeHtml(gLabel) + '</span></div>';
      document.getElementById('avatarInfoRows').innerHTML = rows2 || '<p class="avatar-info-empty">' + t('profile.avatarInfoEmpty') + '</p>';
      document.getElementById('avatarInfoModal').classList.remove('hidden');
    })
    .catch(function(e){ console.warn('Avatar info load failed:', e); });
}
function closeAvatarInfo(){ document.getElementById('avatarInfoModal').classList.add('hidden'); }

