/* ============ USER REQUESTS (private suggestion box to the admin) ============ */
function submitRequest(){
  var session = getSession();
  if(!session) return;
  var body = document.getElementById('fRequestBody').value.trim();
  var err = document.getElementById('requestError');
  err.textContent = '';
  if(!body){ err.textContent = t('err.required'); return; }
  fetch(SUPABASE_URL + '/rest/v1/requests', {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'return=representation' },
    body: JSON.stringify({ user_id: currentUserId(), author_email: currentUserEmail(), body: body })
  }).then(function(r){
    if(!r.ok) throw new Error('request insert failed');
    document.getElementById('fRequestBody').value = '';
    loadMyRequests();
  }).catch(function(e){
    console.warn('Request submit failed:', e);
    err.textContent = t('requests.submitError');
  });
}
function submitSmallNoxRequest(){
  var session = getSession();
  var field = document.getElementById('fSmallNoxRequest');
  var err = document.getElementById('smallnoxRequestError');
  var sent = document.getElementById('smallnoxRequestSent');
  if(!field || !err) return;
  err.textContent = '';
  if(sent) sent.textContent = '';
  if(!session){ err.textContent = t('admin.gate.notSignedIn'); return; }
  var body = field.value.trim();
  if(!body){ err.textContent = t('err.required'); return; }
  fetch(SUPABASE_URL + '/rest/v1/requests', {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'return=representation' },
    body: JSON.stringify({ user_id: currentUserId(), author_email: currentUserEmail(), body: body })
  }).then(function(r){
    if(!r.ok) throw new Error('request insert failed');
    field.value = '';
    if(sent) sent.textContent = t('requests.sent');
    if(document.getElementById('myRequestsList')) loadMyRequests(); // se siamo anche sulla pagina profilo, aggiorna la lista lì
  }).catch(function(e){
    console.warn('SmallNox request submit failed:', e);
    err.textContent = t('requests.submitError');
  });
}

function loadMyRequests(){
  var session = getSession();
  var list = document.getElementById('myRequestsList');
  if(!session){ list.innerHTML = ''; return; }
  fetch(SUPABASE_URL + '/rest/v1/requests?user_id=eq.' + encodeURIComponent(currentUserId()) + '&select=*&order=created_at.desc', {
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
  })
    .then(function(r){ if(!r.ok) throw new Error('requests read failed'); return r.json(); })
    .then(function(rows){
      list.innerHTML = '';
      rows.forEach(function(req){
        var div = document.createElement('div');
        div.className = 'my-request-item';
        var statusLabel = req.status === 'new' ? t('requests.statusNew') : t('requests.statusRead');
        div.innerHTML = escapeHtml(req.body) + '<span class="status">' + statusLabel + '</span>';
        list.appendChild(div);
      });
    })
    .catch(function(err){ console.warn('My requests load failed:', err); });
}

/* ============ NOTIFICATIONS (bell icon — comments on threads you're in, likes/comments for admin) ============ */
var notifPollTimer = null;
var dmCountPollTimer = null;
var notifCache = [];

function notifTimeAgo(iso){
  var diffMin = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if(diffMin < 1) return t('notif.justNow');
  if(diffMin < 60) return t('notif.minsAgo').replace('{n}', diffMin);
  var diffH = Math.floor(diffMin / 60);
  if(diffH < 24) return t('notif.hoursAgo').replace('{n}', diffH);
  var diffD = Math.floor(diffH / 24);
  return t('notif.daysAgo').replace('{n}', diffD);
}

function loadNotifications(){
  var session = getSession();
  var badge = document.getElementById('notifBadge');
  var bellBtn = document.getElementById('btnNotifications');
  if(!isSignedIn()){
    if(bellBtn) bellBtn.classList.add('hidden');
    if(notifPollTimer){ clearInterval(notifPollTimer); notifPollTimer = null; }
    return Promise.resolve();
  }
  if(bellBtn) bellBtn.classList.remove('hidden');
  return fetch(SUPABASE_URL + '/rest/v1/notifications?user_id=eq.' + encodeURIComponent(currentUserId()) + '&select=*&order=created_at.desc&limit=30', {
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
  })
    .then(function(r){ if(!r.ok) throw new Error('notifications read failed'); return r.json(); })
    .then(function(rows){
      notifCache = rows;
      var unread = rows.filter(function(n){ return !n.read; }).length;
      if(badge){
        if(unread > 0){ badge.textContent = unread > 99 ? '99+' : String(unread); badge.classList.remove('hidden'); }
        else { badge.classList.add('hidden'); }
      }
      renderNotifPanel();
      if(!notifPollTimer){ notifPollTimer = setInterval(loadNotifications, 45000); } // polling leggero, non realtime
      pruneOldNotifications(session);
    })
    .catch(function(err){ console.warn('Notifications load failed:', err); });
}

// Anche le notifiche mai aperte non devono restare per sempre — oltre i 30
// giorni si eliminano da sole in background, senza bisogno che l'utente
// faccia nulla. Gira in background dopo ogni caricamento, non blocca la UI.
function pruneOldNotifications(session){
  var cutoff = new Date(Date.now() - 30*24*60*60*1000).toISOString();
  fetch(SUPABASE_URL + '/rest/v1/notifications?user_id=eq.' + encodeURIComponent(currentUserId()) + '&created_at=lt.' + encodeURIComponent(cutoff), {
    method:'DELETE',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
  }).catch(function(){}); // silenzioso: non è critico se una pulizia in background salta un giro
}

function smallNoxState(n){
  var msg = n.message || '';
  if(n.type === 'signup_auto') return 'calm';
  if(n.type === 'verified') return 'calm';
  if(n.type === 'friend_request' && msg.indexOf('sospetto') !== -1) return 'angry';
  if(n.type === 'admin_comment' && msg.indexOf('segnalato') !== -1) return 'angry';
  return null;
}

function renderNotifPanel(){
  var list = document.getElementById('notifList');
  if(!list) return;
  list.innerHTML = '';
  if(notifCache.length === 0){
    list.innerHTML = '<div class="notif-empty">' + t('notif.empty') + '</div>';
    return;
  }
  notifCache.forEach(function(n){
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'notif-item' + (n.read ? '' : ' unread');
    var noxState = smallNoxState(n);
    var noxImg = noxState ? '<img src="smallnox-' + noxState + '.png" alt="SmallNox" class="notif-nox-avatar">' : '';
    var refHtml = '';
    if(n.catalog_id){
      var refItem = getCatalog().find(function(i){ return i.id === n.catalog_id; });
      if(refItem) refHtml = ' <span class="notif-ref" style="color:var(--gold, #c9a24d);font-style:italic;">«' + escapeHtml(refItem.title) + '»</span>';
    }
    btn.innerHTML = noxImg + '<span class="actor">' + escapeHtml(n.actor_name || t('notif.someone')) + '</span> ' + escapeHtml(n.type === 'verified' ? t('notif.verified') : (n.message || '')) + refHtml +
      '<span class="when">' + notifTimeAgo(n.created_at) + '</span>';
    btn.addEventListener('click', function(){ openNotification(n); });
    list.appendChild(btn);
  });
}

function openNotification(n){
  deleteNotification(n.id);
  document.getElementById('notifPanel').classList.add('hidden');
  if(n.type === 'dm_message' && n.source_id){
    if(document.getElementById('chatSection')){
      openChatWithUser(n.source_id, true);
    } else {
      window.location.href = 'chat.html?user=' + encodeURIComponent(n.source_id);
    }
    return;
  }
  if(n.type === 'friend_request' || n.type === 'friend_accepted'){
    var communitySection = document.getElementById('communitySection');
    if(communitySection){
      communitySection.scrollIntoView({behavior:'smooth'});
      switchCommunityTab('friends');
    } else {
      // Non siamo sulla pagina Community: ci navighiamo, ricordando quale tab aprire all'arrivo.
      sessionStorage.setItem('lux_pending_community_tab', 'friends');
      window.location.href = 'community.html#communitySection';
    }
    return;
  }
  if((n.type === 'new_follower' || n.type === 'profile_view' || n.type === 'verified') && n.source_id){
    window.location.href = 'profile.html?user=' + encodeURIComponent(n.source_id);
    return;
  }
  if(n.type === 'creation_invite'){
    var adminSection1 = document.getElementById('adminSection');
    if(adminSection1){ adminSection1.classList.remove('hidden'); adminSection1.scrollIntoView({behavior:'smooth'}); }
    else { window.location.href = 'admin.html'; }
    return;
  }
  if(n.type === 'extension_request'){
    var adminSection2 = document.getElementById('adminSection');
    if(adminSection2){
      adminSection2.classList.remove('hidden');
      switchAdminTab('users');
      adminSection2.scrollIntoView({behavior:'smooth'});
    } else {
      sessionStorage.setItem('lux_pending_admin_tab', 'users');
      window.location.href = 'admin.html';
    }
    return;
  }
  if(n.type === 'announcement'){
    if(document.getElementById('catalogGrid')){
      document.getElementById('library').scrollIntoView({behavior:'smooth'});
    } else {
      window.location.href = 'schedario.html#library';
    }
    return;
  }
  if(n.catalog_id){
    var items = getCatalog();
    var item = items.find(function(i){ return i.id === n.catalog_id; });
    if(item){
      if(item.mature && !matureVisible){
        pendingDeepLinkItem = item;
        openMatureModal();
      } else {
        openTitleModal(item);
      }
    }
  }
}

// Aprire una notifica o premere "Cancella tutte" non le segna più come
// lette: le ELIMINA. Il pannello deve restare sempre pulito, non
// diventare un archivio statico — quello che hai già letto/aperto non ha
// motivo di restare lì.
function deleteNotification(id){
  var session = getSession();
  if(!session) return;
  var idx = notifCache.findIndex(function(x){ return x.id === id; });
  if(idx === -1) return;
  var removed = notifCache[idx];
  notifCache.splice(idx, 1); // aggiorna subito la UI, non aspettare la risposta del server
  updateNotifBadgeFromCache();
  renderNotifPanel();
  fetch(SUPABASE_URL + '/rest/v1/notifications?id=eq.' + encodeURIComponent(id), {
    method:'DELETE',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
  }).then(function(r){
    if(!r.ok) throw new Error('delete failed: ' + r.status);
  }).catch(function(err){
    console.warn('Eliminazione notifica fallita, la rimetto in lista:', err);
    // il server non ha confermato la cancellazione — se la lasciassimo
    // sparita solo qui, tornerebbe al prossimo caricamento senza che se ne
    // capisca il motivo. Meglio rimetterla subito, visibile.
    notifCache.splice(idx, 0, removed);
    updateNotifBadgeFromCache();
    renderNotifPanel();
  });
}

function deleteAllNotifications(){
  var session = getSession();
  if(!session) return;
  if(notifCache.length === 0) return;
  var previous = notifCache;
  notifCache = [];
  updateNotifBadgeFromCache();
  renderNotifPanel();
  fetch(SUPABASE_URL + '/rest/v1/notifications?user_id=eq.' + encodeURIComponent(currentUserId()), {
    method:'DELETE',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
  }).then(function(r){
    if(!r.ok) throw new Error('delete all failed: ' + r.status);
  }).catch(function(err){
    console.warn('Eliminazione di tutte le notifiche fallita, ripristino la lista:', err);
    notifCache = previous; // il server non ha confermato: non mentiamo alla UI
    updateNotifBadgeFromCache();
    renderNotifPanel();
  });
}

function updateNotifBadgeFromCache(){
  var badge = document.getElementById('notifBadge');
  if(!badge) return;
  var unread = notifCache.filter(function(n){ return !n.read; }).length;
  if(unread > 0){ badge.textContent = unread > 99 ? '99+' : String(unread); badge.classList.remove('hidden'); }
  else { badge.classList.add('hidden'); }
}

/* ============ COMMUNITY (canali a tema creati dagli utenti + messaggi privati) ============ */
var currentChannelId = null;
var currentChannelName = null;
var currentDmThreadId = null;
var currentDmOtherName = null;
var displayNameCache = {}; // id -> display_name, per non richiederlo ad ogni messaggio

function communityHeaders(){
  var session = getSession();
  return { 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + (session ? session.access_token : SUPABASE_ANON_KEY) };
}

function switchCommunityTab(tab){
  if(tab !== 'servers'){ closeServerChannel(); stopServerLivePoll(); }
  var commSection = document.getElementById('communitySection');
  if(commSection) commSection.classList.toggle('srv-wide', tab === 'servers');
  if(tab === 'servers' && window.matchMedia('(min-width:900px)').matches){
    // su schermo grande i Server occupano tutto lo schermo sotto la barra: porta il pannello in cima
    setTimeout(function(){
      var shell = document.getElementById('srvShell');
      if(shell) shell.scrollIntoView({ block:'start', behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
    }, 60);
  }
  document.querySelectorAll('.community-tab').forEach(function(btn){
    btn.classList.toggle('active', btn.dataset.ctab === tab);
    if(btn.dataset.ctab === tab && btn.parentNode && btn.parentNode.scrollTo){
      // la scheda scelta resta in vista dentro la riga (senza spostare la pagina)
      var row = btn.parentNode;
      row.scrollTo({ left: Math.max(0, btn.offsetLeft - (row.clientWidth - btn.offsetWidth) / 2), behavior: 'smooth' });
    }
  });
  document.querySelectorAll('.community-panel').forEach(function(panel){
    panel.classList.toggle('hidden', panel.dataset.cpanel !== tab);
  });
  if(tab === 'dms') loadDmThreads();
  if(tab === 'friends') loadFriendsPanel();
  if(tab === 'collab') renderCollabWorksTab();
  if(tab === 'diary') loadDiaryFeed();
  if(tab === 'servers') renderServerRail();
  if(tab === 'events') renderEventsTab();
}

/* ============ SERVER (creati da Amministra: canale reale + elenco iscritti) ============ */
var serverListCache = null;
var activeServerId = null;

function renderServerRail(){
  var rail = document.getElementById('serverRailRow');
  var empty = document.getElementById('serverEmptyState');
  if(!rail) return;
  fetch(SUPABASE_URL + '/rest/v1/communities?select=*&order=created_at.asc', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(servers){
      serverListCache = servers;
      var pendingServerId = sessionStorage.getItem('lux_pending_server_id');
      if(pendingServerId){
        sessionStorage.removeItem('lux_pending_server_id');
        if(servers.some(function(s){ return s.id === pendingServerId; })) activeServerId = pendingServerId;
      }
      if(servers.length === 0){
        rail.innerHTML = '';
        if(empty) empty.classList.remove('hidden');
        document.getElementById('serverDetailBox').innerHTML = '';
        return;
      }
      if(empty) empty.classList.add('hidden');
      rail.innerHTML = '';
      servers.forEach(function(s){
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'server-rail-icon' + (s.id === activeServerId ? ' active' : '');
        btn.textContent = s.icon || '💬';
        btn.title = s.name;
        btn.addEventListener('click', function(){ selectServer(s.id); });
        rail.appendChild(btn);
      });
      selectServer(activeServerId && servers.some(function(s){ return s.id === activeServerId; }) ? activeServerId : servers[0].id);
    })
    .catch(function(e){ console.warn('Server rail load failed:', e); });
}

/* ---- Server stile Discord: categorie, canali con emoji e tipo, stanza vocale (presenza, senza audio) ----
   La chat dei canali testuali è sempre la stessa (channelDetailView): quando si apre da un server
   viene "montata" dentro il pannello Server, e quando si esce torna al suo posto nel tab Canali. */
var channelDetailMounted = false;
var activeServerChannelId = null;
var serverChannelsCache = {}; // serverId -> { cats:[], chs:[] }
var srvClosedCats = {};
var serverLiveTimer = null;
var voiceRoom = { channelId:null, channel:null, joined:false, connecting:false, audio:false, audioFailed:false, amIn:false, muted:false, frame:null, viewTimer:null, beatTimer:null };

function channelIconFor(ch){
  if(ch.emoji) return ch.emoji;
  if(ch.channel_type === 'voice') return '🔊';
  if(ch.channel_type === 'announce') return '📢';
  return '#';
}
function srvByPosition(a, b){ return (a.position || 0) - (b.position || 0); }
function srvAuthHeaders(json){
  var session = getSession();
  var h = { 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + (session ? session.access_token : SUPABASE_ANON_KEY) };
  if(json) h['Content-Type'] = 'application/json';
  return h;
}

function selectServer(id){
  activeServerId = id;
  document.querySelectorAll('.server-rail-icon').forEach(function(btn, i){
    btn.classList.toggle('active', serverListCache[i] && serverListCache[i].id === id);
  });
  var s = (serverListCache || []).find(function(x){ return x.id === id; });
  if(!s) return;
  closeServerChannel();
  var admin = isAdmin();
  var box = document.getElementById('serverDetailBox');
  box.innerHTML =
    '<div class="srv-side">' +
      '<div class="server-detail-head">' +
        '<div class="server-detail-title">' + escapeHtml(s.icon || '💬') + ' ' + escapeHtml(s.name) + '</div>' +
        '<button type="button" class="btn btn-sm" id="serverJoinBtn">…</button>' +
      '</div>' +
      (s.description ? '<p class="form-note">' + escapeHtml(s.description) + '</p>' : '') +
      '<div id="serverChannelsList" class="srv-cats"></div>' +
      (admin
        ? '<button type="button" class="btn btn-sm btn-ghost srv-add-cat" id="btnAddCategory">' + t('servers.newCategory') + '</button>'
        : '<div class="server-new-channel-row">' +
            '<input type="text" id="fNewServerChannelName" maxlength="40" placeholder="' + t('servers.newChannelPh') + '">' +
            '<button type="button" class="btn btn-sm btn-ghost" id="btnAddServerChannel">' + t('community.createChannel') + '</button>' +
          '</div>') +
    '</div>' +
    '<aside class="srv-members">' +
      '<div class="shelf-head"><div class="shelf-eyebrow">' + t('servers.membersLabel') + '</div></div>' +
      '<div id="serverMembersList" class="contatti-list"></div>' +
    '</aside>';

  if(admin){
    document.getElementById('btnAddCategory').addEventListener('click', function(){ addServerCategory(s.id); });
  } else {
    document.getElementById('btnAddServerChannel').addEventListener('click', function(){ createServerChannel(s.id); });
  }
  refreshServerJoinState(s.id, document.getElementById('serverJoinBtn'));
  renderServerChannels(s.id);
  renderServerMembers(s.id);
  startServerLivePoll(s.id);
}

function renderServerChannels(serverId){
  var box = document.getElementById('serverChannelsList');
  if(!box) return;
  box.innerHTML = '<p class="form-note">…</p>';
  var enc = encodeURIComponent(serverId);
  Promise.all([
    // se lo script SQL delle categorie non è ancora stato lanciato questa chiamata fallisce: si torna alla lista semplice, senza rompere nulla
    fetch(SUPABASE_URL + '/rest/v1/channel_categories?community_id=eq.' + enc + '&select=*&order=created_at.asc', { headers: communityHeaders() })
      .then(function(r){ return r.ok ? r.json() : []; }).catch(function(){ return []; }),
    fetch(SUPABASE_URL + '/rest/v1/channels?community_id=eq.' + enc + '&select=*&order=created_at.asc', { headers: communityHeaders() })
      .then(function(r){ if(!r.ok) throw new Error('server channels read failed'); return r.json(); })
  ]).then(function(res){
    serverChannelsCache[serverId] = { cats: res[0].slice().sort(srvByPosition), chs: res[1].slice().sort(srvByPosition) };
    paintServerChannels(serverId);
    refreshServerVoiceLive(serverId);
  }).catch(function(e){
    console.warn('Server channels load failed:', e);
    box.innerHTML = '<p class="form-note">' + t('community.loadError') + '</p>';
  });
}

function paintServerChannels(serverId){
  var box = document.getElementById('serverChannelsList');
  var data = serverChannelsCache[serverId];
  if(!box || !data) return;
  var admin = isAdmin();
  box.innerHTML = '';
  if(!data.chs.length && !data.cats.length){
    box.innerHTML = '<p class="form-note">' + t('servers.noChannels') + '</p>';
    return;
  }
  var byCat = {}, loose = [];
  data.chs.forEach(function(ch){
    if(ch.category_id && data.cats.some(function(c){ return c.id === ch.category_id; })){
      (byCat[ch.category_id] = byCat[ch.category_id] || []).push(ch);
    } else {
      loose.push(ch);
    }
  });
  function group(title, list, cat){
    var key = cat ? cat.id : '_loose';
    var wrap = document.createElement('div');
    wrap.className = 'srv-cat' + (srvClosedCats[key] ? ' closed' : '');
    var head = document.createElement('div');
    head.className = 'srv-cat-head';
    var tg = document.createElement('button');
    tg.type = 'button';
    tg.className = 'srv-cat-toggle';
    tg.setAttribute('aria-expanded', srvClosedCats[key] ? 'false' : 'true');
    var chev = document.createElement('span'); chev.className = 'srv-chev'; chev.textContent = '▼';
    var ttl = document.createElement('span'); ttl.textContent = title;
    var cnt = document.createElement('span'); cnt.className = 'srv-cat-count'; cnt.textContent = String(list.length);
    tg.appendChild(chev); tg.appendChild(ttl); tg.appendChild(cnt);
    tg.addEventListener('click', function(){
      srvClosedCats[key] = !srvClosedCats[key];
      wrap.classList.toggle('closed', !!srvClosedCats[key]);
      tg.setAttribute('aria-expanded', srvClosedCats[key] ? 'false' : 'true');
    });
    head.appendChild(tg);
    if(admin && cat){
      var add = document.createElement('button');
      add.type = 'button'; add.className = 'srv-mini-btn'; add.textContent = '+';
      add.setAttribute('aria-label', t('servers.sheetNew') + ' — ' + cat.name);
      add.addEventListener('click', function(){ openServerSheet(serverId, null, cat.id); });
      head.appendChild(add);
      var del = document.createElement('button');
      del.type = 'button'; del.className = 'srv-mini-btn'; del.textContent = '✕';
      del.setAttribute('aria-label', t('servers.deleteCategory'));
      del.addEventListener('click', function(){ deleteServerCategory(serverId, cat); });
      head.appendChild(del);
    }
    wrap.appendChild(head);
    var body = document.createElement('div');
    body.className = 'srv-cat-body';
    list.forEach(function(ch){ body.appendChild(buildServerChannelRow(ch, serverId, admin)); });
    wrap.appendChild(body);
    return wrap;
  }
  if(loose.length) box.appendChild(group(t('servers.uncategorized'), loose, null));
  data.cats.forEach(function(c){ box.appendChild(group(c.name, byCat[c.id] || [], c)); });
}

function buildServerChannelRow(ch, serverId, admin){
  var row = document.createElement('div');
  row.className = 'srv-ch-row';
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'srv-ch' + (ch.channel_type === 'voice' ? ' is-voice' : '') + (ch.id === activeServerChannelId ? ' active' : '');
  b.dataset.chid = ch.id;
  var ic = document.createElement('span'); ic.className = 'srv-ch-ic'; ic.textContent = channelIconFor(ch);
  var main = document.createElement('span'); main.className = 'srv-ch-main';
  var nm = document.createElement('span'); nm.className = 'srv-ch-name'; nm.textContent = ch.name;
  main.appendChild(nm);
  if(ch.topic){ var tp = document.createElement('span'); tp.className = 'srv-ch-topic'; tp.textContent = ch.topic; main.appendChild(tp); }
  var live = document.createElement('span'); live.className = 'srv-ch-live'; live.dataset.live = ch.id;
  b.appendChild(ic); b.appendChild(main); b.appendChild(live);
  b.addEventListener('click', function(){ openServerChannelEntry(ch); });
  row.appendChild(b);
  if(admin){
    var e = document.createElement('button');
    e.type = 'button'; e.className = 'srv-mini-btn srv-ch-edit'; e.textContent = '⋯';
    e.setAttribute('aria-label', t('servers.editChannel'));
    e.addEventListener('click', function(){ openServerSheet(serverId, ch, null); });
    row.appendChild(e);
  }
  return row;
}

function openServerChannelEntry(ch){
  activeServerChannelId = ch.id;
  document.querySelectorAll('.srv-ch').forEach(function(el){ el.classList.toggle('active', el.dataset.chid === ch.id); });
  if(ch.channel_type === 'voice') openVoiceRoom(ch); else openServerChannel(ch);
}

/* ---- pannello centrale: vuoto / chat / stanza vocale ---- */
function showSrvMain(which){
  var shell = document.getElementById('srvShell');
  if(!shell) return;
  var empty = document.getElementById('srvEmpty');
  var voice = document.getElementById('srvVoice');
  var detail = document.getElementById('channelDetailView');
  if(empty) empty.classList.toggle('hidden', which !== 'empty');
  if(voice) voice.classList.toggle('hidden', which !== 'voice');
  if(detail && channelDetailMounted) detail.classList.toggle('hidden', which !== 'chat');
  shell.setAttribute('data-view', which === 'empty' ? 'list' : which);
}

function setChannelComposeLocked(locked){
  var wrap = document.getElementById('channelComposeWrap');
  var note = document.getElementById('channelLockNote');
  if(wrap) wrap.classList.toggle('hidden', !!locked);
  if(note) note.classList.toggle('hidden', !locked);
}
function setChannelTopic(text){
  var el = document.getElementById('channelDetailTopic');
  if(!el) return;
  el.textContent = text || '';
  el.classList.toggle('hidden', !text);
}

function restoreChannelDetail(){
  var detail = document.getElementById('channelDetailView');
  var home = document.querySelector('[data-cpanel="channels"]');
  if(detail && home){ home.appendChild(detail); detail.classList.add('hidden'); }
  channelDetailMounted = false;
  currentChannelId = null;
  setChannelComposeLocked(false);
  setChannelTopic('');
}

function openServerChannel(ch){
  stopVoiceView();
  var detail = document.getElementById('channelDetailView');
  var main = document.getElementById('srvMain');
  if(!detail || !main) return;
  main.appendChild(detail);
  channelDetailMounted = true;
  currentChannelId = ch.id;
  currentChannelName = ch.name;
  document.getElementById('channelDetailName').textContent = (ch.emoji ? ch.emoji + ' ' : '#') + ch.name;
  setChannelTopic(ch.topic || '');
  setChannelComposeLocked(ch.channel_type === 'announce' && !isAdmin());
  showSrvMain('chat');
  loadChannelMessages();
}

function closeServerChannel(){
  stopVoiceView();
  if(channelDetailMounted) restoreChannelDetail();
  activeServerChannelId = null;
  document.querySelectorAll('.srv-ch.active').forEach(function(el){ el.classList.remove('active'); });
  showSrvMain('empty');
}

/* ---- creazione canale semplice (utenti normali, come prima) ---- */
function createServerChannel(serverId){
  if(!isSignedIn()){ openAuth('login'); return; }
  var input = document.getElementById('fNewServerChannelName');
  var name = input.value.trim();
  if(!name) return;
  fetch(SUPABASE_URL + '/rest/v1/channels', {
    method:'POST', headers: srvAuthHeaders(true),
    body: JSON.stringify({ name: name, created_by: currentUserId(), community_id: serverId })
  }).then(function(r){
    if(!r.ok) throw new Error('server channel insert failed');
    input.value = '';
    renderServerChannels(serverId);
  }).catch(function(e){ console.warn('Server channel create failed:', e); });
}

/* ---- admin: categorie ---- */
function addServerCategory(serverId){
  var name = window.prompt(t('servers.newCategoryPrompt'));
  if(!name || !name.trim()) return;
  var data = serverChannelsCache[serverId] || { cats:[] };
  fetch(SUPABASE_URL + '/rest/v1/channel_categories', {
    method:'POST', headers: srvAuthHeaders(true),
    body: JSON.stringify({ community_id: serverId, name: name.trim().toUpperCase().slice(0, 40), position: data.cats.length })
  }).then(function(r){
    if(!r.ok) throw new Error('category insert failed: ' + r.status);
    renderServerChannels(serverId);
  }).catch(function(e){ console.warn('Category create failed:', e); window.alert(t('servers.saveError')); });
}

function deleteServerCategory(serverId, cat){
  if(!window.confirm(t('servers.deleteCategoryConfirm').replace('{name}', cat.name))) return;
  fetch(SUPABASE_URL + '/rest/v1/channel_categories?id=eq.' + encodeURIComponent(cat.id), {
    method:'DELETE', headers: Object.assign(srvAuthHeaders(false), { 'Prefer':'return=representation' })
  }).then(function(r){
    if(!r.ok) throw new Error('category delete failed: ' + r.status);
    return r.json();
  }).then(function(rows){
    if(!rows.length) throw new Error('category delete: nessuna riga toccata (policy?)');
    renderServerChannels(serverId);
  }).catch(function(e){ console.warn('Category delete failed:', e); window.alert(t('servers.saveError')); });
}

/* ---- admin: scheda crea/modifica canale ---- */
function closeServerSheet(){
  var a = document.getElementById('srvScrim'); if(a) a.remove();
  var b = document.getElementById('srvSheet'); if(b) b.remove();
}

function openServerSheet(serverId, ch, presetCatId){
  closeServerSheet();
  var data = serverChannelsCache[serverId] || { cats:[], chs:[] };
  var editing = !!ch;
  var type = editing ? (ch.channel_type || 'text') : 'text';
  var selectedCat = editing ? (ch.category_id || '') : (presetCatId || '');

  var scrim = document.createElement('div');
  scrim.className = 'srv-scrim'; scrim.id = 'srvScrim';
  scrim.addEventListener('click', closeServerSheet);
  var sh = document.createElement('div');
  sh.className = 'srv-sheet'; sh.id = 'srvSheet';
  sh.setAttribute('role', 'dialog'); sh.setAttribute('aria-modal', 'true');
  sh.innerHTML =
    '<h3>' + t(editing ? 'servers.sheetEdit' : 'servers.sheetNew') + '</h3>' +
    '<div class="srv-f"><label>' + t('servers.typeLabel') + '</label>' +
      '<div class="srv-types" id="srvShTypes">' +
        '<button type="button" data-type="text"><b>#</b>' + t('servers.typeText') + '</button>' +
        '<button type="button" data-type="voice"><b>🔊</b>' + t('servers.typeVoice') + '</button>' +
        '<button type="button" data-type="announce"><b>📢</b>' + t('servers.typeAnnounce') + '</button>' +
      '</div></div>' +
    '<div class="srv-f"><label for="srvShName">' + t('servers.chName') + '</label><input id="srvShName" maxlength="40"></div>' +
    '<div class="srv-f"><label for="srvShEmoji">' + t('servers.chEmoji') + '</label><input id="srvShEmoji" maxlength="4"></div>' +
    '<div class="srv-f"><label for="srvShTopic">' + t('servers.chTopic') + '</label><input id="srvShTopic" maxlength="80"></div>' +
    '<div class="srv-f"><label for="srvShCat">' + t('servers.chCategory') + '</label><select id="srvShCat"></select></div>' +
    '<div class="form-error" id="srvShErr"></div>' +
    '<div class="srv-sheet-acts"></div>';
  document.body.appendChild(scrim);
  document.body.appendChild(sh);

  document.getElementById('srvShName').placeholder = t('servers.chNamePh');
  document.getElementById('srvShTopic').placeholder = t('servers.chTopicPh');
  if(editing){
    document.getElementById('srvShName').value = ch.name || '';
    document.getElementById('srvShEmoji').value = ch.emoji || '';
    document.getElementById('srvShTopic').value = ch.topic || '';
  }
  var sel = document.getElementById('srvShCat');
  var o0 = document.createElement('option'); o0.value = ''; o0.textContent = t('servers.uncategorized'); sel.appendChild(o0);
  data.cats.forEach(function(c){
    var o = document.createElement('option'); o.value = c.id; o.textContent = c.name; sel.appendChild(o);
  });
  sel.value = selectedCat;

  function paintTypes(){
    document.querySelectorAll('#srvShTypes button').forEach(function(b){
      b.setAttribute('aria-pressed', b.dataset.type === type ? 'true' : 'false');
    });
  }
  paintTypes();
  document.getElementById('srvShTypes').addEventListener('click', function(e){
    var b = e.target.closest('button'); if(!b) return;
    type = b.dataset.type; paintTypes();
  });

  var acts = sh.querySelector('.srv-sheet-acts');
  if(editing){
    var del = document.createElement('button');
    del.type = 'button'; del.className = 'btn btn-sm btn-ghost srv-danger'; del.textContent = t('servers.delete');
    del.addEventListener('click', function(){
      if(!window.confirm(t('servers.deleteChannelConfirm').replace('{name}', ch.name))) return;
      fetch(SUPABASE_URL + '/rest/v1/channels?id=eq.' + encodeURIComponent(ch.id), {
        method:'DELETE', headers: Object.assign(srvAuthHeaders(false), { 'Prefer':'return=representation' })
      }).then(function(r){ if(!r.ok) throw new Error('channel delete failed: ' + r.status); return r.json(); })
        .then(function(rows){
          if(!rows.length) throw new Error('channel delete: nessuna riga toccata (policy?)');
          if(activeServerChannelId === ch.id) closeServerChannel();
          closeServerSheet(); renderServerChannels(serverId);
        }).catch(function(e){ console.warn('Channel delete failed:', e); document.getElementById('srvShErr').textContent = t('servers.saveError'); });
    });
    acts.appendChild(del);
  }
  var cancel = document.createElement('button');
  cancel.type = 'button'; cancel.className = 'btn btn-sm btn-ghost'; cancel.textContent = t('servers.cancel');
  cancel.addEventListener('click', closeServerSheet);
  var ok = document.createElement('button');
  ok.type = 'button'; ok.className = 'btn btn-sm btn-primary'; ok.textContent = t(editing ? 'servers.save' : 'community.createChannel');
  ok.addEventListener('click', function(){
    var name = document.getElementById('srvShName').value.trim();
    var errEl = document.getElementById('srvShErr');
    errEl.textContent = '';
    if(!name){ document.getElementById('srvShName').focus(); return; }
    var payload = {
      name: name,
      emoji: document.getElementById('srvShEmoji').value.trim() || null,
      topic: document.getElementById('srvShTopic').value.trim() || null,
      channel_type: type,
      category_id: document.getElementById('srvShCat').value || null
    };
    ok.disabled = true;
    var req;
    if(editing){
      req = fetch(SUPABASE_URL + '/rest/v1/channels?id=eq.' + encodeURIComponent(ch.id), {
        method:'PATCH', headers: Object.assign(srvAuthHeaders(true), { 'Prefer':'return=representation' }), body: JSON.stringify(payload)
      }).then(function(r){
        if(!r.ok) throw new Error('channel update failed: ' + r.status);
        return r.json();
      }).then(function(rows){ if(!rows.length) throw new Error('channel update: nessuna riga toccata (policy?)'); });
    } else {
      payload.created_by = currentUserId();
      payload.community_id = serverId;
      req = fetch(SUPABASE_URL + '/rest/v1/channels', {
        method:'POST', headers: srvAuthHeaders(true), body: JSON.stringify(payload)
      }).then(function(r){ if(!r.ok) throw new Error('channel insert failed: ' + r.status); });
    }
    req.then(function(){ closeServerSheet(); renderServerChannels(serverId); })
      .catch(function(e){ ok.disabled = false; console.warn('Channel save failed:', e); errEl.textContent = t('servers.saveError'); });
  });
  acts.appendChild(cancel); acts.appendChild(ok);
  document.getElementById('srvShName').focus();
}

/* ---- stanza vocale: si vede chi c'è dentro (presenza), l'audio non esiste ---- */
function voiceSince(){ return new Date(Date.now() - 45000).toISOString(); }

function fetchVoicePresence(channelIds){
  if(!channelIds.length) return Promise.resolve([]);
  return fetch(SUPABASE_URL + '/rest/v1/voice_presence?channel_id=in.(' + channelIds.map(encodeURIComponent).join(',') +
      ')&last_seen=gt.' + encodeURIComponent(voiceSince()) + '&select=channel_id,user_id,display_name,avatar_url,muted&order=last_seen.asc',
      { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .catch(function(){ return []; });
}

function srvEscAttr(s){
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/'/g, '&#39;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function srvAvatarHtml(p, cls){
  if(p.avatar_url) return '<img class="' + cls + '" src="' + coverThumbUrl(srvEscAttr(p.avatar_url), 80) + '" alt="" loading="lazy">';
  return '<span class="' + cls + ' ' + cls + '-fb">' + escapeHtml((p.display_name || '?').charAt(0).toUpperCase()) + '</span>';
}

function refreshServerVoiceLive(serverId){
  var data = serverChannelsCache[serverId];
  if(!data) return;
  var ids = data.chs.filter(function(c){ return c.channel_type === 'voice'; }).map(function(c){ return c.id; });
  if(!ids.length) return;
  fetchVoicePresence(ids).then(function(rows){
    document.querySelectorAll('.srv-ch-live').forEach(function(el){
      var mine = rows.filter(function(r){ return r.channel_id === el.dataset.live; });
      el.innerHTML = mine.slice(0, 3).map(function(p){ return srvAvatarHtml(p, 'srv-live-av'); }).join('') +
        (mine.length > 3 ? '<span class="srv-live-more">+' + (mine.length - 3) + '</span>' : '');
    });
  });
}
function startServerLivePoll(serverId){
  stopServerLivePoll();
  serverLiveTimer = setInterval(function(){ if(!document.hidden) refreshServerVoiceLive(serverId); }, 20000);
}
function stopServerLivePoll(){ clearInterval(serverLiveTimer); serverLiveTimer = null; }

/* ---- Audio delle stanze vocali con Daily ----
   La chiave API di Daily non sta mai nel sito: la funzione Supabase "daily-room" controlla che tu sia
   loggato, prepara la stanza e ti dà un permesso d'ingresso. Il sito carica daily-js solo quando entri
   in una stanza. Se qualcosa non funziona (funzione non attiva, rete, microfono) resta la sola presenza. */
var DAILY_JS_SRC = 'daily-js.min.js';
var dailyLoadPromise = null;
var dailyDestroyPromise = Promise.resolve();

function loadDailyJs(){
  if(window.DailyIframe) return Promise.resolve(window.DailyIframe);
  if(dailyLoadPromise) return dailyLoadPromise;
  dailyLoadPromise = new Promise(function(resolve, reject){
    var s = document.createElement('script');
    s.src = DAILY_JS_SRC;
    s.onload = function(){
      if(window.DailyIframe) resolve(window.DailyIframe);
      else { dailyLoadPromise = null; reject(new Error('daily-js caricato ma DailyIframe non definito')); }
    };
    s.onerror = function(){ dailyLoadPromise = null; reject(new Error('daily-js non caricato')); };
    document.head.appendChild(s);
  });
  return dailyLoadPromise;
}

function requestDailyAccess(channelId, displayName){
  if(!getSession()) return Promise.reject(new Error('nessuna sessione'));
  return fetch(SUPABASE_URL + '/functions/v1/daily-room', {
    method:'POST', headers: srvAuthHeaders(true),
    body: JSON.stringify({ channel_id: channelId, display_name: displayName })
  }).then(function(r){
    if(!r.ok) throw new Error('daily-room ' + r.status);
    return r.json();
  }).then(function(d){
    if(!d || !d.url || !d.token) throw new Error('daily-room: risposta incompleta');
    return d;
  });
}

function destroyDailyFrame(){
  var f = voiceRoom.frame;
  voiceRoom.frame = null;
  voiceRoom.audio = false;
  if(!f) return;
  dailyDestroyPromise = Promise.resolve()
    .then(function(){ return f.destroy(); })
    .catch(function(e){ console.warn('Daily destroy:', e); });
}

function patchVoicePresence(fields){
  if(!voiceRoom.channelId || !isSignedIn()) return Promise.resolve();
  var body = Object.assign({ last_seen: new Date().toISOString() }, fields || {});
  return fetch(SUPABASE_URL + '/rest/v1/voice_presence?channel_id=eq.' + encodeURIComponent(voiceRoom.channelId) + '&user_id=eq.' + encodeURIComponent(currentUserId()), {
    method:'PATCH', headers: srvAuthHeaders(true), body: JSON.stringify(body)
  }).catch(function(){});
}

function startDailyCall(access){
  var chId = voiceRoom.channelId;
  var box = document.getElementById('voiceCall');
  if(!box) return Promise.reject(new Error('contenitore audio mancante'));
  return Promise.all([loadDailyJs(), dailyDestroyPromise]).then(function(res){
    var D = res[0];
    if(voiceRoom.channelId !== chId || !voiceRoom.joined) return; // nel frattempo sei uscito
    box.innerHTML = '';
    var frame = D.createFrame(box, {
      showLeaveButton: true,
      showFullscreenButton: false,
      iframeStyle: { width:'100%', height:'100%', border:'0' }
    });
    voiceRoom.frame = frame;
    voiceRoom.audio = true;
    renderVoiceLayout();
    frame.on('left-meeting', function(){
      if(voiceRoom.frame === frame) leaveVoicePresence(); // sei uscito dal pulsante di Daily: esci anche dalla stanza
    });
    frame.on('error', function(ev){ console.warn('Daily error:', ev); });
    frame.on('participant-updated', function(ev){
      var p = ev && ev.participant;
      if(!p || !p.local || typeof p.audio !== 'boolean') return;
      var muted = !p.audio;
      if(muted !== voiceRoom.muted){ voiceRoom.muted = muted; patchVoicePresence({ muted: muted }); }
    });
    return frame.join({ url: access.url, token: access.token, startVideoOff: true });
  });
}

function openVoiceRoom(ch){
  if(channelDetailMounted) restoreChannelDetail();
  stopVoiceView();
  var box = document.getElementById('srvVoice');
  if(!box) return;
  voiceRoom.channelId = ch.id;
  voiceRoom.channel = ch;
  voiceRoom.amIn = false;
  box.innerHTML =
    '<div class="srv-voice-top">' +
      '<button type="button" class="btn btn-ghost btn-sm srv-voice-back" id="btnVoiceBack">' + t('community.back') + '</button>' +
      '<h3 id="voiceTitle"></h3>' +
    '</div>' +
    '<p class="form-note srv-voice-note">' + t('servers.voiceNote') + '</p>' +
    '<div class="srv-voice-count" id="voiceCount"></div>' +
    '<div class="srv-people" id="voicePeople"></div>' +
    '<button type="button" class="btn btn-primary" id="btnVoiceJoin">' + t('servers.voiceJoin') + '</button>' +
    '<p class="form-note hidden" id="voiceConnecting">' + t('servers.voiceConnecting') + '</p>' +
    '<div class="srv-call hidden" id="voiceCall"></div>' +
    '<p class="form-note srv-voice-warn hidden" id="voiceWarn">' + t('servers.voiceNoAudio') + '</p>' +
    '<div class="srv-voice-bar hidden" id="voiceBar">' +
      '<button type="button" class="btn btn-ghost btn-sm" id="btnVoiceLeave">' + t('servers.voiceLeave') + '</button>' +
    '</div>';
  document.getElementById('voiceTitle').textContent = channelIconFor(ch) + ' ' + ch.name;
  document.getElementById('btnVoiceBack').addEventListener('click', closeServerChannel);
  document.getElementById('btnVoiceJoin').addEventListener('click', joinVoiceRoom);
  document.getElementById('btnVoiceLeave').addEventListener('click', leaveVoicePresence);
  showSrvMain('voice');
  renderVoiceLayout();
  renderVoiceRoom();
  voiceRoom.viewTimer = setInterval(function(){ if(!document.hidden) renderVoiceRoom(); }, 5000);
}

/* mostra/nasconde i pezzi della stanza in base allo stato (collegamento, in stanza, audio sì/no) */
function renderVoiceLayout(){
  function tog(id, hide){ var el = document.getElementById(id); if(el) el.classList.toggle('hidden', !!hide); }
  tog('btnVoiceJoin', voiceRoom.connecting || voiceRoom.joined || voiceRoom.amIn);
  tog('voiceConnecting', !voiceRoom.connecting);
  tog('voiceCall', !voiceRoom.audio);
  tog('voiceWarn', !(voiceRoom.joined && voiceRoom.audioFailed));
  tog('voiceBar', !(voiceRoom.joined && !voiceRoom.audio));
}

function renderVoiceRoom(){
  if(!voiceRoom.channelId) return;
  var chId = voiceRoom.channelId;
  fetchVoicePresence([chId]).then(function(rows){
    if(voiceRoom.channelId !== chId) return; // nel frattempo si è cambiato canale
    var people = document.getElementById('voicePeople');
    var count = document.getElementById('voiceCount');
    if(!people || !count) return;
    var me = currentUserId();
    voiceRoom.amIn = rows.some(function(r){ return r.user_id === me; });
    count.textContent = rows.length === 0 ? t('servers.voiceEmpty')
      : (rows.length === 1 ? t('servers.voiceCount1') : t('servers.voiceCountN').replace('{n}', rows.length));
    people.innerHTML = '';
    rows.forEach(function(p){
      var d = document.createElement('div');
      d.className = 'srv-person';
      d.innerHTML = srvAvatarHtml(p, 'srv-person-av') + '<span class="srv-person-name"></span>' + (p.muted ? '<em>' + t('servers.voiceMuted') + '</em>' : '');
      d.querySelector('.srv-person-name').textContent = p.user_id === me ? t('community.you') : (p.display_name || t('notif.someone'));
      people.appendChild(d);
    });
    renderVoiceLayout();
  });
}

function joinVoiceRoom(){
  if(!isSignedIn()){ openAuth('login'); return; }
  var chId = voiceRoom.channelId;
  if(!chId || voiceRoom.connecting || voiceRoom.joined) return;
  voiceRoom.connecting = true;
  voiceRoom.audioFailed = false;
  renderVoiceLayout();
  var nameStep = currentProfile !== null ? Promise.resolve(currentProfile) : loadOwnProfile().then(function(){ return currentProfile; });
  nameStep.then(function(profile){
    var name = publicDisplayName(profile);
    // se l'audio non è disponibile si entra comunque, solo come presenza
    return requestDailyAccess(chId, name)
      .catch(function(e){ console.warn('Audio Daily non disponibile:', e); return null; })
      .then(function(access){
        return fetch(SUPABASE_URL + '/rest/v1/voice_presence?on_conflict=channel_id,user_id', {
          method:'POST',
          headers: Object.assign(srvAuthHeaders(true), { 'Prefer':'resolution=merge-duplicates,return=minimal' }),
          body: JSON.stringify({
            channel_id: chId, user_id: currentUserId(), display_name: name,
            avatar_url: profile && profile.avatar_url ? profile.avatar_url : null,
            muted: false, last_seen: new Date().toISOString()
          })
        }).then(function(r){
          if(!r.ok) throw new Error('voice join failed: ' + r.status);
          return access;
        });
      });
  }).then(function(access){
    voiceRoom.connecting = false;
    if(voiceRoom.channelId !== chId){
      // nel frattempo hai lasciato la stanza: togli la riga appena creata
      fetch(SUPABASE_URL + '/rest/v1/voice_presence?channel_id=eq.' + encodeURIComponent(chId) + '&user_id=eq.' + encodeURIComponent(currentUserId()), {
        method:'DELETE', headers: srvAuthHeaders(false), keepalive: true
      }).catch(function(){});
      return;
    }
    voiceRoom.joined = true; voiceRoom.muted = false;
    clearInterval(voiceRoom.beatTimer);
    voiceRoom.beatTimer = setInterval(function(){ patchVoicePresence({}); }, 15000);
    renderVoiceLayout();
    renderVoiceRoom();
    if(!access){ voiceRoom.audioFailed = true; renderVoiceLayout(); return; }
    return startDailyCall(access).catch(function(e){
      console.warn('Audio Daily non partito:', e);
      destroyDailyFrame();
      voiceRoom.audioFailed = true;
      renderVoiceLayout();
    });
  }).catch(function(e){
    voiceRoom.connecting = false;
    renderVoiceLayout();
    console.warn('Voice join failed:', e);
    window.alert(t('servers.voiceJoinError'));
  });
}

function leaveVoicePresence(){
  destroyDailyFrame();
  clearInterval(voiceRoom.beatTimer); voiceRoom.beatTimer = null;
  var wasIn = voiceRoom.joined && voiceRoom.channelId && isSignedIn();
  var done = wasIn
    ? fetch(SUPABASE_URL + '/rest/v1/voice_presence?channel_id=eq.' + encodeURIComponent(voiceRoom.channelId) + '&user_id=eq.' + encodeURIComponent(currentUserId()), {
        method:'DELETE', headers: srvAuthHeaders(false), keepalive: true
      }).catch(function(){})
    : Promise.resolve();
  voiceRoom.joined = false; voiceRoom.muted = false; voiceRoom.audioFailed = false; voiceRoom.amIn = false;
  renderVoiceLayout();
  done.then(renderVoiceRoom); // dopo la cancellazione, così non ci si rivede ancora dentro per un attimo
}

function stopVoiceView(){
  destroyDailyFrame();
  clearInterval(voiceRoom.viewTimer); voiceRoom.viewTimer = null;
  clearInterval(voiceRoom.beatTimer); voiceRoom.beatTimer = null;
  if(voiceRoom.joined && voiceRoom.channelId && isSignedIn()){
    fetch(SUPABASE_URL + '/rest/v1/voice_presence?channel_id=eq.' + encodeURIComponent(voiceRoom.channelId) + '&user_id=eq.' + encodeURIComponent(currentUserId()), {
      method:'DELETE', headers: srvAuthHeaders(false), keepalive: true
    }).catch(function(){});
  }
  voiceRoom.joined = false; voiceRoom.muted = false; voiceRoom.connecting = false; voiceRoom.audioFailed = false;
  voiceRoom.amIn = false; voiceRoom.channelId = null; voiceRoom.channel = null;
}
window.addEventListener('pagehide', function(){ if(voiceRoom.joined) stopVoiceView(); });

/* ---- formattazione messaggi dei canali: **grassetto** *corsivo* ~~barrato~~ `codice` ```blocco``` > citazione ||spoiler|| ---- */
function renderRichBody(body){
  if(isGifUrl(body)) return renderBodyHtml(body);
  var blocks = [];
  var s = String(body == null ? '' : body).replace(/```([\s\S]*?)```/g, function(_, c){
    blocks.push(c.replace(/^\n/, '').replace(/\n$/, ''));
    return '\uE000' + (blocks.length - 1) + '\uE001';
  });
  s = escapeHtml(s);
  var inl = [];
  s = s.replace(/`([^`\n]+)`/g, function(_, c){ inl.push(c); return '\uE002' + (inl.length - 1) + '\uE003'; }); // il contenuto del codice non si formatta
  s = s.replace(/\*\*([^\s*](?:[^*\n]*[^\s*])?)\*\*/g, '<b>$1</b>');
  s = s.replace(/\*([^\s*](?:[^*\n]*[^\s*])?)\*/g, '<i>$1</i>');
  s = s.replace(/~~([^~\n]+)~~/g, '<s>$1</s>');
  s = s.replace(/\|\|([^|\n]+)\|\|/g, '<span class="sp" tabindex="0" role="button" aria-label="' + t('fmt.spoilerHint') + '">$1</span>');
  s = s.replace(/(^|\n)&gt; ?([^\n]*)/g, function(_, p, l){ return p + '<blockquote>' + l + '</blockquote>'; });
  s = s.replace(/<\/blockquote>\n/g, '</blockquote>');
  s = s.replace(/\uE002(\d+)\uE003/g, function(_, i){ return '<code>' + inl[+i] + '</code>'; });
  s = s.replace(/\uE000(\d+)\uE001/g, function(_, i){ return '<pre>' + escapeHtml(blocks[+i]) + '</pre>'; });
  return s;
}
document.addEventListener('click', function(e){
  var sp = e.target.closest && e.target.closest('.sp');
  if(sp) sp.classList.toggle('show');
});
document.addEventListener('keydown', function(e){
  if((e.key === 'Enter' || e.key === ' ') && e.target.classList && e.target.classList.contains('sp')){
    e.preventDefault(); e.target.classList.toggle('show');
  }
});

function initChannelComposerTools(){
  var tools = document.getElementById('channelFmtTools');
  var ta = document.getElementById('fChannelMessage');
  if(!tools || !ta || tools.dataset.ready) return;
  tools.dataset.ready = '1';
  var labels = { '**':'fmt.bold', '*':'fmt.italic', '~~':'fmt.strike', '`':'fmt.code', '||':'fmt.spoiler' };
  tools.querySelectorAll('button').forEach(function(b){
    var key = b.dataset.fmt ? labels[b.dataset.fmt] : 'fmt.quote';
    b.setAttribute('aria-label', t(key)); b.title = t(key);
  });
  function wrapSel(m){
    var s = ta.selectionStart, e = ta.selectionEnd, sel = ta.value.slice(s, e);
    ta.value = ta.value.slice(0, s) + m + sel + m + ta.value.slice(e);
    ta.focus(); ta.selectionStart = s + m.length; ta.selectionEnd = s + m.length + sel.length;
  }
  tools.addEventListener('click', function(e){
    var b = e.target.closest('button'); if(!b) return;
    if(b.dataset.fmt){ wrapSel(b.dataset.fmt); }
    else if(b.hasAttribute('data-quote')){
      var ls = ta.value.lastIndexOf('\n', ta.selectionStart - 1) + 1;
      ta.value = ta.value.slice(0, ls) + '> ' + ta.value.slice(ls);
      ta.focus();
    }
  });
}

function refreshServerJoinState(serverId, btn){
  if(!isSignedIn()){
    btn.textContent = t('servers.join');
    btn.classList.add('btn-primary');
    btn.onclick = function(){ openAuth('login'); };
    return;
  }
  var uid = currentUserId();
  fetch(SUPABASE_URL + '/rest/v1/community_members?community_id=eq.' + encodeURIComponent(serverId) + '&user_id=eq.' + encodeURIComponent(uid) + '&select=user_id', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      var joined = rows.length > 0;
      btn.textContent = joined ? t('servers.joined') : t('servers.join');
      btn.classList.toggle('btn-primary', !joined);
      btn.classList.toggle('btn-ghost', joined);
      btn.onclick = function(){ toggleServerMembership(serverId, joined, btn); };
    });
}

function toggleServerMembership(serverId, currentlyJoined, btn){
  var session = getSession();
  if(!session) return;
  var uid = currentUserId();
  btn.disabled = true;
  var req = currentlyJoined
    ? fetch(SUPABASE_URL + '/rest/v1/community_members?community_id=eq.' + encodeURIComponent(serverId) + '&user_id=eq.' + encodeURIComponent(uid), {
        method:'DELETE', headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
      })
    : fetch(SUPABASE_URL + '/rest/v1/community_members', {
        method:'POST',
        headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
        body: JSON.stringify({ community_id: serverId, user_id: uid })
      });
  req.then(function(r){
    if(!r.ok) throw new Error('join/leave server fallito');
    btn.disabled = false;
    refreshServerJoinState(serverId, btn);
    renderServerMembers(serverId);
  }).catch(function(e){ btn.disabled = false; console.warn('Server membership toggle failed:', e); });
}

function fetchServerMemberProfiles(serverId){
  var enc = encodeURIComponent(serverId);
  return fetch(SUPABASE_URL + '/rest/v1/community_members?community_id=eq.' + enc + '&select=user_id,profiles(id,display_name,avatar_url,verified,last_seen)', { headers: communityHeaders() })
    .then(function(r){
      if(!r.ok) throw new Error('members embed failed: ' + r.status);
      return r.json();
    })
    .then(function(rows){
      return rows.map(function(row){ return row.profiles || { id: row.user_id, display_name: null }; });
    })
    .catch(function(e){
      console.warn('Server members (embed) fallito, riprovo in due passaggi:', e);
      return fetch(SUPABASE_URL + '/rest/v1/community_members?community_id=eq.' + enc + '&select=user_id', { headers: communityHeaders() })
        .then(function(r){ if(!r.ok) throw new Error('members read failed: ' + r.status); return r.json(); })
        .then(function(rows){
          var ids = rows.map(function(x){ return x.user_id; });
          if(!ids.length) return [];
          return fetch(SUPABASE_URL + '/rest/v1/profiles?id=in.(' + ids.map(encodeURIComponent).join(',') + ')&select=id,display_name,avatar_url,verified,last_seen', { headers: communityHeaders() })
            .then(function(r){ return r.ok ? r.json() : []; })
            .then(function(ps){
              return ids.map(function(id){ return ps.filter(function(p){ return p.id === id; })[0] || { id: id, display_name: null }; });
            });
        });
    });
}

function renderServerMembers(serverId){
  var box = document.getElementById('serverMembersList');
  if(!box) return;
  box.innerHTML = '<p class="form-note">…</p>';
  fetchServerMemberProfiles(serverId)
    .then(function(profiles){
      box.innerHTML = '';
      if(profiles.length === 0){ box.innerHTML = '<p class="form-note">' + t('servers.noMembers') + '</p>'; return; }
      loadFriendshipMap().then(function(){
        var me = currentUserId();
        var on = [], off = [];
        profiles.forEach(function(p){ (isOnlineSince(p.last_seen) ? on : off).push(p); });
        function grp(label, list, cls){
          if(!list.length) return;
          var h = document.createElement('div');
          h.className = 'srv-mem-h';
          h.textContent = label + ' — ' + list.length;
          box.appendChild(h);
          list.forEach(function(p){
            var built = contattiCardRow(p, '');
            if(p.id !== me) built.actions.appendChild(contattiFriendButton(p.id, p.display_name, false));
            if(cls) built.row.classList.add(cls);
            box.appendChild(built.row);
          });
        }
        grp(t('userDir.online'), on, '');
        grp(t('userDir.offline'), off, 'srv-mem-off');
      });
    })
    .catch(function(e){
      box.innerHTML = '<p class="form-note">' + t('community.loadError') + '</p>';
      console.warn('Server members load failed:', e);
    });
}

/* ============ EVENTI (fiere, cinema, incontri) — countdown + traccia post-evento ============
   Nessuna riga viene mai davvero cancellata: una volta passata event_date,
   la card con il countdown sparisce solo lato client, sostituita da una
   riga "X ha partecipato..." per ciascuno che aveva detto "Ci sarò". */
var eventCountdownTimer = null;
// Gli eventi della home si scaricano una volta sola per pagina: prima ogni
// ridisegno del catalogo li richiedeva di nuovo (e con loro chi partecipa a
// ciascun evento), anche tre volte di fila all'apertura della home.
var _homeEventsPromise = null;
var _homeEventsScrolled = false;
function fetchHomeEventsOnce(){
  if(!_homeEventsPromise){
    _homeEventsPromise = fetch(SUPABASE_URL + '/rest/v1/community_events?select=*&order=event_date.asc', { headers: communityHeaders() })
      .then(function(r){ return r.ok ? r.json() : []; })
      .catch(function(e){ _homeEventsPromise = null; throw e; }); // se fallisce, al prossimo giro si riprova
  }
  return _homeEventsPromise;
}

/* Home: teaser dei prossimi 2 eventi, stessa card di Community → Eventi */
function renderHomeEvents(){
  var box = document.getElementById('homeEventsSection');
  var list = document.getElementById('homeEventsList');
  if(!box || !list) return;
  fetchHomeEventsOnce()
    .then(function(events){
      events = events.map(function(ev){ return luxLocalized(ev, ['title', 'description']); }); // v227: nella lingua di chi legge
      var now = new Date();
      var upcoming = events.filter(function(ev){ return !eventIsPast(ev, now); });
      if(upcoming.length === 0){ box.classList.add('hidden'); return; }
      box.classList.remove('hidden');
      // link condiviso (?event=<id>): l'evento indicato passa in cima, anche se non sarebbe tra i primi due
      var deepEventId = new URLSearchParams(window.location.search).get('event');
      // se eventi e lingua sono gli stessi dell'ultimo disegno, le schede restano
      // come sono (conto alla rovescia e "Ci sarò" compresi) invece di rifarle
      var sig = currentLang + '|' + (deepEventId || '') + '|' + upcoming.map(function(ev){ return ev.id + '@' + ev.event_date + '@' + (ev.end_date || '') + '@' + (ev.title || ''); }).join(',');
      if(list.dataset.sig === sig && list.children.length) return;
      list.dataset.sig = sig;
      list.innerHTML = '';
      if(deepEventId){
        var di = upcoming.findIndex(function(e){ return String(e.id) === deepEventId; });
        if(di > 0) upcoming.unshift(upcoming.splice(di, 1)[0]);
      }
      upcoming.slice(0, 2).forEach(function(ev){ list.appendChild(buildEventCard(ev)); });
      if(deepEventId){
        var focusCard = list.querySelector('[data-event-id="' + deepEventId.replace(/[^A-Za-z0-9_-]/g, '') + '"]');
        if(focusCard && !_homeEventsScrolled){
          _homeEventsScrolled = true; // si scorre fino all'evento una volta sola, non a ogni ridisegno
          focusCard.classList.add('event-card-focus');
          setTimeout(function(){
            try { focusCard.scrollIntoView({ block:'center', behavior: (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) ? 'auto' : 'smooth' }); } catch(e){}
          }, 250);
        }
      }
      if(upcoming.length > 2){
        var more = document.createElement('a');
        more.href = 'community.html#communitySection';
        more.className = 'server-channel-link';
        more.style.marginTop = '4px';
        more.textContent = t('events.seeAll');
        more.addEventListener('click', function(){ sessionStorage.setItem('lux_pending_community_tab', 'events'); });
        list.appendChild(more);
      }
      tickEventCountdowns();
      clearInterval(eventCountdownTimer);
      eventCountdownTimer = setInterval(tickEventCountdowns, 1000);
    })
    .catch(function(e){ console.warn('Home events load failed:', e); box.classList.add('hidden'); });
}

function renderEventsTab(){
  var upBox = document.getElementById('eventsUpcomingList');
  var pastBox = document.getElementById('eventsPastList');
  if(!upBox || !pastBox) return;
  upBox.innerHTML = '<p class="form-note">…</p>';
  pastBox.innerHTML = '';
  clearInterval(eventCountdownTimer);

  fetch(SUPABASE_URL + '/rest/v1/community_events?select=*&order=event_date.asc', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(events){
      events = events.map(function(ev){ return luxLocalized(ev, ['title', 'description']); }); // v227: nella lingua di chi legge
      var now = new Date();
      var upcoming = events.filter(function(ev){ return !eventIsPast(ev, now); });
      var past = events.filter(function(ev){ return eventIsPast(ev, now); })
        .sort(function(a,b){ return eventEndDate(b) - eventEndDate(a); });

      upBox.innerHTML = '';
      if(upcoming.length === 0){ upBox.innerHTML = '<p class="form-note">' + t('events.noUpcoming') + '</p>'; }
      upcoming.forEach(function(ev){ upBox.appendChild(buildEventCard(ev)); });

      if(upcoming.length > 0){
        tickEventCountdowns();
        eventCountdownTimer = setInterval(tickEventCountdowns, 1000);
      }

      if(past.length === 0){ pastBox.innerHTML = '<p class="form-note">' + t('events.noPast') + '</p>'; return; }
      renderEventTraces(pastBox, past.slice(0, 20));
    })
    .catch(function(e){
      upBox.innerHTML = '<p class="form-note">' + t('community.loadError') + '</p>';
      console.warn('Events load failed:', e);
    });
}

/* ---- Eventi di più giorni ----
   event_date = inizio; end_date (facoltativa) = fine. Senza fine l'evento dura fino all'inizio, come prima.
   "Passato" vuol dire: la fine è già trascorsa. */
function eventEndDate(ev){ return ev.end_date ? new Date(ev.end_date) : new Date(ev.event_date); }
function eventIsPast(ev, now){ return eventEndDate(ev) < (now || new Date()); }
function eventIsMultiDay(ev){
  if(!ev.end_date) return false;
  return new Date(ev.event_date).toDateString() !== new Date(ev.end_date).toDateString();
}
/* "28 ottobre 2026" · "12–13 dicembre 2026" · "28 ottobre – 1 novembre 2026" · "30 dicembre 2026 – 2 gennaio 2027" */
// creare un formattatore di date costa: prima se ne creava uno nuovo a ogni
// data mostrata (anche ogni secondo, col conto alla rovescia). Ora uno per tipo.
var _evFmtFull = null, _evFmtDayMonth = null;
function evFmtFull(d){ if(!_evFmtFull) _evFmtFull = new Intl.DateTimeFormat('it-IT', { day:'numeric', month:'long', year:'numeric' }); return _evFmtFull.format(d); }
function evFmtDayMonth(d){ if(!_evFmtDayMonth) _evFmtDayMonth = new Intl.DateTimeFormat('it-IT', { day:'numeric', month:'long' }); return _evFmtDayMonth.format(d); }
function eventDateParts(ev){
  var a = new Date(ev.event_date);
  if(!eventIsMultiDay(ev)){
    var one = evFmtFull(a);
    return { multi:false, label:one, startPart:one, endLabel:one };
  }
  var b = new Date(ev.end_date);
  var endLabel = evFmtFull(b);
  var startPart, label;
  if(a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth()){
    startPart = String(a.getDate());
    label = a.getDate() + '\u2013' + endLabel;
  } else if(a.getFullYear() === b.getFullYear()){
    startPart = evFmtDayMonth(a);
    label = startPart + ' \u2013 ' + endLabel;
  } else {
    startPart = evFmtFull(a);
    label = startPart + ' \u2013 ' + endLabel;
  }
  return { multi:true, label:label, startPart:startPart, endLabel:endLabel };
}
function formatEventDates(ev){ return eventDateParts(ev).label; }

/* ---- Condivisione eventi con anteprima social ----
   Ogni evento ha (dopo "Crea anteprima social" nel gestionale) una pagina e/<id>.html con i tag Open Graph:
   è quella che i social leggono per mostrare immagine, titolo, luogo e data. Se la pagina non c'è ancora si
   condivide il link semplice ?event=<id>, che apre comunque l'evento nel sito (con l'anteprima generica). */
var eventPreviewCache = {}; // id -> true/false: esiste la pagina e/<id>.html?
function checkEventPreview(id){
  if(eventPreviewCache[id] !== undefined) return Promise.resolve(eventPreviewCache[id]);
  return fetch(previewPagePath('e', id), { method:'HEAD', cache:'no-store' })
    .then(function(r){ eventPreviewCache[id] = r.ok; return r.ok; })
    .catch(function(){ eventPreviewCache[id] = false; return false; });
}

function shareEvent(ev){
  // la scelta dell'indirizzo è immediata (cache già riempita alla creazione della card): il foglio di condivisione
  // deve partire subito dal tocco, senza attese di rete, altrimenti iPhone lo blocca
  var url = eventPreviewCache[ev.id] === true
    ? previewPagePath('e', ev.id)
    : window.location.origin + '/?event=' + encodeURIComponent(ev.id);
  var d = new Date(ev.event_date);
  var dateLabel = isNaN(d.getTime()) ? '' : formatEventDates(ev);
  var text = ev.title + (ev.location ? ' — 📍 ' + ev.location : '') + (dateLabel ? ' · ' + dateLabel : '');
  if(luxShareMode()){ // v223
    openSharePanel({ title: ev.title, text: text, url: url, image: ev.image_url ? coverThumbUrl(ev.image_url, 160) : '', cover: ev.image_url || '', sub: dateLabel || t('share.tagline') });
    return;
  }
  if(navigator.share){
    navigator.share({ title: ev.title, text: text, url: url }).catch(function(){ /* annullato dall'utente, va bene così */ });
    return;
  }
  var full = text + '\n' + url;
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(full).then(function(){ alert(t('share.copied')); })
      .catch(function(){ alert(t('share.manual') + '\n\n' + full); });
  } else {
    alert(t('share.manual') + '\n\n' + full);
  }
}

function buildEventCard(ev){
  var card = document.createElement('div');
  card.className = 'event-card';
  card.dataset.eventId = String(ev.id);
  var dateLabel = formatEventDates(ev);
  card.innerHTML =
    (ev.image_url ? '<div class="event-img-wrap" style="--img-url:url(\'' + coverThumbUrl(escapeHtml(ev.image_url), 500) + '\')"><img class="event-img" src="' + coverThumbUrl(escapeHtml(ev.image_url), 500) + '" alt="" loading="lazy"></div>' : '') +
    '<div class="event-body">' +
      '<div class="event-title">' + escapeHtml(ev.title) + '</div>' +
      (ev.location ? '<div class="event-loc">📍 ' + escapeHtml(ev.location) + ' · ' + dateLabel + '</div>' : '<div class="event-loc">' + dateLabel + '</div>') +
      (ev.description ? '<div class="event-desc">' + escapeHtml(ev.description) + '</div>' : '') +
      '<div class="event-phase hidden" data-phase>' + t('events.liveEndsIn') + '</div>' +
      '<div class="countdown" data-target="' + new Date(ev.event_date).getTime() + '" data-end="' + eventEndDate(ev).getTime() + '">' +
        '<div class="cd-unit"><div class="cd-num" data-cd="d">–</div><div class="cd-label">' + t('events.days') + '</div></div>' +
        '<div class="cd-unit"><div class="cd-num" data-cd="h">–</div><div class="cd-label">' + t('events.hours') + '</div></div>' +
        '<div class="cd-unit"><div class="cd-num" data-cd="m">–</div><div class="cd-label">' + t('events.minutes') + '</div></div>' +
        '<div class="cd-unit"><div class="cd-num" data-cd="s">–</div><div class="cd-label">' + t('events.seconds') + '</div></div>' +
      '</div>' +
      '<div class="event-actions">' +
        '<div class="event-actions-main">' +
          '<button type="button" class="btn-attend" data-attend>' + t('events.attend') + '</button>' +
          '<button type="button" class="btn-share-event" data-share-event><span aria-hidden="true">↗</span> ' + t('share.button') + '</button>' +
        '</div>' +
        '<span class="attendee-count" data-count>…</span>' +
      '</div>' +
    '</div>';

  var attendBtn = card.querySelector('[data-attend]');
  var countEl = card.querySelector('[data-count]');
  refreshEventAttendState(ev.id, attendBtn, countEl);
  attendBtn.addEventListener('click', function(){ toggleEventAttendance(ev.id, attendBtn, countEl); });
  card.querySelector('[data-share-event]').addEventListener('click', function(){ shareEvent(ev); });
  checkEventPreview(ev.id); // riempie la cache in anticipo
  return card;
}

function tickEventCountdowns(){
  var now = Date.now();
  document.querySelectorAll('.countdown[data-target]').forEach(function(box){
    var start = parseInt(box.dataset.target, 10);
    var end = box.dataset.end ? parseInt(box.dataset.end, 10) : start;
    var multi = end > start;
    var live = multi && now >= start && now < end;   // evento iniziato e non ancora finito
    var target = (multi && now >= start) ? end : start;
    var diff = target - now;
    if(diff < 0) diff = 0;
    var phaseEl = box.parentNode && box.parentNode.querySelector('[data-phase]');
    if(phaseEl) phaseEl.classList.toggle('hidden', !live);
    var d = Math.floor(diff / 86400000);
    var h = Math.floor((diff % 86400000) / 3600000);
    var m = Math.floor((diff % 3600000) / 60000);
    var s = Math.floor((diff % 60000) / 1000);
    box.querySelector('[data-cd="d"]').textContent = d;
    box.querySelector('[data-cd="h"]').textContent = String(h).padStart(2,'0');
    box.querySelector('[data-cd="m"]').textContent = String(m).padStart(2,'0');
    box.querySelector('[data-cd="s"]').textContent = String(s).padStart(2,'0');
  });
}

function refreshEventAttendState(eventId, btn, countEl){
  fetch(SUPABASE_URL + '/rest/v1/event_attendees?event_id=eq.' + encodeURIComponent(eventId) + '&select=user_id', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      countEl.textContent = rows.length + ' ' + t('events.attendeeCount');
      var going = isSignedIn() && rows.some(function(r){ return r.user_id === currentUserId(); });
      btn.textContent = going ? t('events.going') : t('events.attend');
      btn.classList.toggle('going', going);
    })
    .catch(function(){});
}

function toggleEventAttendance(eventId, btn, countEl){
  if(!isSignedIn()){ openAuth('login'); return; }
  var session = getSession();
  var uid = currentUserId();
  var wasGoing = btn.classList.contains('going');
  btn.disabled = true;
  var req = wasGoing
    ? fetch(SUPABASE_URL + '/rest/v1/event_attendees?event_id=eq.' + encodeURIComponent(eventId) + '&user_id=eq.' + encodeURIComponent(uid), {
        method:'DELETE', headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
      })
    : fetch(SUPABASE_URL + '/rest/v1/event_attendees', {
        method:'POST',
        headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
        body: JSON.stringify({ event_id: eventId, user_id: uid })
      });
  req.then(function(r){
    if(!r.ok) throw new Error('event attendance toggle failed');
    btn.disabled = false;
    refreshEventAttendState(eventId, btn, countEl);
  }).catch(function(e){ btn.disabled = false; console.warn('Event attendance toggle failed:', e); });
}

function renderEventTraces(box, pastEvents){
  box.innerHTML = '';
  var myId = currentUserId();
  pastEvents.forEach(function(ev){
    Promise.all([
      fetch(SUPABASE_URL + '/rest/v1/event_attendees?event_id=eq.' + encodeURIComponent(ev.id) + '&select=user_id,profiles(display_name)', { headers: communityHeaders() }).then(function(r){ return r.ok ? r.json() : []; }),
      fetch(SUPABASE_URL + '/rest/v1/event_photos?event_id=eq.' + encodeURIComponent(ev.id) + '&select=*&order=created_at.asc', { headers: communityHeaders() }).then(function(r){ return r.ok ? r.json() : []; })
    ]).then(function(results){
      var attendees = results[0], photos = results[1];
      if(attendees.length === 0 && photos.length === 0) return;
      var dp = eventDateParts(ev);
      var when = dp.multi ? (t('events.traceFrom') + ' ' + dp.startPart + ' ' + t('events.traceTo') + ' ' + dp.endLabel) : (t('events.traceOn') + ' ' + dp.label);
      var linesHtml = attendees.map(function(row){
        var name = (row.profiles && row.profiles.display_name) || t('notif.someone');
        var traceText = t('events.traceHasAttended') + ' <b>' + escapeHtml(ev.title) + '</b> ' + when +
          (ev.location ? ' ' + t('events.traceAt') + ' ' + escapeHtml(ev.location) : '') + '.';
        return '<div class="event-trace"><span class="trace-icon">🎟️</span><span class="trace-text"><b>' + escapeHtml(name) + '</b> ' + traceText + '</span></div>';
      }).join('');
      var iAttended = !!(myId && attendees.some(function(a){ return a.user_id === myId; }));
      var photosHtml = photos.map(function(p){
        return '<div class="event-photo"><img src="' + coverThumbUrl(escapeHtml(p.image_url), 240) + '" alt="" loading="lazy"></div>';
      }).join('');
      var addHtml = iAttended
        ? '<label class="event-photo-add" for="evPhotoInput-' + escapeHtml(ev.id) + '">+<span>' + t('events.addPhoto') + '</span></label>' +
          '<input type="file" id="evPhotoInput-' + escapeHtml(ev.id) + '" accept="image/*" class="hidden" data-event-photo-input="' + escapeHtml(ev.id) + '">'
        : '';
      var wrap = document.createElement('div');
      wrap.className = 'event-trace-group';
      wrap.innerHTML = linesHtml + ((photos.length || iAttended) ? ('<div class="event-gallery" data-event-photos="' + escapeHtml(ev.id) + '">' + photosHtml + addHtml + '</div>') : '');
      box.appendChild(wrap);
      var fileInput = wrap.querySelector('[data-event-photo-input]');
      if(fileInput){
        fileInput.addEventListener('change', function(){
          uploadEventPhoto(ev.id, fileInput, wrap.querySelector('[data-event-photos]'));
        });
      }
    }).catch(function(){});
  });
}

function uploadEventPhoto(eventId, fileInput, galleryEl){
  var session = getSession();
  var file = fileInput.files[0];
  if(!session || !file) return;
  var path = Date.now() + '-' + file.name.replace(/[^a-zA-Z0-9.\-]/g, '_');
  fetch(SUPABASE_URL + '/storage/v1/object/event-photos/' + path, {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type': file.type || 'image/jpeg' },
    body: file
  }).then(function(r){
    if(!r.ok) throw new Error('upload foto evento fallito: ' + r.status);
    var url = SUPABASE_URL + '/storage/v1/object/public/event-photos/' + path;
    return fetch(SUPABASE_URL + '/rest/v1/event_photos', {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'return=representation' },
      body: JSON.stringify({ event_id: eventId, user_id: currentUserId(), image_url: url })
    });
  }).then(function(r){
    if(!r.ok) throw new Error('salvataggio foto evento fallito: ' + r.status);
    return r.json();
  }).then(function(rows){
    var p = rows[0];
    if(!p) throw new Error('nessuna riga salvata: manca il permesso (hai confermato "Ci sarò" a questo evento?)');
    var div = document.createElement('div');
    div.className = 'event-photo';
    div.innerHTML = '<img src="' + coverThumbUrl(escapeHtml(p.image_url), 240) + '" alt="" loading="lazy">';
    var addLabel = galleryEl.querySelector('.event-photo-add');
    if(addLabel) galleryEl.insertBefore(div, addLabel); else galleryEl.appendChild(div);
    fileInput.value = '';
  }).catch(function(e){
    console.warn('Foto evento non caricata:', e);
    window.alert('Non è stato possibile caricare la foto (' + e.message + ').');
    fileInput.value = '';
  });
}

function renderCollabWorksTab(){
  var grid = document.getElementById('collabWorksGrid');
  if(!grid) return;
  var items = getCatalog().filter(function(i){
    return ((i.collaborators && i.collaborators.length > 0) || i.collaborator_name) && matureOk(i);
  });
  items.sort(function(a,b){ return (b.date||'').localeCompare(a.date||''); });
  grid.innerHTML = '';
  if(items.length === 0){
    var empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.style.gridColumn = '1/-1';
    empty.textContent = t('collab.noWorks'); // prima: "— Tutti —", che qui non voleva dire niente
    grid.appendChild(empty);
    return;
  }
  items.forEach(function(item){
    var card = document.createElement('div');
    card.className = 'card-idx';
    card.setAttribute('data-character', item.character || '');
    var badge = item.mature ? '<span class="mature">18+</span>' : '<span class="allages">'+t('badge.allages')+'</span>';
    var coverInner = item.cover_url
      ? '<img class="cover-img" src="'+coverThumbUrl(item.cover_url, 500)+'" data-fallback="'+escapeHtml(item.cover_url)+'" alt="" loading="lazy" decoding="async" onload="this.style.opacity=1">'
      : '<span class="init">'+item.character.charAt(0)+'</span>';
    var collabArr = (item.collaborators && item.collaborators.length)
      ? item.collaborators
      : (item.collaborator_name ? [{ name:item.collaborator_name }] : []);
    var collabNames = collabArr.map(function(c){ return c.name; }).join(', ');
    card.innerHTML =
      '<div class="card-idx-cover">'+coverInner+badge+'</div>'+
      '<div class="card-idx-body" style="cursor:pointer;" data-open="'+item.id+'">'+
        '<div class="num mono">'+(item.issue||'')+'</div>'+
        '<h4>'+escapeHtml(item.title)+'</h4>'+
        '<div class="character">'+t('collab.credit')+' '+escapeHtml(collabNames)+'</div>'+
        '<div class="meta-row"><span>'+(item.date||'')+'</span></div>'+
      '</div>';
    card.querySelector('[data-open]').addEventListener('click', function(){ openTitleModal(item); });
    grid.appendChild(card);
    attachCoverSignature(card.querySelector('.card-idx-cover'), item);
  });
}

/* ============ DIARIO (post utente: foto / stato d'animo / nota) ============ */
var diaryActiveKind = 'photo';
var diaryActiveFilter = 'all';
var diaryAuthorFilter = null; // {id, name} — impostato toccando il nome di un autore su un post

function switchDiaryKind(kind){
  diaryActiveKind = kind;
  document.querySelectorAll('.diary-kind-tab').forEach(function(btn){
    btn.classList.toggle('active', btn.dataset.dkind === kind);
  });
  document.querySelectorAll('.diary-form').forEach(function(f){
    f.classList.toggle('hidden', f.dataset.dform !== kind);
  });
}

function switchDiaryFilter(kind){
  diaryActiveFilter = kind;
  diaryAuthorFilter = null; // cambiare categoria a mano annulla il filtro per persona
  document.querySelectorAll('.diary-filter-btn').forEach(function(btn){
    btn.classList.toggle('active', btn.dataset.dfilter === kind);
  });
  var authorBtn = document.getElementById('diaryFilterAuthorBtn');
  if(authorBtn) authorBtn.classList.add('hidden');
  loadDiaryFeed();
}

function filterDiaryByAuthor(userId, name){
  diaryAuthorFilter = { id: userId, name: name };
  document.querySelectorAll('.diary-filter-btn').forEach(function(btn){ btn.classList.remove('active'); });
  var authorBtn = document.getElementById('diaryFilterAuthorBtn');
  if(authorBtn){
    authorBtn.textContent = t('diary.filterBy').replace('{name}', name);
    authorBtn.classList.remove('hidden');
    authorBtn.classList.add('active');
  }
  loadDiaryFeed();
}

function uploadDiaryPhoto(file){
  var session = getSession();
  var extMatch = /\.([a-zA-Z0-9]+)$/.exec(file.name || '');
  var ext = extMatch ? extMatch[1].toLowerCase() : 'jpg';
  var path = 'posts/' + currentUserId() + '/' + Date.now() + '_' + Math.random().toString(36).slice(2,8) + '.' + ext;
  return fetch(SUPABASE_URL + '/storage/v1/object/comic-pages/' + path, {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type': file.type || 'image/jpeg' },
    body: file
  }).then(function(r){
    if(!r.ok) throw new Error('diary photo upload failed: ' + r.status);
    return SUPABASE_URL + '/storage/v1/object/public/comic-pages/' + path;
  });
}

function submitDiaryPost(){
  if(!isSignedIn()){ openAuth('login'); return; }
  var err = document.getElementById('diaryComposerError');
  err.textContent = '';
  var session = getSession();
  var kind = diaryActiveKind;
  var btn = document.getElementById('btnDiaryPublish');

  var payloadStep;
  if(kind === 'photo'){
    var file = document.getElementById('fDiaryPhoto').files[0];
    var caption = document.getElementById('fDiaryPhotoCaption').value.trim();
    if(!file){ err.textContent = t('diary.needPhoto'); return; }
    btn.disabled = true;
    payloadStep = uploadDiaryPhoto(file).then(function(url){
      return { kind:'photo', body: caption || null, image_url: url };
    });
  } else if(kind === 'mood'){
    var moodBtn = document.querySelector('.diary-mood-btn.active');
    var moodText = document.getElementById('fDiaryMoodText').value.trim();
    if(!moodBtn){ err.textContent = t('diary.needMood'); return; }
    btn.disabled = true;
    var body = moodBtn.dataset.mood + (moodText ? ' ' + moodText : '');
    payloadStep = Promise.resolve({ kind:'mood', body: body, image_url: null });
  } else {
    var noteText = document.getElementById('fDiaryNote').value.trim();
    if(!noteText){ err.textContent = t('err.required'); return; }
    btn.disabled = true;
    payloadStep = Promise.resolve({ kind:'note', body: noteText, image_url: null });
  }

  payloadStep.then(function(payload){
    // la pagina profilo è sempre di una persona precisa, letta dall'indirizzo:
    // è LA SUA bacheca il bersaglio del post, anche quando scrive qualcun altro
    var wallUserId = new URLSearchParams(window.location.search).get('user') || currentUserId();
    payload.user_id = wallUserId;
    payload.author_id = currentUserId();
    return fetch(SUPABASE_URL + '/rest/v1/user_posts', {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'return=representation' },
      body: JSON.stringify(payload)
    });
  }).then(function(r){
    if(!r.ok) throw new Error('post insert failed: ' + r.status);
    document.getElementById('fDiaryPhoto').value = '';
    document.getElementById('fDiaryPhotoCaption').value = '';
    document.getElementById('fDiaryMoodText').value = '';
    document.getElementById('fDiaryNote').value = '';
    document.querySelectorAll('.diary-mood-btn').forEach(function(b){ b.classList.remove('active'); });
    // sul profilo la bacheca è #profileDiaryFeed (quella della persona aperta), in Community #diaryFeed
    if(document.getElementById('profileDiaryFeed')) loadDiaryFeed('profileDiaryFeed', new URLSearchParams(window.location.search).get('user') || currentUserId());
    else loadDiaryFeed();
  }).catch(function(e){
    console.warn('Diary post failed:', e);
    err.textContent = t('diary.publishError');
  }).then(function(){ btn.disabled = false; });
}

function loadDiaryFeed(containerId, forcedUserId){
  containerId = containerId || 'diaryFeed';
  var feed = document.getElementById(containerId);
  if(!feed) return;
  feed.innerHTML = '<p class="form-note">…</p>';
  var url = SUPABASE_URL + '/rest/v1/user_posts?select=*&order=created_at.desc&limit=60';
  if(forcedUserId){
    url += '&user_id=eq.' + encodeURIComponent(forcedUserId);
  } else {
    if(diaryActiveFilter !== 'all') url += '&kind=eq.' + encodeURIComponent(diaryActiveFilter);
    if(diaryAuthorFilter) url += '&user_id=eq.' + encodeURIComponent(diaryAuthorFilter.id);
  }
  fetch(url, { headers: communityHeaders() })
    .then(function(r){ if(!r.ok) throw new Error('diary feed read failed'); return r.json(); })
    .then(function(rows){ renderDiaryFeed(rows, containerId); })
    .catch(function(e){ feed.innerHTML = '<p class="form-note">' + t('community.loadError') + '</p>'; console.warn('Diary feed load failed:', e); });
}

function renderDiaryFeed(posts, containerId){
  containerId = containerId || 'diaryFeed';
  var feed = document.getElementById(containerId);
  if(!feed) return;
  feed.innerHTML = '';
  if(posts.length === 0){
    feed.innerHTML = '<p class="form-note">' + t('diary.empty') + '</p>';
    return;
  }
  if(!feed.dataset.authorClickWired){
    feed.dataset.authorClickWired = '1';
    feed.addEventListener('click', function(e){
      var authorBtn = e.target.closest('[data-author]');
      if(authorBtn) window.location.href = 'profile.html?user=' + encodeURIComponent(authorBtn.dataset.author);
    });
  }
  posts.forEach(function(p){
    // author_id è chi ha scritto per davvero (può differire da user_id quando è
    // un post lasciato sulla bacheca di un altro); sui post più vecchi, da prima
    // che questa colonna esistesse, ripiega su user_id — post "di sé", come sempre
    var authorId = p.author_id || p.user_id;
    var card = document.createElement('div');
    card.className = 'diary-post';
    card.dataset.postId = p.id;
    card.dataset.postOwner = p.user_id || ''; // NON data-author: il clic su [data-author] apre il profilo
    card.dataset.postAuthor = authorId || '';
    var uidNow = currentUserId();
    var canDelete = isSignedIn() && (authorId === uidNow || p.user_id === uidNow || isAdmin());
    var kindIcon = p.kind === 'photo' ? '📷' : (p.kind === 'mood' ? '🙂' : '📝');
    var mediaHtml = p.image_url ? '<img class="diary-post-img" src="'+coverThumbUrl(escapeHtml(p.image_url), 700)+'" alt="" loading="lazy">' : '';
    var bodyHtml = p.body ? '<div class="diary-post-body">'+renderBodyHtml(p.body)+'</div>' : '';
    card.innerHTML =
      '<div class="diary-post-head">'+
        '<button type="button" class="diary-post-author" data-author="'+authorId+'">'+t('notif.someone')+'</button>'+
        '<span class="diary-post-kind">'+kindIcon+'</span>'+
        '<span class="diary-post-when">'+notifTimeAgo(p.created_at)+'</span>'+
        (canDelete ? '<button type="button" class="lux-del-btn diary-post-del" data-del-post="'+p.id+'">'+t('common.delete')+'</button>' : '')+
      '</div>'+
      mediaHtml + bodyHtml +
      '<div class="diary-post-actions">'+
        '<button type="button" class="diary-like-btn" data-like="'+p.id+'">♡ <span class="cnt">'+(p.like_count||0)+'</span></button>'+
        '<button type="button" class="diary-comment-toggle" data-comments="'+p.id+'">💬 <span class="cnt">'+(p.comment_count||0)+'</span></button>'+
      '</div>'+
      '<div class="diary-comments hidden" id="diaryComments_'+p.id+'"></div>';

    getDisplayName(authorId).then(function(name){
      var authorBtn = card.querySelector('[data-author]');
      if(authorBtn) authorBtn.textContent = name;
    });

    card.querySelector('[data-like]').addEventListener('click', function(){ toggleDiaryLike(p.id, this); });
    var delPost = card.querySelector('[data-del-post]');
    if(delPost) delPost.addEventListener('click', function(){
      if(!window.confirm(t('del.confirmPost'))) return;
      delPost.disabled = true;
      luxDelete('user_posts?id=eq.' + encodeURIComponent(p.id)).then(function(){
        card.remove();
        if(!feed.querySelector('.diary-post')) feed.innerHTML = '<p class="form-note">' + t('diary.empty') + '</p>';
      }).catch(function(err){ delPost.disabled = false; luxDeleteFail(err); });
    });
    card.querySelector('[data-comments]').addEventListener('click', function(){ toggleDiaryComments(p.id); });

    feed.appendChild(card);
  });

  if(isSignedIn() && posts.length){
    var ids = posts.map(function(p){ return p.id; }).join(',');
    fetch(SUPABASE_URL + '/rest/v1/post_likes?select=post_id&user_id=eq.'+encodeURIComponent(currentUserId())+'&post_id=in.('+ids+')', { headers: communityHeaders() })
      .then(function(r){ return r.ok ? r.json() : []; })
      .then(function(rows){
        rows.forEach(function(row){
          var btn = feed.querySelector('[data-like="'+row.post_id+'"]');
          if(btn){
            var cnt = btn.querySelector('.cnt').textContent;
            btn.classList.add('active');
            btn.innerHTML = '♥ <span class="cnt">'+cnt+'</span>';
          }
        });
      }).catch(function(){});
  }
}

function toggleDiaryLike(postId, btnEl){
  if(!isSignedIn()){ openAuth('login'); return; }
  var session = getSession();
  var isLiked = btnEl.classList.contains('active');
  var req = isLiked
    ? fetch(SUPABASE_URL + '/rest/v1/post_likes?user_id=eq.'+encodeURIComponent(currentUserId())+'&post_id=eq.'+encodeURIComponent(postId), {
        method:'DELETE', headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
      })
    : fetch(SUPABASE_URL + '/rest/v1/post_likes', {
        method:'POST',
        headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
        body: JSON.stringify({ user_id: currentUserId(), post_id: postId })
      });
  req.then(function(r){
    if(!r.ok) throw new Error('post like toggle failed');
    var cntEl = btnEl.querySelector('.cnt');
    var cnt = parseInt(cntEl.textContent, 10) || 0;
    cnt = isLiked ? Math.max(cnt - 1, 0) : cnt + 1;
    btnEl.classList.toggle('active', !isLiked);
    btnEl.innerHTML = (isLiked ? '♡ ' : '♥ ') + '<span class="cnt">'+cnt+'</span>';
  }).catch(function(e){ console.warn('Post like toggle failed:', e); luxToast(t('net.actionFailed')); });
}

function toggleDiaryComments(postId){
  var box = document.getElementById('diaryComments_' + postId);
  if(!box) return;
  var willShow = box.classList.contains('hidden');
  box.classList.toggle('hidden');
  if(willShow && !box.dataset.loaded){
    box.dataset.loaded = '1';
    loadDiaryComments(postId, box);
  }
}

function loadDiaryComments(postId, box){
  box.innerHTML = '<p class="form-note">…</p>';
  fetch(SUPABASE_URL + '/rest/v1/post_comments?post_id=eq.'+encodeURIComponent(postId)+'&select=*&order=created_at.asc', { headers: communityHeaders() })
    .then(function(r){ if(!r.ok) throw new Error('post comments read failed'); return r.json(); })
    .then(function(rows){
      var list = document.createElement('div');
      list.className = 'diary-comments-list';
      if(rows.length === 0){
        list.innerHTML = '<p class="form-note">' + t('comments.empty') + '</p>';
      } else {
        var postCard = document.querySelector('.diary-post[data-post-id="'+postId+'"]');
        var uidNow = currentUserId();
        var ownsPost = !!(postCard && uidNow && (postCard.dataset.postOwner === uidNow || postCard.dataset.postAuthor === uidNow));
        rows.forEach(function(c){
          var div = document.createElement('div');
          div.className = 'comment-item';
          div.innerHTML = '<span class="author">'+escapeHtml(c.author_name || t('notif.someone'))+'</span><div class="body">'+renderBodyHtml(c.body)+'</div>';
          if(isSignedIn() && c.id && (c.user_id === uidNow || ownsPost || isAdmin())){
            var delC = document.createElement('button');
            delC.type = 'button';
            delC.className = 'lux-del-btn comment-del-btn';
            delC.textContent = t('common.delete');
            delC.addEventListener('click', function(){
              if(!window.confirm(t('del.confirmComment'))) return;
              delC.disabled = true;
              luxDelete('post_comments?id=eq.' + encodeURIComponent(c.id)).then(function(){
                loadDiaryComments(postId, box);
                var cntEl = postCard && postCard.querySelector('[data-comments] .cnt');
                if(cntEl) cntEl.textContent = Math.max(0, (parseInt(cntEl.textContent, 10) || 0) - 1);
              }).catch(function(err){ delC.disabled = false; luxDeleteFail(err); });
            });
            div.appendChild(delC);
          }
          list.appendChild(div);
        });
      }
      box.innerHTML = '';
      box.appendChild(list);
      if(isSignedIn()){
        box.insertAdjacentHTML('beforeend',
          '<div class="diary-comment-form"><input type="text" class="diary-comment-input" maxlength="300" placeholder="'+t('comments.placeholder')+'"><button type="button" class="btn btn-sm btn-ghost diary-comment-send">'+t('community.send')+'</button></div>');
        var input = box.querySelector('.diary-comment-input');
        var sendBtn = box.querySelector('.diary-comment-send');
        sendBtn.addEventListener('click', function(){ submitDiaryComment(postId, input, box); });
        input.addEventListener('keydown', function(e){ if(e.key === 'Enter') submitDiaryComment(postId, input, box); });
      }
    })
    .catch(function(e){ box.innerHTML = '<p class="form-note">' + t('community.loadError') + '</p>'; console.warn('Post comments load failed:', e); });
}

function submitDiaryComment(postId, input, box){
  var body = input.value.trim();
  if(!body) return;
  if(!isSignedIn()){ openAuth('login'); return; }
  var session = getSession();
  var nameStep = currentProfile !== null ? Promise.resolve(currentProfile) : loadOwnProfile().then(function(){ return currentProfile; });
  nameStep.then(function(profile){
    var authorName = publicDisplayName(profile);
    return fetch(SUPABASE_URL + '/rest/v1/post_comments', {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
      body: JSON.stringify({ post_id: postId, user_id: currentUserId(), author_name: authorName, body: body })
    });
  }).then(function(r){
    if(!r.ok) throw new Error('post comment insert failed');
    input.value = '';
    box.dataset.loaded = '';
    loadDiaryComments(postId, box);
    var card = document.querySelector('.diary-post[data-post-id="'+postId+'"]');
    if(card){
      var cntEl = card.querySelector('[data-comments] .cnt');
      if(cntEl) cntEl.textContent = (parseInt(cntEl.textContent,10)||0) + 1;
    }
  }).catch(function(e){ console.warn('Post comment submit failed:', e); luxToast(t('comments.sendError')); });
}

/* ============ PROFILO PUBBLICO (profile.html?user=<id>) ============ */
function renderPublicProfilePage(){
  var section = document.getElementById('profileSection');
  if(!section) return; // non siamo su profile.html
  var params = new URLSearchParams(window.location.search);
  var userId = params.get('user');
  var notFoundBox = document.getElementById('profileNotFound');
  var layoutBox = document.getElementById('profileLayout');
  var titlesBox = document.getElementById('profileTitlesBox');
  if(!userId){ notFoundBox.classList.remove('hidden'); return; }

  fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(userId) + '&select=*', { headers: communityHeaders() })
    .then(function(r){ if(!r.ok) throw new Error('profile read failed'); return r.json(); })
    .then(function(rows){
      var p = rows[0];
      if(!p){ notFoundBox.classList.remove('hidden'); return; }
      layoutBox.classList.remove('hidden');

      var isOwnPage = isSignedIn() && currentUserId() === userId;
      document.getElementById('pubProfileName').textContent = p.display_name || (isOwnPage ? t('profile.noNameYet') : t('notif.someone'));
      var bannerImg = document.getElementById('pubProfileBanner');
      bannerImg.src = p.banner_url || '';
      bannerImg.style.opacity = p.banner_url ? '1' : '0';
      var avatarImg = document.getElementById('pubProfileAvatar');
      avatarImg.src = p.avatar_url || '';
      avatarImg.style.opacity = p.avatar_url ? '1' : '0.15';
      avatarImg.classList.add('avatar-clickable');
      avatarImg.addEventListener('click', function(){ openAvatarInfo(userId); });
      if(p.bio) document.getElementById('pubProfileBio').textContent = p.bio;

      var socialDefs = [
        { key:'social_instagram', label:'Instagram' },
        { key:'social_twitter', label:'Twitter/X' },
        { key:'social_tiktok', label:'TikTok' },
        { key:'social_website', label: t('profile.website') }
      ];
      var socialsHtml = socialDefs.filter(function(s){ return p[s.key]; }).map(function(s){
        var raw = p[s.key];
        var href = /^https?:\/\//i.test(raw) ? raw : ('https://' + raw.replace(/^@/, ''));
        return '<a class="pub-profile-social-pill" href="' + escapeHtml(href) + '" target="_blank" rel="noopener">' + escapeHtml(s.label) + '</a>';
      }).join('');
      document.getElementById('pubProfileSocials').innerHTML = socialsHtml;

      var metaParts = [];
      metaParts.push(verifiedBadge('verified.commenter', !!p.verified));
      if(p.created_at){
        var joined = new Date(p.created_at);
        if(!isNaN(joined)) metaParts.push('<span class="pub-profile-joined">' + t('pubProfile.memberSince').replace('{date}', joined.toLocaleDateString()) + '</span>');
      }
      document.getElementById('pubProfileMeta').innerHTML = metaParts.join(' ');

      var favs = p.favorite_characters || [];
      var favsBox = document.getElementById('pubProfileFavs');
      favsBox.innerHTML = favs.map(function(f){ return '<span class="pub-profile-fav-tag">' + escapeHtml(f) + '</span>'; }).join('');

      var isOwn = isSignedIn() && currentUserId() === userId;
      var titlesCount = getCatalog().filter(function(i){ return i.created_by === userId && matureOk(i); }).length;
      var statTitlesEl = document.getElementById('profileStatTitles');
      if(statTitlesEl) statTitlesEl.textContent = String(titlesCount);

      fetch(SUPABASE_URL + '/rest/v1/friendships?select=id&status=eq.accepted&or=(requester_id.eq.' + encodeURIComponent(userId) + ',addressee_id.eq.' + encodeURIComponent(userId) + ')', { headers: communityHeaders() })
        .then(function(r){ return r.ok ? r.json() : []; })
        .then(function(rows){
          var el = document.getElementById('profileStatFriends');
          if(el) el.textContent = String(rows.length);
        }).catch(function(){});

      loadFollowerCount(userId).then(function(n){
        var el = document.getElementById('profileStatFollowers');
        if(el) el.textContent = String(n);
      });

      fetch(SUPABASE_URL + '/rest/v1/favorites?user_id=eq.' + encodeURIComponent(userId) + '&select=catalog_id', { headers: communityHeaders() })
        .then(function(r){ return r.ok ? r.json() : []; })
        .then(function(rows){
          var el = document.getElementById('profileStatFavs');
          if(el) el.textContent = String(rows.length);
        }).catch(function(){});

      var editBtn = document.getElementById('btnToggleProfileEdit');
      var followBtn = document.getElementById('btnFollowToggle');
      var friendSlot = document.getElementById('pubProfileFriendSlot');
      if(isOwn){
        if(editBtn) editBtn.classList.remove('hidden');
        if(followBtn) followBtn.classList.add('hidden');
        if(friendSlot) friendSlot.innerHTML = '';
        showProfileContent(userId, p);
        if(!p.display_name){
          var alreadyPrompted = false;
          try { alreadyPrompted = !!sessionStorage.getItem('lux_profile_name_prompted'); sessionStorage.setItem('lux_profile_name_prompted', '1'); } catch(e){}
          if(!alreadyPrompted) setProfileEditOpen(true);
        }
      } else {
        if(editBtn) editBtn.classList.add('hidden');
        trackProfileView(userId);
        loadFriendshipMap().then(function(){
          var isFriend = friendshipCache[userId] && friendshipCache[userId].status === 'accepted';
          if(friendSlot){
            friendSlot.innerHTML = '';
            friendSlot.appendChild(contattiFriendButton(userId, p.display_name, !!p.is_private));
          }
          if(followBtn && isSignedIn()){
            followBtn.classList.remove('hidden');
            loadFollowingSet().then(function(set){
              var isFollowing = set.has(userId);
              followBtn.textContent = isFollowing ? t('pubProfile.unfollow') : t('pubProfile.follow');
              followBtn.classList.toggle('active', isFollowing);
              followBtn.onclick = function(){ toggleFollow(userId, followBtn); };
            });
          }
          if(p.is_private && !isFriend){
            var lockBox = document.getElementById('pubProfileLocked');
            var tabsBox = document.getElementById('profileTabs');
            if(lockBox) lockBox.classList.remove('hidden');
            if(tabsBox) tabsBox.classList.add('hidden');
            document.querySelectorAll('.profile-fb-panel').forEach(function(panel){ panel.classList.add('hidden'); });
          } else {
            showProfileContent(userId, p);
          }
        });
      }
    })
    .catch(function(e){
      console.warn('Public profile load failed:', e);
      notFoundBox.classList.remove('hidden');
    });
}

function showProfileContent(userId, p){
  renderProfileTitles(userId);
  renderProfileFavorites(userId);
  loadDiaryFeed('profileDiaryFeed', userId);
  renderProfilePhotos(userId);
  renderProfileVideos(userId);
  var isOwn = isSignedIn() && currentUserId() === userId;
  var uploadBox = document.getElementById('profilePhotosUpload');
  if(uploadBox) uploadBox.classList.toggle('hidden', !isOwn);
  var videoAddBox = document.getElementById('profileVideosAdd');
  if(videoAddBox) videoAddBox.classList.toggle('hidden', !isOwn);
  var diaryComposer = document.getElementById('profileDiaryComposer');
  // il compositore era scritto per intero ma non era mai mostrato: chi è firmato
  // può scrivere sia sulla propria bacheca sia su quella di un altro — il post
  // resta visibile a chiunque legga quella pagina, non solo al proprietario
  if(diaryComposer) diaryComposer.classList.toggle('hidden', !isSignedIn());
}

function trackProfileView(viewedUserId){
  if(!isSignedIn()) return;
  var session = getSession();
  fetch(SUPABASE_URL + '/rest/v1/profile_views', {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
    body: JSON.stringify({ viewer_id: currentUserId(), viewed_id: viewedUserId })
  }).catch(function(e){ console.warn('Profile view tracking failed:', e); });
}

function renderProfileTitles(userId){
  var grid = document.getElementById('profileTitlesGrid');
  var box = document.getElementById('profileTitlesBox');
  if(!grid) return;
  var items = getCatalog().filter(function(i){ return i.created_by === userId && matureOk(i); });
  if(items.length === 0){ box.classList.add('hidden'); return; }
  box.classList.remove('hidden');
  items.sort(function(a,b){ return (b.date||'').localeCompare(a.date||''); });
  grid.innerHTML = '';
  items.forEach(function(item){
    var row = document.createElement('button');
    row.type = 'button';
    row.className = 'profile-sidebar-title-row';
    var thumbInner = item.cover_url
      ? '<img src="'+coverThumbUrl(item.cover_url, 120)+'" data-fallback="'+escapeHtml(item.cover_url)+'" alt="" loading="lazy" decoding="async">'
      : '<span class="init">'+item.character.charAt(0)+'</span>';
    var collabArr = (item.collaborators && item.collaborators.length)
      ? item.collaborators
      : (item.collaborator_name ? [{name:item.collaborator_name}] : []);
    var collabHtml = collabArr.length
      ? '<span class="collab">' + t('collab.credit') + ' ' + collabArr.map(function(c){ return escapeHtml(c.name || ''); }).join(', ') + '</span>'
      : '';
    row.innerHTML =
      '<span class="profile-sidebar-title-thumb">'+thumbInner+'</span>'+
      '<span class="profile-sidebar-title-text"><span class="ttl">'+escapeHtml(item.title)+'</span><span class="sub">'+(item.date||'')+'</span>'+collabHtml+'</span>';
    row.addEventListener('click', function(){ openTitleModal(item); });
    grid.appendChild(row);
  });
}

function renderProfileFavorites(userId){
  var grid = document.getElementById('profileFavoritesGrid');
  var box = document.getElementById('profileFavoritesBox');
  if(!grid) return;
  fetch(SUPABASE_URL + '/rest/v1/favorites?user_id=eq.' + encodeURIComponent(userId) + '&select=catalog_id', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      var ids = rows.map(function(r){ return r.catalog_id; });
      var items = getCatalog().filter(function(i){ return ids.indexOf(i.id) !== -1 && matureOk(i); });
      if(items.length === 0){ box.classList.add('hidden'); return; }
      box.classList.remove('hidden');
      grid.innerHTML = '';
      items.forEach(function(item){
        var row = document.createElement('button');
        row.type = 'button';
        row.className = 'profile-sidebar-title-row';
        var thumbInner = item.cover_url
          ? '<img src="'+coverThumbUrl(item.cover_url, 120)+'" data-fallback="'+escapeHtml(item.cover_url)+'" alt="" loading="lazy" decoding="async">'
          : '<span class="init">'+item.character.charAt(0)+'</span>';
        row.innerHTML =
          '<span class="profile-sidebar-title-thumb">'+thumbInner+'</span>'+
          '<span class="profile-sidebar-title-text"><span class="ttl">'+escapeHtml(item.title)+'</span></span>';
        row.addEventListener('click', function(){ openTitleModal(item); });
        grid.appendChild(row);
      });
    })
    .catch(function(e){ console.warn('Profile favorites load failed:', e); box.classList.add('hidden'); });
}

/* ============ GALLERIA FOTO del profilo (upload vero, stesso schema di sicurezza degli avatar) ============ */
function renderProfilePhotos(userId){
  var grid = document.getElementById('profilePhotosGrid');
  if(!grid) return;
  var isOwn = isSignedIn() && currentUserId() === userId;
  grid.innerHTML = '<p class="form-note">…</p>';
  fetch(SUPABASE_URL + '/rest/v1/profile_photos?user_id=eq.' + encodeURIComponent(userId) + '&select=*&order=created_at.desc', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      grid.innerHTML = '';
      if(rows.length === 0){ grid.innerHTML = '<p class="form-note">' + t('profile.noPhotos') + '</p>'; return; }
      rows.forEach(function(photo){
        var item = document.createElement('div');
        item.className = 'profile-photo-item';
        item.innerHTML = '<img src="' + coverThumbUrl(escapeHtml(photo.image_url), 300) + '" alt="" loading="lazy">' +
          (isOwn ? '<button type="button" class="profile-photo-remove" data-del-photo="' + photo.id + '">✕</button>' : '') +
          (photo.caption ? '<div class="profile-photo-caption">' + escapeHtml(photo.caption) + '</div>' : '');
        item.querySelector('img').addEventListener('click', function(){ openImageLightbox(photo.image_url); });
        var delBtn = item.querySelector('[data-del-photo]');
        if(delBtn) delBtn.addEventListener('click', function(e){
          e.stopPropagation();
          deleteProfilePhoto(photo.id, userId);
        });
        grid.appendChild(item);
      });
    })
    .catch(function(e){ grid.innerHTML = '<p class="form-note">' + t('community.loadError') + '</p>'; console.warn('Profile photos load failed:', e); });
}

function uploadProfilePhoto(){
  var fileInput = document.getElementById('fProfilePhotoUpload');
  var captionInput = document.getElementById('fProfilePhotoCaption');
  var errEl = document.getElementById('profilePhotoError');
  var file = fileInput.files[0];
  errEl.textContent = '';
  if(!file){ errEl.textContent = t('err.required'); return; }
  var session = getSession();
  if(!session) return;
  var uid = currentUserId();
  compressImageFile(file, 1600, 0.88).then(function(compressed){
    var ext = (compressed.type && compressed.type.split('/')[1]) || 'jpg';
    var path = uid + '/' + Date.now() + '_' + Math.random().toString(36).slice(2,8) + '.' + ext;
    return fetch(SUPABASE_URL + '/storage/v1/object/profile-gallery/' + path, {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type': compressed.type || 'image/jpeg' },
      body: compressed
    }).then(function(r){
      if(!r.ok) throw new Error('upload foto fallito: ' + r.status);
      return SUPABASE_URL + '/storage/v1/object/public/profile-gallery/' + path;
    });
  }).then(function(imageUrl){
    return fetch(SUPABASE_URL + '/rest/v1/profile_photos', {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
      body: JSON.stringify({ user_id: uid, image_url: imageUrl, caption: captionInput.value.trim() || null })
    });
  }).then(function(r){
    if(!r.ok) throw new Error('salvataggio foto fallito: ' + r.status);
    fileInput.value = '';
    captionInput.value = '';
    renderProfilePhotos(uid);
  }).catch(function(err){
    console.warn('Upload foto profilo fallito:', err);
    errEl.textContent = t('profile.photoError');
  });
}

function deleteProfilePhoto(id, userId){
  var session = getSession();
  if(!session) return;
  if(!confirm(t('profile.deletePhotoConfirm'))) return;
  luxDelete('profile_photos?id=eq.' + encodeURIComponent(id)).then(function(){ renderProfilePhotos(userId); }, luxDeleteFail);
}

/* ============ VIDEO del profilo (link incorporato YouTube/Vimeo, nessun file caricato) ============ */
function extractVideoEmbedUrl(url){
  url = (url || '').trim();
  var yt = url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/shorts\/)([a-zA-Z0-9_-]{6,})/);
  if(yt) return 'https://www.youtube.com/embed/' + yt[1];
  var vimeo = url.match(/vimeo\.com\/(\d+)/);
  if(vimeo) return 'https://player.vimeo.com/video/' + vimeo[1];
  return null;
}

function renderProfileVideos(userId){
  var list = document.getElementById('profileVideosList');
  if(!list) return;
  var isOwn = isSignedIn() && currentUserId() === userId;
  list.innerHTML = '<p class="form-note">…</p>';
  fetch(SUPABASE_URL + '/rest/v1/profile_videos?user_id=eq.' + encodeURIComponent(userId) + '&select=*&order=created_at.desc', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      list.innerHTML = '';
      if(rows.length === 0){ list.innerHTML = '<p class="form-note">' + t('profile.noVideos') + '</p>'; return; }
      rows.forEach(function(video){
        var embedUrl = extractVideoEmbedUrl(video.video_url);
        if(!embedUrl) return;
        var card = document.createElement('div');
        card.className = 'profile-video-card';
        card.innerHTML =
          '<iframe src="' + escapeHtml(embedUrl) + '" allowfullscreen loading="lazy"></iframe>' +
          '<div class="cap"><span>' + escapeHtml(video.caption || '') + '</span>' +
          (isOwn ? '<button type="button" class="btn btn-sm btn-ghost" data-del-video="' + video.id + '">' + t('profile.deleteVideo') + '</button>' : '') +
          '</div>';
        var delBtn = card.querySelector('[data-del-video]');
        if(delBtn) delBtn.addEventListener('click', function(){ deleteProfileVideo(video.id, userId); });
        list.appendChild(card);
      });
    })
    .catch(function(e){ list.innerHTML = '<p class="form-note">' + t('community.loadError') + '</p>'; console.warn('Profile videos load failed:', e); });
}

function addProfileVideo(){
  var input = document.getElementById('fProfileVideoUrl');
  var errEl = document.getElementById('profileVideoError');
  errEl.textContent = '';
  var embedUrl = extractVideoEmbedUrl(input.value);
  if(!embedUrl){ errEl.textContent = t('profile.videoUrlError'); return; }
  var session = getSession();
  if(!session) return;
  var uid = currentUserId();
  fetch(SUPABASE_URL + '/rest/v1/profile_videos', {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
    body: JSON.stringify({ user_id: uid, video_url: input.value.trim() })
  }).then(function(r){
    if(!r.ok) throw new Error('salvataggio video fallito: ' + r.status);
    input.value = '';
    renderProfileVideos(uid);
  }).catch(function(err){
    console.warn('Aggiunta video profilo fallita:', err);
    errEl.textContent = t('profile.videoUrlError');
  });
}

function deleteProfileVideo(id, userId){
  var session = getSession();
  if(!session) return;
  luxDelete('profile_videos?id=eq.' + encodeURIComponent(id)).then(function(){ renderProfileVideos(userId); }, luxDeleteFail);
}

/* ============ CHAT DEDICATA (chat.html?user=<id>) — fuori da Community ============ */
var currentChatThreadId = null;
var currentChatOtherId = null;
var currentChatLastMessageAt = null;
var chatPollTimer = null;

/* Suoni generati al volo (nessun file audio da caricare/ospitare) — due toni brevi e distinti */
function playChatSound(kind){
  try{
    var Ctx = window.AudioContext || window.webkitAudioContext;
    if(!Ctx) return;
    var ctx = new Ctx();
    var o = ctx.createOscillator();
    var g = ctx.createGain();
    o.connect(g); g.connect(ctx.destination);
    o.type = 'sine';
    if(kind === 'sent'){
      o.frequency.setValueAtTime(660, ctx.currentTime);
      o.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.09);
    } else {
      o.frequency.setValueAtTime(520, ctx.currentTime);
      o.frequency.exponentialRampToValueAtTime(400, ctx.currentTime + 0.12);
    }
    g.gain.setValueAtTime(0.001, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.12, ctx.currentTime + 0.02);
    g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.18);
    o.start();
    o.stop(ctx.currentTime + 0.2);
  }catch(e){ /* audio non disponibile: nessun problema, la chat funziona lo stesso */ }
}

function uploadChatAttachment(file){
  var session = getSession();
  var extMatch = /\.([a-zA-Z0-9]+)$/.exec(file.name || '');
  var ext = extMatch ? extMatch[1].toLowerCase() : 'bin';
  var path = 'dm-attachments/' + currentChatThreadId + '/' + Date.now() + '_' + Math.random().toString(36).slice(2,8) + '.' + ext;
  return fetch(SUPABASE_URL + '/storage/v1/object/comic-pages/' + path, {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type': file.type || 'application/octet-stream' },
    body: file
  }).then(function(r){
    if(!r.ok) throw new Error('chat attachment upload failed: ' + r.status);
    return SUPABASE_URL + '/storage/v1/object/public/comic-pages/' + path;
  });
}

/* ============ SFONDO CHAT PERSONALIZZABILE ============
   Scelta salvata localmente sul dispositivo (per account), come il tema
   chiaro/scuro — non richiede modifiche al database. Un domani, se serve
   sincronizzarlo tra dispositivi, si può spostare su una colonna profiles. */
var CHAT_BG_PRESETS = [
  { id:'default', label:'Predefinito', css:'radial-gradient(ellipse at 20% 0%, rgba(201,162,77,0.05), transparent 60%), #0b0607' },
  { id:'wine',    label:'Vino',        css:'linear-gradient(160deg, #2a0d13, #0b0607)' },
  { id:'verdigris', label:'Verderame', css:'linear-gradient(160deg, #16241d, #0b0607)' },
  { id:'ember',   label:'Ambra',       css:'linear-gradient(160deg, #2e160a, #0b0607)' },
  { id:'parchment', label:'Pergamena', css:'linear-gradient(160deg, #2a2317, #0b0607)' },
  { id:'void',    label:'Notte piena', css:'#0b0607' }
];

function chatBgStorageKey(){
  var uid = currentUserId();
  return uid ? ('lux_chat_bg_' + uid) : null;
}

function getChatBgChoice(){
  var key = chatBgStorageKey();
  if(!key) return null;
  try{
    var raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  }catch(e){ return null; }
}

function saveChatBgChoice(choice){
  var key = chatBgStorageKey();
  if(!key) return;
  try{
    if(choice) localStorage.setItem(key, JSON.stringify(choice));
    else localStorage.removeItem(key);
  }catch(e){ /* storage piena o non disponibile: la chat resta comunque usabile */ }
}

function applyChatBackground(){
  var wrap = document.getElementById('chatMessages');
  if(!wrap) return;
  var choice = getChatBgChoice();
  if(!choice){ wrap.style.background = ''; wrap.style.backgroundSize = ''; return; }
  if(choice.type === 'custom' && (choice.url || choice.dataUrl)){
    wrap.style.background = 'center / cover no-repeat url(' + JSON.stringify(choice.url || choice.dataUrl) + '), var(--void)';
  } else {
    var preset = CHAT_BG_PRESETS.find(function(p){ return p.id === choice.id; }) || CHAT_BG_PRESETS[0];
    wrap.style.background = preset.css;
  }
}

function renderChatBgSwatches(){
  var box = document.getElementById('chatBgSwatches');
  if(!box) return;
  var current = getChatBgChoice();
  box.innerHTML = '';
  CHAT_BG_PRESETS.forEach(function(p){
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'chat-bg-swatch' + ((!current && p.id === 'default') || (current && current.type === 'preset' && current.id === p.id) ? ' active' : '');
    btn.style.background = p.css;
    btn.title = p.label;
    btn.setAttribute('aria-label', p.label);
    btn.addEventListener('click', function(){
      saveChatBgChoice(p.id === 'default' ? null : { type:'preset', id:p.id });
      applyChatBackground();
      renderChatBgSwatches();
    });
    box.appendChild(btn);
  });
}

function toggleChatBgPanel(){
  var panel = document.getElementById('chatBgPanel');
  if(!panel) return;
  var opening = panel.classList.contains('hidden');
  panel.classList.toggle('hidden');
  if(opening) renderChatBgSwatches();
}

function uploadChatBgImage(file){
  var session = getSession();
  var uid = currentUserId();
  var extMatch = /\.([a-zA-Z0-9]+)$/.exec(file.name || '');
  var ext = extMatch ? extMatch[1].toLowerCase() : 'jpg';
  var path = 'chat-backgrounds/' + uid + '/' + Date.now() + '_' + Math.random().toString(36).slice(2,8) + '.' + ext;
  return fetch(SUPABASE_URL + '/storage/v1/object/comic-pages/' + path, {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type': file.type || 'application/octet-stream' },
    body: file
  }).then(function(r){
    if(!r.ok) throw new Error('chat background upload failed: ' + r.status);
    return SUPABASE_URL + '/storage/v1/object/public/comic-pages/' + path;
  });
}

function handleChatBgUpload(file){
  if(!file) return;
  if(!file.type || file.type.indexOf('image/') !== 0){
    window.alert('Scegli un file immagine.');
    return;
  }
  var bgBtn = document.getElementById('btnChatBg');
  if(bgBtn) bgBtn.textContent = '…';
  uploadChatBgImage(file).then(function(url){
    saveChatBgChoice({ type:'custom', url: url });
    applyChatBackground();
    renderChatBgSwatches();
  }).catch(function(err){
    console.warn('Chat background upload failed:', err);
    window.alert('Caricamento non riuscito. Riprova.');
  }).then(function(){
    if(bgBtn) bgBtn.textContent = '🖼️';
  });
}

function initChatPage(){
  var section = document.getElementById('chatSection');
  if(!section){ return; } // non siamo su chat.html
  if(!isSignedIn()){ openAuth('login'); return; }
  loadChatSidebar();
  var params = new URLSearchParams(window.location.search);
  var otherUserId = params.get('user');
  if(!otherUserId){
    document.getElementById('chatBox').classList.remove('hidden');
    setChatMobileView('list');
    return;
  }
  openChatWithUser(otherUserId, false);
}

function setChatMobileView(mode){
  // su schermi stretti mostriamo un pannello alla volta (lista o conversazione),
  // su schermi larghi restano sempre affiancati — questa funzione controlla solo
  // quale dei due è visibile quando lo spazio non basta per entrambi
  var box = document.getElementById('chatBox');
  if(!box) return;
  box.classList.toggle('showing-list', mode === 'list');
  box.classList.toggle('showing-conversation', mode === 'conversation');
}

function openChatWithUser(otherUserId, updateHistory){
  var uid = currentUserId();
  chatInfoPhotoList = []; // v223: le foto sono della conversazione che si apre
  if(otherUserId === uid){ document.getElementById('chatNotFound').classList.remove('hidden'); return; }
  currentChatOtherId = otherUserId;
  var userA = uid < otherUserId ? uid : otherUserId;
  var userB = uid < otherUserId ? otherUserId : uid;
  var session = getSession();

  if(updateHistory !== false){
    var url = new URL(window.location.href);
    url.searchParams.set('user', otherUserId);
    window.history.pushState({}, '', url);
  }
  setChatMobileView('conversation');
  document.querySelectorAll('.chat-sidebar-row').forEach(function(row){
    row.classList.toggle('active', row.dataset.otherId === otherUserId);
  });

  fetch(SUPABASE_URL + '/rest/v1/dm_threads?user_a=eq.' + encodeURIComponent(userA) + '&user_b=eq.' + encodeURIComponent(userB) + '&select=id', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      if(rows.length > 0) return rows[0].id;
      return fetch(SUPABASE_URL + '/rest/v1/dm_threads', {
        method:'POST',
        headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'return=representation' },
        body: JSON.stringify({ user_a: userA, user_b: userB })
      }).then(function(r2){ if(!r2.ok) throw new Error('dm thread create failed'); return r2.json(); })
        .then(function(rows2){ return rows2[0].id; });
    })
    .then(function(threadId){
      currentChatThreadId = threadId;
      document.getElementById('chatBox').classList.remove('hidden');
      document.body.classList.add('chat-fullscreen'); // nasconde l'intestazione del sito: la chat occupa tutto lo schermo, come un'app di messaggistica
      renderChatInfo(otherUserId); // v223: da computer la scheda del contatto

      getDisplayName(otherUserId).then(function(name){
        document.getElementById('chatOtherName').textContent = name;
      });
      var avatarEl = document.getElementById('chatOtherAvatar');
      avatarEl.classList.add('avatar-clickable');
      avatarEl.onclick = function(){ openAvatarInfo(otherUserId); };
      fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(otherUserId) + '&select=avatar_url,last_seen', { headers: communityHeaders() })
        .then(function(r){ return r.ok ? r.json() : []; })
        .then(function(rows){
          var p = rows[0];
          if(!p) return;
          if(p.avatar_url) avatarEl.src = p.avatar_url;
          else getDisplayName(otherUserId).then(function(n){ avatarEl.src = avatarInitialsDataUri(n, otherUserId); });
          var online = isOnlineSince(p.last_seen);
          document.getElementById('chatOtherDot').className = 'chat-header-dot ' + (online ? 'online' : 'offline');
          document.getElementById('chatOtherStatus').textContent = online ? t('userDir.online') : (p.last_seen ? notifTimeAgo(p.last_seen) : t('userDir.offline'));
        });

      loadChatMessages();
      startChatPolling();
      applyChatBackground();

      var mine = userA === uid;
      var field = mine ? 'last_read_at_a' : 'last_read_at_b';
      var patch = {}; patch[field] = new Date().toISOString();
      fetch(SUPABASE_URL + '/rest/v1/dm_threads?id=eq.' + encodeURIComponent(threadId), {
        method:'PATCH',
        headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
        body: JSON.stringify(patch)
      }).then(function(){
        // niente reload completo della sidebar: basta togliere il puntino
        // "non letto" dalla riga già a schermo, senza rifare 3 chiamate di rete
        var row = document.querySelector('.chat-sidebar-row[data-other-id="' + CSS.escape(otherUserId) + '"]');
        if(row){
          row.classList.remove('unread');
          var dot = row.querySelector('.chat-sidebar-unread-dot');
          if(dot) dot.remove();
        }
        loadUnreadDmCount(); // il numeretto sull'icona in alto deve scendere subito, non al prossimo giro di polling
      }).catch(function(){});
    })
    .catch(function(e){
      console.warn('Chat init failed:', e);
      var errBox = document.getElementById('chatOpenError');
      if(!errBox) return;
      var errMsg = errBox.querySelector('[data-i18n="chat.openError"]');
      if(errMsg) errMsg.textContent = navigator.onLine === false ? t('del.offline') : t('chat.openError');
      errBox.classList.remove('hidden');
      var retry = document.getElementById('chatOpenRetry');
      if(retry && !retry.dataset.wired){
        retry.dataset.wired = '1';
        retry.addEventListener('click', function(){ errBox.classList.add('hidden'); openChatWithUser(otherUserId, false); });
      }
    });
}

/* ============ LISTA CONVERSAZIONI FISSA (chat.html, stile WhatsApp) ============
   Su schermi larghi resta sempre visibile a fianco della conversazione aperta;
   su schermi stretti è l'unica cosa mostrata finché non tocchi un contatto. */
var allFriendsForNewMessage = null; // cache in-pagina: gli amici cambiano raramente durante una sessione
function loadFriendsForNewMessage(){
  if(allFriendsForNewMessage) return Promise.resolve(allFriendsForNewMessage);
  var uid = currentUserId();
  return fetch(SUPABASE_URL + '/rest/v1/friendships?select=requester_id,addressee_id&status=eq.accepted&or=(requester_id.eq.' + encodeURIComponent(uid) + ',addressee_id.eq.' + encodeURIComponent(uid) + ')', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(friendships){
      var otherIds = friendships.map(function(f){ return f.requester_id === uid ? f.addressee_id : f.requester_id; });
      if(otherIds.length === 0) return [];
      return fetch(SUPABASE_URL + '/rest/v1/profiles?id=in.(' + otherIds.map(encodeURIComponent).join(',') + ')&select=id,display_name', { headers: communityHeaders() })
        .then(function(r){ return r.ok ? r.json() : []; });
    })
    .then(function(list){
      allFriendsForNewMessage = list;
      return list;
    });
}
function renderNewMessageList(query){
  var listEl = document.getElementById('newMessageList');
  if(!listEl || !allFriendsForNewMessage) return;
  var q = (query || '').trim().toLowerCase();
  var filtered = q
    ? allFriendsForNewMessage.filter(function(p){ return (p.display_name || '').toLowerCase().indexOf(q) !== -1; })
    : allFriendsForNewMessage;
  listEl.innerHTML = '';
  if(filtered.length === 0){
    listEl.innerHTML = '<div class="form-note">' + t('community.noResults') + '</div>';
    return;
  }
  filtered.forEach(function(p){
    var row = document.createElement('button');
    row.type = 'button';
    row.className = 'chat-new-message-row';
    row.textContent = p.display_name || t('notif.someone');
    row.addEventListener('click', function(){
      document.getElementById('newMessagePanel').classList.add('hidden');
      document.getElementById('newMessageSearch').value = '';
      openChatWithUser(p.id);
    });
    listEl.appendChild(row);
  });
}

function loadChatSidebar(){
  var list = document.getElementById('chatSidebarList');
  if(!list || !isSignedIn()) return;
  var uid = currentUserId();

  var threadsStep = fetch(SUPABASE_URL + '/rest/v1/dm_threads?select=*&or=(user_a.eq.' + encodeURIComponent(uid) + ',user_b.eq.' + encodeURIComponent(uid) + ')', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; });
  threadsStep.catch(function(){}); // senza rete: l'errore lo gestisce il ramo qui sotto, non resta "in sospeso"

  fetch(SUPABASE_URL + '/rest/v1/friendships?select=requester_id,addressee_id&status=eq.accepted&or=(requester_id.eq.' + encodeURIComponent(uid) + ',addressee_id.eq.' + encodeURIComponent(uid) + ')', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(friendships){
      var otherIds = friendships.map(function(f){ return f.requester_id === uid ? f.addressee_id : f.requester_id; });
      // la richiesta profili parte SUBITO, appena sappiamo chi sono gli amici —
      // non aspetta che arrivino anche le conversazioni: le due chiamate corrono
      // in parallelo invece che una dopo l'altra, dimezzando l'attesa percepita
      var profilesStep = otherIds.length === 0
        ? Promise.resolve([])
        : fetch(SUPABASE_URL + '/rest/v1/profiles?id=in.(' + otherIds.map(encodeURIComponent).join(',') + ')&select=id,display_name,avatar_url,last_seen', { headers: communityHeaders() })
            .then(function(r){ return r.ok ? r.json() : []; });

      return Promise.all([profilesStep, threadsStep]).then(function(results){
        var profiles = results[0], threads = results[1];
        var threadByOtherId = {}, archivedByOtherId = {};
        threads.forEach(function(th){
          var st = dmThreadState(th, uid);
          if(!st.archived) threadByOtherId[st.otherId] = th;
          else archivedByOtherId[st.otherId] = th; // prima sparivano per sempre: ora si possono ripristinare
        });
        var archivedProfiles = profiles.filter(function(p){ return archivedByOtherId[p.id] && !threadByOtherId[p.id]; });
        // solo conversazioni davvero iniziate — chi cancelli sparisce per
        // davvero da qui; per scriverne una nuova c'è il bottone "Nuovo messaggio"
        profiles = profiles.filter(function(p){ return threadByOtherId[p.id]; });
        profiles.sort(function(a,b){
          return (a.display_name || '').localeCompare(b.display_name || '', 'it', { sensitivity:'base' });
        });
        renderChatSidebar(profiles, threadByOtherId, archivedProfiles, archivedByOtherId);
      });
    })
    .catch(function(err){
      console.warn('Chat sidebar load failed:', err);
      if(list.querySelector('.chat-sidebar-row')) return; // c'è già una lista: resta quella, riprova il prossimo aggiornamento
      list.innerHTML = '<p class="form-note">' + t('community.loadError') + ' <button type="button" class="retry-link">' + t('community.retry') + '</button></p>';
      list.querySelector('.retry-link').addEventListener('click', loadChatSidebar);
    });
}

/* Rubrica amici in stile WhatsApp: TUTTI gli amici accettati, in ordine
   alfabetico, con pallino online/offline — non più solo le conversazioni
   già iniziate. Se un amico ha già una conversazione, mostriamo comunque
   l'anteprima dell'ultimo messaggio e i pulsanti Archivia/Elimina. */
var chatSidebarArchivedOpen = false;
function renderChatSidebar(profiles, threadByOtherId, archivedProfiles, archivedByOtherId){
  var list = document.getElementById('chatSidebarList');
  if(!list) return;
  var uid = currentUserId();
  archivedProfiles = archivedProfiles || [];
  list.innerHTML = '';
  if(profiles.length === 0 && archivedProfiles.length === 0){
    list.innerHTML = '<p class="form-note">' + t('community.noDms') + '</p>';
    return;
  }
  if(profiles.length === 0) list.innerHTML = '<p class="form-note">' + t('community.noDms') + '</p>';

  var rowsByThreadId = {}; // per aggiornare l'anteprima dell'ultimo messaggio

  profiles.forEach(function(p){
    var th = threadByOtherId[p.id];
    var st = th ? dmThreadState(th, uid) : null;
    var unread = st ? !st.read : false;
    var online = isOnlineSince(p.last_seen);
    var name = p.display_name || t('userDir.title');

    var row = document.createElement('div');
    row.className = 'chat-sidebar-row' + (unread ? ' unread' : '') + (th && th.id === currentChatThreadId ? ' active' : '');
    row.dataset.otherId = p.id;

    var main = document.createElement('div');
    main.className = 'chat-sidebar-row-main';
    main.innerHTML =
      '<span class="chat-sidebar-avatar-wrap">' +
        avatarHtml(p.avatar_url, name, p.id, 'chat-sidebar-avatar') +
        '<span class="chat-sidebar-dot ' + (online ? 'online' : 'offline') + '"></span>' +
      '</span>' +
      '<span class="chat-sidebar-info">' +
        '<span class="chat-sidebar-name">' + escapeHtml(name) + '</span>' +
        '<span class="chat-sidebar-preview">' + (th ? '…' : '') + '</span>' +
      '</span>' +
      '<span class="chat-sidebar-meta">' +
        (th && th.last_message_at ? '<span class="chat-sidebar-time">' + notifTimeAgo(th.last_message_at) + '</span>' : '') +
        (unread ? '<span class="chat-sidebar-unread-dot"></span>' : '') +
      '</span>';
    main.addEventListener('click', function(){
      // tre casi possibili: dentro chat.html si apre sul posto con tutto il resto
      // dell'interfaccia già presente; dentro il cassetto del segnalibro si apre lì
      // dentro (ha la sua vista conversazione, con gli stessi id ma un contesto suo);
      // da qualunque altra pagina (es. la scheda Chat di Contatti) si naviga per davvero
      if(document.getElementById('chatBox')) openChatWithUser(p.id, true);
      else if(main.closest('#bookmarkDrawer')) openBookmarkChat(p.id);
      else window.location.href = 'chat.html?user=' + encodeURIComponent(p.id);
    });
    row.appendChild(main);

    if(th){
      var actions = document.createElement('div');
      actions.className = 'chat-sidebar-actions';

      var archBtn = document.createElement('button');
      archBtn.type = 'button';
      archBtn.className = 'chat-sidebar-action';
      var archLabel = t('community.archive') || 'Archivia';
      archBtn.textContent = archLabel;
      archBtn.setAttribute('aria-label', archLabel);
      archBtn.addEventListener('click', function(e){
        e.stopPropagation();
        var mine = th.user_a === uid;
        var field = mine ? 'archived_a' : 'archived_b';
        setDmFlag(th.id, field, true).then(function(){ loadChatSidebar(); });
      });
      actions.appendChild(archBtn);

      var delBtn = document.createElement('button');
      delBtn.type = 'button';
      delBtn.className = 'chat-sidebar-action danger';
      var delLabel = t('chat.delete') || 'Elimina';
      delBtn.textContent = delLabel;
      delBtn.setAttribute('aria-label', delLabel);
      delBtn.addEventListener('click', function(e){
        e.stopPropagation();
        if(!window.confirm(t('chat.deleteConfirm'))) return;
        deleteDmThread(th.id);
      });
      actions.appendChild(delBtn);

      row.appendChild(actions);
      rowsByThreadId[th.id] = row;
    }

    list.appendChild(row);
  });

  // ---- conversazioni archiviate: in fondo, chiuse finché non le apri ----
  if(archivedProfiles.length){
    var archToggle = document.createElement('button');
    archToggle.type = 'button';
    archToggle.className = 'chat-sidebar-archived-toggle';
    archToggle.setAttribute('aria-expanded', chatSidebarArchivedOpen ? 'true' : 'false');
    archToggle.textContent = t('chat.archivedToggle').replace('{n}', archivedProfiles.length) + (chatSidebarArchivedOpen ? '  ▴' : '  ▾');
    archToggle.addEventListener('click', function(){
      chatSidebarArchivedOpen = !chatSidebarArchivedOpen;
      renderChatSidebar(profiles, threadByOtherId, archivedProfiles, archivedByOtherId);
    });
    list.appendChild(archToggle);
    if(chatSidebarArchivedOpen){
      archivedProfiles.forEach(function(p){
        var th = archivedByOtherId[p.id];
        var name = p.display_name || t('userDir.title');
        var row = document.createElement('div');
        row.className = 'chat-sidebar-row is-archived';
        var main = document.createElement('div');
        main.className = 'chat-sidebar-row-main';
        main.innerHTML =
          '<span class="chat-sidebar-avatar-wrap">' + avatarHtml(p.avatar_url, name, p.id, 'chat-sidebar-avatar') + '</span>' +
          '<span class="chat-sidebar-info"><span class="chat-sidebar-name">' + escapeHtml(name) + '</span>' +
          '<span class="chat-sidebar-preview">' + escapeHtml(t('chat.archivedNote')) + '</span></span>';
        main.addEventListener('click', function(){
          if(document.getElementById('chatBox')) openChatWithUser(p.id, true);
          else if(main.closest('#bookmarkDrawer')) openBookmarkChat(p.id);
          else window.location.href = 'chat.html?user=' + encodeURIComponent(p.id);
        });
        row.appendChild(main);
        var actions = document.createElement('div');
        actions.className = 'chat-sidebar-actions';
        var back = document.createElement('button');
        back.type = 'button';
        back.className = 'chat-sidebar-action restore';
        back.textContent = t('chat.unarchive');
        back.setAttribute('aria-label', t('chat.unarchive'));
        back.addEventListener('click', function(e){
          e.stopPropagation();
          var field = th.user_a === uid ? 'archived_a' : 'archived_b';
          setDmFlag(th.id, field, false).then(function(){ loadChatSidebar(); });
        });
        actions.appendChild(back);
        var del = document.createElement('button');
        del.type = 'button';
        del.className = 'chat-sidebar-action danger';
        del.textContent = t('chat.delete') || 'Elimina';
        del.setAttribute('aria-label', t('chat.delete') || 'Elimina');
        del.addEventListener('click', function(e){
          e.stopPropagation();
          if(!window.confirm(t('chat.deleteConfirm'))) return;
          deleteDmThread(th.id);
        });
        actions.appendChild(del);
        row.appendChild(actions);
        list.appendChild(row);
      });
    }
  }

  // un'unica richiesta per tutte le anteprime, invece di una per contatto:
  // prendiamo più messaggi recenti del necessario (ordinati dal più nuovo)
  // e teniamo solo il primo che troviamo per ciascuna conversazione
  var threadIds = Object.keys(rowsByThreadId);
  if(threadIds.length > 0){
    fetch(SUPABASE_URL + '/rest/v1/dm_messages?thread_id=in.(' + threadIds.map(encodeURIComponent).join(',') + ')&select=thread_id,body,attachment_type&order=created_at.desc&limit=' + (threadIds.length * 6), { headers: communityHeaders() })
      .then(function(r){ return r.ok ? r.json() : []; })
      .then(function(rows){
        var seen = {};
        rows.forEach(function(last){
          if(seen[last.thread_id]) return;
          seen[last.thread_id] = true;
          var row = rowsByThreadId[last.thread_id];
          if(!row) return;
          var preview = '…';
          if(last.attachment_type === 'image') preview = '📷 ' + t('chat.photo');
          else if(last.attachment_type) preview = '📎 ' + t('chat.file');
          else if(last.body && isGifUrl(last.body)) preview = 'GIF';
          else preview = last.body || '';
          row.querySelector('.chat-sidebar-preview').textContent = preview;
        });
      })
      .catch(function(){});
  }
}

/* Elimina definitivamente una conversazione: prima tutti i suoi messaggi,
   poi il thread stesso. Richiede che il database permetta la cancellazione
   ai due partecipanti (vedi migrazione-elimina-chat.sql) — se quel permesso
   non è stato ancora concesso, il tentativo fallisce e lo segnaliamo. */
function deleteDmThread(threadId){
  var session = getSession();
  if(!session) return;
  // prima i messaggi (possono essere zero), poi la conversazione: deve sparire davvero
  luxDelete('dm_messages?thread_id=eq.' + encodeURIComponent(threadId), { allowEmpty: true })
    .then(function(){ return luxDelete('dm_threads?id=eq.' + encodeURIComponent(threadId)); })
    .then(function(){
      if(currentChatThreadId === threadId){
        currentChatThreadId = null;
        var wrap = document.getElementById('chatMessages');
        if(wrap) wrap.innerHTML = '';
        setChatMobileView('list');
        var url = new URL(window.location.href);
        url.searchParams.delete('user');
        window.history.pushState({}, '', url);
      }
      loadChatSidebar();
    })
    .catch(function(e){
      console.warn('Delete thread failed:', e);
      window.alert(e && e.kind && e.kind !== 'http' && e.kind !== 'network' ? luxDeleteMsg(e) : t('chat.deleteError'));
    });
}

var chatTranslations = {}; // id messaggio -> traduzione già fatta (sopravvive al ridisegno della chat)
function loadChatMessages(){
  var wrap = document.getElementById('chatMessages');
  if(!wrap || !currentChatThreadId) return;
  wrap.innerHTML = '<p class="form-note">…</p>';
  var threadId = currentChatThreadId;
  var messagesStep = fetch(SUPABASE_URL + '/rest/v1/dm_messages?thread_id=eq.' + encodeURIComponent(threadId) + '&select=*&order=created_at.asc', { headers: communityHeaders() })
    .then(function(r){ if(!r.ok) throw new Error('chat messages read failed'); return r.json(); });
  // parte subito insieme ai messaggi, invece di aspettare che i messaggi
  // siano arrivati prima di chiedere anche lo stato di lettura
  var threadStep = fetch(SUPABASE_URL + '/rest/v1/dm_threads?id=eq.' + encodeURIComponent(threadId) + '&select=user_a,last_read_at_a,last_read_at_b', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; });

  Promise.all([messagesStep, threadStep])
    .then(function(results){
      var rows = results[0], thRows = results[1];
      updateChatInfoPhotos(rows); // v223
      wrap.innerHTML = '';
      if(rows.length > 0) currentChatLastMessageAt = rows[rows.length - 1].created_at;
      if(rows.length === 0){ wrap.innerHTML = '<p class="form-note">' + t('community.noMessages') + '</p>'; return; }
      var uid = currentUserId();
      var th = thRows[0];
      var otherLastRead = null;
      if(th){
        var mineSide = th.user_a === uid;
        otherLastRead = mineSide ? th.last_read_at_b : th.last_read_at_a;
      }
      rows.forEach(function(m){
            var div = document.createElement('div');
            div.className = 'chat-bubble ' + (m.sender_id === uid ? 'mine' : 'theirs');
            var readByOther = otherLastRead && new Date(m.created_at) <= new Date(otherLastRead);
            var tickHtml = (m.sender_id === uid)
              ? '<span class="chat-tick ' + (readByOther ? 'read">✓✓' : 'sent">✓') + '</span>'
              : '';
            var attachHtml = '';
            if(m.attachment_url){
              if(m.attachment_type === 'image'){
                attachHtml = '<img class="chat-attachment-img" src="' + coverThumbUrl(escapeHtml(m.attachment_url), 500) + '" alt="" loading="lazy">';
              } else {
                attachHtml = '<a class="chat-attachment-file" href="' + escapeHtml(m.attachment_url) + '" target="_blank" rel="noopener">📎 ' + escapeHtml(m.attachment_name || t('chat.file')) + '</a>';
              }
            }
            var bodyHtml = m.body ? '<div class="body">' + renderBodyHtml(m.body) + '</div>' : '';
            var showTranslate = (m.sender_id !== uid) && m.body && !isGifUrl(m.body);
            div.innerHTML = attachHtml + bodyHtml + '<div class="chat-bubble-meta">' + notifTimeAgo(m.created_at) + tickHtml + '</div>';
            if(showTranslate){
              var translateBtn = document.createElement('button');
              translateBtn.type = 'button';
              translateBtn.className = 'chat-translate-btn';
              translateBtn.textContent = t('chat.translate') || 'Traduci';
              var showTranslation = function(text){
                var tDiv = document.createElement('div');
                tDiv.className = 'chat-translated-body';
                tDiv.textContent = text;
                translateBtn.insertAdjacentElement('afterend', tDiv);
                translateBtn.dataset.done = '1';
                translateBtn.textContent = t('chat.translateUndo') || 'Mostra originale';
              };
              translateBtn.addEventListener('click', function(){
                if(translateBtn.dataset.done === '1'){
                  var existing = div.querySelector('.chat-translated-body');
                  if(existing) existing.remove();
                  delete chatTranslations[m.id]; // al prossimo aggiornamento resta l'originale
                  translateBtn.dataset.done = '0';
                  translateBtn.textContent = t('chat.translate') || 'Traduci';
                  return;
                }
                translateBtn.disabled = true;
                translateBtn.classList.remove('is-error');
                translateBtn.textContent = '…';
                translateChatMessage(m.body).then(function(res){
                  var out = (res && res.translated) || '';
                  var src = (res && res.detected_source_language || '').slice(0, 2).toLowerCase();
                  if(!out || out.trim() === String(m.body).trim() || src === currentLang){
                    // stessa lingua: DeepL restituisce il testo identico, meglio dirlo
                    translateBtn.textContent = t('chat.translateSame');
                    setTimeout(function(){ if(translateBtn.dataset.done !== '1') translateBtn.textContent = t('chat.translate') || 'Traduci'; }, 3500);
                    return;
                  }
                  chatTranslations[m.id] = out;
                  showTranslation(out);
                }).catch(function(err){
                  console.warn('Chat translate failed:', err);
                  // prima tornava "Traduci" come se niente fosse: ora si vede, e un tocco riprova
                  translateBtn.classList.add('is-error');
                  translateBtn.textContent = navigator.onLine === false ? t('del.offline') : t('chat.translateFail');
                }).then(function(){ translateBtn.disabled = false; });
              });
              div.appendChild(translateBtn);
              if(chatTranslations[m.id]) showTranslation(chatTranslations[m.id]); // la chat si ridisegna a ogni messaggio nuovo: la traduzione resta
            }
            if(m.sender_id === uid && m.id){
              // i propri messaggi si possono eliminare (tocca il messaggio per vedere "Elimina")
              var delBtn = document.createElement('button');
              delBtn.type = 'button';
              delBtn.className = 'lux-del-btn chat-del-btn';
              delBtn.textContent = t('common.delete');
              delBtn.addEventListener('click', function(e){
                e.stopPropagation();
                if(!window.confirm(t('del.confirmMessage'))) return;
                delBtn.disabled = true;
                luxDelete('dm_messages?id=eq.' + encodeURIComponent(m.id)).then(function(){
                  div.remove();
                  loadChatMessages();
                }).catch(function(err){ delBtn.disabled = false; luxDeleteFail(err); });
              });
              var metaEl = div.querySelector('.chat-bubble-meta');
              (metaEl || div).appendChild(delBtn);
              div.addEventListener('click', function(e){
                if(e.target.closest('a, button')) return;
                div.classList.toggle('show-actions');
              });
            }
            wrap.appendChild(div);
          });
          wrap.scrollTop = wrap.scrollHeight;
    })
    .catch(function(e){ wrap.innerHTML = '<p class="form-note">' + t('community.loadError') + '</p>'; console.warn('Chat messages load failed:', e); });
}

function startChatPolling(otherUserIdParam){
  if(chatPollTimer) clearInterval(chatPollTimer);
  chatPollTimer = setInterval(function(){
    if(!currentChatThreadId) return;
    var query = SUPABASE_URL + '/rest/v1/dm_messages?thread_id=eq.' + encodeURIComponent(currentChatThreadId) + '&select=sender_id,created_at&order=created_at.asc';
    if(currentChatLastMessageAt) query += '&created_at=gt.' + encodeURIComponent(currentChatLastMessageAt);
    fetch(query, { headers: communityHeaders() })
      .then(function(r){ return r.ok ? r.json() : []; })
      .then(function(rows){
        if(rows.length === 0) return;
        var uid = currentUserId();
        var hasIncoming = rows.some(function(m){ return m.sender_id !== uid; });
        if(hasIncoming) playChatSound('received');
        loadChatMessages();
        // segna come letti anche i messaggi arrivati mentre la chat è aperta
        var session = getSession();
        // fuori da chat.html non c'è ?user= nell'indirizzo: usa quello passato da chi ha aperto la conversazione
        var otherUserId = otherUserIdParam || new URLSearchParams(window.location.search).get('user');
        if(session && otherUserId){
          var userA = uid < otherUserId ? uid : otherUserId;
          var field = (userA === uid) ? 'last_read_at_a' : 'last_read_at_b';
          var patch = {}; patch[field] = new Date().toISOString();
          fetch(SUPABASE_URL + '/rest/v1/dm_threads?id=eq.' + encodeURIComponent(currentChatThreadId), {
            method:'PATCH',
            headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
            body: JSON.stringify(patch)
          }).catch(function(){});
        }
      })
      .catch(function(){});
  }, 6000);
}

/* ============ v225: IL CAMPO DEI MESSAGGI VA A CAPO ============
   Il campo si allunga mentre scrivi, fino a 6 righe (poi scorre dentro).
   Da computer Invio manda e Maiuscolo+Invio va a capo; da telefono e tablet
   il tasto Invio va a capo e si manda con «Invia», come su WhatsApp.
   (Con una pagina vecchia ancora in memoria il campo può essere su una riga:
   allora Invio manda, come prima.) */
var CHAT_INPUT_MAX_LINES = 6;
function luxAutoGrow(el){
  if(!el || el.tagName !== 'TEXTAREA') return;
  if(!el.getClientRects().length){ el.style.height = ''; return; } // nascosto (es. telefono, si vede l'elenco): si misura quando compare
  var cs = window.getComputedStyle(el);
  var borders = (parseFloat(cs.borderTopWidth) || 0) + (parseFloat(cs.borderBottomWidth) || 0);
  var line = parseFloat(cs.lineHeight) || 22;
  var max = Math.round(line * CHAT_INPUT_MAX_LINES + (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0) + borders);
  var cssMax = parseFloat(cs.maxHeight);
  if(cssMax > 0) max = Math.min(max, cssMax);
  el.style.height = 'auto';
  var h = el.scrollHeight + borders;
  el.style.height = Math.min(h, max) + 'px';
  el.style.overflowY = h > max + 1 ? 'auto' : 'hidden';
}
// telefono o tablet (dito, tastiera sullo schermo): lì il tasto Invio va a capo
function luxTouchTyping(){ return !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches); }
function setupChatInput(el, send){
  if(!el || el.dataset.luxInput) return;
  el.dataset.luxInput = '1';
  el.addEventListener('keydown', function(e){
    if(e.key !== 'Enter' || e.isComposing || e.keyCode === 229) return; // 229: la tastiera sta ancora componendo la parola
    if(el.tagName === 'TEXTAREA' && (e.shiftKey || luxTouchTyping())) return; // va a capo
    e.preventDefault();
    send();
  });
  luxAutoGrow(el);
}
// mentre scrivi (anche incollando) il campo si allunga; vale anche per i canali
document.addEventListener('input', function(e){
  var el = e.target;
  if(el && (el.id === 'fChatMessage' || el.id === 'bmChatInput' || el.id === 'fChannelMessage')) luxAutoGrow(el);
});

function sendChatMessage(){
  var box = document.getElementById('fChatMessage');
  var fileInput = document.getElementById('fChatAttachment');
  var err = document.getElementById('chatMessageError');
  var body = box.value.trim();
  var file = fileInput.files[0];
  err.textContent = '';
  if(!body && !file){ err.textContent = t('err.required'); return; }
  if(!isSignedIn()){ openAuth('login'); return; }
  var session = getSession();
  var sendBtn = document.getElementById('btnSendChat');
  sendBtn.disabled = true;

  var attachStep = file
    ? uploadChatAttachment(file).then(function(url){
        return { attachment_url: url, attachment_type: (file.type && file.type.indexOf('image/') === 0) ? 'image' : 'file', attachment_name: file.name };
      })
    : Promise.resolve({});

  attachStep.then(function(attach){
    var payload = { thread_id: currentChatThreadId, sender_id: currentUserId(), body: body || null };
    for(var k in attach) payload[k] = attach[k];
    return fetch(SUPABASE_URL + '/rest/v1/dm_messages', {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
      body: JSON.stringify(payload)
    });
  }).then(function(r){
    if(!r.ok) throw new Error('chat message insert failed');
    box.value = '';
    luxAutoGrow(box); // v225: il campo torna a una riga
    fileInput.value = '';
    document.getElementById('chatAttachPreview').classList.add('hidden');
    playChatSound('sent');
    loadChatMessages();
  }).catch(function(e){
    err.textContent = t('chat.sendError');
    console.warn('Chat message send failed:', e);
  }).then(function(){ sendBtn.disabled = false; });
}

function loadChannels(){
  if(!isSignedIn()) return;
  fetch(SUPABASE_URL + '/rest/v1/channels?community_id=is.null&select=*&order=created_at.desc', { headers: communityHeaders() })
    .then(function(r){ if(!r.ok) throw new Error('channels read failed'); return r.json(); })
    .then(function(rows){
      var list = document.getElementById('channelsList');
      if(!list) return;
      list.innerHTML = '';
      if(rows.length === 0){ list.innerHTML = '<p class="form-note">' + t('community.noChannels') + '</p>'; return; }
      rows.forEach(function(ch){
        var card = document.createElement('button');
        card.type = 'button';
        card.className = 'channel-card';
        card.innerHTML = '<div class="name">#' + escapeHtml(ch.name) + '</div>' +
          (ch.description ? '<div class="meta">' + escapeHtml(ch.description) + '</div>' : '');
        card.addEventListener('click', function(){ openChannel(ch.id, ch.name); });
        list.appendChild(card);
      });
    })
    .catch(function(err){ console.warn('Channels load failed:', err); });
}

function createChannel(){
  var input = document.getElementById('fNewChannelName');
  var err = document.getElementById('channelCreateError');
  var name = input.value.trim();
  err.textContent = '';
  if(!name){ err.textContent = t('err.required'); return; }
  if(!isSignedIn()){ openAuth('login'); return; }
  var session = getSession();
  fetch(SUPABASE_URL + '/rest/v1/channels', {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'return=representation' },
    body: JSON.stringify({ name: name, created_by: currentUserId() })
  }).then(function(r){
    if(!r.ok) throw new Error('channel insert failed');
    input.value = '';
    loadChannels();
  }).catch(function(e){
    err.textContent = t('err.required');
    console.warn('Channel create failed:', e);
  });
}

function openChannel(id, name){
  if(channelDetailMounted) restoreChannelDetail(); // la chat era montata nel pannello Server: torna al suo posto
  currentChannelId = id;
  currentChannelName = name;
  document.getElementById('channelListView').classList.add('hidden');
  document.getElementById('channelDetailView').classList.remove('hidden');
  document.getElementById('channelDetailName').textContent = '#' + name;
  loadChannelMessages();
}

function backToChannels(){
  if(channelDetailMounted){ closeServerChannel(); return; } // aperta da un server: si torna al pannello Server
  currentChannelId = null;
  document.getElementById('channelDetailView').classList.add('hidden');
  document.getElementById('channelListView').classList.remove('hidden');
  loadChannels();
}

function getDisplayName(userId){
  if(displayNameCache[userId]) return Promise.resolve(displayNameCache[userId]);
  return fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(userId) + '&select=display_name', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      var name = (rows[0] && rows[0].display_name) ? rows[0].display_name : t('notif.someone');
      displayNameCache[userId] = name;
      return name;
    })
    .catch(function(){ return t('notif.someone'); });
}

var chatAvatarCache = {}; // user_id -> avatar_url ('' se non ne ha una)
var chatRoleCache = {}; // user_id -> 'mod' | 'coll' | '' (nessun ruolo)
function roleBadgeHtml(role){
  if(role === 'mod') return ' <span class="role-badge role-mod">' + t('role.mod') + '</span>';
  if(role === 'coll') return ' <span class="role-badge role-coll">' + t('role.coll') + '</span>';
  return '';
}
function chatRoleBadge(userId){ return roleBadgeHtml(chatRoleCache[userId]); }
/* Il nome nei commenti porta al profilo di chi ha scritto — se il commento non ha un user_id
   collegato (account cancellato, o commento molto vecchio) resta testo semplice, non cliccabile. */
function commentAuthorHtml(name, userId){
  var safeName = escapeHtml(name);
  return userId ? '<a href="profile.html?user=' + encodeURIComponent(userId) + '" class="author author-link">' + safeName + '</a>' : '<span class="author">' + safeName + '</span>';
}

function chatMsgTime(iso){
  if(!iso) return '';
  var d = new Date(iso);
  if(isNaN(d.getTime())) return '';
  var hm = ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2);
  if(d.toDateString() === new Date().toDateString()) return hm;
  return ('0' + d.getDate()).slice(-2) + '/' + ('0' + (d.getMonth() + 1)).slice(-2) + ' ' + hm;
}

function loadChannelMessages(){
  var wrap = document.getElementById('channelMessages');
  var chId = currentChannelId;
  wrap.innerHTML = '<p class="form-note">…</p>';
  var searchInput = document.getElementById('channelSearchInput');
  if(searchInput) searchInput.value = ''; // canale nuovo: la ricerca del canale precedente non ha senso qui
  initChannelSearch();
  fetch(SUPABASE_URL + '/rest/v1/channel_messages?channel_id=eq.' + encodeURIComponent(chId) + '&select=*&order=created_at.asc', { headers: communityHeaders() })
    .then(function(r){ if(!r.ok) throw new Error('channel messages read failed'); return r.json(); })
    .then(function(rows){
      var seen = {}, missing = [];
      rows.forEach(function(m){
        if(m.user_id && chatAvatarCache[m.user_id] === undefined && !seen[m.user_id]){ seen[m.user_id] = true; missing.push(m.user_id); }
      });
      var pre = missing.length
        ? fetch(SUPABASE_URL + '/rest/v1/profiles?id=in.(' + missing.map(encodeURIComponent).join(',') + ')&select=id,avatar_url,role', { headers: communityHeaders() })
            .then(function(r){ return r.ok ? r.json() : []; })
            .then(function(ps){
              missing.forEach(function(id){ chatAvatarCache[id] = ''; chatRoleCache[id] = ''; });
              ps.forEach(function(p){ chatAvatarCache[p.id] = p.avatar_url || ''; chatRoleCache[p.id] = p.role || ''; });
            })
            .catch(function(){ missing.forEach(function(id){ chatAvatarCache[id] = ''; chatRoleCache[id] = ''; }); }) // senza avatar si vedono le iniziali, senza ruolo nessuna etichetta
        : Promise.resolve();
      return pre.then(function(){
        if(chId !== currentChannelId) return; // nel frattempo si è aperto un altro canale
        wrap.innerHTML = '';
        if(rows.length === 0){ wrap.innerHTML = '<p class="form-note">' + t('community.noMessages') + '</p>'; return; }
        rows.forEach(function(m){ wrap.appendChild(renderChannelMessage(m)); });
        wrap.scrollTop = wrap.scrollHeight;
      });
    })
    .catch(function(err){ wrap.innerHTML = ''; console.warn('Channel messages load failed:', err); });
}

/* ---- Ricerca dentro il canale aperto: filtra quello che è già stato caricato, senza nuove richieste ---- */
function initChannelSearch(){
  var input = document.getElementById('channelSearchInput');
  if(!input || input.dataset.ready) return;
  input.dataset.ready = '1';
  input.addEventListener('input', function(){ filterChannelMessages(input.value); });
}
function filterChannelMessages(query){
  var wrap = document.getElementById('channelMessages');
  if(!wrap) return;
  var q = (query || '').trim().toLowerCase();
  var any = false;
  Array.prototype.forEach.call(wrap.querySelectorAll('.channel-msg'), function(msg){
    var match = !q || msg.textContent.toLowerCase().indexOf(q) > -1;
    msg.classList.toggle('hidden', !match);
    if(match) any = true;
  });
  var empty = document.getElementById('channelSearchEmpty');
  if(empty) empty.classList.toggle('hidden', any || !q);
}

function renderChannelMessage(m){
  var div = document.createElement('div');
  div.className = 'channel-msg' + (m.flagged ? ' flagged' : '');
  var isOwn = m.user_id === currentUserId();
  var name = m.author_name || '';
  var av;
  if(chatAvatarCache[m.user_id]){
    av = document.createElement('img');
    av.className = 'msg-av';
    av.alt = '';
    av.src = chatAvatarCache[m.user_id];
  } else {
    av = document.createElement('span');
    av.className = 'msg-av msg-av-fb';
    av.textContent = (name || '?').charAt(0).toUpperCase();
  }
  div.appendChild(av);
  var main = document.createElement('div');
  main.className = 'msg-main';
  main.innerHTML = '<div class="msg-head"><span class="author">' + escapeHtml(name) + '</span>' + chatRoleBadge(m.user_id) + '<span class="msg-time">' + escapeHtml(chatMsgTime(m.created_at)) + '</span></div>' +
    '<div class="body">' + renderRichBody(m.body) + '</div>' +
    '<div class="msg-actions"><span class="friend-action-slot"></span>' +
      (isOwn ? '' : '<button type="button" class="report-btn">' + t('community.report') + '</button>') +
      ((isOwn || isAdmin()) && m.id ? '<button type="button" class="lux-del-btn channel-del-btn">' + t('common.delete') + '</button>' : '') +
    '</div>';
  div.appendChild(main);
  var reportBtn = main.querySelector('.report-btn');
  if(reportBtn) reportBtn.addEventListener('click', function(){ reportContent('channel_message', m.id); });
  var chDel = main.querySelector('.channel-del-btn');
  if(chDel) chDel.addEventListener('click', function(){
    if(!window.confirm(t('del.confirmChannelMsg'))) return;
    chDel.disabled = true;
    luxDelete('channel_messages?id=eq.' + encodeURIComponent(m.id)).then(function(){ div.remove(); })
      .catch(function(err){ chDel.disabled = false; luxDeleteFail(err); });
  });
  if(!isOwn) renderFriendActionSlot(main.querySelector('.friend-action-slot'), m.user_id, m.author_name);
  return div;
}

/* ---- Amicizia (necessaria prima di poter scrivere in privato) ---- */
var friendshipCache = {}; // otherUserId -> {status, requesterId, id}

function loadFriendshipMap(){
  if(!isSignedIn()) return Promise.resolve({});
  var uid = currentUserId();
  return fetch(SUPABASE_URL + '/rest/v1/friendships?select=*&or=(requester_id.eq.' + encodeURIComponent(uid) + ',addressee_id.eq.' + encodeURIComponent(uid) + ')', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      friendshipCache = {};
      rows.forEach(function(f){
        var otherId = f.requester_id === uid ? f.addressee_id : f.requester_id;
        friendshipCache[otherId] = f;
      });
      return friendshipCache;
    })
    .catch(function(){ return {}; });
}

function buildFriendActionButton(otherUserId, otherName){
  var uid = currentUserId();
  var f = friendshipCache[otherUserId];
  var btn = document.createElement('button');
  btn.type = 'button';
  if(!f){
    btn.textContent = t('community.addFriend');
    btn.addEventListener('click', function(){ sendFriendRequest(otherUserId, btn); });
  } else if(f.status === 'accepted'){
    btn.textContent = t('community.privateMessage');
    btn.addEventListener('click', function(){ startDmWith(otherUserId, otherName); });
  } else if(f.status === 'pending' && f.requester_id === uid){
    btn.textContent = t('community.requestSent');
    btn.disabled = true;
  } else if(f.status === 'pending' && f.addressee_id === uid){
    btn.textContent = t('community.acceptFriend');
    btn.addEventListener('click', function(){ respondFriendRequest(f.id, true); });
  }
  return btn;
}

function renderFriendActionSlot(slot, otherUserId, otherName){
  loadFriendshipMap().then(function(){
    slot.innerHTML = '';
    slot.appendChild(buildFriendActionButton(otherUserId, otherName));
  });
}

var friendSearchDebounce = null;
function searchFriends(query){
  var box = document.getElementById('friendSearchResults');
  if(!query || query.trim().length < 2){ box.innerHTML = ''; return; }
  if(!isSignedIn()){ openAuth('login'); return; }
  box.innerHTML = '<p class="form-note">…</p>';
  var uid = currentUserId();
  Promise.all([
    loadFriendshipMap(),
    fetch(SUPABASE_URL + '/rest/v1/profiles?display_name=ilike.*' + encodeURIComponent(query.trim()) + '*&id=neq.' + encodeURIComponent(uid) + '&select=id,display_name&limit=10', { headers: communityHeaders() })
      .then(function(r){ return r.ok ? r.json() : []; })
  ]).then(function(results){
    var rows = results[1];
    box.innerHTML = '';
    if(rows.length === 0){ box.innerHTML = '<p class="form-note">' + t('community.noResults') + '</p>'; return; }
    rows.forEach(function(p){
      var row = document.createElement('div');
      row.className = 'admin-row';
      row.innerHTML = '<div class="info"><div class="t">' + escapeHtml(p.display_name) + '</div></div><div class="admin-actions"></div>';
      row.querySelector('.admin-actions').appendChild(buildFriendActionButton(p.id, p.display_name));
      box.appendChild(row);
    });
  }).catch(function(err){ box.innerHTML = ''; console.warn('Friend search failed:', err); });
}

function sendFriendRequest(otherUserId, btnEl){
  if(!isSignedIn()){ openAuth('login'); return; }
  var session = getSession();
  if(btnEl) btnEl.disabled = true;
  fetch(SUPABASE_URL + '/rest/v1/friendships', {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
    body: JSON.stringify({ requester_id: currentUserId(), addressee_id: otherUserId })
  }).then(function(r){
    if(!r.ok) throw new Error('friend request failed');
    if(btnEl){
      btnEl.textContent = '✓ ' + t('community.requestSent');
      btnEl.style.color = '#4ade80';
      btnEl.style.borderColor = '#4ade80';
      btnEl.disabled = true;
    }
    if(currentChannelId) loadChannelMessages();
    var sentBox = document.getElementById('friendRequestsSent');
    if(sentBox) loadFriendsPanel(); // aggiorna subito la lista "Richieste inviate" se il pannello Amici è aperto
  }).catch(function(e){
    if(btnEl) btnEl.disabled = false;
    console.warn('Friend request failed:', e);
    luxToast(t('net.actionFailed'));
  });
}

function respondFriendRequest(friendshipId, accept){
  var session = getSession();
  var action = accept
    ? fetch(SUPABASE_URL + '/rest/v1/friendships?id=eq.' + encodeURIComponent(friendshipId), {
        method:'PATCH',
        headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
        body: JSON.stringify({status:'accepted'})
      })
    : fetch(SUPABASE_URL + '/rest/v1/friendships?id=eq.' + encodeURIComponent(friendshipId), {
        method:'DELETE',
        headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
      });
  action.then(function(r){
    if(!r.ok) throw new Error('friend response failed: ' + r.status);
    loadFriendsPanel();
    if(currentChannelId) loadChannelMessages();
  }).catch(function(e){ console.warn('Friend response failed:', e); luxToast(t('net.actionFailed')); });
}

/* ---- Sessioni di creazione a tempo (amico/collaboratore invitato a pubblicare) ---- */
var myCreationSession = null;
var collabCountdownTimer = null;

function hasActiveCreationSession(){
  return !!(myCreationSession && new Date(myCreationSession.expires_at) > new Date());
}

function loadMyCreationSession(){
  if(!isSignedIn() || isAdmin()){ myCreationSession = null; return Promise.resolve(null); }
  var session = getSession();
  return fetch(SUPABASE_URL + '/rest/v1/creation_sessions?invited_user_id=eq.' + encodeURIComponent(currentUserId()) + '&status=eq.active&select=*&order=expires_at.desc&limit=1', {
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
  })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      var row = rows[0];
      myCreationSession = (row && new Date(row.expires_at) > new Date()) ? row : null;
      return myCreationSession;
    })
    .catch(function(err){ console.warn('Creation session load failed:', err); myCreationSession = null; return null; });
}

function renderCollabSessionBanner(){
  var countdownEl = document.getElementById('collabSessionCountdown');
  var extBtn = document.getElementById('btnRequestExtension');
  var extStatus = document.getElementById('collabSessionExtensionStatus');
  if(!countdownEl || !myCreationSession) return;

  function tick(){
    var msLeft = new Date(myCreationSession.expires_at).getTime() - Date.now();
    if(msLeft <= 0){
      countdownEl.textContent = t('collabSession.expired');
      if(collabCountdownTimer) clearInterval(collabCountdownTimer);
      loadMyCreationSession().then(refreshAdminUI);
      return;
    }
    var h = Math.floor(msLeft / 3600000);
    var m = Math.floor((msLeft % 3600000) / 60000);
    countdownEl.textContent = t('collabSession.countdown').replace('{h}', h).replace('{m}', m);
  }
  tick();
  if(collabCountdownTimer) clearInterval(collabCountdownTimer);
  collabCountdownTimer = setInterval(tick, 60000);

  if(myCreationSession.extension_requested){
    extBtn.classList.add('hidden');
    extStatus.textContent = t('collabSession.extensionPending');
  } else {
    extBtn.classList.remove('hidden');
    extStatus.textContent = '';
  }
}

function requestSessionExtension(){
  if(!myCreationSession) return;
  var session = getSession();
  var status = document.getElementById('collabSessionExtensionStatus');
  status.textContent = '…';
  fetch(SUPABASE_URL + '/rest/v1/rpc/request_creation_extension', {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
    body: JSON.stringify({ session_id: myCreationSession.id })
  }).then(function(r){
    if(!r.ok) throw new Error('extension request failed');
    myCreationSession.extension_requested = true;
    renderCollabSessionBanner();
  }).catch(function(e){
    status.textContent = t('mod.banFailed');
    console.warn('Extension request failed:', e);
  });
}

function inviteFriendToCreate(otherUserId, otherName){
  if(!isAdmin()) return;
  if(!window.confirm(t('collabSession.inviteConfirm').replace('{name}', otherName))) return;
  var session = getSession();
  var expires = new Date(Date.now() + 24*3600000).toISOString();
  fetch(SUPABASE_URL + '/rest/v1/creation_sessions', {
    method:'POST',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
    body: JSON.stringify({ invited_user_id: otherUserId, granted_by: currentUserId(), expires_at: expires, status: 'active', extension_requested: false })
  }).then(function(r){
    if(!r.ok) throw new Error('invite failed');
    return fetch(SUPABASE_URL + '/rest/v1/notifications', {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
      body: JSON.stringify({ user_id: otherUserId, type:'creation_invite', actor_name:'Nox Morningstar', message: t('collabSession.inviteNotif') })
    });
  }).then(function(){
    window.alert(t('collabSession.inviteSent'));
    renderAdminSessions();
  }).catch(function(e){
    window.alert(t('mod.banFailed'));
    console.warn('Invite failed:', e);
  });
}

function renderAdminSessions(){
  if(!isAdmin()) return;
  var box = document.getElementById('adminSessionsList');
  if(!box) return;
  var session = getSession();
  box.innerHTML = '<p class="form-note">…</p>';
  fetch(SUPABASE_URL + '/rest/v1/creation_sessions?status=eq.active&select=*&order=expires_at.asc', {
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
  })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      box.innerHTML = '';
      var active = rows.filter(function(s){ return new Date(s.expires_at) > new Date(); });
      if(active.length === 0){ box.innerHTML = '<p class="form-note">' + t('mod.empty') + '</p>'; return; }
      var chain = Promise.resolve();
      active.forEach(function(s){
        chain = chain.then(function(){
          return getDisplayName(s.invited_user_id).then(function(name){
            var row = document.createElement('div');
            row.className = 'admin-row';
            var msLeft = new Date(s.expires_at).getTime() - Date.now();
            var h = Math.floor(msLeft / 3600000), m = Math.floor((msLeft % 3600000) / 60000);
            var extFlag = s.extension_requested ? ' — ' + t('collabSession.extensionPending') : '';
            row.innerHTML = '<div class="info"><div class="t">' + escapeHtml(name) + '</div>' +
              '<div class="m">' + t('collabSession.countdown').replace('{h}', h).replace('{m}', m) + extFlag + '</div></div>' +
              '<div class="admin-actions"><button class="btn btn-sm btn-ghost" data-extend>' + t('collabSession.extend48') + '</button></div>';
            row.querySelector('[data-extend]').addEventListener('click', function(){
              fetch(SUPABASE_URL + '/rest/v1/rpc/admin_extend_creation_session', {
                method:'POST',
                headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
                body: JSON.stringify({ session_id: s.id, hours: 48 })
              }).then(function(r){ if(!r.ok) throw new Error('extend failed'); renderAdminSessions(); })
                .catch(function(e){ window.alert(t('mod.banFailed')); console.warn('Extend failed:', e); });
            });
            box.appendChild(row);
          });
        });
      });
    })
    .catch(function(err){ console.warn('Admin sessions load failed:', err); });
}

function loadFriendsPanel(){
  if(!isSignedIn()) return;
  var uid = currentUserId();
  var receivedBox = document.getElementById('friendRequestsReceived');
  var sentBox = document.getElementById('friendRequestsSent');
  var friendsBox = document.getElementById('friendsList');
  receivedBox.innerHTML = '<p class="form-note">…</p>';
  sentBox.innerHTML = '<p class="form-note">…</p>';
  friendsBox.innerHTML = '<p class="form-note">…</p>';

  fetch(SUPABASE_URL + '/rest/v1/friendships?select=*&or=(requester_id.eq.' + encodeURIComponent(uid) + ',addressee_id.eq.' + encodeURIComponent(uid) + ')', {
    headers: communityHeaders(),
    signal: (typeof AbortSignal !== 'undefined' && AbortSignal.timeout) ? AbortSignal.timeout(10000) : undefined
  })
    .then(function(r){
      if(!r.ok){
        return r.text().then(function(bodyText){ throw new Error('HTTP ' + r.status + ': ' + bodyText); });
      }
      return r.json();
    })
    .then(function(rows){
      var received = rows.filter(function(f){ return f.status === 'pending' && f.addressee_id === uid; });
      var sent = rows.filter(function(f){ return f.status === 'pending' && f.requester_id === uid; });
      var accepted = rows.filter(function(f){ return f.status === 'accepted'; });

      receivedBox.innerHTML = received.length === 0 ? '<p class="form-note">' + t('mod.empty') + '</p>' : '';
      received.forEach(function(f){
        getDisplayName(f.requester_id).then(function(name){
          var row = document.createElement('div');
          row.className = 'admin-row';
          row.innerHTML = '<div class="info"><div class="t">' + escapeHtml(name) + '</div></div>' +
            '<div class="admin-actions">' +
              '<button class="btn btn-sm btn-ghost" data-accept>' + t('community.acceptFriend') + '</button>' +
              '<button class="btn btn-sm btn-ghost" data-decline>' + t('community.declineFriend') + '</button>' +
            '</div>';
          row.querySelector('[data-accept]').addEventListener('click', function(){ respondFriendRequest(f.id, true); });
          row.querySelector('[data-decline]').addEventListener('click', function(){ respondFriendRequest(f.id, false); });
          receivedBox.appendChild(row);
        });
      });

      sentBox.innerHTML = sent.length === 0 ? '<p class="form-note">' + t('mod.empty') + '</p>' : '';
      sent.forEach(function(f){
        getDisplayName(f.addressee_id).then(function(name){
          var row = document.createElement('div');
          row.className = 'admin-row';
          row.innerHTML = '<div class="info"><div class="t">' + escapeHtml(name) + '</div><div class="m">' + t('community.requestSent') + '</div></div>';
          sentBox.appendChild(row);
        });
      });

      renderFriendContactList(friendsBox, accepted, uid);
    })
    .catch(function(err){
      var detail = (err && err.message) ? err.message : String(err);
      var errMsg = '<p class="form-note">' + t('community.loadError') + ' <button type="button" class="retry-link" id="btnRetryFriends">' + t('community.retry') + '</button>' +
        '<br><span style="font-family:\'Space Mono\',monospace;font-size:10px;opacity:0.6;word-break:break-all;">' + escapeHtml(detail) + '</span></p>';
      receivedBox.innerHTML = errMsg;
      sentBox.innerHTML = '';
      friendsBox.innerHTML = '';
      var retryBtn = document.getElementById('btnRetryFriends');
      if(retryBtn) retryBtn.addEventListener('click', loadFriendsPanel);
      console.warn('Friends panel load failed:', err);
    });
}

/* Lista "I tuoi amici" in stile WhatsApp: avatar, pallino online/offline,
   ordine alfabetico. Click su un contatto porta dritto a chat.html (prima
   puntava a una tab "Messaggi privati" ormai rimossa da Community). */
function renderFriendContactList(friendsBox, accepted, uid){
  if(accepted.length === 0){
    friendsBox.innerHTML = '<p class="form-note">' + t('mod.empty') + '</p>';
    return;
  }
  var otherIds = accepted.map(function(f){ return f.requester_id === uid ? f.addressee_id : f.requester_id; });
  var friendshipByOtherId = {};
  accepted.forEach(function(f){
    var oid = f.requester_id === uid ? f.addressee_id : f.requester_id;
    friendshipByOtherId[oid] = f.id;
  });
  friendsBox.innerHTML = '<p class="form-note">…</p>';
  fetch(SUPABASE_URL + '/rest/v1/profiles?id=in.(' + otherIds.map(encodeURIComponent).join(',') + ')&select=id,display_name,avatar_url,last_seen', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(profiles){
      profiles.sort(function(a,b){
        return (a.display_name || '').localeCompare(b.display_name || '', 'it', { sensitivity:'base' });
      });
      friendsBox.innerHTML = '';
      if(profiles.length === 0){ friendsBox.innerHTML = '<p class="form-note">' + t('mod.empty') + '</p>'; return; }
      profiles.forEach(function(p){
        var online = isOnlineSince(p.last_seen);
        var name = p.display_name || t('notif.someone');
        var row = document.createElement('div');
        row.className = 'friend-contact-row';
        row.innerHTML =
          '<span class="friend-contact-avatar-wrap">' +
            avatarHtml(p.avatar_url, name, p.id, 'friend-contact-avatar') +
            '<span class="friend-contact-dot ' + (online ? 'online' : 'offline') + '"></span>' +
          '</span>' +
          '<span class="friend-contact-info">' +
            '<span class="friend-contact-name">' + escapeHtml(name) + '</span>' +
            '<span class="friend-contact-status">' + (online ? t('userDir.online') : t('userDir.offline')) + '</span>' +
          '</span>' +
          '<span class="friend-contact-actions">' +
            '<button type="button" class="friend-contact-msg" data-msg aria-label="' + t('community.privateMessage') + '" title="' + t('community.privateMessage') + '">💬</button>' +
            (isAdmin() ? '<button type="button" class="btn btn-sm btn-ghost friend-contact-invite" data-invite>' + t('collabSession.invite') + '</button>' : '') +
            '<button type="button" class="friend-contact-remove" data-remove aria-label="' + t('community.removeFriend') + '" title="' + t('community.removeFriend') + '">✕</button>' +
          '</span>';
        row.addEventListener('click', function(e){
          if(e.target.closest('[data-invite]') || e.target.closest('[data-remove]') || e.target.closest('[data-msg]')) return;
          window.location.href = 'chat.html?user=' + encodeURIComponent(p.id);
        });
        var msgBtn = row.querySelector('[data-msg]');
        msgBtn.addEventListener('click', function(e){
          e.stopPropagation();
          window.location.href = 'chat.html?user=' + encodeURIComponent(p.id);
        });
        var inviteBtn = row.querySelector('[data-invite]');
        if(inviteBtn) inviteBtn.addEventListener('click', function(e){
          e.stopPropagation();
          inviteFriendToCreate(p.id, name);
        });
        var removeBtn = row.querySelector('[data-remove]');
        removeBtn.addEventListener('click', function(e){
          e.stopPropagation();
          removeFriend(friendshipByOtherId[p.id], name, row);
        });
        friendsBox.appendChild(row);
      });
    })
    .catch(function(err){
      friendsBox.innerHTML = '<p class="form-note">' + t('community.loadError') + '</p>';
      console.warn('Friend contact list load failed:', err);
    });
}

function removeFriend(friendshipId, otherName, rowEl){
  if(!friendshipId) return;
  if(!window.confirm(t('community.removeFriendConfirm').replace('{name}', otherName))) return;
  var session = getSession();
  if(!session) return;
  luxDelete('friendships?id=eq.' + encodeURIComponent(friendshipId)).then(function(){
    friendshipCache = {}; // la cache amicizie va ricalcolata: questo amico non c'è più
    if(rowEl && rowEl.parentNode) rowEl.parentNode.removeChild(rowEl);
    if(document.getElementById('friendsList')) loadFriendsPanel();
    if(document.getElementById('contattiAmiciList')) renderContattiAmici();
  }).catch(function(err){
    console.warn('Remove friend failed:', err);
    window.alert(err && err.kind === 'denied' ? luxDeleteMsg(err) : t('community.removeFriendError'));
  });
}

function sendChannelMessage(){
  var box = document.getElementById('fChannelMessage');
  var err = document.getElementById('channelMessageError');
  var body = box.value.trim();
  err.textContent = '';
  if(!body){ err.textContent = t('err.required'); return; }
  if(!isSignedIn()){ openAuth('login'); return; }
  var session = getSession();
  var nameStep = currentProfile !== null ? Promise.resolve(currentProfile) : loadOwnProfile().then(function(){ return currentProfile; });
  nameStep.then(function(profile){
    var authorName = publicDisplayName(profile);
    return fetch(SUPABASE_URL + '/rest/v1/channel_messages', {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
      body: JSON.stringify({ channel_id: currentChannelId, user_id: currentUserId(), author_name: authorName, body: body })
    });
  }).then(function(r){
    if(!r.ok) throw new Error('channel message insert failed');
    box.value = ''; luxAutoGrow(box);
    loadChannelMessages();
  }).catch(function(e){
    err.textContent = t('err.required');
    console.warn('Channel message send failed:', e);
  });
}

/* ---- Messaggi privati ---- */
var dmActiveTab = 'all'; // all | unread | important | archived
var dmThreadsCache = [];

function loadUnreadDmCount(){
  var session = getSession();
  var badge = document.getElementById('chatHeaderBadge');
  var btn = document.getElementById('btnChatHeader');
  var bookmarkDot = document.getElementById('bookmarkDot');
  if(!isSignedIn()){ if(btn) btn.classList.add('hidden'); if(dmCountPollTimer){ clearInterval(dmCountPollTimer); dmCountPollTimer = null; } return Promise.resolve(); }
  if(btn) btn.classList.remove('hidden');
  var uid = currentUserId();
  return fetchMyDmThreads(uid)
    .then(function(rows){
      if(rows === null) return; // richiesta fallita: il contatore resta com'era
      var unread = rows.filter(function(th){ return !dmThreadState(th, uid).read; }).length;
      if(badge){
        if(unread > 0){ badge.textContent = unread > 99 ? '99+' : String(unread); badge.classList.remove('hidden'); }
        else { badge.classList.add('hidden'); }
      }
      if(bookmarkDot) bookmarkDot.classList.toggle('hidden', unread === 0);
      if(!dmCountPollTimer){ dmCountPollTimer = setInterval(loadUnreadDmCount, 45000); } // stesso ritmo leggero delle notifiche, non realtime
    })
    .catch(function(err){ console.warn('Unread DM count failed:', err); });
}

function dmThreadState(th, uid){
  var mine = th.user_a === uid;
  var myLastRead = mine ? th.last_read_at_a : th.last_read_at_b;
  var unread = !!th.last_message_at && (!myLastRead || new Date(th.last_message_at) > new Date(myLastRead));
  return {
    read: !unread,
    important: mine ? th.important_a : th.important_b,
    archived: mine ? th.archived_a : th.archived_b,
    otherId: mine ? th.user_b : th.user_a,
    otherLastRead: mine ? th.last_read_at_b : th.last_read_at_a
  };
}

function switchDmTab(tab){
  dmActiveTab = tab;
  document.querySelectorAll('.dm-tab').forEach(function(btn){
    btn.classList.toggle('active', btn.dataset.dmTab === tab);
  });
  renderDmThreadsList();
}

function setDmFlag(threadId, field, value){
  var session = getSession();
  if(!session) return Promise.resolve();
  var body = {}; body[field] = value;
  return fetch(SUPABASE_URL + '/rest/v1/dm_threads?id=eq.' + encodeURIComponent(threadId), {
    method:'PATCH',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
    body: JSON.stringify(body)
  }).catch(function(e){ console.warn('DM flag update failed:', e); });
}

function toggleDmImportant(th, uid, btn){
  var mine = th.user_a === uid;
  var field = mine ? 'important_a' : 'important_b';
  var newVal = !(mine ? th.important_a : th.important_b);
  if(mine) th.important_a = newVal; else th.important_b = newVal;
  btn.classList.toggle('active', newVal);
  setDmFlag(th.id, field, newVal);
}

function archiveDmThread(th, uid){
  var mine = th.user_a === uid;
  var field = mine ? 'archived_a' : 'archived_b';
  if(mine) th.archived_a = true; else th.archived_b = true;
  setDmFlag(th.id, field, true).then(renderDmThreadsList);
}

function unarchiveDmThread(th, uid){
  var mine = th.user_a === uid;
  var field = mine ? 'archived_a' : 'archived_b';
  if(mine) th.archived_a = false; else th.archived_b = false;
  setDmFlag(th.id, field, false).then(renderDmThreadsList);
}

function loadDmThreads(){
  var list = document.getElementById('dmThreadsList');
  if(!list || !isSignedIn()) return;
  var uid = currentUserId();
  fetch(SUPABASE_URL + '/rest/v1/dm_threads?select=*&or=(user_a.eq.' + encodeURIComponent(uid) + ',user_b.eq.' + encodeURIComponent(uid) + ')&order=last_message_at.desc', { headers: communityHeaders() })
    .then(function(r){ if(!r.ok) throw new Error('dm threads read failed'); return r.json(); })
    .then(function(rows){
      dmThreadsCache = rows;
      renderDmThreadsList();
    })
    .catch(function(err){ console.warn('DM threads load failed:', err); });
}

/* ---- Presenza online (attivo negli ultimi 2 minuti) ---- */
var ONLINE_THRESHOLD_MS = 120000;
function isOnlineSince(lastActiveAt){
  if(!lastActiveAt) return false;
  return (Date.now() - new Date(lastActiveAt).getTime()) < ONLINE_THRESHOLD_MS;
}
/* ============ CONTATTI (pagina dedicata: conversazioni recenti + altri utenti) ============ */
/* ============ FOLLOW (senso unico, separato dalle amicizie) ============ */
var followingCache = null;

function loadFollowingSet(){
  if(!isSignedIn()) return Promise.resolve(new Set());
  if(followingCache) return Promise.resolve(followingCache);
  var uid = currentUserId();
  return fetch(SUPABASE_URL + '/rest/v1/follows?follower_id=eq.' + encodeURIComponent(uid) + '&select=followed_id', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      followingCache = new Set(rows.map(function(r){ return r.followed_id; }));
      return followingCache;
    })
    .catch(function(){ return new Set(); });
}

function loadFollowerCount(userId){
  return fetch(SUPABASE_URL + '/rest/v1/follows?followed_id=eq.' + encodeURIComponent(userId) + '&select=follower_id', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){ return rows.length; })
    .catch(function(){ return 0; });
}

function toggleFollow(otherUserId, btnEl){
  if(!isSignedIn()){ openAuth('login'); return; }
  var session = getSession();
  var uid = currentUserId();
  var wasFollowing = followingCache && followingCache.has(otherUserId);
  btnEl.disabled = true;
  var req = wasFollowing
    ? fetch(SUPABASE_URL + '/rest/v1/follows?follower_id=eq.' + encodeURIComponent(uid) + '&followed_id=eq.' + encodeURIComponent(otherUserId), {
        method:'DELETE', headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
      })
    : fetch(SUPABASE_URL + '/rest/v1/follows', {
        method:'POST',
        headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
        body: JSON.stringify({ follower_id: uid, followed_id: otherUserId })
      });
  req.then(function(r){
    if(!r.ok) throw new Error('follow toggle failed');
    var nowFollowing = !wasFollowing;
    if(followingCache){ if(nowFollowing) followingCache.add(otherUserId); else followingCache.delete(otherUserId); }
    btnEl.textContent = nowFollowing ? t('pubProfile.unfollow') : t('pubProfile.follow');
    btnEl.classList.toggle('active', nowFollowing);
    btnEl.disabled = false;
    var statEl = document.getElementById('profileStatFollowers');
    if(statEl) statEl.textContent = String(Math.max(0, (parseInt(statEl.textContent, 10) || 0) + (nowFollowing ? 1 : -1)));
  }).catch(function(e){ btnEl.disabled = false; console.warn('Follow toggle failed:', e); luxToast(t('net.actionFailed')); });
}

/* ============ CONTATTI (hub Scopri / Amici / Richieste, stile pillola moderno) ============ */
var contattiWired = false;
var contattiActiveTab = 'chat'; // prima cosa che si vede aprendo Contatti: le conversazioni, non la rubrica amici
var contattiSearchDebounce = null;

function switchContattiTab(tab){
  contattiActiveTab = tab;
  document.querySelectorAll('#contattiTabs [data-ctab]').forEach(function(btn){
    btn.classList.toggle('active', btn.dataset.ctab === tab);
  });
  document.querySelectorAll('#contattiSignedIn .community-panel').forEach(function(p){
    p.classList.toggle('hidden', p.dataset.cpanel !== tab);
  });
  if(tab === 'chat') loadChatSidebar();
  else if(tab === 'scopri') renderContattiScopri('');
  else if(tab === 'amici') renderContattiAmici();
  else renderContattiRichieste();
}

/* Aggiunge la scheda "Chat" a Contatti, per prima — riusa la stessa lista che
   già esiste in chat.html (stesso aspetto, stesso caricamento), così non c'è
   una seconda versione da mantenere a parte. Va chiamata una sola volta,
   prima di wireContattiHub(), così il pulsante nuovo viene agganciato dal
   suo stesso giro di ascolto — solo su contatti.html: altrove i contenitori
   che cerca non esistono e la funzione non fa nulla. */
function ensureContattiChatTab(){
  var tabsBar = document.getElementById('contattiTabs');
  var panelsHost = document.getElementById('contattiSignedIn');
  if(!tabsBar || !panelsHost || document.getElementById('contattiChatTabBtn')) return;

  var existingBtn = tabsBar.querySelector('[data-ctab]');
  var chatBtn = document.createElement('button');
  chatBtn.type = 'button';
  chatBtn.id = 'contattiChatTabBtn';
  chatBtn.dataset.ctab = 'chat';
  chatBtn.className = (existingBtn ? existingBtn.className : 'community-tab').replace(/\bactive\b/g, '').replace(/\s+/g, ' ').trim(); // stessa classe delle altre schede, ma mai "già attiva" di suo
  chatBtn.textContent = t('contatti.chatTab');
  chatBtn.addEventListener('click', function(){ switchContattiTab('chat'); });
  tabsBar.insertBefore(chatBtn, tabsBar.firstChild);

  var panel = document.createElement('div');
  panel.className = 'community-panel hidden';
  panel.dataset.cpanel = 'chat';
  panel.id = 'contattiChatPanel';
  panel.innerHTML =
    '<div class="contatti-chat-new-row">' +
      '<button type="button" class="btn btn-sm btn-ghost" id="contattiNewMsgBtn">+ ' + t('contatti.newMessage') + '</button>' +
    '</div>' +
    '<div class="chat-sidebar-list" id="chatSidebarList"></div>';
  var firstPanel = panelsHost.querySelector('.community-panel');
  if(firstPanel) panelsHost.insertBefore(panel, firstPanel); else panelsHost.appendChild(panel);
  document.getElementById('contattiNewMsgBtn').addEventListener('click', function(){ switchContattiTab('scopri'); });
}

function wireContattiHub(){
  if(contattiWired) return;
  contattiWired = true;
  document.querySelectorAll('#contattiTabs [data-ctab]').forEach(function(btn){
    btn.addEventListener('click', function(){ switchContattiTab(btn.dataset.ctab); });
  });
  var search = document.getElementById('contattiSearchInput');
  if(search){
    search.addEventListener('input', function(){
      var q = search.value;
      clearTimeout(contattiSearchDebounce);
      contattiSearchDebounce = setTimeout(function(){
        if(contattiActiveTab !== 'scopri') switchContattiTab('scopri');
        else renderContattiScopri(q);
      }, 300);
    });
  }
}

function contattiFriendButton(otherUserId, otherName, isPrivate){
  var uid = currentUserId();
  var f = friendshipCache[otherUserId];
  var btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'btn btn-sm';
  if(!f){
    btn.classList.add('btn-primary');
    btn.textContent = isPrivate ? t('contatti.request') : t('community.addFriend');
    btn.addEventListener('click', function(){ sendFriendRequest(otherUserId, btn); });
  } else if(f.status === 'accepted'){
    btn.classList.add('btn-ghost');
    btn.textContent = t('community.privateMessage');
    btn.addEventListener('click', function(){ window.location.href = 'chat.html?user=' + encodeURIComponent(otherUserId); });
  } else if(f.status === 'pending' && f.requester_id === uid){
    btn.classList.add('btn-ghost');
    btn.textContent = t('community.requestSent');
    btn.disabled = true;
  } else {
    btn.classList.add('btn-primary');
    btn.textContent = t('community.acceptFriend');
    btn.addEventListener('click', function(){ respondFriendRequest(f.id, true); });
  }
  return btn;
}

function contattiCardRow(p, extraMetaHtml){
  var row = document.createElement('div');
  row.className = 'admin-row';
  var avatarHtml = p.avatar_url
    ? '<img class="user-directory-avatar" src="'+coverThumbUrl(escapeHtml(p.avatar_url), 80)+'" alt="" loading="lazy">'
    : '<span class="user-directory-avatar user-directory-avatar-fallback">'+escapeHtml((p.display_name||'?').charAt(0).toUpperCase())+'</span>';
  var lockHtml = p.is_private ? ' 🔒' : '';
  var verifiedHtml = ' ' + verifiedBadge('verified.commenter', !!p.verified);
  var info = document.createElement('div');
  info.className = 'info';
  info.innerHTML =
    '<div class="t">' + escapeHtml(p.display_name || t('notif.someone')) + verifiedHtml + lockHtml + '</div>' +
    '<div class="m">' + (extraMetaHtml || '') + '</div>';
  info.style.cursor = 'pointer';
  info.addEventListener('click', function(){ window.location.href = 'profile.html?user=' + encodeURIComponent(p.id); });
  var actions = document.createElement('div');
  actions.className = 'admin-actions';
  row.innerHTML = '<span class="user-directory-avatar-wrap" style="cursor:pointer;">' + avatarHtml + '</span>';
  row.querySelector('.user-directory-avatar-wrap').addEventListener('click', function(){ window.location.href = 'profile.html?user=' + encodeURIComponent(p.id); });
  row.appendChild(info);
  row.appendChild(actions);
  return { row: row, actions: actions };
}

function renderContattiScopri(query){
  var box = document.getElementById('contattiScopriList');
  if(!box || !isSignedIn()) return;
  box.innerHTML = '<p class="form-note">…</p>';
  var uid = currentUserId();
  var q = (query || '').trim();

  var profilesUrl = SUPABASE_URL + '/rest/v1/profiles?id=neq.' + encodeURIComponent(uid) +
    (q.length >= 2 ? '&display_name=ilike.*' + encodeURIComponent(q) + '*' : '') +
    '&select=id,display_name,avatar_url,verified,is_private&order=display_name.asc&limit=40';

  Promise.all([loadFriendshipMap(), fetch(profilesUrl, { headers: communityHeaders() }).then(function(r){ return r.ok ? r.json() : []; })])
    .then(function(results){
      var profiles = results[1];
      box.innerHTML = '';
      if(profiles.length === 0){ box.innerHTML = '<p class="form-note">' + t('community.noResults') + '</p>'; return; }
      profiles.forEach(function(p){
        loadFollowerCount(p.id).then(function(n){
          var metaText = n + ' ' + t('pubProfile.statFollowers');
          var built = contattiCardRow(p, metaText);
          built.actions.appendChild(contattiFriendButton(p.id, p.display_name, !!p.is_private));
          box.appendChild(built.row);
        });
      });
    })
    .catch(function(e){
      box.innerHTML = '<p class="form-note">' + t('userDir.loadError') + '</p>';
      console.warn('Contatti scopri load failed:', e);
    });
}

function renderContattiAmici(){
  var box = document.getElementById('contattiAmiciList');
  if(!box || !isSignedIn()) return;
  var uid = currentUserId();
  box.innerHTML = '<p class="form-note">…</p>';
  fetch(SUPABASE_URL + '/rest/v1/friendships?select=*&or=(requester_id.eq.' + encodeURIComponent(uid) + ',addressee_id.eq.' + encodeURIComponent(uid) + ')&status=eq.accepted', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(accepted){ renderFriendContactList(box, accepted, uid); })
    .catch(function(e){
      box.innerHTML = '<p class="form-note">' + t('community.loadError') + '</p>';
      console.warn('Contatti amici load failed:', e);
    });
}

function renderContattiRichieste(){
  var box = document.getElementById('contattiRichiesteList');
  var badge = document.getElementById('contattiRequestBadge');
  if(!box || !isSignedIn()) return;
  var uid = currentUserId();
  box.innerHTML = '<p class="form-note">…</p>';
  fetch(SUPABASE_URL + '/rest/v1/friendships?select=*&or=(requester_id.eq.' + encodeURIComponent(uid) + ',addressee_id.eq.' + encodeURIComponent(uid) + ')&status=eq.pending', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      var received = rows.filter(function(f){ return f.addressee_id === uid; });
      var sent = rows.filter(function(f){ return f.requester_id === uid; });
      if(badge){
        badge.textContent = String(received.length);
        badge.classList.toggle('hidden', received.length === 0);
      }
      box.innerHTML = '';
      if(received.length === 0 && sent.length === 0){ box.innerHTML = '<p class="form-note">' + t('contatti.noRequests') + '</p>'; return; }

      received.forEach(function(f){
        getDisplayName(f.requester_id).then(function(name){
          var row = document.createElement('div');
          row.className = 'admin-row';
          row.innerHTML = '<div class="info"><div class="t">' + escapeHtml(name) + '</div></div>' +
            '<div class="admin-actions">' +
              '<button class="btn btn-sm btn-primary" data-accept>' + t('community.acceptFriend') + '</button>' +
              '<button class="btn btn-sm btn-ghost" data-decline>' + t('community.declineFriend') + '</button>' +
            '</div>';
          row.querySelector('[data-accept]').addEventListener('click', function(){
            respondFriendRequest(f.id, true);
            setTimeout(function(){ renderContattiRichieste(); refreshContattiRequestBadge(); }, 400);
          });
          row.querySelector('[data-decline]').addEventListener('click', function(){
            respondFriendRequest(f.id, false);
            setTimeout(function(){ renderContattiRichieste(); refreshContattiRequestBadge(); }, 400);
          });
          box.appendChild(row);
        });
      });
      sent.forEach(function(f){
        getDisplayName(f.addressee_id).then(function(name){
          var row = document.createElement('div');
          row.className = 'admin-row';
          row.innerHTML = '<div class="info"><div class="t">' + escapeHtml(name) + '</div><div class="m">' + t('community.requestSent') + '</div></div>';
          box.appendChild(row);
        });
      });
    })
    .catch(function(e){
      box.innerHTML = '<p class="form-note">' + t('community.loadError') + '</p>';
      console.warn('Contatti richieste load failed:', e);
    });
}

function refreshContattiRequestBadge(){
  var badge = document.getElementById('contattiRequestBadge');
  if(!badge || !isSignedIn()) return;
  var uid = currentUserId();
  fetch(SUPABASE_URL + '/rest/v1/friendships?select=id&addressee_id=eq.' + encodeURIComponent(uid) + '&status=eq.pending', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      badge.textContent = String(rows.length);
      badge.classList.toggle('hidden', rows.length === 0);
    })
    .catch(function(){});
}

function loadContattiPage(){
  var signedInBox = document.getElementById('contattiSignedIn');
  var signedOutBox = document.getElementById('contattiSignedOut');
  if(!signedInBox) return;
  if(!isSignedIn()){
    if(signedOutBox) signedOutBox.classList.remove('hidden');
    signedInBox.classList.add('hidden');
    return;
  }
  if(signedOutBox) signedOutBox.classList.add('hidden');
  signedInBox.classList.remove('hidden');
  followingCache = null;
  ensureContattiChatTab();
  wireContattiHub();
  refreshContattiRequestBadge();
  switchContattiTab(contattiActiveTab);
}

/* ============ NOVITÀ DEL SITO (popup automatico di SmallNox) ============ */
function formatVersion(dateStr){
  var d = new Date(dateStr);
  var mm = String(d.getMonth()+1).padStart(2,'0');
  var dd = String(d.getDate()).padStart(2,'0');
  return d.getFullYear() + '.' + mm + '.' + dd;
}

function checkForSiteUpdates(){
  if(!isSignedIn()) return;
  var lastShown = localStorage.getItem('lux_updates_last_shown');
  var dayMs = 24 * 60 * 60 * 1000;
  if(lastShown && (Date.now() - new Date(lastShown).getTime()) < dayMs) return; // già visto meno di 24h fa

  fetch(SUPABASE_URL + '/rest/v1/site_updates?select=title,created_at&order=created_at.desc&limit=50', { headers: communityHeaders() })
    .then(function(r){ if(!r.ok) throw new Error('site updates read failed'); return r.json(); })
    .then(function(rows){
      if(rows.length === 0) return;
      renderSiteUpdatesModal(rows);
      document.getElementById('smallnoxUpdatesModal').classList.remove('hidden');
    })
    .catch(function(e){ console.warn('Site updates check failed:', e); });
}

/* Badge sul pallino di SmallNox: acceso solo se esiste un aggiornamento più recente
   dell'ultima volta che l'utente ha visto il popup (automatico o manuale) — decade
   da solo perché smette di avere senso non appena non ci sono aggiornamenti nuovi. */
function refreshSmallNoxBadge(){
  var badge = document.getElementById('smallnoxBadge');
  if(!badge) return;
  fetch(SUPABASE_URL + '/rest/v1/site_updates?select=created_at&order=created_at.desc&limit=1', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      if(rows.length === 0){ badge.classList.add('hidden'); return; }
      var latest = new Date(rows[0].created_at).getTime();
      var lastShown = localStorage.getItem('lux_updates_last_shown');
      var unseen = !lastShown || latest > new Date(lastShown).getTime();
      badge.classList.toggle('hidden', !unseen);
    })
    .catch(function(){ badge.classList.add('hidden'); });
}

/* Cliccando l'icona di SmallNox: apre sempre l'assistente, e se ci sono
   aggiornamenti mai visti apre anche il popup delle novità, col numero di versione. */
function openSmallNoxAssistant(){
  document.getElementById('smallnoxModal').classList.remove('hidden');
  ensureSmallNoxHistoryButton();
  fetch(SUPABASE_URL + '/rest/v1/site_updates?select=title,created_at&order=created_at.desc&limit=50', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      if(rows.length === 0) return;
      var latest = new Date(rows[0].created_at).getTime();
      var lastShown = localStorage.getItem('lux_updates_last_shown');
      var unseen = !lastShown || latest > new Date(lastShown).getTime();
      if(!unseen) return;
      renderSiteUpdatesModal(rows);
      var vt = document.getElementById('smallnoxVersionTag');
      if(vt) vt.textContent = 'v' + formatVersion(rows[0].created_at);
      document.getElementById('smallnoxUpdatesModal').classList.remove('hidden');
    })
    .catch(function(e){ console.warn('SmallNox updates check failed:', e); });
}

/* Il popup delle novità si apriva solo la prima volta che ce n'era una non
   vista — una volta chiuso, non c'era più modo di riaprirlo per rivederlo.
   Questo bottone dentro l'assistente lo riapre sempre, con tutto lo
   storico (vecchie e nuove voci insieme, come già fa renderSiteUpdatesModal
   raggruppandole per data), a prescindere da cosa è già stato visto. */
function showSiteUpdatesHistory(){
  fetch(SUPABASE_URL + '/rest/v1/site_updates?select=title,created_at&order=created_at.desc&limit=50', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){
      if(rows.length === 0) return;
      renderSiteUpdatesModal(rows);
      document.getElementById('smallnoxUpdatesModal').classList.remove('hidden');
    })
    .catch(function(e){ console.warn('SmallNox history fetch failed:', e); });
}

function ensureSmallNoxHistoryButton(){
  var modal = document.getElementById('smallnoxModal');
  if(!modal || document.getElementById('smallnoxHistoryBtn')) return;
  var btn = document.createElement('button');
  btn.type = 'button';
  btn.id = 'smallnoxHistoryBtn';
  btn.textContent = t('smallnoxUpdates.viewHistory') || 'Vedi tutte le novità';
  btn.style.cssText = 'display:block;width:calc(100% - 40px);margin:16px 20px 4px;padding:12px;' +
    'border-radius:10px;border:1px solid var(--gold);background:transparent;color:var(--gold);' +
    'font-family:"Cinzel",serif;font-size:14px;cursor:pointer;';
  btn.addEventListener('click', showSiteUpdatesHistory);
  // #smallnoxModal è quasi sicuramente il contenitore esterno (a schermo
  // intero), non la card visibile — se ha un figlio diretto che fa da
  // "scatola" del contenuto, il bottone va dentro quello, non attaccato
  // al contenitore esterno (altrimenti finisce fuori dalla card, come
  // successo la prima volta).
  var innerBox = modal.querySelector(':scope > div') || modal;
  innerBox.appendChild(btn);
}

/* Le voci di site_updates sono scritte in italiano nel database — le
   traduciamo al volo verso la lingua dell'interfaccia (stesso motore di
   translateChatMessage, DeepL rileva la lingua di partenza da solo), con
   una cache locale così non richiamiamo il traduttore ogni volta che si
   riapre lo stesso popup con le stesse voci. */
function getUpdatesTranslationCache(){
  try{ return JSON.parse(localStorage.getItem('lux_updates_i18n') || '{}'); }catch(e){ return {}; }
}
function saveUpdatesTranslationCache(cache){
  try{ localStorage.setItem('lux_updates_i18n', JSON.stringify(cache)); }catch(e){}
}
function translateUpdateTitles(titles){
  if(currentLang === 'it' || !getSession()) return Promise.resolve({});
  var cache = getUpdatesTranslationCache();
  var langCache = cache[currentLang] || (cache[currentLang] = {});
  var toFetch = titles.filter(function(title){ return !langCache[title]; });
  if(toFetch.length === 0) return Promise.resolve(langCache);
  return Promise.all(toFetch.map(function(title){
    return translateChatMessage(title).then(function(res){
      langCache[title] = res.translated || title;
    }).catch(function(){ langCache[title] = title; });
  })).then(function(){
    saveUpdatesTranslationCache(cache);
    return langCache;
  });
}

/* Disegna il bordo del pannello come farebbe una matita: un rettangolo SVG
   tracciato con un'animazione dello stroke (da invisibile a completo), con
   una piccola matita che compare all'inizio del tratto e sparisce appena
   il bordo è finito. Ogni pannello parte con un piccolo ritardo in più
   rispetto al precedente, così si "disegnano" uno dietro l'altro scendendo
   lungo la lista invece che tutti insieme. */
function animateComicPanelFrame(panel, color, delayMs){
  requestAnimationFrame(function(){
    var w = panel.offsetWidth, h = panel.offsetHeight;
    if(!w || !h) return;
    var svgNS = 'http://www.w3.org/2000/svg';
    var svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('width', w);
    svg.setAttribute('height', h);
    svg.style.cssText = 'position:absolute;top:0;left:0;overflow:visible;pointer-events:none;';
    var rEl = document.createElementNS(svgNS, 'rect');
    rEl.setAttribute('x', 1.5);
    rEl.setAttribute('y', 1.5);
    rEl.setAttribute('width', Math.max(0, w - 3));
    rEl.setAttribute('height', Math.max(0, h - 3));
    rEl.setAttribute('rx', 10);
    rEl.setAttribute('fill', 'none');
    rEl.setAttribute('stroke', color);
    rEl.setAttribute('stroke-width', 2.5);
    rEl.setAttribute('stroke-linecap', 'round');
    svg.appendChild(rEl);
    panel.insertBefore(svg, panel.firstChild);

    var len = rEl.getTotalLength();
    var drawMs = 850;
    rEl.style.strokeDasharray = len;
    rEl.style.strokeDashoffset = len;
    rEl.style.transition = 'stroke-dashoffset ' + drawMs + 'ms ease-out ' + delayMs + 'ms';

    var pencil = document.createElement('span');
    pencil.textContent = '✎';
    pencil.setAttribute('aria-hidden', 'true');
    pencil.style.cssText = 'position:absolute;left:6px;top:-15px;font-size:17px;color:' + color +
      ';opacity:0;transition:opacity 160ms ease ' + delayMs + 'ms;';
    panel.appendChild(pencil);

    // Il timbro "A.I." prende il posto della matita non appena il tratto è
    // finito — il pubblico vede prima il gesto ("disegnato a mano"), poi
    // la firma che dice chi l'ha disegnato davvero.
    var aiTag = document.createElement('span');
    aiTag.textContent = 'A.I.';
    aiTag.setAttribute('aria-hidden', 'true');
    aiTag.style.cssText = 'position:absolute;right:10px;top:-11px;font-family:"Space Mono",monospace;' +
      'font-size:10px;letter-spacing:0.08em;color:' + color + ';background:#150d0e;border:1.5px solid ' + color +
      ';border-radius:20px;padding:2px 8px;opacity:0;transition:opacity 320ms ease ' + (delayMs + drawMs + 150) + 'ms;';
    panel.appendChild(aiTag);

    requestAnimationFrame(function(){
      rEl.style.strokeDashoffset = 0;
      pencil.style.opacity = 1;
      aiTag.style.opacity = 1;
      setTimeout(function(){
        pencil.style.transition = 'opacity 280ms ease';
        pencil.style.opacity = 0;
      }, delayMs + drawMs);
    });
  });
}

/* Iniettato una sola volta: il retino a puntini in stile fumetto che si
   muove piano dietro ai pannelli delle novità, e il font per la firma. */
function ensureSmallNoxComicStyle(){
  var existing = document.getElementById('smallnoxComicStyle');
  if(existing) return;
  var styleEl = document.createElement('style');
  styleEl.id = 'smallnoxComicStyle';
  styleEl.textContent =
    '@keyframes smallnoxDotsMove{from{background-position:0 0;}to{background-position:36px 36px;}}' +
    '.smallnox-comic-bg{position:relative;background-image:radial-gradient(circle,rgba(201,162,77,0.18) 1.6px,transparent 1.7px);' +
    'background-size:18px 18px;animation:smallnoxDotsMove 7s linear infinite;border-radius:14px;' +
    'display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:26px 14px;align-items:start;width:100%;box-sizing:border-box;}' +
    '.smallnox-comic-span{grid-column:1 / -1;}' +
    '.smallnox-updates-box{position:relative;}';
  document.head.appendChild(styleEl);
}

/* Il popup che contiene #smallnoxUpdatesList ha una larghezza fissa e
   stretta pensata per la vecchia lista puntata — troppo poco per una
   griglia di pannelli su schermi larghi. Allarghiamo qui, via JS, il
   contenitore diretto della lista, senza toccare il resto della finestra
   di dialogo (avatar, titolo, pulsante). Il dipinto va qui e non dentro
   la lista: con "background-attachment:fixed" resta ancorato alla vista
   del popup mentre i pannelli scorrono sopra, invece di allungarsi e
   scomparire lungo tutta l'altezza scrollabile della lista. */
function widenSmallNoxUpdatesBox(list){
  var box = list.parentElement;
  if(box){
    box.style.maxWidth = 'min(92vw, 760px)';
    box.style.width = '100%';
    box.style.boxSizing = 'border-box';
    box.classList.add('smallnox-updates-box');
    box.style.backgroundImage = 'linear-gradient(rgba(24,15,16,0.72),rgba(24,15,16,0.8)), url("smallnox-updates-bg.webp")';
    box.style.backgroundSize = 'cover';
    box.style.backgroundPosition = 'center';
    box.style.backgroundAttachment = 'fixed';
    box.style.backgroundRepeat = 'no-repeat';
  }
}

function renderSiteUpdatesModal(rows){
  var list = document.getElementById('smallnoxUpdatesList');
  if(!list) return;
  var vt = document.getElementById('smallnoxVersionTag');
  if(vt && rows.length) vt.textContent = 'v' + formatVersion(rows[0].created_at);
  ensureSmallNoxComicStyle();
  widenSmallNoxUpdatesBox(list);

  // Stile "tavola a fumetti": pannelli con un numero cerchiato che sporge
  // dall'angolo, come un numero di uscita — font del sito (Cinzel per il
  // numero, Crimson Pro per il testo). Il bordo di ogni pannello si disegna
  // da solo come tracciato a matita (vedi animateComicPanelFrame). Sfondo a
  // due livelli: il dipinto delle due sorelle in trasparenza, con sopra il
  // retino a puntini animato. Griglia a colonne flessibili (auto-fit) così la lista resta
  // compatta invece di allungarsi in verticale.
  list.innerHTML = '';
  list.className = (list.className ? list.className + ' ' : '') + 'smallnox-comic-bg';
  list.style.cssText = 'padding:14px;';

  var accentColors = ['#c9a24d', '#5dcaa5', '#e2916b'];
  var groups = {};
  var order = [];
  rows.forEach(function(row){
    var d = new Date(row.created_at);
    var key = d.toISOString().slice(0,13);
    if(!groups[key]){ groups[key] = { date: d, items: [] }; order.push(key); }
    groups[key].items.push(row);
  });

  var rowEls = [];
  var counter = 0;
  order.forEach(function(key, gi){
    var g = groups[key];
    var head = document.createElement('div');
    head.className = 'smallnox-comic-span';
    head.style.cssText = 'font-family:"Space Mono",monospace;font-size:11px;letter-spacing:0.06em;color:var(--gold);margin:' + (gi===0?'0':'12px') + ' 0 4px;';
    head.textContent = g.date.toLocaleDateString() + ' — ' + g.date.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});
    list.appendChild(head);

    g.items.forEach(function(row){
      counter++;
      var color = accentColors[(counter-1) % accentColors.length];
      var panel = document.createElement('div');
      panel.style.cssText = 'position:relative;border-radius:10px;background:rgba(21,13,14,0.82);padding:16px 16px 16px 36px;';
      var badge = document.createElement('div');
      badge.style.cssText = 'position:absolute;top:-16px;left:12px;width:32px;height:32px;border-radius:50%;background:' + color +
        ';border:3px solid #150d0e;display:flex;align-items:center;justify-content:center;font-family:"Cinzel Decorative",serif;font-weight:700;font-size:14px;color:#150d0e;';
      badge.textContent = String(counter);
      var titleEl = document.createElement('div');
      titleEl.style.cssText = 'font-family:"Crimson Pro",serif;font-size:15px;line-height:1.45;color:#f0e4cd;';
      titleEl.textContent = row.title;
      panel.appendChild(badge);
      panel.appendChild(titleEl);
      list.appendChild(panel);
      rowEls.push({ el: titleEl, original: row.title });
      animateComicPanelFrame(panel, color, (counter - 1) * 260);
    });
  });

  var signature = document.createElement('div');
  signature.className = 'smallnox-comic-span';
  signature.style.cssText = 'font-family:"Crimson Pro",serif;font-style:italic;font-size:18px;color:var(--gold);text-align:right;margin:8px 6px 0;';
  signature.textContent = '— Nox Morningstar';
  list.appendChild(signature);

  var uniqueTitles = rows.map(function(r){ return r.title; }).filter(function(v,i,a){ return a.indexOf(v)===i; });
  translateUpdateTitles(uniqueTitles).then(function(map){
    rowEls.forEach(function(r){
      if(map[r.original] && map[r.original] !== r.original) r.el.textContent = map[r.original];
    });
  });
}

function dismissSiteUpdates(){
  localStorage.setItem('lux_updates_last_shown', new Date().toISOString());
  document.getElementById('smallnoxUpdatesModal').classList.add('hidden');
  var badge = document.getElementById('smallnoxBadge');
  if(badge) badge.classList.add('hidden');
}

function heartbeatPresence(){
  if(!isSignedIn()) return;
  if(Date.now() - lastHeartbeatAt < 30000) return; // appena scritto dall'altro battito
  lastHeartbeatAt = Date.now();
  var session = getSession();
  var uid = currentUserId();
  if(!uid) return;
  fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(uid), {
    method:'PATCH',
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
    body: JSON.stringify({ last_seen: new Date().toISOString() })
  }).catch(function(){});
}
function getPresence(userId){
  return fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(userId) + '&select=last_seen', { headers: communityHeaders() })
    .then(function(r){ return r.ok ? r.json() : []; })
    .then(function(rows){ return rows[0] ? isOnlineSince(rows[0].last_seen) : false; })
    .catch(function(){ return false; });
}

function renderDmThreadsList(){
  var list = document.getElementById('dmThreadsList');
  if(!list) return;
  var uid = currentUserId();
  var rows = dmThreadsCache.filter(function(th){
    var st = dmThreadState(th, uid);
    if(dmActiveTab === 'archived') return st.archived;
    if(st.archived) return false; // le archiviate si vedono solo nella loro scheda
    if(dmActiveTab === 'unread') return !st.read;
    if(dmActiveTab === 'important') return st.important;
    return true; // 'all'
  });
  list.innerHTML = '';
  if(rows.length === 0){ list.innerHTML = '<p class="form-note">' + t('community.noDms') + '</p>'; return; }
  rows.forEach(function(th){
    var st = dmThreadState(th, uid);
    getDisplayName(st.otherId).then(function(name){
      var row = document.createElement('div');
      row.className = 'dm-thread-row' + (st.read ? '' : ' unread');

      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'dm-thread-item';
      var dot = document.createElement('span');
      dot.className = 'dm-presence-dot';
      var nameSpan = document.createElement('span');
      nameSpan.textContent = name + (st.read ? '' : ' •');
      btn.appendChild(dot);
      btn.appendChild(nameSpan);
      getPresence(st.otherId).then(function(online){ dot.classList.toggle('online', online); });
      btn.addEventListener('click', function(){ openDmThread(th.id, name); });
      row.appendChild(btn);

      var starBtn = document.createElement('button');
      starBtn.type = 'button';
      starBtn.className = 'dm-thread-star' + (st.important ? ' active' : '');
      starBtn.setAttribute('aria-label', t('community.important') || 'Importante');
      starBtn.textContent = '★';
      starBtn.addEventListener('click', function(e){ e.stopPropagation(); toggleDmImportant(th, uid, starBtn); });
      row.appendChild(starBtn);

      var archBtn = document.createElement('button');
      archBtn.type = 'button';
      archBtn.className = 'dm-thread-archive';
      archBtn.setAttribute('aria-label', t('community.archive') || 'Archivia');
      archBtn.textContent = st.archived ? '↩' : '🗄';
      archBtn.addEventListener('click', function(e){
        e.stopPropagation();
        if(st.archived) unarchiveDmThread(th, uid); else archiveDmThread(th, uid);
      });
      row.appendChild(archBtn);

      list.appendChild(row);
    });
  });
}

function ensureDmTabsBar(){
  var list = document.getElementById('dmThreadsList');
  if(!list || document.getElementById('dmTabsBar')) return;
  var bar = document.createElement('div');
  bar.id = 'dmTabsBar';
  bar.className = 'dm-tabs';
  bar.innerHTML =
    '<button type="button" class="dm-tab active" data-dm-tab="all">Tutti</button>' +
    '<button type="button" class="dm-tab" data-dm-tab="unread">Da leggere</button>' +
    '<button type="button" class="dm-tab" data-dm-tab="important">Importanti</button>' +
    '<button type="button" class="dm-tab" data-dm-tab="archived">Archiviate</button>';
  list.parentNode.insertBefore(bar, list);
  Array.prototype.forEach.call(bar.querySelectorAll('.dm-tab'), function(btn){
    btn.addEventListener('click', function(){ switchDmTab(btn.dataset.dmTab); });
  });
}
new MutationObserver(ensureDmTabsBar).observe(document.body, { childList: true, subtree: true });
ensureDmTabsBar();

