    '.ml-adult[aria-pressed="true"] .sw::after{transform:translateX(16px);}',
    '.ml-tabs{display:flex;gap:6px;padding:0 16px 10px;overflow-x:auto;flex-shrink:0;scrollbar-width:none;}',
    '.ml-tabs::-webkit-scrollbar{display:none;}',
