    '.music-library-navbtn.active{background:var(--ml-wine);border-color:var(--ml-wine);color:#fff;}',
    '.ml-tools{display:flex;gap:10px;flex-wrap:wrap;align-items:center;padding:0 16px 8px;flex-shrink:0;}',
