/* ============ MODERATION QUEUE (admin) ============ */
/* ============ DIAGNOSTICA DEL SITO (solo Admin) ============
   Controlla pagine chiave, tabelle del database e un campione di
   file multimediali; ogni controllo ha un codice fisso (LX-1xx
   pagine, LX-2xx database, LX-3xx media, LX-4xx errori JavaScript
   rilevati) così un problema segnalato è sempre lo stesso identico
   controllo, riproducibile da conversazione a conversazione. */

var __diagnosticsJsErrors = [];
window.addEventListener('error', function(e){
  __diagnosticsJsErrors.push((e.message || 'Errore sconosciuto') + ' — ' + (e.filename || '') + ':' + (e.lineno || '?'));
});
window.addEventListener('unhandledrejection', function(e){
  __diagnosticsJsErrors.push('Promise non gestita: ' + (e.reason && e.reason.message ? e.reason.message : String(e.reason)));
});

function fetchWithTimeout(url, options, ms){
  var controller = new AbortController();
  var timer = setTimeout(function(){ controller.abort(); }, ms || 8000);
  return fetch(url, Object.assign({}, options, { signal: controller.signal }))
    .finally(function(){ clearTimeout(timer); });
}

function runSiteDiagnostics(){
  var progressEl = document.getElementById('diagnosticsProgress');
  var resultsEl = document.getElementById('diagnosticsResults');
  var copyBtn = document.getElementById('btnCopyDiagnostics');
  var runBtn = document.getElementById('btnRunDiagnostics');
  runBtn.disabled = true;
  copyBtn.classList.add('hidden');
  resultsEl.innerHTML = '';
  progressEl.textContent = 'Controllo pagine e file...';

  var results = [];

  // ---------- LX-1xx: pagine e file chiave del sito ----------
  var files = [
    'app.js','style.css','loader.js','chrome-top.html','chrome-footer.html','chrome-modals.html',
    'manifest.json','sw.js','index.html','schedario.html','dossier.html','founder.html',
    'community.html','mycomics.html','luxtify.html','luxtify-logo.jpg'
  ];
  var fileChecks = files.map(function(f, i){
    var code = 'LX-1' + String(i + 1).padStart(2, '0');
    return fetchWithTimeout(f, { method: 'HEAD', cache: 'no-store' }, 8000)
      .then(function(r){ return { code: code, label: 'Pagina/file: ' + f, ok: r.ok, detail: r.ok ? '' : 'HTTP ' + r.status }; })
      .catch(function(err){ return { code: code, label: 'Pagina/file: ' + f, ok: false, detail: 'Non raggiungibile (' + (err.name === 'AbortError' ? 'timeout' : err.message) + ')' }; });
  });

  // ---------- LX-2xx: tabelle del database ----------
  var tables = ['catalog','songs','playlists','playlist_songs','podcasts','podcast_episodes','comments','song_likes','notifications','profiles','saved_collaborators'];
  var tableChecks = tables.map(function(tbl, i){
    var code = 'LX-2' + String(i + 1).padStart(2, '0');
    return fetchWithTimeout(SUPABASE_URL + '/rest/v1/' + tbl + '?select=id&limit=1', { headers:{ 'apikey':SUPABASE_ANON_KEY } }, 8000)
      .then(function(r){ return { code: code, label: 'Tabella database: ' + tbl, ok: r.ok, detail: r.ok ? '' : 'HTTP ' + r.status }; })
      .catch(function(err){ return { code: code, label: 'Tabella database: ' + tbl, ok: false, detail: 'Non raggiungibile (' + (err.name === 'AbortError' ? 'timeout' : err.message) + ')' }; });
  });

  Promise.all(fileChecks.concat(tableChecks)).then(function(fileAndTableResults){
    results = results.concat(fileAndTableResults);
    progressEl.textContent = 'Controllo di un campione di copertine e file audio...';

    // ---------- LX-3xx: campione di media (copertine/audio) ----------
    return fetch(SUPABASE_URL + '/rest/v1/songs?select=id,title,cover_url,audio_url&order=created_at.desc&limit=5', { headers:{ 'apikey':SUPABASE_ANON_KEY } })
      .then(function(r){ return r.ok ? r.json() : []; })
      .catch(function(){ return []; });
  }).then(function(sampleSongs){
    var mediaChecks = [];
    var counter = 1;
    sampleSongs.forEach(function(s){
      ['cover_url','audio_url'].forEach(function(field){
        if(!s[field]) return;
        var code = 'LX-3' + String(counter++).padStart(2, '0');
        var label = 'Media "' + (s.title || s.id) + '" (' + field + ')';
        var check;
        if(field === 'audio_url' && s[field].indexOf('http') !== 0){
          // Audio protetto: nel database c'è solo il percorso nel bucket privato, non un indirizzo. Il lettore chiede un link
          // firmato temporaneo: si controlla la stessa cosa (prima non lo si faceva, e ogni canzone nuova risultava "404" a torto)
          check = resolveSongAudioUrl(s[field]).then(function(realUrl){
            if(!realUrl) return { code: code, label: label, ok: false, detail: 'Link di ascolto non creato: il file non risulta nel bucket privato "songs-private" (percorso: ' + s[field] + ')' };
            return fetchWithTimeout(realUrl, { method:'GET', headers:{ 'Range':'bytes=0-0' } }, 10000)
              .then(function(r){ return { code: code, label: label, ok: r.ok, detail: r.ok ? '' : 'HTTP ' + r.status + ' sul link firmato' }; });
          });
        } else {
          check = fetchWithTimeout(s[field], { method:'HEAD' }, 10000)
            .then(function(r){ return { code: code, label: label, ok: r.ok, detail: r.ok ? '' : 'HTTP ' + r.status }; });
        }
        mediaChecks.push(check.catch(function(err){ return { code: code, label: label, ok: false, detail: 'Non raggiungibile (' + (err.name === 'AbortError' ? 'timeout' : err.message) + ')' }; }));
      });
    });
    return Promise.all(mediaChecks);
  }).then(function(mediaResults){
    results = results.concat(mediaResults);

    // ---------- LX-4xx: errori JavaScript rilevati in questa sessione ----------
    if(__diagnosticsJsErrors.length === 0){
      results.push({ code: 'LX-401', label: 'Errori JavaScript rilevati in questa sessione', ok: true, detail: '' });
    } else {
      __diagnosticsJsErrors.forEach(function(msg, i){
        results.push({ code: 'LX-4' + String(i + 1).padStart(2, '0'), label: 'Errore JavaScript rilevato', ok: false, detail: msg });
      });
    }

    renderDiagnosticsResults(results);
    progressEl.textContent = 'Analisi completata.';
    runBtn.disabled = false;
  }).catch(function(err){
    progressEl.textContent = "Errore durante l'analisi: " + err.message;
    runBtn.disabled = false;
  });
}

function renderDiagnosticsResults(results){
  var resultsEl = document.getElementById('diagnosticsResults');
  var copyBtn = document.getElementById('btnCopyDiagnostics');
  var failed = results.filter(function(r){ return !r.ok; });
  var passed = results.filter(function(r){ return r.ok; });

  var summary = failed.length === 0
    ? '<p style="color:#4ade80;font-weight:600;">✅ Nessun problema trovato (' + passed.length + ' controlli superati).</p>'
    : '<p style="color:#e24b4a;font-weight:600;">⚠️ ' + failed.length + ' problemi trovati su ' + results.length + ' controlli.</p>';

  var rows = failed.map(function(r){
    return '<div style="display:flex;gap:10px;padding:8px 0;border-bottom:1px solid var(--line);">' +
      '<span style="font-family:monospace;color:#e24b4a;font-weight:600;flex-shrink:0;">' + r.code + '</span>' +
      '<div><div style="color:var(--parchment);font-size:13px;">' + escapeHtml(r.label) + '</div>' +
      (r.detail ? '<div style="color:var(--parchment-dim);font-size:12px;">' + escapeHtml(r.detail) + '</div>' : '') + '</div>' +
    '</div>';
  }).join('');

  resultsEl.innerHTML = summary + rows;

  if(failed.length > 0){
    copyBtn.classList.remove('hidden');
    copyBtn.onclick = function(){
      var report = failed.map(function(r){ return r.code + ' — ' + r.label + (r.detail ? ' (' + r.detail + ')' : ''); }).join('\n');
      navigator.clipboard.writeText(report).then(function(){
        copyBtn.textContent = '✅ Copiato!';
        setTimeout(function(){ copyBtn.textContent = '📋 Copia report'; }, 2000);
      }).catch(function(){ window.alert(report); });
    };
  } else {
    copyBtn.classList.add('hidden');
  }
}

function switchAdminTab(tabName){
  document.querySelectorAll('.admin-tab').forEach(function(btn){
    btn.classList.toggle('active', btn.dataset.tab === tabName);
  });
  document.querySelectorAll('.admin-tab-panel').forEach(function(panel){
    panel.classList.toggle('hidden', panel.dataset.tabPanel !== tabName);
  });
  if(tabName === 'moderation') renderCommunityModeration();
  if(tabName === 'stats') renderSongStatsLeaderboard();
  if(tabName === 'artists') renderAdminArtistsList();
  if(tabName === 'servers') loadServersAdminList();
  if(tabName === 'events') loadEventsAdminList();
  if(tabName === 'maintenance') renderAdminStatusPanel();
}

function renderAdminArtistsList(){
  var box = document.getElementById('adminArtistsList');
  if(!box) return;
  box.innerHTML = '<p class="form-note">…</p>';
  Promise.all([
    fetch(SUPABASE_URL + '/rest/v1/songs?select=artist&order=artist.asc', { headers:{ 'apikey':SUPABASE_ANON_KEY } }).then(function(r){ return r.ok ? r.json() : []; }),
    fetch(SUPABASE_URL + '/rest/v1/artists?select=*', { headers:{ 'apikey':SUPABASE_ANON_KEY } }).then(function(r){ return r.ok ? r.json() : []; })
  ]).then(function(results){
    var names = [];
    results[0].forEach(function(s){ if(s.artist && names.indexOf(s.artist) === -1) names.push(s.artist); });
    var bios = {};
    results[1].forEach(function(a){ bios[a.name] = a.bio || ''; });

    if(names.length === 0){ box.innerHTML = '<p class="form-note">Nessun artista ancora (aggiungi canzoni con un nome artista).</p>'; return; }

    box.innerHTML = names.map(function(name, i){
      return '<div style="border-bottom:1px solid var(--line);padding:10px 0;">' +
        '<div style="color:var(--parchment);font-size:13px;font-weight:600;margin-bottom:6px;">' + escapeHtml(name) + '</div>' +
        '<textarea data-artist-bio="' + i + '" rows="2" placeholder="Biografia..." style="width:100%;box-sizing:border-box;margin-bottom:6px;">' + escapeHtml(bios[name] || '') + '</textarea>' +
        '<button type="button" class="btn btn-sm btn-ghost" data-save-artist="' + i + '">Salva</button>' +
        '<span class="form-note" data-artist-status="' + i + '" style="margin-left:8px;"></span>' +
      '</div>';
    }).join('');

    Array.prototype.forEach.call(box.querySelectorAll('[data-save-artist]'), function(btn){
      btn.addEventListener('click', function(){
        var i = btn.dataset.saveArtist;
        var name = names[Number(i)];
        var bio = box.querySelector('[data-artist-bio="' + i + '"]').value.trim();
        var statusEl = box.querySelector('[data-artist-status="' + i + '"]');
        var session = getSession();
        fetch(SUPABASE_URL + '/rest/v1/artists?on_conflict=name', {
          method:'POST',
          headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'resolution=merge-duplicates' },
          body: JSON.stringify({ name: name, bio: bio || null })
        }).then(function(r){
          if(!r.ok) throw new Error('salvataggio bio fallito: ' + r.status);
          statusEl.textContent = 'Salvata ✓';
          setTimeout(function(){ statusEl.textContent = ''; }, 2000);
        }).catch(function(){ statusEl.textContent = 'Errore.'; });
      });
    });
  });
}

function renderSongStatsLeaderboard(){
  var box = document.getElementById('songStatsLeaderboard');
  if(!box) return;
  box.innerHTML = '<p class="form-note">…</p>';
  fetch(SUPABASE_URL + '/rest/v1/songs?select=id,title,artist,views,plays&order=plays.desc.nullslast&limit=15', {
    headers:{ 'apikey':SUPABASE_ANON_KEY }
  }).then(function(r){ return r.ok ? r.json() : []; }).then(function(rows){
    if(rows.length === 0){ box.innerHTML = '<p class="form-note">Nessuna canzone caricata ancora.</p>'; return; }
    box.innerHTML = rows.map(function(s, i){
      return '<div style="display:flex;align-items:center;gap:10px;padding:6px 0;border-bottom:1px solid var(--line);">' +
        '<span style="color:var(--gold);font-size:12px;width:20px;flex-shrink:0;">' + (i + 1) + '</span>' +
        '<div style="flex:1;min-width:0;"><div style="color:var(--parchment);font-size:13px;">' + escapeHtml(s.title) + '</div>' +
        (s.artist ? '<div style="color:var(--parchment-dim);font-size:11px;">' + escapeHtml(s.artist) + '</div>' : '') + '</div>' +
        '<span style="color:var(--parchment-dim);font-size:12px;white-space:nowrap;">👁 ' + (s.views || 0) + ' · 🎧 ' + (s.plays || 0) + '</span>' +
      '</div>';
    }).join('');
  }).catch(function(){ box.innerHTML = '<p class="form-note">Errore nel caricamento.</p>'; });
}

function renderStatsPanel(){
  if(!isAdmin()) return;
  var box = document.getElementById('statsPanel');
  if(!box) return;
  var items = getCatalog().slice();
  if(items.length === 0){ box.innerHTML = '<p class="form-note">' + t('stats.empty') + '</p>'; return; }
  items.sort(function(a,b){ return (b.view_count||0) - (a.view_count||0); });
  var maxViews = Math.max.apply(null, items.map(function(i){ return i.view_count || 0; })) || 1;
  box.innerHTML = '';
  items.forEach(function(item){
    var row = document.createElement('div');
    row.className = 'stats-row';
    var pct = Math.round(((item.view_count || 0) / maxViews) * 100);
    row.innerHTML =
      '<div class="stats-title">' + escapeHtml(item.title) + '</div>' +
      '<div class="stats-numbers">' +
        (item.view_count||0) + ' ' + t('stats.views') + ' · ' +
        (item.like_count||0) + ' ' + t('stats.likes') + ' · ' +
        (item.save_count||0) + ' ' + t('stats.saves') + ' · ' +
        (item.share_count||0) + ' ' + t('stats.shares') + ' · ' +
        (item.cart_add_count||0) + ' ' + t('stats.cartAdds') +
      '</div>' +
      '<div class="stats-bar-track"><div class="stats-bar-fill" style="width:' + pct + '%"></div></div>';
    box.appendChild(row);
  });
}

function handleAddAnnouncement(){
  var title = document.getElementById('fAnnTitle').value.trim();
  var body = document.getElementById('fAnnBody').value.trim();
  var link = document.getElementById('fAnnLink').value.trim();
  var imageFile = document.getElementById('fAnnImage').files[0];
  var pdfFile = document.getElementById('fAnnPdf') ? document.getElementById('fAnnPdf').files[0] : null;
  var err = document.getElementById('announcementError');
  err.textContent = '';
  if(!title || !body){ err.textContent = t('err.required'); return; }
  var session = getSession();

  var imageStep = Promise.resolve(null);
  if(imageFile){
    var extMatch = /\.([a-zA-Z0-9]+)$/.exec(imageFile.name || '');
    var ext = extMatch ? extMatch[1].toLowerCase() : 'jpg';
    var path = 'announcements/' + Date.now() + '_' + Math.random().toString(36).slice(2, 8) + '.' + ext;
    imageStep = fetch(SUPABASE_URL + '/storage/v1/object/comic-pages/' + path, {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type': imageFile.type || 'image/jpeg' },
      body: imageFile
    }).then(function(r){
      if(!r.ok){
        return r.text().then(function(bodyText){
          throw new Error('Caricamento immagine fallito (HTTP ' + r.status + ') — ' + bodyText.slice(0,200));
        });
      }
      return SUPABASE_URL + '/storage/v1/object/public/comic-pages/' + path;
    });
  }

  var pdfStep = imageStep.then(function(imageUrl){
    if(!pdfFile) return { imageUrl: imageUrl, pdfUrl: null };
    var pdfPath = 'announcements/' + Date.now() + '_' + Math.random().toString(36).slice(2, 8) + '.pdf';
    return fetch(SUPABASE_URL + '/storage/v1/object/comic-pages/' + pdfPath, {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type': 'application/pdf' },
      body: pdfFile
    }).then(function(r){
      if(!r.ok){
        return r.text().then(function(bodyText){
          throw new Error('Caricamento PDF fallito (HTTP ' + r.status + ') — ' + bodyText.slice(0,200));
        });
      }
      return { imageUrl: imageUrl, pdfUrl: SUPABASE_URL + '/storage/v1/object/public/comic-pages/' + pdfPath };
    });
  });

  pdfStep.then(function(urls){
    return fetch(SUPABASE_URL + '/rest/v1/announcements', {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'return=representation' },
      body: JSON.stringify({ title: title, body: body, link_url: link || null, image_url: urls.imageUrl, pdf_url: urls.pdfUrl, published: true, expires_at: new Date(Date.now() + 24*60*60*1000).toISOString() })
    }).then(function(r){
      if(!r.ok){
        return r.text().then(function(bodyText){
          throw new Error('Salvataggio annuncio fallito (HTTP ' + r.status + ') — ' + bodyText.slice(0,200));
        });
      }
      return r;
    });
  }).then(function(r){
    r.json().then(function(rows){ if(rows && rows[0]) luxTranslateRow('announcements', rows[0]); }).catch(function(){}); // v227
    document.getElementById('fAnnTitle').value = '';
    document.getElementById('fAnnBody').value = '';
    document.getElementById('fAnnLink').value = '';
    document.getElementById('fAnnImage').value = '';
    document.getElementById('fAnnImagePreview').classList.add('hidden');
    if(document.getElementById('fAnnPdf')) document.getElementById('fAnnPdf').value = '';
    renderAdminAnnouncements();
    fetchAnnouncements();
  }).catch(function(e){
    console.warn('Announcement publish failed:', e);
    err.textContent = t('announcements.publishError') + (e && e.message ? ' — ' + e.message : '');
  });
}

var VERIFICATION_MIN_DAYS = 90; // regola dei 90 giorni: la spunta blu non si può assegnare prima

/* Dopo "Assegna spunta": l'utente riceve da solo notifica, push ed email (le manda il database) — lo si scrive sopra l'elenco */
function showUsersVerifyNotice(name){
  var list = document.getElementById('adminUsersList');
  if(!list || !list.parentNode) return;
  var el = document.getElementById('usersVerifyNote');
  if(!el){
    el = document.createElement('div');
    el.id = 'usersVerifyNote';
    el.className = 'form-note';
    el.setAttribute('role', 'status');
    el.style.color = '#5fb98a';
    list.parentNode.insertBefore(el, list);
  }
  el.textContent = t('users.verifiedNotice').replace('{name}', name);
}
function clearUsersVerifyNotice(){
  var el = document.getElementById('usersVerifyNote');
  if(el) el.textContent = '';
}

function renderAdminUsers(){
  if(!isAdmin()) return;
  var list = document.getElementById('adminUsersList');
  if(!list) return;
  var session = getSession();
  fetch(SUPABASE_URL + '/rest/v1/profiles?select=id,display_name,created_at,verified,last_seen,role&order=created_at.desc', {
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
  })
    .then(function(r){ if(!r.ok) throw new Error('admin users read failed'); return r.json(); })
    .then(function(rows){
      list.innerHTML = '';
      if(rows.length === 0){ list.innerHTML = '<p class="form-note">' + t('users.empty') + '</p>'; return; }
      var onlineCount = rows.filter(function(u){
        return u.last_seen && (Date.now() - new Date(u.last_seen).getTime()) < ONLINE_WINDOW_MS;
      }).length;
      var summary = document.createElement('p');
      summary.className = 'form-note';
      summary.id = 'onlineCountSummary';
      summary.innerHTML = '<span class="online-dot"></span> ' + t('users.onlineNow').replace('{n}', onlineCount);
      list.appendChild(summary);

      rows.forEach(function(u){
        var joined = new Date(u.created_at);
        var daysHere = Math.floor((Date.now() - joined.getTime()) / 86400000);
        var eligible = daysHere >= VERIFICATION_MIN_DAYS;
        var displayLabel = u.display_name ? escapeHtml(u.display_name) : (t('users.noName') + ' ' + u.id.slice(0,8));
        var isOnline = u.last_seen && (Date.now() - new Date(u.last_seen).getTime()) < ONLINE_WINDOW_MS;

        var row = document.createElement('div');
        row.className = 'admin-row';
        var statusHtml = eligible
          ? '<span class="user-eligible-tag">' + t('users.eligible') + '</span>'
          : '<span class="user-waiting-tag">' + t('users.waitingDays').replace('{n}', VERIFICATION_MIN_DAYS - daysHere) + '</span>';
        var onlineHtml = isOnline ? '<span class="online-dot" title="' + t('users.onlineTag') + '"></span> ' : '';
        row.innerHTML =
          '<div class="info"><div class="t">' + onlineHtml + displayLabel + ' ' + verifiedBadge('verified.commenter', !!u.verified) + '</div>' +
          '<div class="m">' + t('users.joined') + ' ' + joined.toISOString().slice(0,10) + ' · ' + t('users.daysHere').replace('{n}', daysHere) + ' · ' + statusHtml + '</div></div>' +
          '<div class="admin-actions">' +
            '<select class="admin-role-select" data-role-select="' + u.id + '" aria-label="Ruolo">' +
              '<option value=""' + (u.role ? '' : ' selected') + '>' + t('role.none') + '</option>' +
              '<option value="mod"' + (u.role === 'mod' ? ' selected' : '') + '>' + t('role.mod') + '</option>' +
              '<option value="coll"' + (u.role === 'coll' ? ' selected' : '') + '>' + t('role.coll') + '</option>' +
            '</select>' +
            '<button class="btn btn-sm btn-ghost" data-toggle-verified="' + u.id + '">' +
              (u.verified ? t('users.revoke') : t('users.grant')) +
            '</button>' +
          '</div>';
        row.querySelector('[data-role-select]').addEventListener('change', function(e){
          var sel = e.target;
          fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(u.id), {
            method:'PATCH',
            headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'return=representation' },
            body: JSON.stringify({ role: sel.value || null })
          }).then(function(r){ return r.json().then(function(j){ return { ok:r.ok, rows:j }; }); })
            .then(function(res){
              if(!res.ok || !res.rows.length){ sel.value = u.role || ''; window.alert('Non salvato: manca il permesso sui ruoli (lancia lo SQL dei ruoli).'); }
            })
            .catch(function(){ sel.value = u.role || ''; window.alert('Errore di rete.'); });
        });
        row.querySelector('[data-toggle-verified]').addEventListener('click', function(){
          if(!eligible && !u.verified){
            var msg = t('users.earlyGrantConfirm').replace('{n}', VERIFICATION_MIN_DAYS - daysHere).replace('{name}', displayLabel);
            if(!window.confirm(msg)) return;
          }
          var willGrant = !u.verified; // deciso al momento del click: true = si sta assegnando la spunta
          fetch(SUPABASE_URL + '/rest/v1/profiles?id=eq.' + encodeURIComponent(u.id), {
            method:'PATCH',
            headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
            body: JSON.stringify({verified: willGrant})
          }).then(function(r){
            if(r.ok){
              renderAdminUsers();
              if(willGrant) showUsersVerifyNotice(u.display_name || (t('users.noName') + ' ' + u.id.slice(0,8)));
              else clearUsersVerifyNotice();
            } else {
              r.json().then(function(e){ window.alert((e && e.message) || 'Errore'); }).catch(function(){ window.alert('Errore'); });
            }
          });
        });
        list.appendChild(row);
      });
    })
    .catch(function(err){ console.warn('Admin users load failed:', err); });
}

function renderAdminAnnouncements(){
  if(!isAdmin()) return;
  var list = document.getElementById('adminAnnouncementsList');
  if(!list) return;
  var session = getSession();
  fetch(SUPABASE_URL + '/rest/v1/announcements?select=*&order=created_at.desc', {
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
  })
    .then(function(r){ if(!r.ok) throw new Error('admin announcements read failed'); return r.json(); })
    .then(function(rows){
      list.innerHTML = '';
      if(rows.length === 0){ list.innerHTML = '<p class="form-note">' + t('announcements.empty') + '</p>'; return; }
      rows.forEach(function(a){
        var row = document.createElement('div');
        row.className = 'admin-row';
        var dateStr = a.created_at ? a.created_at.slice(0,10) : '';
        var isExpired = a.expires_at ? (new Date(a.expires_at) <= new Date()) : false;
        var expiryLabel;
        if(isExpired){
          expiryLabel = '<span class="ann-expired-tag">' + t('announcements.archived') + '</span>';
        } else {
          var hoursLeft = Math.max(0, Math.round((new Date(a.expires_at) - new Date()) / 3600000));
          expiryLabel = '<span class="ann-active-tag">' + t('announcements.expiresIn').replace('{h}', hoursLeft) + '</span>';
        }
        var extendBtnHtml = !isExpired ? '<button class="btn btn-sm btn-ghost" data-extend-ann="' + a.id + '">' + t('announcements.extend') + '</button>' : '';
        row.innerHTML =
          '<div class="info"><div class="t">' + escapeHtml(a.title) + '</div>' +
          '<div class="m">' + dateStr + ' · ' + (a.published ? t('announcements.statusPublished') : t('announcements.statusHidden')) + ' · ' + expiryLabel + '</div></div>' +
          '<div class="admin-actions">' +
            extendBtnHtml +
            '<button class="btn btn-sm btn-ghost" data-toggle-ann="' + a.id + '">' + (a.published ? t('announcements.hide') : t('announcements.show')) + '</button>' +
            '<button class="btn btn-sm btn-ghost" data-del-ann="' + a.id + '">×</button>' +
          '</div>';
        if(extendBtnHtml){
          row.querySelector('[data-extend-ann]').addEventListener('click', function(){
            fetch(SUPABASE_URL + '/rest/v1/announcements?id=eq.' + encodeURIComponent(a.id), {
              method:'PATCH',
              headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
              body: JSON.stringify({expires_at: new Date(Date.now() + 24*60*60*1000).toISOString()})
            }).then(function(r){ if(r.ok){ renderAdminAnnouncements(); fetchAnnouncements(); } });
          });
        }
        row.querySelector('[data-toggle-ann]').addEventListener('click', function(){
          fetch(SUPABASE_URL + '/rest/v1/announcements?id=eq.' + encodeURIComponent(a.id), {
            method:'PATCH',
            headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
            body: JSON.stringify({published: !a.published})
          }).then(function(r){ if(r.ok){ renderAdminAnnouncements(); fetchAnnouncements(); } });
        });
        row.querySelector('[data-del-ann]').addEventListener('click', function(){
          if(!confirm(t('admin.confirmDelete'))) return;
          luxDelete('announcements?id=eq.' + encodeURIComponent(a.id)).then(function(){ renderAdminAnnouncements(); fetchAnnouncements(); }, luxDeleteFail);
        });
        list.appendChild(row);
      });
    })
    .catch(function(err){ console.warn('Admin announcements load failed:', err); });
}

function ensureClearReadRequestsButton(){
  if(document.getElementById('btnClearReadRequests')) return;
  var list = document.getElementById('adminRequestsList');
  if(!list || !list.parentNode) return;
  var btn = document.createElement('button');
  btn.type = 'button';
  btn.id = 'btnClearReadRequests';
  btn.className = 'btn btn-ghost btn-sm';
  btn.style.marginBottom = '14px';
  btn.textContent = 'Elimina tutte le richieste già lette';
  btn.addEventListener('click', function(){
    if(!confirm('Eliminare tutte le richieste già segnate come lette?')) return;
    var session = getSession();
    luxDelete('requests?status=eq.read', { allowEmpty: true }).then(function(rows){
      renderAdminRequests();
      // "ok" con zero righe ma richieste lette ancora in lista = permesso negato
      if(!rows.length && document.querySelector('#adminRequestsList [data-read-tag]')) luxDeleteFail(luxDeleteErr('denied'));
    }, luxDeleteFail);
  });
  list.parentNode.insertBefore(btn, list);
}

function renderAdminRequests(){
  if(!isAdmin()) return;
  var list = document.getElementById('adminRequestsList');
  if(!list) return;
  ensureClearReadRequestsButton();
  var session = getSession();
  var authH = { 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token };
  // chi ha già il pagamento verificato: il pulsante lo ricorda anche dopo aver ricaricato
  var verifiedReq = fetch(SUPABASE_URL + '/rest/v1/verified_supporters?select=user_id', { headers: authH })
    .then(function(r){ return r.ok ? r.json() : []; }).catch(function(){ return []; });
  var requestsReq = fetch(SUPABASE_URL + '/rest/v1/requests?select=*&order=created_at.desc', { headers: authH })
    .then(function(r){ if(!r.ok) throw new Error('admin requests read failed'); return r.json(); });
  Promise.all([requestsReq, verifiedReq])
    .then(function(res){
      var rows = res[0];
      var verified = {};
      (res[1] || []).forEach(function(v){ if(v && v.user_id) verified[v.user_id] = true; });
      list.innerHTML = '';
      if(rows.length === 0){ list.innerHTML = '<p class="form-note">' + t('requests.empty') + '</p>'; return; }
      rows.forEach(function(req){
        var isPurchase = (req.body || '').indexOf('[ACQUISTO]') === 0;
        var isDonation = (req.body || '').indexOf('[DONAZIONE]') === 0;
        var isSupport = isPurchase || isDonation;
        var row = document.createElement('div');
        row.className = 'mod-row';
        row.innerHTML =
          '<div>' +
            '<div class="who">' + escapeHtml(req.author_email || '') + (req.status === 'new' ? ' · <b>' + t('requests.statusNew') + '</b>' : '') + '</div>' +
            '<div class="txt">' + escapeHtml(req.body) + '</div>' +
          '</div>' +
          '<div class="admin-actions">' +
          (isSupport && req.user_id ? (verified[req.user_id]
            ? '<span class="req-done-tag">✓ Pagamento verificato</span>'
            : '<button class="btn btn-primary btn-sm" data-verify-supporter="' + req.id + '">Verifica pagamento (sblocca pagine pulite)</button>') : '') +
          (isSupport && !req.user_id ? '<span class="mono" style="font-size:11px;color:var(--parchment-dim);">non collegato a un account — non verificabile</span>' : '') +
          (isSupport ? '' : '<button class="btn btn-primary btn-sm" data-approve-collab="' + req.id + '">Approva collaborazione</button>') +
          (req.status === 'new'
            ? '<button class="btn btn-ghost btn-sm" data-mark-read="' + req.id + '">' + t('requests.markRead') + '</button>'
            : '<span class="req-done-tag" data-read-tag>✓ Letta</span>') +
          '<button class="btn btn-ghost btn-sm" data-del-req="' + req.id + '" style="border-color:#e24b4a;color:#e24b4a;">Elimina</button>' +
          '</div>';
        var markBtn = row.querySelector('[data-mark-read]');
        if(markBtn) markBtn.addEventListener('click', function(){
          markBtn.disabled = true;
          fetch(SUPABASE_URL + '/rest/v1/requests?id=eq.' + encodeURIComponent(req.id), {
            method:'PATCH',
            headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'return=representation' },
            body: JSON.stringify({status:'read'})
          }).then(function(r){
            if(!r.ok) throw new Error('HTTP ' + r.status);
            return r.json();
          }).then(function(changed){
            // "ok" ma nessuna riga cambiata = il database non lo permette (prima non succedeva niente)
            if(!changed || !changed.length) window.alert('Non è stato possibile segnarla come letta: il database non lo consente. Lancia elimina_contenuti.sql su Supabase (SQL Editor).');
            renderAdminRequests();
          }).catch(function(){ markBtn.disabled = false; luxToast(t('net.actionFailed')); });
        });
        row.querySelector('[data-del-req]').addEventListener('click', function(){
          if(!confirm('Eliminare questa richiesta?')) return;
          var delReqBtn = this;
          delReqBtn.disabled = true;
          luxDelete('requests?id=eq.' + encodeURIComponent(req.id)).then(function(){ renderAdminRequests(); })
            .catch(function(err){ delReqBtn.disabled = false; luxDeleteFail(err); });
        });
        var approveBtn = row.querySelector('[data-approve-collab]');
        if(approveBtn){
          approveBtn.addEventListener('click', function(){
            inviteFriendToCreate(req.user_id, req.author_email || 'questo utente');
          });
        }
        var verifyBtn = row.querySelector('[data-verify-supporter]');
        if(verifyBtn){
          verifyBtn.addEventListener('click', function(){
            verifyBtn.disabled = true;
            var originalText = verifyBtn.textContent;
            verifyBtn.textContent = '…';
            fetch(SUPABASE_URL + '/rest/v1/verified_supporters', {
              method:'POST',
              headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'resolution=merge-duplicates' },
              body: JSON.stringify({ user_id: req.user_id, note: req.body })
            }).then(function(r){
              if(!r.ok){
                return r.text().then(function(errText){ throw new Error(r.status + ': ' + errText); });
              }
              verifyBtn.textContent = '✓ Verificato';
            }).catch(function(e){
              console.warn('Verify supporter failed:', e);
              verifyBtn.textContent = originalText;
              verifyBtn.disabled = false;
              window.alert('Verifica non riuscita: ' + e.message);
            });
          });
        }
        list.appendChild(row);
      });
    })
    .catch(function(err){ console.warn('Admin requests load failed:', err); });
}

function renderModerationQueue(){
  var box = document.getElementById('modQueue');
  if(!box || !SUPABASE_URL || !isAdmin()) return;
  var session = getSession();
  fetch(SUPABASE_URL + '/rest/v1/comments?approved=eq.false&select=*&order=created_at.asc', {
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token }
  })
    .then(function(r){ if(!r.ok) throw new Error('moderation read failed'); return r.json(); })
    .then(function(rows){
      box.innerHTML = '';
      if(rows.length === 0){ box.innerHTML = '<p class="form-note">' + t('comments.noPending') + '</p>'; return; }
      var items = getCatalog();
      rows.forEach(function(c){
        var titleObj = items.find(function(i){ return i.id === c.catalog_id; });
        var row = document.createElement('div');
        row.className = 'mod-row';
        row.innerHTML =
          '<div><div class="who">' + escapeHtml(c.author_name) + ' · ' + (titleObj ? escapeHtml(titleObj.title) : c.catalog_id) + '</div>' +
          '<div class="txt">' + escapeHtml(c.body) + '</div></div>' +
          '<div class="admin-actions"><button class="btn btn-sm btn-ghost" data-approve="' + c.id + '">✓</button><button class="btn btn-sm btn-ghost" data-reject="' + c.id + '">×</button></div>';
        row.querySelector('[data-approve]').addEventListener('click', function(){ moderateComment(c.id, true, c.catalog_id); });
        row.querySelector('[data-reject]').addEventListener('click', function(){ moderateComment(c.id, false, c.catalog_id); });
        box.appendChild(row);
      });
    })
    .catch(function(err){ console.warn('Moderation queue load failed:', err); });
}
function moderateComment(id, approve, catalogId){
  var session = getSession();
  var req = approve
    ? fetch(SUPABASE_URL + '/rest/v1/comments?id=eq.' + encodeURIComponent(id), {
        method:'PATCH',
        headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json' },
        body: JSON.stringify({approved:true})
      })
    : luxDelete('comments?id=eq.' + encodeURIComponent(id)).then(function(){ return { ok: true }; });
  req.then(function(r){
    if(!r.ok) throw new Error('moderation action failed');
    if(approve && catalogId) bumpLocalCommentCount(catalogId, 1);
    renderModerationQueue();
  }).catch(function(err){ console.warn('Moderation action failed:', err); if(err && err.kind) luxDeleteFail(err); else luxToast(t('net.actionFailed')); });
}
function bumpLocalCommentCount(catalogId, delta){
  var items = getCatalog();
  var item = items.find(function(i){ return i.id === catalogId; });
  if(!item) return;
  item.comment_count = Math.max(0, (item.comment_count || 0) + delta);
  saveCatalogLocal(items);
  renderCatalog();
  if(currentModalCatalogId === catalogId) updateEngagementCountsLabel(catalogId);
}

