var characterImages = {};
var CHAR_LIST = ['Lucifer','Lilith','Lucifera','Lucio','Nox'];

function fetchCharacterImages(){
  if(!SUPABASE_URL) return Promise.resolve();
  return fetch(SUPABASE_URL + '/rest/v1/character_images?select=*', {
    headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + SUPABASE_ANON_KEY }
  })
    .then(function(r){ if(!r.ok) throw new Error('character images read failed'); return r.json(); })
    .then(function(rows){
      characterImages = {};
      rows.forEach(function(row){ if(row.image_url) characterImages[row.character] = row.image_url; });
      renderDossiers();
      renderHeroBg();
    })
    .catch(function(err){ console.warn('Character images load failed:', err); });
}
function renderHeroBg(){
  var box = document.getElementById('heroBg');
  if(!box) return;
  if(window.LUX_NET === 'slow') return; // su 2G: niente ritratti velati, resta lo sfondo leggero
  box.innerHTML = '';
  var sliceW = window.innerWidth <= 700 ? 300 : 600; // su telefono ogni striscia è larga un dito: basta metà
  charList(false).map(function(c){ return c.id; }).slice(0, 6).forEach(function(name){
    var url = characterImages[name];
    if(!url) return;
    var slice = document.createElement('div');
    slice.className = 'char-slice';
    // versione ridotta invece dell'originale a piena risoluzione (sono comunque
    // velate e scurite): si scaricano in una frazione del tempo, e compaiono
    // solo a immagine completa invece di disegnarsi a pezzi
    slice.innerHTML = '<img src="' + escapeHtml(coverThumbUrl(url, sliceW)) + '" data-fallback="' + escapeHtml(url) + '" alt="" decoding="async" onload="this.classList.add(\'is-in\')">';
    box.appendChild(slice);
  });
}

/* v219: immagini decorative sotto la piega (data-lazy-src) solo quando ci si
   avvicina. Il loading="lazy" del browser su 2G/3G scarica tutto ciò che sta
   nei primi 2500px — sulla home anche il banner del sostegno, 127 KB. */
function luxLazyImages(){
  var imgs = document.querySelectorAll('img[data-lazy-src]');
  if(!imgs.length) return;
  var load = function(img){ var u = img.getAttribute('data-lazy-src'); if(!u) return; img.removeAttribute('data-lazy-src'); img.src = u; };
  if(!('IntersectionObserver' in window)){ Array.prototype.forEach.call(imgs, load); return; }
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(en){
      if(!en.isIntersecting) return;
      if(document.body.classList.contains('home-loading')){
        // home ancora coperta: appena compare le sezioni si spostano, si ricontrolla tra poco
        setTimeout(function(){ io.unobserve(en.target); io.observe(en.target); }, 800);
        return;
      }
      io.unobserve(en.target);
      load(en.target);
    });
  }, { rootMargin: '300px 0px' });
  Array.prototype.forEach.call(imgs, function(img){ io.observe(img); });
}
if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', luxLazyImages);
else luxLazyImages();

function renderCharImageAdmin(){
  if(!isAdmin()) return;
  var row = document.getElementById('charImageRow');
  if(!row) return;
  row.innerHTML = '';
  charList(true).map(function(c){ return c.id; }).forEach(function(name){
    var item = document.createElement('div');
    item.className = 'char-image-item';
    var thumbSrc = characterImages[name] || '';
    item.innerHTML =
      '<img class="thumb" src="'+thumbSrc+'" alt="'+name+'" style="'+(thumbSrc ? '' : 'opacity:0.25;')+'">'+
      '<div class="name">'+name+'</div>'+
      '<input type="file" accept="image/*" data-char="'+name+'">';
    item.querySelector('input').addEventListener('change', function(e){
      if(e.target.files[0]) uploadCharacterImage(name, e.target.files[0]);
    });
    row.appendChild(item);
  });
}

function uploadCharacterImage(name, file){
  var extMatch = /\.([a-zA-Z0-9]+)$/.exec(file.name || '');
  var ext = extMatch ? extMatch[1].toLowerCase() : 'jpg';
  compressImageFile(file, 800, 0.85).then(function(compressed){
    return uploadCatalogAsset(compressed, 'characters/' + name.toLowerCase() + '.' + ext);
  }).then(function(url){
    var session = getSession();
    return fetch(SUPABASE_URL + '/rest/v1/character_images?on_conflict=character', {
      method:'POST',
      headers:{ 'apikey':SUPABASE_ANON_KEY, 'Authorization':'Bearer ' + session.access_token, 'Content-Type':'application/json', 'Prefer':'resolution=merge-duplicates' },
      body: JSON.stringify({character: name, image_url: url})
    }).then(function(r){
      if(!r.ok) throw new Error('character image save failed');
      characterImages[name] = url;
      renderDossiers();
      renderCharImageAdmin();
    });
  }).catch(function(err){ console.warn('Character image upload failed:', err); });
}

